window.CODIGO_JAVA = window.CODIGO_JAVA || {};
window.CODIGO_JAVA["nexus-ms"] = {"src/main/java/com/mx/josesaid/develop/nexus/NexusApplication.java": "package com.mx.josesaid.develop.nexus;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Aplicación de nexus-ms. Activa las tareas programadas, por ejemplo la limpieza de acciones vencidas. */\n@SpringBootApplication\n@EnableScheduling\npublic class NexusApplication {\n\n    /** Arranca la aplicación de Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(NexusApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/AccionResumen.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Lo que el usuario ve de una acción pendiente. El payload técnico no sale de la API.\n *\n * @param id componente de tipo {@code UUID}.\n * @param tipo componente de tipo {@code String}.\n * @param resumen componente de tipo {@code String}.\n * @param estatus componente de tipo {@code String}.\n * @param expiraUtc componente de tipo {@code Instant}.\n */\npublic record AccionResumen(UUID id, String tipo, String resumen, String estatus, Instant expiraUtc) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/ConsultaRequest.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\n\n/**\n * Pregunta del usuario al asistente. Debe tener texto y no pasar de 2000 caracteres.\n *\n * @param pregunta componente de tipo {@code String}.\n */\npublic record ConsultaRequest(\n        @NotBlank(message = \"La pregunta es obligatoria\")\n        @Size(max = 2000, message = \"La pregunta no puede superar 2000 caracteres\")\n        String pregunta) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/ConsultaResponse.java": "package com.mx.josesaid.develop.nexus.api;\n\n/**\n * Respuesta del asistente en texto plano.\n *\n * @param respuesta componente de tipo {@code String}.\n */\npublic record ConsultaResponse(String respuesta) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/ManejoErrores.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport java.net.SocketTimeoutException;\n\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\nimport org.springframework.web.client.ResourceAccessException;\n\nimport com.mx.josesaid.develop.nexus.application.PresupuestoAgotadoException;\n\n/** Errores de la API con formato de problema (RFC 9457). */\n@RestControllerAdvice\npublic class ManejoErrores {\n\n    /** Convierte un tiempo agotado al llamar al modelo o a otro servicio en un 504 con formato RFC 9457. */\n    @ExceptionHandler(ResourceAccessException.class)\n    ProblemDetail tiempoAgotado(ResourceAccessException e) {\n        return problema(HttpStatus.GATEWAY_TIMEOUT, \"tiempo-agotado\",\n                \"El modelo o un servicio no respondió a tiempo. Intenta de nuevo.\");\n    }\n\n    /** Igual que el anterior, para el tiempo agotado de la conexión por socket. */\n    @ExceptionHandler(SocketTimeoutException.class)\n    ProblemDetail tiempoAgotadoSocket(SocketTimeoutException e) {\n        return problema(HttpStatus.GATEWAY_TIMEOUT, \"tiempo-agotado\",\n                \"El modelo o un servicio no respondió a tiempo. Intenta de nuevo.\");\n    }\n\n    /** Convierte el agotamiento del presupuesto de tokens en un 429. El mensaje describe qué presupuesto se agotó. */\n    @ExceptionHandler(PresupuestoAgotadoException.class)\n    ProblemDetail presupuestoAgotado(PresupuestoAgotadoException e) {\n        return problema(HttpStatus.TOO_MANY_REQUESTS, \"presupuesto-agotado\", e.getMessage());\n    }\n\n    /** Construye la respuesta de error con el tipo, el título del estado HTTP y el detalle indicados. */\n    private static ProblemDetail problema(HttpStatus estado, String tipo, String detalle) {\n        ProblemDetail p = ProblemDetail.forStatusAndDetail(estado, detalle);\n        p.setType(java.net.URI.create(\"https://empresa-josesaid/errores/\" + tipo));\n        p.setTitle(estado.getReasonPhrase());\n        return p;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/NexusControlador.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.DatosAlta;\nimport com.mx.josesaid.develop.nexus.application.AccionNoEncontradaException;\nimport com.mx.josesaid.develop.nexus.application.AccionNoPendienteException;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacionInvalidoException;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Pattern;\n\nimport jakarta.validation.Valid;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.validation.annotation.Validated;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RestController;\n\nimport java.time.Instant;\n\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.AuditoriaConsultas;\nimport com.mx.josesaid.develop.nexus.application.PreguntaAsistente;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoTokens;\nimport com.mx.josesaid.develop.nexus.application.RegistroConsulta;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/** Endpoints del asistente Nexus: consultas, confirmación de acciones y administración de presupuesto. Todos requieren un JWT válido. */\n@RestController\n@RequestMapping(\"/nexus\")\n@Validated\npublic class NexusControlador {\n\n    private final AsistenteIA asistente;\n    private final AuditoriaConsultas auditoria;\n    private final AccionesPendientes acciones;\n    private final PresupuestoTokens presupuesto;\n    private final ConfirmacionAcciones confirmacion;\n\n    /** Recibe el asistente, la auditoría, el registro de acciones, el control de presupuesto de tokens y la confirmación de acciones. */\n    public NexusControlador(AsistenteIA asistente, AuditoriaConsultas auditoria, AccionesPendientes acciones,\n                            PresupuestoTokens presupuesto, ConfirmacionAcciones confirmacion) {\n        this.asistente = asistente;\n        this.auditoria = auditoria;\n        this.acciones = acciones;\n        this.presupuesto = presupuesto;\n        this.confirmacion = confirmacion;\n    }\n\n    /** El usuario confirma una acción que Nexus preparó. Solo quien la preparó puede confirmarla. */\n    @PostMapping(\"/acciones/{id}/confirmacion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','CONTADOR')\")\n    public ResponseEntity<String> confirmarAccion(@PathVariable UUID id,\n                                                  @RequestBody @Valid ConfirmacionSolicitud solicitud,\n                                                  @AuthenticationPrincipal Jwt jwt) {\n        String respuesta = confirmacion.confirmarConCodigo(id, jwt.getSubject(), solicitud.codigo());\n        return ResponseEntity.status(HttpStatus.CREATED)\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(respuesta);\n    }\n\n    /** Datos del alta pendiente (sin contraseña) para que la pantalla de altas los muestre y envíe. */\n    @GetMapping(\"/acciones/{id}/alta\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public DatosAlta datosAlta(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt) {\n        return DatosAlta.de(acciones.altaVigente(id, jwt.getSubject()).payload());\n    }\n\n    /** El administrador verifica el código de un alta antes de crear el usuario. Código incorrecto cancela la acción. */\n    @PostMapping(\"/acciones/{id}/alta/verificacion\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ResponseEntity<Void> verificarAlta(@PathVariable UUID id,\n                                              @RequestBody @Valid ConfirmacionSolicitud solicitud,\n                                              @AuthenticationPrincipal Jwt jwt) {\n        confirmacion.verificarAlta(id, jwt.getSubject(), solicitud.codigo());\n        return ResponseEntity.noContent().build();\n    }\n\n    /** Marca el alta como completada después de que la pantalla de altas creó el usuario. */\n    @PostMapping(\"/acciones/{id}/alta/completacion\")\n    @PreAuthorize(\"hasRole('ADMIN')\")\n    public ResponseEntity<Void> completarAlta(@PathVariable UUID id,\n                                              @RequestBody @Valid ConfirmacionSolicitud solicitud,\n                                              @AuthenticationPrincipal Jwt jwt) {\n        confirmacion.completarAlta(id, jwt.getSubject(), solicitud.codigo());\n        return ResponseEntity.noContent().build();\n    }\n\n    /** Muestra al dueño la acción pendiente antes de confirmarla. */\n    @GetMapping(\"/acciones/{id}\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','CONTADOR','ADMIN')\")\n    public AccionResumen consultarAccion(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt) {\n        var accion = acciones.consultar(id, jwt.getSubject());\n        return new AccionResumen(accion.id(), accion.tipo(), accion.resumen(), accion.estatus(), accion.expiraUtc());\n    }\n\n    /** El usuario descarta una acción pendiente sin ejecutarla. */\n    @PostMapping(\"/acciones/{id}/cancelacion\")\n    @PreAuthorize(\"hasAnyRole('VENTAS','CONTADOR')\")\n    public ResponseEntity<Void> cancelarAccion(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt) {\n        acciones.cancelar(id, jwt.getSubject());\n        return ResponseEntity.noContent().build();\n    }\n\n    /**\n     * Código de confirmación de 8 dígitos que el usuario escribe para ejecutar una acción pendiente.\n     *\n     * @param codigo componente de tipo {@code String}.\n     */\n    public record ConfirmacionSolicitud(@NotBlank @Pattern(regexp = \"\\\\d{8}\") String codigo) {\n    }\n\n    /** Responde 422 cuando el código de confirmación no coincide o ya no sirve. */\n    @ExceptionHandler(CodigoConfirmacionInvalidoException.class)\n    ResponseEntity<String> codigoInvalido(CodigoConfirmacionInvalidoException e) {\n        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(e.getMessage());\n    }\n\n    /** Responde 409 cuando la acción ya fue confirmada, cancelada o expiró. */\n    @ExceptionHandler(AccionNoPendienteException.class)\n    ResponseEntity<String> noPendiente(AccionNoPendienteException e) {\n        return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());\n    }\n\n    /** Responde 404 cuando la acción no existe o es de otro usuario. */\n    @ExceptionHandler(AccionNoEncontradaException.class)\n    ResponseEntity<String> noEncontrada(AccionNoEncontradaException e) {\n        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(e.getMessage());\n    }\n\n    /** Responde una consulta en lenguaje natural. Antes de llamar al modelo verifica el presupuesto de tokens, y después registra la consulta en auditoría. Sus herramientas solo preparan acciones; nunca las ejecutan. */\n    @PostMapping(\"/consultas\")\n    @PreAuthorize(\"isAuthenticated()\")\n    public ConsultaResponse consultar(@RequestBody @Valid ConsultaRequest solicitud,\n                                      @AuthenticationPrincipal Jwt jwt) {\n        String usuario = jwt.getSubject();\n        String usuarioAuditoria = jwt.getClaimAsString(\"correo\");\n        if (usuarioAuditoria == null || usuarioAuditoria.isBlank()) {\n            usuarioAuditoria = usuario;\n        }\n        presupuesto.exigirDisponible(usuarioAuditoria);\n        var respuesta = asistente.consultar(new PreguntaAsistente(usuario, solicitud.pregunta()));\n        String texto = respuesta.texto() == null ? \"\" : respuesta.texto();\n        String resumen = FiltroDatosSensibles.redactar(texto.length() > 500 ? texto.substring(0, 500) : texto).texto();\n        String herramientas = String.join(\",\", respuesta.herramientas());\n        if (herramientas.length() > 500) {\n            herramientas = herramientas.substring(0, 500);\n        }\n        auditoria.registrar(new RegistroConsulta(\n                usuarioAuditoria,\n                FiltroDatosSensibles.redactar(solicitud.pregunta()).texto(),\n                resumen,\n                herramientas.isEmpty() ? null : herramientas,\n                respuesta.tokensEntrada(),\n                respuesta.tokensSalida(),\n                Instant.now()));\n        return new ConsultaResponse(FiltroDatosSensibles.redactar(texto).texto());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/PolizasControlador.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\n\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.validation.annotation.Validated;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.application.ServicioPolizas;\nimport com.mx.josesaid.develop.nexus.application.SugerenciaPolizaInvalidaException;\n\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.Size;\n\n/**\n * Sugerencias de pólizas. Nexus solo prepara la acción: la póliza se registra cuando el contador\n * la confirma con POST /nexus/acciones/{id}/confirmacion.\n */\n@RestController\n@RequestMapping(\"/nexus/polizas\")\n@Validated\npublic class PolizasControlador {\n\n    private final ServicioPolizas servicio;\n    private final CodigoConfirmacion codigos;\n\n    /** Recibe el servicio que prepara las sugerencias y el generador de códigos de confirmación. */\n    public PolizasControlador(ServicioPolizas servicio, CodigoConfirmacion codigos) {\n        this.servicio = servicio;\n        this.codigos = codigos;\n    }\n\n    /** Prepara una sugerencia de póliza a partir de la descripción del contador. Devuelve la acción pendiente junto con su código de confirmación de una sola vez. Solo CONTADOR puede llamarlo. */\n    @PostMapping(\"/sugerencias\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('CONTADOR')\")\n    public SugerenciaRespuesta sugerir(@RequestBody @Valid SugerenciaPolizaSolicitud solicitud,\n                                       @AuthenticationPrincipal Jwt jwt) {\n        AccionPendiente accion = servicio.preparar(jwt.getSubject(), solicitud.descripcion());\n        return new SugerenciaRespuesta(accion.id(), accion.tipo(), accion.resumen(), accion.estatus(),\n                accion.expiraUtc(), codigos.generar(accion.id(), accion.usuario()));\n    }\n\n    /** Responde 422 cuando la sugerencia no es válida, con el motivo en el campo error. */\n    @ExceptionHandler(SugerenciaPolizaInvalidaException.class)\n    ResponseEntity<Map<String, String>> sugerenciaInvalida(SugerenciaPolizaInvalidaException e) {\n        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(Map.of(\"error\", e.getMessage()));\n    }\n\n    /**\n     * Cuerpo de la petición: descripción de la póliza, de 1 a 500 caracteres.\n     *\n     * @param descripcion componente de tipo {@code String}.\n     */\n    public record SugerenciaPolizaSolicitud(@NotBlank @Size(max = 500) String descripcion) {\n    }\n\n    /**\n     * Respuesta de una sugerencia. Incluye el código de confirmación de una sola vez, que solo recibe\n     * quien pidió la sugerencia (CONTADOR). Sin el código la acción no puede confirmarse.\n      * @param id componente de tipo {@code UUID}.\n      * @param tipo componente de tipo {@code String}.\n      * @param resumen componente de tipo {@code String}.\n      * @param estatus componente de tipo {@code String}.\n      * @param expiraUtc componente de tipo {@code Instant}.\n      * @param codigoConfirmacion componente de tipo {@code String}.\n     */\n    public record SugerenciaRespuesta(UUID id, String tipo, String resumen, String estatus,\n                                      Instant expiraUtc, String codigoConfirmacion) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/api/package-info.java": "/**\n * Capa \"api\" de Nexus. Ver docs/diseno.md para las reglas de dependencia entre capas.\n */\npackage com.mx.josesaid.develop.nexus.api;\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AccionNoEncontradaException.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** La acción no existe o no pertenece al usuario que la confirma. */\npublic class AccionNoEncontradaException extends RuntimeException {\n\n    /** Crea la excepción con el mensaje que se mostrará al usuario. */\n    public AccionNoEncontradaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AccionNoPendienteException.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** La acción ya fue confirmada, cancelada o expiró. */\npublic class AccionNoPendienteException extends RuntimeException {\n\n    /** Crea la excepción con el mensaje que se mostrará al usuario. */\n    public AccionNoPendienteException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AccionPendiente.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Acción de escritura que Nexus preparó y que espera la confirmación del usuario.\n *\n * @param id componente de tipo {@code UUID}.\n * @param usuario componente de tipo {@code String}.\n * @param tipo componente de tipo {@code String}.\n * @param payload componente de tipo {@code String}.\n * @param resumen componente de tipo {@code String}.\n * @param estatus componente de tipo {@code String}.\n * @param creadaUtc componente de tipo {@code Instant}.\n * @param expiraUtc componente de tipo {@code Instant}.\n */\npublic record AccionPendiente(UUID id, String usuario, String tipo, String payload, String resumen,\n                              String estatus, Instant creadaUtc, Instant expiraUtc) {\n\n    public static final String PENDIENTE = \"PENDIENTE\";\n    public static final String CONFIRMADA = \"CONFIRMADA\";\n    public static final String EXPIRADA = \"EXPIRADA\";\n    public static final String CANCELADA = \"CANCELADA\";\n\n    /** Devuelve una copia de la acción con otro estatus. Los registros son inmutables; cambiar el estatus siempre crea una nueva instancia. */\n    public AccionPendiente conEstatus(String nuevoEstatus) {\n        return new AccionPendiente(id, usuario, tipo, payload, resumen, nuevoEstatus, creadaUtc, expiraUtc);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AccionesPendientes.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Prepara y confirma acciones de escritura. Nexus nunca ejecuta una acción por sí solo:\n * la confirmación la hace el usuario con su propia sesión, y solo quien preparó la acción puede confirmarla.\n */\npublic final class AccionesPendientes {\n\n    public static final String TIPO_PEDIDO_BORRADOR = \"PEDIDO_BORRADOR\";\n    public static final String TIPO_PROSPECTO_BORRADOR = \"PROSPECTO_BORRADOR\";\n    public static final String TIPO_PEDIDO_CONFIRMAR = \"PEDIDO_CONFIRMAR\";\n    public static final String TIPO_PEDIDO_CANCELAR = \"PEDIDO_CANCELAR\";\n    public static final String TIPO_COTIZACION_ENVIAR = \"COTIZACION_ENVIAR\";\n    public static final String TIPO_COTIZACION_ACEPTAR = \"COTIZACION_ACEPTAR\";\n    public static final String TIPO_COTIZACION_A_PEDIDO = \"COTIZACION_A_PEDIDO\";\n    public static final String TIPO_COTIZACION_CREAR = \"COTIZACION_CREAR\";\n    public static final String TIPO_PEDIDO_REEMPLAZAR_LINEAS = \"PEDIDO_REEMPLAZAR_LINEAS\";\n    public static final String TIPO_PEDIDO_DEVOLVER = \"PEDIDO_DEVOLVER\";\n    public static final String TIPO_PROSPECTO_ESTATUS = \"PROSPECTO_ESTATUS\";\n    public static final String TIPO_PROSPECTO_CONVERTIR = \"PROSPECTO_CONVERTIR\";\n    public static final String TIPO_INTERACCION_REGISTRAR = \"INTERACCION_REGISTRAR\";\n    public static final String TIPO_POLIZA_REGISTRAR = \"POLIZA_REGISTRAR\";\n    public static final String TIPO_DOCUMENTO_ELIMINAR = \"DOCUMENTO_ELIMINAR\";\n    public static final String TIPO_CLIENTE_CREAR = \"CLIENTE_CREAR\";\n    public static final String TIPO_CLIENTE_ACTUALIZAR = \"CLIENTE_ACTUALIZAR\";\n    public static final String TIPO_CLIENTE_CONTACTO_AGREGAR = \"CLIENTE_CONTACTO_AGREGAR\";\n    public static final String TIPO_PROVEEDOR_CREAR = \"PROVEEDOR_CREAR\";\n    public static final String TIPO_ORDEN_COMPRA_CREAR = \"ORDEN_COMPRA_CREAR\";\n    public static final String TIPO_ORDEN_COMPRA_RECEPCION = \"ORDEN_COMPRA_RECEPCION\";\n    public static final String TIPO_ORDEN_COMPRA_CANCELAR = \"ORDEN_COMPRA_CANCELAR\";\n    public static final String TIPO_ARTICULO_CREAR = \"ARTICULO_CREAR\";\n    public static final String TIPO_MOVIMIENTO_REGISTRAR = \"MOVIMIENTO_REGISTRAR\";\n    public static final String TIPO_ORDEN_OPERACION_CREAR = \"ORDEN_OPERACION_CREAR\";\n    public static final String TIPO_COMPROBANTE_PAGO_REGISTRAR = \"COMPROBANTE_PAGO_REGISTRAR\";\n    public static final String TIPO_CLIENTE_ESTATUS = \"CLIENTE_ESTATUS\";\n    public static final String TIPO_ALMACEN_CREAR = \"ALMACEN_CREAR\";\n    public static final String TIPO_PEDIDO_ENTREGAR = \"PEDIDO_ENTREGAR\";\n    public static final String TIPO_INDICADOR_REGISTRAR = \"INDICADOR_REGISTRAR\";\n    /** El alta no la ejecuta Nexus: la pantalla de altas crea el usuario con la contraseña que escribe el administrador. */\n    public static final String TIPO_USUARIO_ALTA = \"USUARIO_ALTA\";\n    public static final Duration VIGENCIA = Duration.ofMinutes(10);\n\n    private final AlmacenAcciones almacen;\n    private final EjecutorAcciones ejecutor;\n    private final Clock reloj;\n\n    /** Recibe el almacén donde se guardan las acciones, el ejecutor que las aplica y el reloj para calcular vencimientos. */\n    public AccionesPendientes(AlmacenAcciones almacen, EjecutorAcciones ejecutor, Clock reloj) {\n        this.almacen = almacen;\n        this.ejecutor = ejecutor;\n        this.reloj = reloj;\n    }\n\n    /** Guarda una acción nueva en estado PENDIENTE. Vence a los 10 minutos (VIGENCIA). Nada se ejecuta todavía. */\n    public AccionPendiente preparar(String usuario, String tipo, String payload, String resumen) {\n        Instant ahora = reloj.instant();\n        AccionPendiente accion = new AccionPendiente(UUID.randomUUID(), usuario, tipo, payload, resumen,\n                AccionPendiente.PENDIENTE, ahora, ahora.plus(VIGENCIA));\n        almacen.guardar(accion);\n        return accion;\n    }\n\n    /**\n     * Confirma y ejecuta la acción. Si la ejecución falla, la acción sigue pendiente\n     * para que el usuario pueda intentarlo de nuevo mientras no expire.\n     */\n    public String confirmar(UUID id, String usuario) {\n        AccionPendiente accion = propia(id, usuario);\n        if (TIPO_USUARIO_ALTA.equals(accion.tipo())) {\n            throw new AccionNoPendienteException(\"Las altas de usuario se completan desde la pantalla de altas\");\n        }\n        if (!AccionPendiente.PENDIENTE.equals(accion.estatus())) {\n            throw new AccionNoPendienteException(\"La acción ya está \" + accion.estatus().toLowerCase());\n        }\n        if (reloj.instant().isAfter(accion.expiraUtc())) {\n            almacen.guardar(accion.conEstatus(AccionPendiente.EXPIRADA));\n            throw new AccionNoPendienteException(\"La acción expiró; pide a Nexus que la prepare de nuevo\");\n        }\n        String respuesta = ejecutor.ejecutar(accion.tipo(), accion.payload());\n        almacen.guardar(accion.conEstatus(AccionPendiente.CONFIRMADA));\n        return respuesta;\n    }\n\n    /** Devuelve la acción para mostrarla antes de confirmar. Si ya venció, la marca como EXPIRADA. */\n    public AccionPendiente consultar(UUID id, String usuario) {\n        AccionPendiente accion = propia(id, usuario);\n        if (AccionPendiente.PENDIENTE.equals(accion.estatus()) && reloj.instant().isAfter(accion.expiraUtc())) {\n            AccionPendiente expirada = accion.conEstatus(AccionPendiente.EXPIRADA);\n            almacen.guardar(expirada);\n            return expirada;\n        }\n        return accion;\n    }\n\n    /** El usuario descarta la acción sin ejecutarla. */\n    public void cancelar(UUID id, String usuario) {\n        AccionPendiente accion = propia(id, usuario);\n        if (!AccionPendiente.PENDIENTE.equals(accion.estatus())) {\n            throw new AccionNoPendienteException(\"La acción ya está \" + accion.estatus().toLowerCase());\n        }\n        almacen.guardar(accion.conEstatus(AccionPendiente.CANCELADA));\n    }\n\n    /** Marca un alta como completada. La creación del usuario ocurre en usuarios-accesos, no aquí. */\n    public void completarAlta(UUID id, String usuario) {\n        AccionPendiente accion = altaVigente(id, usuario);\n        almacen.guardar(accion.conEstatus(AccionPendiente.CONFIRMADA));\n    }\n\n    /**\n     * Devuelve un alta pendiente, vigente y del usuario. Si ya venció la marca como expirada.\n     * No cambia nada si la acción sigue vigente.\n     */\n    public AccionPendiente altaVigente(UUID id, String usuario) {\n        AccionPendiente accion = propia(id, usuario);\n        if (!TIPO_USUARIO_ALTA.equals(accion.tipo())) {\n            throw new AccionNoPendienteException(\"La acción no es un alta de usuario\");\n        }\n        if (!AccionPendiente.PENDIENTE.equals(accion.estatus())) {\n            throw new AccionNoPendienteException(\"La acción ya está \" + accion.estatus().toLowerCase());\n        }\n        if (reloj.instant().isAfter(accion.expiraUtc())) {\n            almacen.guardar(accion.conEstatus(AccionPendiente.EXPIRADA));\n            throw new AccionNoPendienteException(\"La acción expiró; pide a Nexus que la prepare de nuevo\");\n        }\n        return accion;\n    }\n\n    /** Busca la acción y verifica que pertenezca al usuario indicado. Si no existe o es de otro usuario responde lo mismo, para no revelar que existe. */\n    private AccionPendiente propia(UUID id, String usuario) {\n        return almacen.buscar(id)\n                .filter(a -> a.usuario().equals(usuario))\n                .orElseThrow(() -> new AccionNoEncontradaException(\"Acción no encontrada\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AlmacenAcciones.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto de persistencia de acciones pendientes. La implementación vive en infrastructure. */\npublic interface AlmacenAcciones {\n\n    void guardar(AccionPendiente accion);\n\n    Optional<AccionPendiente> buscar(UUID id);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AlmacenFragmentos.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Set;\n\n/** Guarda fragmentos de políticas con su vector y los busca filtrando por rol antes de comparar. */\npublic interface AlmacenFragmentos {\n\n    /** Reemplaza todos los fragmentos de una política de forma atómica. */\n    void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos);\n\n    /**\n     * Devuelve los fragmentos más parecidos a la consulta que el usuario puede ver:\n     * al menos uno de sus roles debe estar en la política y la política debe estar vigente en {@code hoy}.\n     */\n    List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AsistenteIA.java": "package com.mx.josesaid.develop.nexus.application;\n\n/**\n * Puerto del asistente. La aplicación depende de esta interfaz, no del proveedor de modelo.\n * El adaptador concreto vive en infrastructure.\n */\npublic interface AsistenteIA {\n\n    RespuestaAsistente consultar(PreguntaAsistente pregunta);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/AuditoriaConsultas.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** Puerto de auditoría: registra cada consulta. La implementación vive en infrastructure. */\npublic interface AuditoriaConsultas {\n\n    void registrar(RegistroConsulta registro);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/CodigoConfirmacion.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.nio.charset.StandardCharsets;\nimport java.security.GeneralSecurityException;\nimport java.security.MessageDigest;\nimport java.util.UUID;\n\nimport javax.crypto.Mac;\nimport javax.crypto.spec.SecretKeySpec;\n\n/**\n * Código de confirmación de una sola vez para acciones preparadas por MCP. Se deriva con HMAC del\n * identificador de la acción y del usuario que la preparó, así que no requiere guardarlo.\n * Quien prepara la acción recibe el código; quien la confirma debe presentarlo.\n */\npublic final class CodigoConfirmacion {\n\n    private static final String ALGORITMO = \"HmacSHA256\";\n    private static final int MINIMO_BYTES_SECRETO = 16;\n    private static final int LONGITUD = 8;\n\n    private final byte[] secreto;\n\n    /** Recibe el secreto que firma los códigos. Debe tener al menos MINIMO_BYTES_SECRETO bytes; si no, la aplicación no arranca. */\n    public CodigoConfirmacion(byte[] secreto) {\n        if (secreto == null || secreto.length < MINIMO_BYTES_SECRETO) {\n            throw new IllegalArgumentException(\"El secreto de confirmación debe tener al menos \" + MINIMO_BYTES_SECRETO + \" bytes\");\n        }\n        this.secreto = secreto.clone();\n    }\n\n    /** Genera el código de 8 dígitos para una acción y usuario. El código sale de un HMAC, así que no se puede adivinar sin el secreto ni reutilizar en otra acción. */\n    public String generar(UUID accionId, String usuario) {\n        byte[] mac = hmac(accionId + \"|\" + usuario);\n        int numero = ((mac[0] & 0x7f) << 24) | ((mac[1] & 0xff) << 16) | ((mac[2] & 0xff) << 8) | (mac[3] & 0xff);\n        int limite = (int) Math.pow(10, LONGITUD);\n        return String.format(\"%0\" + LONGITUD + \"d\", numero % limite);\n    }\n\n    /** Compara en tiempo constante para no revelar el código por diferencias de tiempo. */\n    public boolean coincide(UUID accionId, String usuario, String codigo) {\n        if (codigo == null) {\n            return false;\n        }\n        byte[] esperado = generar(accionId, usuario).getBytes(StandardCharsets.UTF_8);\n        return MessageDigest.isEqual(esperado, codigo.trim().getBytes(StandardCharsets.UTF_8));\n    }\n\n    /** Calcula el HMAC-SHA256 del texto con el secreto. Si falla el algoritmo, lanza una excepción, porque significa que el entorno no es válido. */\n    private byte[] hmac(String texto) {\n        try {\n            Mac mac = Mac.getInstance(ALGORITMO);\n            mac.init(new SecretKeySpec(secreto, ALGORITMO));\n            return mac.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo calcular el código de confirmación\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/CodigoConfirmacionInvalidoException.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** El código no coincide. La acción se cancela para que no pueda adivinarse por intentos repetidos. */\npublic class CodigoConfirmacionInvalidoException extends RuntimeException {\n\n    /** Crea la excepción con el mensaje que se mostrará al usuario. */\n    public CodigoConfirmacionInvalidoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/ConfirmacionAcciones.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.UUID;\n\n/**\n * Confirmación desde MCP: exige el código de una sola vez además de la identidad del usuario.\n * Un código incorrecto cancela la acción: no se permiten intentos repetidos contra la misma acción.\n */\npublic final class ConfirmacionAcciones {\n\n    private final AccionesPendientes acciones;\n    private final CodigoConfirmacion codigos;\n\n    /** Recibe el registro de acciones y el verificador de códigos. */\n    public ConfirmacionAcciones(AccionesPendientes acciones, CodigoConfirmacion codigos) {\n        this.acciones = acciones;\n        this.codigos = codigos;\n    }\n\n    /** Confirma una acción pidiendo el código de confirmación. Primero verifica que esté pendiente y que el código coincida. Solo si todo es válido la ejecuta. */\n    public String confirmarConCodigo(UUID id, String usuario, String codigo) {\n        AccionPendiente accion = acciones.consultar(id, usuario);\n        if (!AccionPendiente.PENDIENTE.equals(accion.estatus())) {\n            throw new AccionNoPendienteException(\"La acción ya está \" + accion.estatus().toLowerCase());\n        }\n        if (!codigos.coincide(id, usuario, codigo)) {\n            acciones.cancelar(id, usuario);\n            throw new CodigoConfirmacionInvalidoException(\n                    \"Código incorrecto. La acción se canceló por seguridad; pide a Nexus que la prepare de nuevo\");\n        }\n        return acciones.confirmar(id, usuario);\n    }\n\n    /** Verifica el código de un alta sin crear nada. Código incorrecto cancela la acción por seguridad. */\n    public void verificarAlta(UUID id, String usuario, String codigo) {\n        acciones.altaVigente(id, usuario);\n        if (!codigos.coincide(id, usuario, codigo)) {\n            acciones.cancelar(id, usuario);\n            throw new CodigoConfirmacionInvalidoException(\n                    \"Código incorrecto. La acción se canceló por seguridad; pide a Nexus que la prepare de nuevo\");\n        }\n    }\n\n    /** Marca el alta como completada tras crear el usuario. Vuelve a verificar el código. */\n    public void completarAlta(UUID id, String usuario, String codigo) {\n        verificarAlta(id, usuario, codigo);\n        acciones.completarAlta(id, usuario);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/ConsumoTokens.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.Instant;\n\n/** Puerto de lectura: tokens consumidos desde un instante, por usuario o por todo el servicio. La implementación vive en infrastructure. */\npublic interface ConsumoTokens {\n\n    long desde(String usuario, Instant desde);\n\n    long delServicio(Instant desde);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/ContextoContable.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Lectura del catálogo y de pólizas históricas con el token del usuario. Nexus no escribe aquí. */\npublic interface ContextoContable {\n\n    List<CuentaCatalogo> catalogo();\n\n    /** Pólizas aplicadas recientes, usadas como ejemplos few-shot. */\n    List<PolizaEjemplo> ejemplosRecientes();\n\n    /**\n     * Cuenta del catálogo contable, usada como ejemplo para el modelo.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param codigo componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     */\n    record CuentaCatalogo(UUID id, String codigo, String nombre) {\n    }\n\n    /**\n     * Póliza de ejemplo para que el modelo copie el formato correcto.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param fecha componente de tipo {@code LocalDate}.\n     * @param lineas componente de tipo {@code List<LineaEjemplo>}.\n     */\n    record PolizaEjemplo(String tipo, LocalDate fecha, List<LineaEjemplo> lineas) {\n    }\n\n    /**\n     * Línea de una póliza de ejemplo: cuenta, cargo y abono.\n     *\n     * @param cuentaId componente de tipo {@code UUID}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    record LineaEjemplo(UUID cuentaId, BigDecimal cargo, BigDecimal abono) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/DatosAlta.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.List;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\n\n/**\n * Datos de un alta de usuario que Nexus prepara. No contiene contraseña: la escribe el administrador\n * en la pantalla de altas, que la envía directo a usuarios-accesos.\n  * @param correo componente de tipo {@code String}.\n  * @param nombreCompleto componente de tipo {@code String}.\n  * @param roles componente de tipo {@code List<String>}.\n */\npublic record DatosAlta(String correo, String nombreCompleto, List<String> roles) {\n\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    /** Lee los datos de un alta de usuario desde el JSON guardado en la acción. Si el JSON no es válido, lanza una excepción. */\n    public static DatosAlta de(String payload) {\n        try {\n            return JSON.readValue(payload, DatosAlta.class);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"El alta guardada no se puede leer\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/EjecutorAcciones.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** Ejecuta una acción confirmada llamando al servicio de negocio con el token del usuario. */\npublic interface EjecutorAcciones {\n\n    /** Devuelve el cuerpo de la respuesta del servicio. Lanza excepción si la operación falla. */\n    String ejecutar(String tipo, String payload);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/Embedder.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.List;\n\n/** Convierte textos en vectores. La implementación concreta (Voyage AI) vive en infrastructure. */\npublic interface Embedder {\n\n    /** DOCUMENTO para fragmentos que se guardan; CONSULTA para la pregunta del usuario. */\n    enum TipoEntrada { DOCUMENTO, CONSULTA }\n\n    List<float[]> embeber(List<String> textos, TipoEntrada tipo);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/FragmentoIndexado.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.LocalDate;\nimport java.util.List;\n\n/**\n * Fragmento de una política listo para guardarse, con su vector.\n *\n * @param politicaId componente de tipo {@code String}.\n * @param indice componente de tipo {@code int}.\n * @param titulo componente de tipo {@code String}.\n * @param vigencia componente de tipo {@code LocalDate}.\n * @param roles componente de tipo {@code List<String>}.\n * @param texto componente de tipo {@code String}.\n * @param vector componente de tipo {@code float[]}.\n */\npublic record FragmentoIndexado(String politicaId, int indice, String titulo, LocalDate vigencia,\n                                List<String> roles, String texto, float[] vector) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/IngestaPoliticas.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * Trocea cada política en líneas con contenido (cada punto o regla es un fragmento),\n * genera sus embeddings y reemplaza lo que hubiera guardado para esa política.\n */\npublic final class IngestaPoliticas {\n\n    private final Embedder embedder;\n    private final AlmacenFragmentos almacen;\n\n    /** Recibe el generador de embeddings y el almacén de fragmentos. */\n    public IngestaPoliticas(Embedder embedder, AlmacenFragmentos almacen) {\n        this.embedder = embedder;\n        this.almacen = almacen;\n    }\n\n    /** Devuelve cuántos fragmentos quedaron guardados. */\n    public int ingerir(List<Politica> politicas) {\n        int total = 0;\n        for (Politica politica : politicas) {\n            List<String> trozos = trocear(politica);\n            if (trozos.isEmpty()) {\n                almacen.reemplazar(politica.id(), List.of());\n                continue;\n            }\n            // El título va en el texto que se embebe para que la búsqueda tenga contexto; se guarda solo el trozo\n            List<String> paraEmbeber = trozos.stream().map(t -> politica.titulo() + \". \" + t).toList();\n            List<float[]> vectores = embedder.embeber(paraEmbeber, Embedder.TipoEntrada.DOCUMENTO);\n            if (vectores.size() != trozos.size()) {\n                throw new IllegalStateException(\"El proveedor de embeddings devolvió \" + vectores.size()\n                        + \" vectores para \" + trozos.size() + \" fragmentos de \" + politica.id());\n            }\n            List<FragmentoIndexado> fragmentos = new ArrayList<>();\n            for (int i = 0; i < trozos.size(); i++) {\n                fragmentos.add(new FragmentoIndexado(politica.id(), i, politica.titulo(), politica.vigencia(),\n                        politica.roles(), trozos.get(i), vectores.get(i)));\n            }\n            almacen.reemplazar(politica.id(), fragmentos);\n            total += fragmentos.size();\n        }\n        return total;\n    }\n\n    /** Parte el texto de una política en trozos. Cada trozo es una línea no vacía, para que la búsqueda encuentre fragmentos pequeños y precisos. */\n    static List<String> trocear(Politica politica) {\n        List<String> trozos = new ArrayList<>();\n        for (String linea : politica.cuerpo().split(\"\\\\R\")) {\n            String texto = linea.trim();\n            if (texto.isEmpty() || texto.startsWith(\"#\")) {\n                continue;\n            }\n            trozos.add(texto);\n        }\n        return trozos;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/Politica.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.LocalDate;\nimport java.util.Arrays;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Map;\n\n/**\n * Política de la empresa leída de un archivo Markdown con front matter:\n * título, vigencia (fecha desde la que aplica) y roles que pueden consultarla.\n  * @param id componente de tipo {@code String}.\n  * @param titulo componente de tipo {@code String}.\n  * @param vigencia componente de tipo {@code LocalDate}.\n  * @param roles componente de tipo {@code List<String>}.\n  * @param cuerpo componente de tipo {@code String}.\n */\npublic record Politica(String id, String titulo, LocalDate vigencia, List<String> roles, String cuerpo) {\n\n    private static final String SEPARADOR = \"---\";\n\n    public Politica {\n        if (id == null || id.isBlank()) {\n            throw new IllegalArgumentException(\"La política necesita un identificador\");\n        }\n        // Sin roles nadie podría consultarla: se rechaza al ingerir en lugar de dejarla inaccesible en silencio\n        roles = List.copyOf(roles);\n        if (roles.isEmpty()) {\n            throw new IllegalArgumentException(\"La política \" + id + \" no tiene roles\");\n        }\n    }\n\n    /** Crea una política a partir de su archivo. El archivo debe empezar con el bloque de metadatos (front matter); si no, lanza una excepción. */\n    public static Politica desde(String id, String contenido) {\n        String[] lineas = contenido.split(\"\\\\R\");\n        if (lineas.length == 0 || !SEPARADOR.equals(lineas[0].trim())) {\n            throw new IllegalArgumentException(\"La política \" + id + \" no tiene front matter\");\n        }\n        int fin = -1;\n        for (int i = 1; i < lineas.length; i++) {\n            if (SEPARADOR.equals(lineas[i].trim())) {\n                fin = i;\n                break;\n            }\n        }\n        if (fin < 0) {\n            throw new IllegalArgumentException(\"El front matter de \" + id + \" no cierra\");\n        }\n        Map<String, String> meta = new HashMap<>();\n        for (int i = 1; i < fin; i++) {\n            String linea = lineas[i];\n            int dosPuntos = linea.indexOf(':');\n            if (dosPuntos > 0) {\n                meta.put(linea.substring(0, dosPuntos).trim(), linea.substring(dosPuntos + 1).trim());\n            }\n        }\n        String titulo = requerido(id, meta, \"titulo\");\n        LocalDate vigencia = LocalDate.parse(requerido(id, meta, \"vigencia\"));\n        List<String> roles = Arrays.stream(requerido(id, meta, \"roles\").replaceAll(\"[\\\\[\\\\]]\", \"\").split(\",\"))\n                .map(r -> r.trim().toUpperCase(Locale.ROOT))\n                .filter(r -> !r.isEmpty())\n                .toList();\n        String cuerpo = String.join(\"\\n\", Arrays.copyOfRange(lineas, fin + 1, lineas.length));\n        return new Politica(id, titulo, vigencia, roles, cuerpo);\n    }\n\n    /** Devuelve un metadato obligatorio. Si falta o está vacío, lanza una excepción que indica la política y el campo. */\n    private static String requerido(String id, Map<String, String> meta, String clave) {\n        String valor = meta.get(clave);\n        if (valor == null || valor.isBlank()) {\n            throw new IllegalArgumentException(\"La política \" + id + \" no define \" + clave);\n        }\n        return valor;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/PolizaSugerida.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.math.BigDecimal;\nimport java.util.List;\n\n/**\n * Lo que propone el modelo. Todavía no es una póliza: nadie la ha registrado.\n *\n * @param tipo componente de tipo {@code String}.\n * @param lineas componente de tipo {@code List<LineaSugerida>}.\n * @param confianza componente de tipo {@code double}.\n * @param motivo componente de tipo {@code String}.\n */\npublic record PolizaSugerida(String tipo, List<LineaSugerida> lineas, double confianza, String motivo) {\n\n    /**\n     * Línea sugerida de una póliza: código de cuenta, cargo y abono.\n     *\n     * @param codigoCuenta componente de tipo {@code String}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    public record LineaSugerida(String codigoCuenta, BigDecimal cargo, BigDecimal abono) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/PreguntaAsistente.java": "package com.mx.josesaid.develop.nexus.application;\n\n/**\n * Pregunta de un usuario autenticado. El usuario se usa para medir tokens y auditar.\n *\n * @param usuario componente de tipo {@code String}.\n * @param texto componente de tipo {@code String}.\n */\npublic record PreguntaAsistente(String usuario, String texto) {\n\n    public PreguntaAsistente {\n        if (texto == null || texto.isBlank()) {\n            throw new IllegalArgumentException(\"La pregunta no puede estar vacía\");\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/PresupuestoAgotadoException.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** Se lanza cuando un presupuesto de tokens está agotado. Responde 429 en la API. */\npublic class PresupuestoAgotadoException extends RuntimeException {\n\n    /** Crea la excepción con el mensaje que se mostrará al usuario. */\n    public PresupuestoAgotadoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/PresupuestoTokens.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.atomic.AtomicLong;\nimport java.util.concurrent.atomic.AtomicReference;\n\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\n\nimport io.micrometer.core.instrument.Gauge;\nimport io.micrometer.core.instrument.MeterRegistry;\n\n/**\n * Topes de tokens: por usuario (diario y mensual) y por servicio (mensual).\n * Se revisan antes de llamar al modelo: si un tope se alcanzó, Nexus no gasta tokens en esa consulta.\n * Los días y meses se cuentan en la hora de Ciudad de México.\n *\n * Observabilidad: métricas Prometheus (bloqueos por ámbito, consumo mensual del servicio y su límite),\n * un aviso en log al cruzar el 80% del tope de servicio y un error en log cada vez que se bloquea.\n */\npublic final class PresupuestoTokens {\n\n    static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n    static final double UMBRAL_AVISO = 0.8;\n\n    private static final Logger log = LoggerFactory.getLogger(PresupuestoTokens.class);\n\n    private final ConsumoTokens consumo;\n    private final long tokensMensuales;\n    private final long tokensDiarios;\n    private final long tokensServicioMensuales;\n    private final Clock reloj;\n    private final MeterRegistry registro;\n    private final AtomicLong consumoServicioMes = new AtomicLong();\n    private final AtomicReference<YearMonth> avisoEmitido = new AtomicReference<>();\n\n    /** Recibe los límites de tokens mensual, diario y del servicio, el reloj y el registro de métricas. */\n    public PresupuestoTokens(ConsumoTokens consumo, long tokensMensuales, long tokensDiarios,\n                             long tokensServicioMensuales, Clock reloj, MeterRegistry registro) {\n        this.consumo = consumo;\n        this.tokensMensuales = tokensMensuales;\n        this.tokensDiarios = tokensDiarios;\n        this.tokensServicioMensuales = tokensServicioMensuales;\n        this.reloj = reloj;\n        this.registro = registro;\n        Gauge.builder(\"nexus.presupuesto.servicio.consumo\", consumoServicioMes, AtomicLong::get)\n                .description(\"Tokens consumidos por nexus-ms en el mes en curso\")\n                .register(registro);\n        Gauge.builder(\"nexus.presupuesto.servicio.limite\", () -> tokensServicioMensuales)\n                .description(\"Tope mensual de tokens de nexus-ms\")\n                .register(registro);\n    }\n\n    /** Lanza PresupuestoAgotadoException si el usuario o el servicio ya alcanzaron su tope. */\n    public void exigirDisponible(String usuario) {\n        LocalDate hoy = reloj.instant().atZone(ZONA).toLocalDate();\n        Instant inicioDia = hoy.atStartOfDay(ZONA).toInstant();\n        Instant inicioMes = hoy.withDayOfMonth(1).atStartOfDay(ZONA).toInstant();\n\n        if (consumo.desde(usuario, inicioDia) >= tokensDiarios) {\n            bloquear(\"usuario-diario\", usuario, \"Alcanzaste tu límite diario de tokens. \"\n                    + \"Se renueva mañana a las 00:00 (hora de Ciudad de México).\");\n        }\n        if (consumo.desde(usuario, inicioMes) >= tokensMensuales) {\n            bloquear(\"usuario-mensual\", usuario, \"Alcanzaste tu límite mensual de tokens. \"\n                    + \"Se renueva el día 1 del próximo mes.\");\n        }\n        revisarServicio(hoy, inicioMes, usuario);\n    }\n\n    /** Revisa el consumo mensual del servicio completo. Si lo supera, bloquea todas las consultas. */\n    private void revisarServicio(LocalDate hoy, Instant inicioMes, String usuario) {\n        long usado = consumo.delServicio(inicioMes);\n        consumoServicioMes.set(usado);\n        if (usado >= tokensServicioMensuales) {\n            bloquear(\"servicio\", usuario, \"Nexus alcanzó el presupuesto mensual del servicio. \"\n                    + \"Se renueva el día 1 del próximo mes; avisa al administrador si necesitas usarlo antes.\");\n        }\n        if (usado >= tokensServicioMensuales * UMBRAL_AVISO) {\n            avisarUmbral(YearMonth.from(hoy), usado);\n        }\n    }\n\n    /** Emite un aviso una sola vez al mes cuando el consumo llega al umbral de alerta. */\n    private void avisarUmbral(YearMonth mes, long usado) {\n        YearMonth previo = avisoEmitido.get();\n        if (mes.equals(previo) || !avisoEmitido.compareAndSet(previo, mes)) {\n            return;\n        }\n        registro.counter(\"nexus.presupuesto.umbral.alcanzado\").increment();\n        log.warn(\"Nexus superó el {}% de su presupuesto mensual de tokens: {} de {} en {}\",\n                (int) (UMBRAL_AVISO * 100), usado, tokensServicioMensuales, mes);\n    }\n\n    /** Registra el bloqueo en métricas y log, y lanza PresupuestoAgotadoException. */\n    private void bloquear(String ambito, String usuario, String mensaje) {\n        registro.counter(\"nexus.presupuesto.bloqueos\", \"ambito\", ambito).increment();\n        log.warn(\"Consulta bloqueada por presupuesto de tokens: ámbito={} usuario={}\", ambito, etiqueta(usuario));\n        throw new PresupuestoAgotadoException(mensaje);\n    }\n\n    /**\n     * Identificador no reversible para los logs: no se registra el correo del usuario.\n     * Mismo usuario, misma etiqueta, para poder correlacionar bloqueos sin exponer datos personales.\n     */\n    static String etiqueta(String usuario) {\n        if (usuario == null || usuario.isBlank()) {\n            return \"desconocido\";\n        }\n        try {\n            byte[] hash = MessageDigest.getInstance(\"SHA-256\")\n                    .digest(usuario.trim().toLowerCase().getBytes(StandardCharsets.UTF_8));\n            StringBuilder hex = new StringBuilder();\n            for (int i = 0; i < 6; i++) {\n                hex.append(String.format(\"%02x\", hash[i]));\n            }\n            return \"u-\" + hex;\n        } catch (NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"SHA-256 no disponible\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/RecuperadorPoliticas.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static java.util.stream.Collectors.toUnmodifiableSet;\n\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.Objects;\nimport java.util.Set;\n\n/**\n * Busca en las políticas solo lo que los roles del usuario pueden ver.\n * Sin roles no se consulta nada: el acceso se niega por defecto.\n */\npublic final class RecuperadorPoliticas {\n\n    private static final int LIMITE_MAXIMO = 10;\n\n    private final Embedder embedder;\n    private final AlmacenFragmentos almacen;\n    private final Clock reloj;\n\n    /** Recibe el generador de embeddings, el almacén de fragmentos y el reloj. */\n    public RecuperadorPoliticas(Embedder embedder, AlmacenFragmentos almacen, Clock reloj) {\n        this.embedder = embedder;\n        this.almacen = almacen;\n        this.reloj = reloj;\n    }\n\n    /** Busca las políticas más parecidas a la pregunta. Solo devuelve fragmentos de políticas que los roles del usuario pueden ver. Los roles se normalizan a mayúsculas. */\n    public List<ResultadoPolitica> buscar(String pregunta, Set<String> roles, int limite) {\n        Set<String> normalizados = roles.stream()\n                .filter(Objects::nonNull)\n                .map(r -> r.trim().toUpperCase(Locale.ROOT))\n                .filter(r -> !r.isEmpty())\n                .collect(toUnmodifiableSet());\n        if (normalizados.isEmpty()) {\n            return List.of();\n        }\n        float[] consulta = embedder.embeber(List.of(pregunta), Embedder.TipoEntrada.CONSULTA).get(0);\n        return almacen.buscar(normalizados, consulta, LocalDate.now(reloj), Math.min(Math.max(limite, 1), LIMITE_MAXIMO));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/RegistroConsulta.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.time.Instant;\n\n/**\n * Datos de una consulta para auditoría. Los textos llegan ya redactados.\n *\n * @param usuario componente de tipo {@code String}.\n * @param preguntaRedactada componente de tipo {@code String}.\n * @param respuestaResumen componente de tipo {@code String}.\n * @param herramientas componente de tipo {@code String}.\n * @param tokensEntrada componente de tipo {@code Integer}.\n * @param tokensSalida componente de tipo {@code Integer}.\n * @param creadoUtc componente de tipo {@code Instant}.\n */\npublic record RegistroConsulta(\n        String usuario,\n        String preguntaRedactada,\n        String respuestaResumen,\n        String herramientas,\n        Integer tokensEntrada,\n        Integer tokensSalida,\n        Instant creadoUtc) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/RespuestaAsistente.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.List;\n\n/**\n * Respuesta del asistente con los datos de consumo y herramientas para la auditoría.\n *\n * @param texto componente de tipo {@code String}.\n * @param tokensEntrada componente de tipo {@code Integer}.\n * @param tokensSalida componente de tipo {@code Integer}.\n * @param herramientas componente de tipo {@code List<String>}.\n */\npublic record RespuestaAsistente(String texto, Integer tokensEntrada, Integer tokensSalida, List<String> herramientas) {\n\n    public RespuestaAsistente {\n        herramientas = herramientas == null ? List.of() : List.copyOf(herramientas);\n    }\n\n    /** Respuesta sin fuentes ni herramientas usadas. Se usa para respuestas de texto simple, como el rechazo de temas fuera de la empresa. */\n    public RespuestaAsistente(String texto) {\n        this(texto, null, null, List.of());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/ResultadoPolitica.java": "package com.mx.josesaid.develop.nexus.application;\n\n/**\n * Fragmento recuperado para responder, con su fuente para poder citarla.\n *\n * @param politicaId componente de tipo {@code String}.\n * @param indice componente de tipo {@code int}.\n * @param titulo componente de tipo {@code String}.\n * @param texto componente de tipo {@code String}.\n * @param similitud componente de tipo {@code double}.\n */\npublic record ResultadoPolitica(String politicaId, int indice, String titulo, String texto, double similitud) {\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/ServicioPolizas.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.function.Function;\nimport java.util.stream.Collectors;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.CuentaCatalogo;\nimport com.mx.josesaid.develop.nexus.application.PolizaSugerida.LineaSugerida;\n\n/**\n * Sugiere una póliza y la deja PENDIENTE. Nunca la registra: el registro ocurre solo cuando\n * una persona confirma la acción con su propia sesión (EjecutorAcciones).\n */\npublic final class ServicioPolizas {\n\n    static final Set<String> TIPOS = Set.of(\"INGRESO\", \"EGRESO\", \"DIARIO\");\n\n    private final ContextoContable contexto;\n    private final SugeridorPolizas sugeridor;\n    private final AccionesPendientes acciones;\n    private final PresupuestoTokens presupuesto;\n    private final Clock reloj;\n    private final ObjectMapper json = new ObjectMapper();\n\n    /** Recibe el contexto contable, el sugeridor de pólizas, el registro de acciones, el presupuesto de tokens y el reloj con zona de México. */\n    public ServicioPolizas(ContextoContable contexto, SugeridorPolizas sugeridor, AccionesPendientes acciones,\n                           PresupuestoTokens presupuesto, Clock reloj) {\n        this.contexto = contexto;\n        this.sugeridor = sugeridor;\n        this.acciones = acciones;\n        this.presupuesto = presupuesto;\n        this.reloj = reloj;\n    }\n\n    /** Prepara una sugerencia de póliza. Verifica el presupuesto, pide la sugerencia al modelo, la valida contra el catálogo y la guarda como acción pendiente. No registra nada en contabilidad. */\n    public AccionPendiente preparar(String usuario, String descripcion) {\n        presupuesto.exigirDisponible(usuario);\n        List<CuentaCatalogo> catalogo = contexto.catalogo();\n        PolizaSugerida sugerencia = sugeridor.sugerir(usuario, descripcion, catalogo, contexto.ejemplosRecientes());\n\n        Map<String, CuentaCatalogo> porCodigo = catalogo.stream()\n                .collect(Collectors.toMap(CuentaCatalogo::codigo, Function.identity(), (a, b) -> a));\n        validar(sugerencia, porCodigo);\n\n        LocalDate fecha = LocalDate.now(reloj);\n        String payload = payload(sugerencia, porCodigo, fecha);\n        return acciones.preparar(usuario, AccionesPendientes.TIPO_POLIZA_REGISTRAR, payload,\n                resumen(sugerencia, fecha));\n    }\n\n    /** Valida que la sugerencia sea coherente: tipo permitido, cuentas que existen en el catálogo, al menos dos líneas y cargos iguales a abonos. Si algo falla, lanza SugerenciaPolizaInvalidaException. */\n    static void validar(PolizaSugerida s, Map<String, CuentaCatalogo> porCodigo) {\n        if (s == null || !TIPOS.contains(s.tipo())) {\n            throw new SugerenciaPolizaInvalidaException(\"Tipo de póliza no válido\");\n        }\n        if (Double.isNaN(s.confianza()) || s.confianza() < 0 || s.confianza() > 1) {\n            throw new SugerenciaPolizaInvalidaException(\"Nivel de confianza fuera de rango\");\n        }\n        if (s.lineas() == null || s.lineas().size() < 2) {\n            throw new SugerenciaPolizaInvalidaException(\"Una póliza necesita al menos dos movimientos\");\n        }\n        BigDecimal cargos = BigDecimal.ZERO;\n        BigDecimal abonos = BigDecimal.ZERO;\n        for (LineaSugerida l : s.lineas()) {\n            if (!porCodigo.containsKey(l.codigoCuenta())) {\n                throw new SugerenciaPolizaInvalidaException(\"La cuenta \" + l.codigoCuenta() + \" no está en el catálogo activo\");\n            }\n            if (l.cargo() == null || l.abono() == null || l.cargo().signum() < 0 || l.abono().signum() < 0) {\n                throw new SugerenciaPolizaInvalidaException(\"Montos inválidos en la cuenta \" + l.codigoCuenta());\n            }\n            if ((l.cargo().signum() > 0) == (l.abono().signum() > 0)) {\n                throw new SugerenciaPolizaInvalidaException(\"Cada movimiento debe tener solo cargo o solo abono\");\n            }\n            cargos = cargos.add(l.cargo());\n            abonos = abonos.add(l.abono());\n        }\n        if (cargos.signum() == 0 || cargos.compareTo(abonos) != 0) {\n            throw new SugerenciaPolizaInvalidaException(\"La póliza no cuadra: cargos \" + cargos + \", abonos \" + abonos);\n        }\n    }\n\n    /** Arma el payload JSON de la póliza que ejecutará la acción al confirmarse. Los cargos y abonos se envían como texto para no perder decimales. */\n    private String payload(PolizaSugerida s, Map<String, CuentaCatalogo> porCodigo, LocalDate fecha) {\n        List<Map<String, Object>> movimientos = new ArrayList<>();\n        for (LineaSugerida l : s.lineas()) {\n            Map<String, Object> m = new LinkedHashMap<>();\n            m.put(\"cuentaId\", porCodigo.get(l.codigoCuenta()).id().toString());\n            m.put(\"cargo\", l.cargo());\n            m.put(\"abono\", l.abono());\n            movimientos.add(m);\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"tipo\", s.tipo());\n        cuerpo.put(\"fecha\", fecha.toString());\n        cuerpo.put(\"movimientos\", movimientos);\n        try {\n            return json.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la póliza sugerida\", e);\n        }\n    }\n\n    /** Genera el resumen legible de la póliza que el contador ve antes de confirmar: tipo, fecha, total y cuentas afectadas. */\n    private static String resumen(PolizaSugerida s, LocalDate fecha) {\n        BigDecimal total = s.lineas().stream().map(LineaSugerida::cargo).reduce(BigDecimal.ZERO, BigDecimal::add);\n        String cuentas = s.lineas().stream()\n                .map(l -> (l.cargo().signum() > 0 ? \"cargo \" : \"abono \") + l.codigoCuenta()\n                        + \" \" + (l.cargo().signum() > 0 ? l.cargo() : l.abono()))\n                .collect(Collectors.joining(\"; \"));\n        String texto = \"Registrar póliza \" + s.tipo() + \" del \" + fecha + \" por \" + total\n                + \" (confianza \" + Math.round(s.confianza() * 100) + \"%): \" + cuentas\n                + \". \" + (s.motivo() == null ? \"\" : s.motivo());\n        return texto.length() > 900 ? texto.substring(0, 900) : texto;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/SugerenciaPolizaInvalidaException.java": "package com.mx.josesaid.develop.nexus.application;\n\n/** La sugerencia no cuadra, usa cuentas fuera del catálogo o no es utilizable. No se prepara ninguna acción. */\npublic class SugerenciaPolizaInvalidaException extends RuntimeException {\n\n    /** Crea la excepción con el motivo de la sugerencia rechazada. */\n    public SugerenciaPolizaInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/SugeridorPolizas.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.util.List;\n\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.CuentaCatalogo;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.PolizaEjemplo;\n\n/** Propone una póliza a partir de una descripción, con pólizas históricas como referencia. */\npublic interface SugeridorPolizas {\n\n    /** Pide al modelo una sugerencia de póliza a partir de la descripción. Recibe el catálogo de cuentas y ejemplos recientes para que use cuentas existentes. */\n    PolizaSugerida sugerir(String usuario, String descripcion, List<CuentaCatalogo> catalogo,\n                           List<PolizaEjemplo> ejemplos);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/TemasEmpresa.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport java.text.Normalizer;\nimport java.util.Locale;\nimport java.util.regex.Pattern;\n\n/**\n * Filtro previo al modelo: solo deja pasar preguntas sobre EMPRESA_JOSESAID.\n * Las preguntas ajenas se rechazan sin llamar a Claude, así que no hay consumo de tokens.\n */\npublic final class TemasEmpresa {\n\n    public static final String RECHAZO = \"Solo puedo ayudarte con consultas de EMPRESA_JOSESAID, \"\n            + \"por ejemplo: \\\"¿Cuántas existencias hay del SKU-001?\\\" o \\\"¿Qué comprobantes siguen pendientes de cobro?\\\".\";\n\n    /** Palabras clave de los temas de la empresa: clientes, pedidos, compras, inventario, contabilidad, etc. Una pregunta que no contiene ninguna se rechaza antes de llamar al modelo. */\n    private static final Pattern TEMAS = Pattern.compile(\n            \"\\\\b(clientes?|rfc|usuarios?|accesos?|roles?|factur\\\\w*|comprobantes?|cobros?|cobr\\\\w*|pagos?|pagar\"\n            + \"|cuentas?|saldos?|cartera|polizas?|contab\\\\w*|periodos?|compras?|ordenes?|proveedor\\\\w*|pedidos?\"\n            + \"|ventas?|cotizaci\\\\w*|inventario\\\\w*|existencias?|sku\\\\w*|almacen\\\\w*|insumos?|documentos?\"\n            + \"|contratos?|cumplimiento|reportes?|indicadores?|politicas?|empresa|emitid\\\\w*|pendientes?\"\n            + \"|aprob\\\\w*|cancel\\\\w*|reversas?)\\\\b\");\n\n    /** Saludos y ayuda, solo cuando son el mensaje completo. */\n    private static final Pattern SALUDO = Pattern.compile(\n            \"^[\\\\s!¡?¿.,]*(hola|buenos dias|buenas tardes|buenas noches|ayuda|que puedes hacer)[\\\\s!¡?¿.,]*$\");\n\n    /** Un identificador UUID es dato de inventario: se deja pasar aunque la frase no tenga tema. */\n    private static final Pattern UUID = Pattern.compile(\n            \"\\\\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\\\\b\");\n\n    /** Clase de utilidad: no se instancia. */\n    private TemasEmpresa() {\n    }\n\n    /** Indica si el texto habla de un tema de la empresa, buscando las palabras clave sin distinguir mayúsculas. */\n    public static boolean esDeEmpresa(String texto) {\n        if (texto == null || texto.isBlank()) {\n            return false;\n        }\n        String normalizado = Normalizer.normalize(texto, Normalizer.Form.NFD)\n                .replaceAll(\"\\\\p{M}\", \"\")\n                .toLowerCase(Locale.ROOT)\n                .trim();\n        return SALUDO.matcher(normalizado).matches()\n                || TEMAS.matcher(normalizado).find()\n                || UUID.matcher(normalizado).find();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/application/package-info.java": "/**\n * Capa \"application\" de Nexus. Ver docs/diseno.md para las reglas de dependencia entre capas.\n */\npackage com.mx.josesaid.develop.nexus.application;\n", "src/main/java/com/mx/josesaid/develop/nexus/config/McpConfig.java": "package com.mx.josesaid.develop.nexus.config;\n\nimport java.nio.charset.StandardCharsets;\nimport java.util.Arrays;\nimport java.security.SecureRandom;\nimport java.util.List;\nimport java.util.Map;\n\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.ai.support.ToolCallbacks;\nimport org.springframework.ai.tool.ToolCallback;\nimport org.springframework.beans.factory.ObjectProvider;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.web.servlet.function.ServerRequest;\nimport org.springframework.ai.mcp.server.webmvc.transport.WebMvcStreamableServerTransportProvider;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport com.mx.josesaid.develop.nexus.application.ServicioPolizas;\nimport com.mx.josesaid.develop.nexus.infrastructure.AutorizacionMcpCallback;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasAccionesMcp;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasContabilidad;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasPoliticas;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasPolizas;\n\nimport io.modelcontextprotocol.common.McpTransportContext;\nimport io.modelcontextprotocol.json.McpJsonDefaults;\n\n/**\n * Servidor MCP de Nexus (endpoint /mcp, transporte streamable). Expone lectura y preparación de acciones.\n * Cada llamada viaja con el JWT del cliente: nunca hay sesión anónima ni confirmación sin código.\n */\n@Configuration\npublic class McpConfig {\n\n    private static final Logger log = LoggerFactory.getLogger(McpConfig.class);\n\n    /** Crea el generador de códigos de confirmación. Si no hay secreto configurado usa uno aleatorio por instancia: los códigos dejan de valer al reiniciar y no se pueden confirmar entre réplicas. */\n    @Bean\n    CodigoConfirmacion codigoConfirmacion(@Value(\"${nexus.mcp.confirmacion-secreto:}\") String secreto) {\n        if (secreto == null || secreto.isBlank()) {\n            // Sin secreto configurado, los códigos solo sirven dentro de esta instancia y tras reiniciar dejan de valer.\n            log.warn(\"NEXUS_CONFIRMACION_SECRETO no está definido; se usa un secreto aleatorio por instancia\");\n            byte[] aleatorio = new byte[32];\n            new SecureRandom().nextBytes(aleatorio);\n            return new CodigoConfirmacion(aleatorio);\n        }\n        return new CodigoConfirmacion(secreto.getBytes(StandardCharsets.UTF_8));\n    }\n\n    /** Crea el servicio de confirmación de acciones con código. */\n    @Bean\n    ConfirmacionAcciones confirmacionAcciones(AccionesPendientes acciones, CodigoConfirmacion codigos) {\n        return new ConfirmacionAcciones(acciones, codigos);\n    }\n\n    /** Crea las herramientas MCP de pólizas. Usa un proveedor perezoso porque el servicio de pólizas puede no existir en todos los perfiles. */\n    @Bean\n    HerramientasPolizas herramientasPolizas(ObjectProvider<ServicioPolizas> servicio, CodigoConfirmacion codigos) {\n        return new HerramientasPolizas(servicio::getObject, codigos);\n    }\n\n    /** Crea las herramientas MCP para confirmar y cancelar acciones. */\n    @Bean\n    HerramientasAccionesMcp herramientasAccionesMcp(ConfirmacionAcciones confirmaciones, AccionesPendientes acciones) {\n        return new HerramientasAccionesMcp(confirmaciones, acciones);\n    }\n\n    /** Herramientas que el servidor MCP publica. Cada una pasa por AutorizacionMcpCallback. */\n    @Bean\n    List<ToolCallback> herramientasMcp(HerramientasPoliticas politicas, HerramientasContabilidad contabilidad,\n                                       HerramientasPolizas polizas, HerramientasAccionesMcp acciones) {\n        return Arrays.stream(ToolCallbacks.from(politicas, contabilidad, polizas, acciones))\n                .map(AutorizacionMcpCallback::new)\n                .map(ToolCallback.class::cast)\n                .toList();\n    }\n\n    /** Crea el transporte HTTP del servidor MCP en el endpoint configurado (por defecto /mcp). */\n    @Bean\n    WebMvcStreamableServerTransportProvider webMvcStreamableServerTransportProvider(\n            @Value(\"${spring.ai.mcp.server.streamable-http.mcp-endpoint:/mcp}\") String endpoint) {\n        return WebMvcStreamableServerTransportProvider.builder()\n                .jsonMapper(McpJsonDefaults.getMapper())\n                .mcpEndpoint(endpoint)\n                .contextExtractor(McpConfig::extraerContexto)\n                .build();\n    }\n\n    /** Toma la identidad ya autenticada por Spring Security y la pasa a cada llamada de herramienta. */\n    static McpTransportContext extraerContexto(ServerRequest solicitud) {\n        return solicitud.principal()\n                .filter(Authentication.class::isInstance)\n                .map(p -> McpTransportContext.create(\n                        Map.<String, Object>of(AutorizacionMcpCallback.CLAVE_AUTENTICACION, p)))\n                .orElse(McpTransportContext.EMPTY);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/config/NexusConfig.java": "package com.mx.josesaid.develop.nexus.config;\n\nimport java.io.IOException;\nimport java.time.Clock;\nimport java.time.ZoneId;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.AlmacenFragmentos;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable;\nimport com.mx.josesaid.develop.nexus.application.ServicioPolizas;\nimport com.mx.josesaid.develop.nexus.application.SugeridorPolizas;\nimport com.mx.josesaid.develop.nexus.application.Embedder;\nimport com.mx.josesaid.develop.nexus.application.IngestaPoliticas;\nimport com.mx.josesaid.develop.nexus.application.RecuperadorPoliticas;\nimport com.mx.josesaid.develop.nexus.infrastructure.ClaudeSugeridorPolizas;\nimport com.mx.josesaid.develop.nexus.infrastructure.ContextoContableGateway;\nimport com.mx.josesaid.develop.nexus.infrastructure.EjecutorAccionesGateway;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasPoliticas;\nimport com.mx.josesaid.develop.nexus.infrastructure.PoliticasClasspath;\nimport com.mx.josesaid.develop.nexus.infrastructure.VoyageEmbedder;\nimport com.mx.josesaid.develop.nexus.infrastructure.persistence.AlmacenFragmentosJdbc;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.ai.chat.model.ChatModel;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.transaction.PlatformTransactionManager;\nimport org.springframework.transaction.support.TransactionTemplate;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.ConsumoTokens;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoTokens;\nimport com.mx.josesaid.develop.nexus.comun.prompts.RepositorioPrompts;\nimport com.mx.josesaid.develop.nexus.comun.tokens.PreciosTokens;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokens;\nimport com.mx.josesaid.develop.nexus.infrastructure.ClaudeAsistenteIA;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasClientes;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasCompras;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasFinanzas;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasContabilidad;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasInventario;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasDocumentos;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasUsuarios;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasVentas;\nimport com.mx.josesaid.develop.nexus.infrastructure.HerramientasReportes;\n\nimport io.micrometer.core.instrument.MeterRegistry;\n\n/** Configuración de Nexus: crea los beans de prompts, RAG, presupuesto, herramientas del asistente y servicio de pólizas. */\n@Configuration\npublic class NexusConfig {\n\n    private static final Logger log = LoggerFactory.getLogger(NexusConfig.class);\n\n    /** Repositorio de prompts versionados, leído de los recursos de nexus-comun. */\n    @Bean\n    RepositorioPrompts repositorioPrompts() {\n        return new RepositorioPrompts();\n    }\n\n    /** Cliente de embeddings de Voyage. La URL, la clave y el modelo se configuran por entorno. */\n    @Bean\n    Embedder embedder(@Value(\"${nexus.rag.voyage.url:https://api.voyageai.com}\") String url,\n                      @Value(\"${nexus.rag.voyage.api-key:}\") String clave,\n                      @Value(\"${nexus.rag.voyage.modelo:voyage-3}\") String modelo) {\n        return new VoyageEmbedder(RestClient.builder().baseUrl(url).build(), clave, modelo);\n    }\n\n    /** Almacén de fragmentos de políticas en PostgreSQL. Las escrituras van dentro de una transacción. */\n    @Bean\n    AlmacenFragmentos almacenFragmentos(JdbcTemplate jdbc, PlatformTransactionManager transacciones) {\n        return new AlmacenFragmentosJdbc(jdbc, new TransactionTemplate(transacciones));\n    }\n\n    /** Servicio que indexa las políticas para la búsqueda. */\n    @Bean\n    IngestaPoliticas ingestaPoliticas(Embedder embedder, AlmacenFragmentos almacen) {\n        return new IngestaPoliticas(embedder, almacen);\n    }\n\n    /** Servicio que busca políticas vigentes. Usa hora de México para que una política aplique desde su fecha local. */\n    @Bean\n    RecuperadorPoliticas recuperadorPoliticas(Embedder embedder, AlmacenFragmentos almacen) {\n        // Vigencia en hora de México: una política que entra en vigor el 1 de noviembre aplica desde esa fecha local\n        return new RecuperadorPoliticas(embedder, almacen, Clock.system(ZoneId.of(\"America/Mexico_City\")));\n    }\n\n    /** Indexa las políticas al arrancar. Si falta la clave o Voyage falla, el servicio arranca igual y lo registra. */\n    @Bean\n    ApplicationRunner ingestaPoliticasAlArrancar(IngestaPoliticas ingesta,\n                                                 @Value(\"${nexus.rag.ingesta-al-arrancar:true}\") boolean activa,\n                                                 @Value(\"${nexus.rag.voyage.api-key:}\") String clave) {\n        return args -> {\n            if (!activa) {\n                return;\n            }\n            if (clave.isBlank()) {\n                log.warn(\"Ingesta de políticas omitida: falta VOYAGE_API_KEY\");\n                return;\n            }\n            try {\n                int fragmentos = ingesta.ingerir(PoliticasClasspath.cargar());\n                log.info(\"Políticas indexadas: {} fragmentos\", fragmentos);\n            } catch (IOException | RuntimeException e) {\n                log.error(\"Falló la ingesta de políticas; Nexus arranca sin RAG de políticas\", e);\n            }\n        };\n    }\n\n    /** Control de presupuesto de tokens. Los límites mensual, diario y del servicio se configuran por entorno. */\n    @Bean\n    PresupuestoTokens presupuestoTokens(ConsumoTokens consumo, MeterRegistry registro,\n                                        @Value(\"${nexus.presupuesto.tokens-mensuales:150000}\") long mensuales,\n                                        @Value(\"${nexus.presupuesto.tokens-diarios:15000}\") long diarios,\n                                        @Value(\"${nexus.presupuesto.tokens-servicio-mensuales:1000000}\") long servicio) {\n        return new PresupuestoTokens(consumo, mensuales, diarios, servicio, Clock.systemUTC(), registro);\n    }\n\n    /** Registro de consumo de tokens. Los precios aún no están configurados, así que el costo estimado queda en cero. */\n    @Bean\n    RegistroTokens registroTokens(MeterRegistry registro) {\n        // Precios por millón de tokens: se configuran por entorno en un paso posterior.\n        return new RegistroTokens(registro, PreciosTokens.SIN_PRECIO);\n    }\n\n    /** Herramienta de reportes para el asistente, con acceso al gateway. */\n    @Bean\n    HerramientasReportes herramientasReportes(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasReportes(gatewayClient, acciones);\n    }\n\n    /** Herramienta de clientes para el asistente. */\n    @Bean\n    HerramientasClientes herramientasClientes(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasClientes(gatewayClient, acciones);\n    }\n\n    /** Ejecutor de acciones aprobadas, que las envía al gateway con la hora de UTC. */\n    @Bean\n    AccionesPendientes accionesPendientes(AlmacenAcciones almacen, RestClient gatewayClient) {\n        return new AccionesPendientes(almacen, new EjecutorAccionesGateway(gatewayClient), Clock.systemUTC());\n    }\n\n    /** Herramienta de ventas para el asistente. */\n    @Bean\n    HerramientasVentas herramientasVentas(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasVentas(gatewayClient, acciones);\n    }\n\n    /** Herramienta de compras para el asistente. */\n    @Bean\n    HerramientasCompras herramientasCompras(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasCompras(gatewayClient, acciones);\n    }\n\n    /** Herramienta de finanzas para el asistente. */\n    @Bean\n    HerramientasFinanzas herramientasFinanzas(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasFinanzas(gatewayClient, acciones);\n    }\n\n    /** Herramienta de contabilidad. Solo lectura, por eso no recibe el registro de acciones. */\n    @Bean\n    HerramientasContabilidad herramientasContabilidad(RestClient gatewayClient) {\n        return new HerramientasContabilidad(gatewayClient);\n    }\n\n    /** Herramienta de inventario para el asistente. */\n    @Bean\n    HerramientasInventario herramientasInventario(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasInventario(gatewayClient, acciones);\n    }\n\n    /** Herramienta de documentos para el asistente. */\n    @Bean\n    HerramientasDocumentos herramientasDocumentos(RestClient gatewayClient, AccionesPendientes acciones) {\n        return new HerramientasDocumentos(gatewayClient, acciones);\n    }\n\n    /** Herramienta de usuarios. Recibe el generador de códigos porque las altas usan confirmación. */\n    @Bean\n    HerramientasUsuarios herramientasUsuarios(RestClient gatewayClient, AccionesPendientes acciones,\n                                              CodigoConfirmacion codigos) {\n        return new HerramientasUsuarios(gatewayClient, acciones, codigos);\n    }\n\n    /** Asistente principal con todas sus herramientas y el modelo de Claude. */\n    @Bean\n    AsistenteIA asistenteIA(ChatModel modelo, RegistroTokens registro, RepositorioPrompts prompts,\n                            HerramientasReportes reportes, HerramientasClientes clientes,\n                            HerramientasVentas ventas, HerramientasCompras compras,\n                            HerramientasFinanzas finanzas, HerramientasContabilidad contabilidad,\n                            HerramientasInventario inventario, HerramientasDocumentos documentos,\n                            HerramientasUsuarios usuarios, HerramientasPoliticas politicas) {\n        return new ClaudeAsistenteIA(modelo, registro, prompts, reportes, clientes, ventas, compras, finanzas,\n                contabilidad, inventario, documentos, usuarios, politicas);\n    }\n\n    /** Herramienta que consulta las políticas de la empresa. */\n    @Bean\n    HerramientasPoliticas herramientasPoliticas(RecuperadorPoliticas recuperador) {\n        return new HerramientasPoliticas(recuperador);\n    }\n\n    /** Contexto contable (catálogo y ejemplos) leído del gateway, con la zona de México. */\n    @Bean\n    ContextoContable contextoContable(RestClient gatewayClient) {\n        return new ContextoContableGateway(gatewayClient, ZoneId.of(\"America/Mexico_City\"));\n    }\n\n    /** Sugeridor de pólizas basado en el modelo de Claude. */\n    @Bean\n    SugeridorPolizas sugeridorPolizas(ChatModel modelo, RegistroTokens registro) {\n        return new ClaudeSugeridorPolizas(modelo, registro);\n    }\n\n    /** Servicio de pólizas con el reloj de México. */\n    @Bean\n    ServicioPolizas servicioPolizas(ContextoContable contexto, SugeridorPolizas sugeridor,\n                                    AccionesPendientes acciones, PresupuestoTokens presupuesto) {\n        return new ServicioPolizas(contexto, sugeridor, acciones, presupuesto,\n                Clock.system(ZoneId.of(\"America/Mexico_City\")));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/config/PropagacionTokenConfig.java": "package com.mx.josesaid.develop.nexus.config;\n\nimport org.springframework.beans.factory.ObjectProvider;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.boot.http.client.ClientHttpRequestFactoryBuilder;\nimport org.springframework.boot.http.client.HttpClientSettings;\nimport org.springframework.boot.ssl.SslBundle;\nimport org.springframework.boot.ssl.SslBundles;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.web.client.RestClient;\n\n/**\n * Cliente hacia gateway-ms que reenvía el token del usuario que pregunta.\n * Así cada servicio aplica sus propios permisos: Nexus no tiene credenciales propias.\n */\n@Configuration\npublic class PropagacionTokenConfig {\n\n    /**\n     * Si nexus.gateway.tls-bundle tiene un nombre, usa ese bundle SSL (CA interna) para el gateway por HTTPS.\n     */\n    @Bean\n    RestClient gatewayClient(@Value(\"${nexus.gateway.url}\") String url,\n            @Value(\"${nexus.gateway.tls-bundle:}\") String bundle,\n            ObjectProvider<SslBundles> bundles) {\n        RestClient.Builder builder = RestClient.builder();\n        if (!bundle.isBlank()) {\n            SslBundle ssl = bundles.getObject().getBundle(bundle);\n            builder.requestFactory(ClientHttpRequestFactoryBuilder.detect()\n                    .build(HttpClientSettings.ofSslBundle(ssl)));\n        }\n        return builder\n                .baseUrl(url)\n                .requestInterceptor((request, body, ejecucion) -> {\n                    var autenticacion = SecurityContextHolder.getContext().getAuthentication();\n                    if (autenticacion instanceof JwtAuthenticationToken jwt) {\n                        request.getHeaders().setBearerAuth(jwt.getToken().getTokenValue());\n                    }\n                    return ejecucion.execute(request, body);\n                })\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/config/SeguridadConfig.java": "package com.mx.josesaid.develop.nexus.config;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad de nexus-ms. Los roles vienen en el claim \"roles\" del JWT de usuarios-accesos-ms\n * y se convierten en autoridades ROLE_*, igual que en los demás servicios.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad: exige JWT válido en todas las rutas, salvo las públicas de salud. Los roles del token se leen de la claim roles con el prefijo ROLE_. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n\n        return http\n                .csrf(csrf -> csrf.disable())\n                .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n                .authorizeHttpRequests(auth -> auth\n                        .requestMatchers(\"/actuator/health/**\", \"/actuator/info\", \"/actuator/prometheus\", \"/error\").permitAll()\n                        .requestMatchers(\"/nexus/**\", \"/mcp\", \"/mcp/**\").authenticated()\n                        .anyRequest().denyAll())\n                .oauth2ResourceServer(oauth -> oauth.jwt(jwt -> jwt.jwtAuthenticationConverter(convertidor)))\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/config/package-info.java": "/**\n * Capa \"config\" de Nexus. Ver docs/diseno.md para las reglas de dependencia entre capas.\n */\npackage com.mx.josesaid.develop.nexus.config;\n", "src/main/java/com/mx/josesaid/develop/nexus/domain/package-info.java": "/**\n * Capa \"domain\" de Nexus. Ver docs/diseno.md para las reglas de dependencia entre capas.\n */\npackage com.mx.josesaid.develop.nexus.domain;\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/AlcanceHerramientas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static java.util.stream.Collectors.toUnmodifiableSet;\n\nimport java.util.Map;\nimport java.util.Set;\n\nimport org.springframework.security.core.Authentication;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\n/**\n * Decide qué herramientas se ofrecen al modelo según los roles del usuario que pregunta.\n * Si el usuario no tiene el rol, la herramienta no se ofrece: el modelo no puede pedirla.\n * Cada servicio vuelve a validar el rol con el mismo token.\n */\nfinal class AlcanceHerramientas {\n\n    private static final Set<String> ROLES_REPORTES = Set.of(\"ROLE_DIRECCION\");\n    private static final Set<String> ROLES_CLIENTES = Set.of(\"ROLE_VENTAS\", \"ROLE_ADMIN\");\n    private static final Set<String> ROLES_PEDIDOS = Set.of(\"ROLE_VENTAS\", \"ROLE_DIRECCION\");\n    private static final Set<String> ROLES_COTIZACION = Set.of(\"ROLE_VENTAS\", \"ROLE_DIRECCION\", \"ROLE_FINANZAS\");\n    /** Roles que pueden ver el detalle de un pedido. */\n    private static final Set<String> ROLES_PEDIDO_DETALLE = Set.of(\"ROLE_VENTAS\", \"ROLE_DIRECCION\",\n            \"ROLE_FINANZAS\", \"ROLE_ALMACEN\");\n    // Catálogos que cualquier usuario autenticado puede leer.\n    /** Catálogos que cualquier usuario autenticado puede leer. */\n    private static final Set<String> ROLES_TODOS = Set.of(\"ROLE_ADMIN\", \"ROLE_FINANZAS\", \"ROLE_CONTADOR\",\n            \"ROLE_VENTAS\", \"ROLE_COMPRAS\", \"ROLE_ALMACEN\", \"ROLE_OPERACIONES\", \"ROLE_CALIDAD\", \"ROLE_DIRECCION\",\n            \"ROLE_LEGAL\", \"ROLE_JEFE_AREA\");\n    private static final Set<String> ROLES_PREPARAR_PEDIDO = Set.of(\"ROLE_VENTAS\");\n    private static final Set<String> ROLES_ADMIN = Set.of(\"ROLE_ADMIN\");\n    private static final Set<String> ROLES_VENTAS_CLIENTES = Set.of(\"ROLE_VENTAS\");\n    private static final Set<String> ROLES_COMPRAS = Set.of(\"ROLE_COMPRAS\");\n    private static final Set<String> ROLES_ALMACEN = Set.of(\"ROLE_ALMACEN\");\n    private static final Set<String> ROLES_OPERACIONES = Set.of(\"ROLE_OPERACIONES\");\n    private static final Set<String> ROLES_FINANZAS = Set.of(\"ROLE_FINANZAS\");\n    private static final Set<String> ROLES_ACCIONES_VENTAS = Set.of(\"ROLE_VENTAS\");\n    private static final Set<String> ROLES_USUARIOS = Set.of(\"ROLE_ADMIN\");\n    private static final Set<String> ROLES_RESUMEN_VENTAS = Set.of(\"ROLE_DIRECCION\", \"ROLE_FINANZAS\");\n    private static final Set<String> ROLES_DOCUMENTOS = Set.of(\"ROLE_LEGAL\", \"ROLE_DIRECCION\");\n    private static final Set<String> ROLES_ELIMINAR_DOCUMENTO = Set.of(\"ROLE_LEGAL\");\n    /** Roles que pueden consultar existencias. */\n    private static final Set<String> ROLES_EXISTENCIAS = Set.of(\"ROLE_ALMACEN\", \"ROLE_COMPRAS\", \"ROLE_VENTAS\",\n            \"ROLE_ADMIN\");\n    private static final Set<String> ROLES_TRAZABILIDAD = Set.of(\"ROLE_OPERACIONES\", \"ROLE_CALIDAD\");\n    private static final Set<String> ROLES_MOVIMIENTOS = Set.of(\"ROLE_ALMACEN\", \"ROLE_COMPRAS\");\n    private static final Set<String> ROLES_BAJO_MINIMO = Set.of(\"ROLE_ALMACEN\", \"ROLE_COMPRAS\");\n    private static final Set<String> ROLES_CONTABILIDAD = Set.of(\"ROLE_CONTADOR\", \"ROLE_DIRECCION\");\n    private static final Set<String> ROLES_COMPROBANTES = Set.of(\"ROLE_FINANZAS\", \"ROLE_VENTAS\");\n    private static final Set<String> ROLES_PROVEEDORES = Set.of(\"ROLE_COMPRAS\", \"ROLE_FINANZAS\");\n    private static final Set<String> ROLES_PAGOS_PROVEEDOR = Set.of(\"ROLE_FINANZAS\");\n    private static final Set<String> ROLES_ORDENES_COMPRA = Set.of(\"ROLE_COMPRAS\", \"ROLE_ALMACEN\", \"ROLE_DIRECCION\");\n    // Roles que aparecen en alguna política. Un rol nuevo debe agregarse aquí y en la política correspondiente.\n    private static final Set<String> ROLES_POLITICAS = Set.of(\"ROLE_COMPRAS\", \"ROLE_DIRECCION\");\n    // Acciones por MCP: quien las prepara debe tener uno de estos roles y además presentar el código.\n    private static final Set<String> ROLES_ACCIONES_MCP = Set.of(\"ROLE_CONTADOR\", \"ROLE_VENTAS\");\n    private static final Set<String> ROLES_CONSULTA_ACCION = Set.of(\"ROLE_CONTADOR\", \"ROLE_VENTAS\", \"ROLE_ADMIN\");\n    private static final Set<String> ROLES_ENTREGA_PEDIDO = Set.of(\"ROLE_ALMACEN\", \"ROLE_DIRECCION\");\n\n    /** Rol(es) que pueden usar cada herramienta. Lo que no aparece aquí se niega. */\n    private static final Map<String, Set<String>> ROLES_POR_HERRAMIENTA = Map.ofEntries(\n            Map.entry(\"buscar_clientes\", ROLES_CLIENTES),\n            Map.entry(\"obtener_cliente\", ROLES_CLIENTES),\n            Map.entry(\"consultar_indicadores\", ROLES_REPORTES),\n            Map.entry(\"consultar_reporte\", ROLES_REPORTES),\n            Map.entry(\"consultar_pedidos\", ROLES_PEDIDOS),\n            Map.entry(\"obtener_cotizacion\", ROLES_COTIZACION),\n            Map.entry(\"obtener_pedido\", ROLES_PEDIDO_DETALLE),\n            Map.entry(\"consultar_tasas_iva\", ROLES_TODOS),\n            Map.entry(\"consultar_monedas\", ROLES_TODOS),\n            Map.entry(\"consultar_interacciones_cliente\", ROLES_VENTAS_CLIENTES),\n            Map.entry(\"obtener_prospecto\", ROLES_VENTAS_CLIENTES),\n            Map.entry(\"consultar_metricas_conversion\", ROLES_VENTAS_CLIENTES),\n            Map.entry(\"crear_cliente\", ROLES_ADMIN),\n            Map.entry(\"actualizar_cliente\", ROLES_ADMIN),\n            Map.entry(\"agregar_contacto_cliente\", ROLES_ADMIN),\n            Map.entry(\"crear_proveedor\", ROLES_COMPRAS),\n            Map.entry(\"crear_orden_compra\", ROLES_COMPRAS),\n            Map.entry(\"registrar_recepcion_orden\", ROLES_ALMACEN),\n            Map.entry(\"cancelar_orden_compra\", ROLES_COMPRAS),\n            Map.entry(\"crear_articulo\", ROLES_OPERACIONES),\n            Map.entry(\"registrar_movimiento_inventario\", ROLES_ALMACEN),\n            Map.entry(\"crear_orden_operacion\", ROLES_OPERACIONES),\n            Map.entry(\"consultar_cuenta_por_pagar\", ROLES_FINANZAS),\n            Map.entry(\"registrar_pago_comprobante\", ROLES_FINANZAS),\n            Map.entry(\"resumen_ventas\", ROLES_RESUMEN_VENTAS),\n            Map.entry(\"consultar_proveedor\", ROLES_PROVEEDORES),\n            Map.entry(\"consultar_orden_compra\", ROLES_ORDENES_COMPRA),\n            Map.entry(\"listar_ordenes_compra\", ROLES_ORDENES_COMPRA),\n            Map.entry(\"consultar_comprobante\", ROLES_COMPROBANTES),\n            Map.entry(\"listar_comprobantes_pendientes_cobro\", ROLES_COMPROBANTES),\n            Map.entry(\"listar_pagos_proveedor\", ROLES_PAGOS_PROVEEDOR),\n            Map.entry(\"consultar_poliza\", ROLES_CONTABILIDAD),\n            Map.entry(\"consultar_estados_financieros\", ROLES_CONTABILIDAD),\n            Map.entry(\"consultar_existencias\", ROLES_EXISTENCIAS),\n            Map.entry(\"listar_movimientos_articulo\", ROLES_MOVIMIENTOS),\n            Map.entry(\"listar_articulos_bajo_minimo\", ROLES_BAJO_MINIMO),\n            Map.entry(\"consultar_trazabilidad_lote\", ROLES_TRAZABILIDAD),\n            Map.entry(\"consultar_documento\", ROLES_DOCUMENTOS),\n            Map.entry(\"consultar_documentos_por_vencer\", ROLES_DOCUMENTOS),\n            Map.entry(\"buscar_documentos\", ROLES_DOCUMENTOS),\n            Map.entry(\"solicitar_eliminacion_documento\", ROLES_ELIMINAR_DOCUMENTO),\n            Map.entry(\"consultar_tipos_documento\", ROLES_TODOS),\n            Map.entry(\"consultar_usuario\", ROLES_USUARIOS),\n            Map.entry(\"preparar_alta_usuario\", ROLES_USUARIOS),\n            Map.entry(\"listar_usuarios\", ROLES_USUARIOS),\n            Map.entry(\"buscar_proveedores\", ROLES_PROVEEDORES),\n            Map.entry(\"buscar_comprobante_por_folio\", ROLES_COMPROBANTES),\n            Map.entry(\"listar_polizas\", ROLES_CONTABILIDAD),\n            Map.entry(\"consultar_catalogo_cuentas\", ROLES_CONTABILIDAD),\n            Map.entry(\"preparar_pedido_borrador\", ROLES_PREPARAR_PEDIDO),\n            Map.entry(\"crear_prospecto_borrador\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"confirmar_pedido\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"cancelar_pedido\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"enviar_cotizacion\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"aceptar_cotizacion\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"convertir_cotizacion_en_pedido\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"crear_cotizacion_borrador\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"reemplazar_lineas_pedido\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"registrar_devolucion_pedido\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"cambiar_estatus_prospecto\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"convertir_prospecto_en_cliente\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"consultar_politicas\", ROLES_POLITICAS),\n            Map.entry(\"registrar_interaccion_cliente\", ROLES_ACCIONES_VENTAS),\n            Map.entry(\"sugerir_poliza\", Set.of(\"ROLE_CONTADOR\")),\n            Map.entry(\"confirmar_accion\", ROLES_ACCIONES_MCP),\n            Map.entry(\"cancelar_accion\", ROLES_ACCIONES_MCP),\n            Map.entry(\"consultar_estado_accion\", ROLES_CONSULTA_ACCION),\n            Map.entry(\"cambiar_estatus_cliente\", ROLES_ADMIN),\n            Map.entry(\"crear_almacen\", ROLES_ALMACEN),\n            Map.entry(\"registrar_entrega_pedido\", ROLES_ENTREGA_PEDIDO),\n            Map.entry(\"registrar_indicador\", ROLES_REPORTES));\n\n    /** Clase de utilidad: no se instancia. */\n    private AlcanceHerramientas() {\n    }\n\n    /** Indica si la herramienta existe en el mapa de roles. */\n    static boolean conoce(String herramienta) {\n        return ROLES_POR_HERRAMIENTA.containsKey(herramienta);\n    }\n\n    /** Indica si el usuario actual tiene un rol que permite usar la herramienta. */\n    static boolean puedeUsar(String herramienta) {\n        Set<String> roles = ROLES_POR_HERRAMIENTA.get(herramienta);\n        return roles != null && tieneAlgunRol(roles);\n    }\n\n    /** Indica si el usuario puede consultar reportes. */\n    static boolean puedeConsultarReportes() {\n        return tieneAlgunRol(ROLES_REPORTES);\n    }\n\n    /** Indica si el usuario puede consultar clientes. */\n    static boolean puedeConsultarClientes() {\n        return tieneAlgunRol(ROLES_CLIENTES);\n    }\n\n    /** Indica si el usuario puede consultar pedidos. */\n    static boolean puedeConsultarPedidos() {\n        return tieneAlgunRol(ROLES_PEDIDOS);\n    }\n\n    /** Indica si el usuario puede consultar usuarios. */\n    static boolean puedeConsultarUsuarios() {\n        return tieneAlgunRol(ROLES_USUARIOS);\n    }\n\n    /** Indica si el usuario puede consultar documentos. */\n    static boolean puedeConsultarDocumentos() {\n        return tieneAlgunRol(ROLES_DOCUMENTOS);\n    }\n\n    /** Indica si el usuario puede consultar inventario: existencias o trazabilidad. */\n    static boolean puedeConsultarInventario() {\n        return tieneAlgunRol(ROLES_EXISTENCIAS) || tieneAlgunRol(ROLES_TRAZABILIDAD);\n    }\n\n    /** Indica si el usuario puede consultar contabilidad. */\n    static boolean puedeConsultarContabilidad() {\n        return tieneAlgunRol(ROLES_CONTABILIDAD);\n    }\n\n    /** Indica si el usuario puede consultar comprobantes. */\n    static boolean puedeConsultarComprobantes() {\n        return tieneAlgunRol(ROLES_COMPROBANTES);\n    }\n\n    /** Indica si el usuario puede consultar proveedores. */\n    static boolean puedeConsultarProveedores() {\n        return tieneAlgunRol(ROLES_PROVEEDORES);\n    }\n\n    /** Indica si el usuario puede consultar órdenes de compra. */\n    static boolean puedeConsultarOrdenesCompra() {\n        return tieneAlgunRol(ROLES_ORDENES_COMPRA);\n    }\n\n    /** Roles del usuario actual sin el prefijo ROLE_, como los guarda la política. */\n    static Set<String> rolesDelUsuario() {\n        Authentication autenticacion = SecurityContextHolder.getContext().getAuthentication();\n        if (autenticacion == null) {\n            return Set.of();\n        }\n        return autenticacion.getAuthorities().stream()\n                .map(GrantedAuthority::getAuthority)\n                .filter(r -> r.startsWith(\"ROLE_\"))\n                .map(r -> r.substring(\"ROLE_\".length()))\n                .collect(toUnmodifiableSet());\n    }\n\n    /** Indica si el usuario actual tiene alguno de los roles indicados. Sin autenticación, responde que no. */\n    private static boolean tieneAlgunRol(Set<String> roles) {\n        Authentication autenticacion = SecurityContextHolder.getContext().getAuthentication();\n        if (autenticacion == null) {\n            return false;\n        }\n        return autenticacion.getAuthorities().stream()\n                .map(a -> a.getAuthority())\n                .anyMatch(roles::contains);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/AutorizacionMcpCallback.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.Map;\nimport java.util.Optional;\n\nimport org.springframework.ai.chat.model.ToolContext;\nimport org.springframework.ai.tool.ToolCallback;\nimport org.springframework.ai.tool.definition.ToolDefinition;\nimport org.springframework.ai.tool.metadata.ToolMetadata;\nimport org.springframework.ai.mcp.McpToolUtils;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.security.core.context.SecurityContext;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\n/**\n * Envuelve una herramienta expuesta por MCP. Restaura en el hilo de la llamada la identidad que\n * llegó con el token del cliente, aplica el mapa de roles y, al terminar, devuelve el contexto anterior.\n * Sin identidad o sin rol, la herramienta no se ejecuta.\n */\npublic final class AutorizacionMcpCallback implements ToolCallback {\n\n    public static final String CLAVE_AUTENTICACION = \"nexus.autenticacion\";\n    static final String DENEGADO = \"Sin permiso para usar esta herramienta con tu rol o sesión actual.\";\n\n    private final ToolCallback delegado;\n\n    /** Envuelve una herramienta MCP para revisar la autorización antes de ejecutarla. */\n    public AutorizacionMcpCallback(ToolCallback delegado) {\n        this.delegado = delegado;\n    }\n\n    /** Devuelve la definición de la herramienta original. */\n    @Override\n    public ToolDefinition getToolDefinition() {\n        return delegado.getToolDefinition();\n    }\n\n    /** Devuelve los metadatos de la herramienta original. */\n    @Override\n    public ToolMetadata getToolMetadata() {\n        return delegado.getToolMetadata();\n    }\n\n    /** Ejecuta la herramienta sin contexto de seguridad. Por diseño, se rechaza si no hay identidad. */\n    @Override\n    public String call(String toolInput) {\n        return call(toolInput, null);\n    }\n\n    /** Ejecuta la herramienta solo si el usuario de la sesión puede usarla. Si no, devuelve un error para el modelo en lugar de ejecutarla. */\n    @Override\n    public String call(String toolInput, ToolContext toolContext) {\n        String nombre = delegado.getToolDefinition().name();\n        Optional<Authentication> autenticacion = identidad(toolContext);\n        if (autenticacion.isEmpty()) {\n            throw new SinPermisoMcpException(DENEGADO);\n        }\n        SecurityContext anterior = SecurityContextHolder.getContext();\n        SecurityContext durante = SecurityContextHolder.createEmptyContext();\n        durante.setAuthentication(autenticacion.get());\n        SecurityContextHolder.setContext(durante);\n        try {\n            if (!AlcanceHerramientas.puedeUsar(nombre)) {\n                throw new SinPermisoMcpException(DENEGADO);\n            }\n            return toolContext == null ? delegado.call(toolInput) : delegado.call(toolInput, toolContext);\n        } finally {\n            SecurityContextHolder.setContext(anterior);\n        }\n    }\n\n    /** Lanzarla hace que la respuesta MCP llegue con isError=true, no como texto de éxito. */\n    public static final class SinPermisoMcpException extends RuntimeException {\n        SinPermisoMcpException(String mensaje) {\n            super(mensaje);\n        }\n    }\n\n    /** Obtiene la identidad del usuario que hace la petición desde el contexto de la herramienta. */\n    private static Optional<Authentication> identidad(ToolContext toolContext) {\n        if (toolContext == null) {\n            return Optional.empty();\n        }\n        return McpToolUtils.getMcpExchange(toolContext)\n                .map(ex -> ex.transportContext().get(CLAVE_AUTENTICACION))\n                .filter(Authentication.class::isInstance)\n                .map(Authentication.class::cast);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/ClaudeAsistenteIA.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.Arrays;\n\nimport org.springframework.ai.chat.client.ChatClient;\nimport org.springframework.ai.chat.model.ChatModel;\nimport org.springframework.ai.chat.model.ChatResponse;\nimport org.springframework.ai.tool.ToolCallback;\nimport org.springframework.ai.support.ToolCallbacks;\n\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.PreguntaAsistente;\nimport com.mx.josesaid.develop.nexus.application.RespuestaAsistente;\nimport com.mx.josesaid.develop.nexus.application.TemasEmpresa;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensiblesAdvisor;\nimport com.mx.josesaid.develop.nexus.comun.prompts.PromptVersionado;\nimport com.mx.josesaid.develop.nexus.comun.prompts.RepositorioPrompts;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokens;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokensAdvisor;\n\n/**\n * Adaptador del puerto AsistenteIA sobre Claude, con ChatClient de Spring AI.\n * Los datos sensibles se redactan antes de llamar al modelo y el consumo se mide por llamada.\n */\npublic final class ClaudeAsistenteIA implements AsistenteIA {\n\n    static final String SERVICIO = \"nexus-ms\";\n    static final String PROMPT = \"asistente-base\";\n\n    private final ChatClient cliente;\n    private final HerramientasReportes reportes;\n    private final HerramientasClientes clientes;\n    private final HerramientasVentas ventas;\n    private final HerramientasCompras compras;\n    private final HerramientasFinanzas finanzas;\n    private final HerramientasContabilidad contabilidad;\n    private final HerramientasInventario inventario;\n    private final HerramientasDocumentos documentos;\n    private final HerramientasUsuarios usuarios;\n    private final HerramientasPoliticas politicas;\n    private final ToolCallback[] herramientas;\n\n    /** Recibe el modelo de Claude, el registro de tokens, los prompts y las herramientas de cada área del asistente. */\n    public ClaudeAsistenteIA(ChatModel modelo, RegistroTokens registro, RepositorioPrompts prompts,\n                             HerramientasReportes reportes, HerramientasClientes clientes,\n                             HerramientasVentas ventas, HerramientasCompras compras,\n                             HerramientasFinanzas finanzas, HerramientasContabilidad contabilidad,\n                             HerramientasInventario inventario, HerramientasDocumentos documentos,\n                             HerramientasUsuarios usuarios, HerramientasPoliticas politicas) {\n        this.reportes = reportes;\n        this.clientes = clientes;\n        this.ventas = ventas;\n        this.compras = compras;\n        this.finanzas = finanzas;\n        this.contabilidad = contabilidad;\n        this.inventario = inventario;\n        this.documentos = documentos;\n        this.usuarios = usuarios;\n        this.politicas = politicas;\n        this.herramientas = ToolCallbacks.from(reportes, clientes, ventas, compras, finanzas, contabilidad,\n                inventario, documentos, usuarios, politicas);\n        PromptVersionado prompt = prompts.obtener(PROMPT);\n        this.cliente = ChatClient.builder(modelo)\n                .defaultSystem(prompt.texto())\n                .defaultAdvisors(\n                        new FiltroDatosSensiblesAdvisor(),\n                        new RegistroTokensAdvisor(registro))\n                .build();\n    }\n\n    /** Solo un ADMIN que pide un alta puede dejar pasar el correo al modelo. */\n    static boolean pideAltaDeAdmin(String texto) {\n        return AlcanceHerramientas.rolesDelUsuario().contains(\"ADMIN\")\n                && texto != null && texto.matches(\"(?is).*\\\\balta\\\\b.*\");\n    }\n\n    /** Responde una pregunta. Antes de llamar al modelo rechaza los temas que no son de la empresa; así no se gasta presupuesto en preguntas ajenas. */\n    @Override\n    public RespuestaAsistente consultar(PreguntaAsistente pregunta) {\n        if (!TemasEmpresa.esDeEmpresa(pregunta.texto())) {\n            return new RespuestaAsistente(TemasEmpresa.RECHAZO);\n        }\n        var solicitud = cliente.prompt()\n                .user(pregunta.texto())\n                .advisors(a -> a\n                        .param(RegistroTokensAdvisor.CLAVE_SERVICIO, SERVICIO)\n                        .param(RegistroTokensAdvisor.CLAVE_USUARIO, pregunta.usuario())\n                        .param(FiltroDatosSensiblesAdvisor.CLAVE_CORREO_PERMITIDO, pideAltaDeAdmin(pregunta.texto())));\n        ToolCallback[] permitidas = Arrays.stream(herramientas)\n                .filter(h -> AlcanceHerramientas.puedeUsar(h.getToolDefinition().name()))\n                .toArray(ToolCallback[]::new);\n        if (permitidas.length > 0) {\n            solicitud = solicitud.toolCallbacks(permitidas);\n        }\n\n        RegistroHerramientasUsadas.iniciar();\n        try {\n            ChatResponse respuesta = solicitud.call().chatResponse();\n            String texto = respuesta.getResult() == null ? \"\" : respuesta.getResult().getOutput().getText();\n            var metadatos = respuesta.getMetadata();\n            var uso = metadatos == null ? null : metadatos.getUsage();\n            Integer entrada = uso == null ? null : uso.getPromptTokens();\n            Integer salida = uso == null ? null : uso.getCompletionTokens();\n            return new RespuestaAsistente(texto, entrada, salida, RegistroHerramientasUsadas.terminar());\n        } finally {\n            RegistroHerramientasUsadas.terminar();\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/ClaudeSugeridorPolizas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.function.Function;\nimport java.util.stream.Collectors;\n\nimport org.springframework.ai.chat.client.ChatClient;\nimport org.springframework.ai.chat.model.ChatModel;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.DeserializationFeature;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.CuentaCatalogo;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.PolizaEjemplo;\nimport com.mx.josesaid.develop.nexus.application.PolizaSugerida;\nimport com.mx.josesaid.develop.nexus.application.PolizaSugerida.LineaSugerida;\nimport com.mx.josesaid.develop.nexus.application.SugeridorPolizas;\nimport com.mx.josesaid.develop.nexus.application.SugerenciaPolizaInvalidaException;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensiblesAdvisor;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokens;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokensAdvisor;\n\n/**\n * Sugiere pólizas con Claude usando pólizas históricas como ejemplos (few-shot).\n * El modelo solo devuelve JSON: no tiene herramientas para registrar nada.\n */\npublic final class ClaudeSugeridorPolizas implements SugeridorPolizas {\n\n    static final String SERVICIO = \"nexus-ms\";\n\n    static final String INSTRUCCIONES = \"\"\"\n            Eres un asistente contable. Propones una póliza a partir de la descripción del usuario.\n            Usa solo cuentas del catálogo, identificadas por su código.\n            Responde únicamente con JSON, sin texto adicional, con esta forma:\n            {\"tipo\":\"INGRESO|EGRESO|DIARIO\",\"lineas\":[{\"codigo\":\"...\",\"cargo\":0,\"abono\":0}],\"confianza\":0.0,\"motivo\":\"...\"}\n            Cada línea tiene cargo o abono, y el otro en cero. La suma de cargos debe ser igual a la de abonos.\n            Si no estás seguro, baja la confianza. Los ejemplos son pólizas históricas de referencia.\n            \"\"\";\n\n    private final ChatClient cliente;\n    /** Lector JSON que ignora propiedades nuevas, por si el modelo agrega campos. */\n    private final ObjectMapper json = new ObjectMapper()\n            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);\n\n    /** Crea el cliente del modelo con las instrucciones de sistema y registra el consumo de tokens. */\n    public ClaudeSugeridorPolizas(ChatModel modelo, RegistroTokens registro) {\n        this.cliente = ChatClient.builder(modelo)\n                .defaultSystem(INSTRUCCIONES)\n                .defaultAdvisors(new FiltroDatosSensiblesAdvisor(), new RegistroTokensAdvisor(registro))\n                .build();\n    }\n\n    /** Pide al modelo la póliza sugerida y convierte su respuesta JSON en una sugerencia. Cualquier respuesta que no cumpla el formato se rechaza. */\n    @Override\n    public PolizaSugerida sugerir(String usuario, String descripcion, List<CuentaCatalogo> catalogo,\n                                  List<PolizaEjemplo> ejemplos) {\n        String respuesta = cliente.prompt()\n                .user(contexto(descripcion, catalogo, ejemplos))\n                .advisors(a -> a\n                        .param(RegistroTokensAdvisor.CLAVE_SERVICIO, SERVICIO)\n                        .param(RegistroTokensAdvisor.CLAVE_USUARIO, usuario))\n                .call()\n                .content();\n        RespuestaModelo r = parsear(respuesta);\n        List<LineaSugerida> lineas = r.lineas() == null ? List.of() : r.lineas().stream()\n                .map(l -> new LineaSugerida(l.codigo(), l.cargo(), l.abono()))\n                .toList();\n        return new PolizaSugerida(r.tipo(), lineas, r.confianza(), r.motivo());\n    }\n\n    /** Arma el texto de contexto para el modelo: la descripción, el catálogo de cuentas y ejemplos recientes. Las cuentas van con su código, no con su identificador. */\n    static String contexto(String descripcion, List<CuentaCatalogo> catalogo, List<PolizaEjemplo> ejemplos) {\n        Map<java.util.UUID, String> codigoPorId = catalogo.stream()\n                .collect(Collectors.toMap(CuentaCatalogo::id, CuentaCatalogo::codigo, (a, b) -> a));\n        StringBuilder sb = new StringBuilder(\"Catálogo de cuentas:\\n\");\n        catalogo.forEach(c -> sb.append(c.codigo()).append(' ').append(c.nombre()).append('\\n'));\n        sb.append(\"\\nPólizas históricas de referencia:\\n\");\n        for (PolizaEjemplo e : ejemplos) {\n            sb.append(e.tipo()).append(' ').append(e.fecha()).append(\": \");\n            sb.append(e.lineas().stream()\n                    .map(l -> codigoPorId.getOrDefault(l.cuentaId(), \"?\") + \" \"\n                            + (l.cargo().signum() > 0 ? \"cargo \" + l.cargo() : \"abono \" + l.abono()))\n                    .collect(Collectors.joining(\"; \")));\n            sb.append('\\n');\n        }\n        sb.append(\"\\nDescripción de la operación: \").append(descripcion);\n        return sb.toString();\n    }\n\n    /** Lee la respuesta JSON del modelo. Si está vacía o no es JSON válido, lanza SugerenciaPolizaInvalidaException. */\n    private RespuestaModelo parsear(String respuesta) {\n        if (respuesta == null) {\n            throw new SugerenciaPolizaInvalidaException(\"El modelo no devolvió respuesta\");\n        }\n        int inicio = respuesta.indexOf('{');\n        int fin = respuesta.lastIndexOf('}');\n        if (inicio < 0 || fin < inicio) {\n            throw new SugerenciaPolizaInvalidaException(\"El modelo no devolvió JSON\");\n        }\n        try {\n            return json.readValue(respuesta.substring(inicio, fin + 1), RespuestaModelo.class);\n        } catch (JsonProcessingException e) {\n            throw new SugerenciaPolizaInvalidaException(\"El JSON del modelo no es válido\");\n        }\n    }\n\n    /**\n     * Respuesta del modelo: tipo de póliza, líneas, nivel de confianza y motivo.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param lineas componente de tipo {@code List<LineaModelo>}.\n     * @param confianza componente de tipo {@code double}.\n     * @param motivo componente de tipo {@code String}.\n     */\n    record RespuestaModelo(String tipo, List<LineaModelo> lineas, double confianza, String motivo) {\n    }\n\n    /**\n     * Línea propuesta por el modelo: código de cuenta, cargo y abono.\n     *\n     * @param codigo componente de tipo {@code String}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    record LineaModelo(String codigo, BigDecimal cargo, BigDecimal abono) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/ContextoContableGateway.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.ContextoContable;\n\n/** Lee el catálogo y las pólizas aplicadas por gateway-ms con el token del usuario; contabilidad valida el rol. */\npublic final class ContextoContableGateway implements ContextoContable {\n\n    static final String RUTA_CUENTAS = \"/contabilidad-ms/v1/cuentas\";\n    static final String RUTA_POLIZAS = \"/contabilidad-ms/v1/polizas\";\n    static final int MESES = 3;\n    static final int MAX_EJEMPLOS = 10;\n    static final String APLICADA = \"APLICADA\";\n\n    private final RestClient gateway;\n    private final ZoneId zona;\n\n    /** Recibe el cliente del gateway y la zona horaria para calcular el mes actual. */\n    public ContextoContableGateway(RestClient gateway, ZoneId zona) {\n        this.gateway = gateway;\n        this.zona = zona;\n    }\n\n    /** Trae el catálogo de cuentas del gateway. Si no hay respuesta, devuelve una lista vacía. */\n    @Override\n    public List<CuentaCatalogo> catalogo() {\n        RespuestaCuenta[] cuentas = gateway.get().uri(RUTA_CUENTAS).retrieve().body(RespuestaCuenta[].class);\n        if (cuentas == null) {\n            return List.of();\n        }\n        return java.util.Arrays.stream(cuentas)\n                .map(c -> new CuentaCatalogo(c.id(), c.codigo(), c.nombre()))\n                .toList();\n    }\n\n    /** Trae hasta cinco pólizas registradas del mes y del mes anterior, como ejemplos de formato para el modelo. */\n    @Override\n    public List<PolizaEjemplo> ejemplosRecientes() {\n        YearMonth actual = YearMonth.now(zona);\n        List<PolizaEjemplo> ejemplos = new ArrayList<>();\n        for (int i = 0; i < MESES && ejemplos.size() < MAX_EJEMPLOS; i++) {\n            String periodo = actual.minusMonths(i).toString();\n            RespuestaPoliza[] polizas = gateway.get()\n                    .uri(u -> u.path(RUTA_POLIZAS).queryParam(\"periodo\", periodo).build())\n                    .retrieve()\n                    .body(RespuestaPoliza[].class);\n            if (polizas == null) {\n                continue;\n            }\n            for (RespuestaPoliza p : polizas) {\n                // Las reversadas no sirven de ejemplo: la póliza original quedó compensada\n                if (!APLICADA.equals(p.estatus()) || ejemplos.size() >= MAX_EJEMPLOS) {\n                    continue;\n                }\n                List<LineaEjemplo> lineas = p.movimientos().stream()\n                        .map(m -> new LineaEjemplo(m.cuentaId(), m.cargo(), m.abono()))\n                        .toList();\n                ejemplos.add(new PolizaEjemplo(p.tipo(), p.fecha(), lineas));\n            }\n        }\n        return ejemplos;\n    }\n\n    /**\n     * Cuenta tal como la devuelve el gateway.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param codigo componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     */\n    record RespuestaCuenta(UUID id, String codigo, String nombre) {\n    }\n\n    /**\n     * Póliza tal como la devuelve el gateway.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param fecha componente de tipo {@code LocalDate}.\n     * @param estatus componente de tipo {@code String}.\n     * @param movimientos componente de tipo {@code List<RespuestaMovimiento>}.\n     */\n    record RespuestaPoliza(String tipo, LocalDate fecha, String estatus, List<RespuestaMovimiento> movimientos) {\n    }\n\n    /**\n     * Movimiento de una póliza: cuenta, cargo y abono.\n     *\n     * @param cuentaId componente de tipo {@code UUID}.\n     * @param cargo componente de tipo {@code BigDecimal}.\n     * @param abono componente de tipo {@code BigDecimal}.\n     */\n    record RespuestaMovimiento(UUID cuentaId, BigDecimal cargo, BigDecimal abono) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/EjecutorAccionesGateway.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.Map;\n\nimport org.springframework.http.MediaType;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.fasterxml.jackson.databind.node.ObjectNode;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\n/** Ejecuta acciones confirmadas por gateway-ms con el token del usuario, así cada servicio aplica sus permisos. */\npublic final class EjecutorAccionesGateway implements EjecutorAcciones {\n\n    static final String RUTA_PEDIDOS = \"/pedidos-ventas-ms/v1/pedidos\";\n    static final String RUTA_PROSPECTOS = \"/clientes-ms/v1/prospectos\";\n    static final String RUTA_COTIZACIONES = \"/pedidos-ventas-ms/v1/cotizaciones\";\n    static final String RUTA_CLIENTES = \"/clientes-ms/v1/clientes\";\n    static final String RUTA_POLIZAS = \"/contabilidad-ms/v1/polizas\";\n    static final String RUTA_DOCUMENTOS = \"/documentos-cumplimiento-ms/v1/documentos\";\n    static final String RUTA_PROVEEDORES = \"/compras-proveedores-ms/v1/proveedores\";\n    static final String RUTA_ORDENES_COMPRA = \"/compras-proveedores-ms/v1/ordenes-compra\";\n    static final String RUTA_INVENTARIO = \"/inventario-operaciones-ms/v1\";\n    static final String RUTA_FACTURACION = \"/facturacion-pagos-ms/v1\";\n    static final String RUTA_REPORTES = \"/reportes-ejecutivos-ms/v1\";\n\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n\n    /** Recibe el cliente del gateway, que es quien ejecuta las acciones confirmadas. */\n    public EjecutorAccionesGateway(RestClient gateway) {\n        this.gateway = gateway;\n    }\n\n    /** Ejecuta la acción confirmada llamando al servicio que corresponde a su tipo. Un tipo sin implementación lanza excepción. */\n    @Override\n    public String ejecutar(String tipo, String payload) {\n        return switch (tipo) {\n            case AccionesPendientes.TIPO_PEDIDO_BORRADOR -> enviar(RUTA_PEDIDOS, payload);\n            case AccionesPendientes.TIPO_PROSPECTO_BORRADOR -> enviar(RUTA_PROSPECTOS, payload);\n            case AccionesPendientes.TIPO_COTIZACION_CREAR -> enviar(RUTA_COTIZACIONES, payload);\n            case AccionesPendientes.TIPO_PEDIDO_REEMPLAZAR_LINEAS -> {\n                String pedidoId = id(payload, \"pedidoId\");\n                yield gateway.put()\n                        .uri(RUTA_PEDIDOS + \"/\" + pedidoId + \"/lineas\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(sinCampo(payload, \"pedidoId\"))\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_PEDIDO_DEVOLVER -> {\n                String pedidoId = id(payload, \"pedidoId\");\n                yield gateway.post()\n                        .uri(RUTA_PEDIDOS + \"/\" + pedidoId + \"/devolucion\")\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_PROSPECTO_ESTATUS -> {\n                String prospectoId = id(payload, \"prospectoId\");\n                yield gateway.patch()\n                        .uri(RUTA_PROSPECTOS + \"/\" + prospectoId + \"/estatus\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(sinCampo(payload, \"prospectoId\"))\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_PROSPECTO_CONVERTIR -> {\n                String prospectoId = id(payload, \"prospectoId\");\n                yield gateway.post()\n                        .uri(RUTA_PROSPECTOS + \"/\" + prospectoId + \"/conversion\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(sinCampo(payload, \"prospectoId\"))\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_INTERACCION_REGISTRAR -> {\n                String clienteId = id(payload, \"clienteId\");\n                yield gateway.post()\n                        .uri(RUTA_CLIENTES + \"/\" + clienteId + \"/interacciones\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(sinCampo(payload, \"clienteId\"))\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_PEDIDO_CONFIRMAR -> {\n                String pedidoId = leer(payload).get(\"pedidoId\").asText();\n                yield gateway.post()\n                        .uri(RUTA_PEDIDOS + \"/\" + pedidoId + \"/confirmacion\")\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_PEDIDO_CANCELAR -> {\n                JsonNode datos = leer(payload);\n                String cuerpo = \"{\\\"motivo\\\":\\\"\" + datos.get(\"motivo\").asText() + \"\\\"}\";\n                yield gateway.post()\n                        .uri(RUTA_PEDIDOS + \"/\" + datos.get(\"pedidoId\").asText() + \"/cancelacion\")\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(cuerpo)\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_COTIZACION_ENVIAR -> accionCotizacion(payload, \"/envio\");\n            case AccionesPendientes.TIPO_COTIZACION_ACEPTAR -> accionCotizacion(payload, \"/aceptacion\");\n            case AccionesPendientes.TIPO_COTIZACION_A_PEDIDO -> accionCotizacion(payload, \"/pedido\");\n            case AccionesPendientes.TIPO_POLIZA_REGISTRAR -> enviar(RUTA_POLIZAS, payload);\n            case AccionesPendientes.TIPO_DOCUMENTO_ELIMINAR -> eliminarDocumento(payload);\n            case AccionesPendientes.TIPO_CLIENTE_CREAR -> enviar(RUTA_CLIENTES, payload);\n            case AccionesPendientes.TIPO_CLIENTE_ACTUALIZAR -> actualizarCliente(payload);\n            case AccionesPendientes.TIPO_CLIENTE_CONTACTO_AGREGAR -> postSinId(payload, RUTA_CLIENTES, \"clienteId\", \"/contactos\");\n            case AccionesPendientes.TIPO_PROVEEDOR_CREAR -> enviar(RUTA_PROVEEDORES, payload);\n            case AccionesPendientes.TIPO_ARTICULO_CREAR -> enviar(RUTA_INVENTARIO + \"/articulos\", payload);\n            case AccionesPendientes.TIPO_MOVIMIENTO_REGISTRAR -> enviarMovimiento(payload);\n            case AccionesPendientes.TIPO_COMPROBANTE_PAGO_REGISTRAR -> registrarPagoComprobante(payload);\n            case AccionesPendientes.TIPO_ORDEN_OPERACION_CREAR -> enviar(RUTA_INVENTARIO + \"/ordenes-operacion\", payload);\n            case AccionesPendientes.TIPO_ORDEN_COMPRA_CREAR -> enviar(RUTA_ORDENES_COMPRA, payload);\n            case AccionesPendientes.TIPO_ORDEN_COMPRA_RECEPCION ->\n                    postSinId(payload, RUTA_ORDENES_COMPRA, \"ordenId\", \"/recepciones\");\n            case AccionesPendientes.TIPO_ORDEN_COMPRA_CANCELAR ->\n                    postSinId(payload, RUTA_ORDENES_COMPRA, \"ordenId\", \"/cancelacion\");\n            case AccionesPendientes.TIPO_CLIENTE_ESTATUS -> cambiarEstatusCliente(payload);\n            case AccionesPendientes.TIPO_ALMACEN_CREAR -> enviar(RUTA_INVENTARIO + \"/almacenes\", payload);\n            case AccionesPendientes.TIPO_PEDIDO_ENTREGAR -> {\n                String pedidoId = id(payload, \"pedidoId\");\n                yield gateway.post()\n                        .uri(RUTA_PEDIDOS + \"/\" + pedidoId + \"/entrega\")\n                        .retrieve()\n                        .body(String.class);\n            }\n            case AccionesPendientes.TIPO_INDICADOR_REGISTRAR -> enviar(RUTA_REPORTES + \"/indicadores\", payload);\n            default -> throw new IllegalArgumentException(\"Tipo de acción no soportado: \" + tipo);\n        };\n    }\n\n    /** Cambia el estatus de un cliente (ACTIVO, SUSPENDIDO o BAJA). */\n    private String cambiarEstatusCliente(String payload) {\n        JsonNode datos = leer(payload);\n        return gateway.patch()\n                .uri(RUTA_CLIENTES + \"/\" + datos.get(\"clienteId\").asText() + \"/estatus\")\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(Map.of(\"estatus\", datos.get(\"estatus\").asText()))\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Actualiza los datos de un cliente. */\n    private String actualizarCliente(String payload) {\n        JsonNode datos = leer(payload);\n        return gateway.patch()\n                .uri(RUTA_CLIENTES + \"/\" + datos.get(\"clienteId\").asText())\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(Map.of(\"razonSocial\", datos.get(\"razonSocial\").asText()))\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Registra el cobro con la clave de idempotencia de la acción, que no forma parte del cuerpo. */\n    private String registrarPagoComprobante(String payload) {\n        ObjectNode cuerpo = ((ObjectNode) leer(payload)).deepCopy();\n        String comprobanteId = cuerpo.remove(\"comprobanteId\").asText();\n        String clave = cuerpo.remove(\"idempotencyKey\").asText();\n        return gateway.post()\n                .uri(RUTA_FACTURACION + \"/comprobantes/\" + comprobanteId + \"/pagos\")\n                .header(\"Idempotency-Key\", clave)\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(cuerpo.toString())\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Envía el movimiento con la clave de idempotencia de la acción, que no forma parte del cuerpo. */\n    private String enviarMovimiento(String payload) {\n        ObjectNode cuerpo = ((ObjectNode) leer(payload)).deepCopy();\n        String clave = cuerpo.remove(\"idempotencyKey\").asText();\n        return gateway.post()\n                .uri(RUTA_INVENTARIO + \"/movimientos\")\n                .header(\"Idempotency-Key\", clave)\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(cuerpo.toString())\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Envía al recurso del identificador del payload, sin ese campo en el cuerpo. */\n    private String postSinId(String payload, String ruta, String campoId, String sufijo) {\n        ObjectNode cuerpo = ((ObjectNode) leer(payload)).deepCopy();\n        String id = cuerpo.remove(campoId).asText();\n        return gateway.post()\n                .uri(ruta + \"/\" + id + sufijo)\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(cuerpo.toString())\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Elimina un documento. */\n    private String eliminarDocumento(String payload) {\n        JsonNode datos = leer(payload);\n        return gateway.post()\n                .uri(RUTA_DOCUMENTOS + \"/\" + datos.get(\"documentoId\").asText() + \"/eliminacion\")\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(Map.of(\"motivo\", datos.get(\"motivo\").asText()))\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Ejecuta una acción sobre una cotización (enviar, aceptar o convertir), según el parámetro accion. */\n    private String accionCotizacion(String payload, String accion) {\n        String cotizacionId = leer(payload).get(\"cotizacionId\").asText();\n        return gateway.post()\n                .uri(RUTA_COTIZACIONES + \"/\" + cotizacionId + accion)\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Envía un POST con el payload al endpoint indicado y devuelve la respuesta. */\n    private String enviar(String ruta, String payload) {\n        return gateway.post()\n                .uri(ruta)\n                .contentType(MediaType.APPLICATION_JSON)\n                .body(payload)\n                .retrieve()\n                .body(String.class);\n    }\n\n    /** Convierte el payload JSON en un árbol. Si el JSON no es válido, lanza excepción. */\n    private static JsonNode leer(String payload) {\n        try {\n            return JSON.readTree(payload);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"Payload de acción inválido\", e);\n        }\n    }\n\n    /** Lee un campo de texto del payload. */\n    private static String id(String payload, String campo) {\n        return leer(payload).get(campo).asText();\n    }\n\n    /** El cuerpo HTTP es el payload sin el identificador que va en la ruta. */\n    private static String sinCampo(String payload, String campo) {\n        ObjectNode datos = (ObjectNode) leer(payload);\n        datos.remove(campo);\n        return datos.toString();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasAccionesMcp.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\nimport com.mx.josesaid.develop.nexus.application.AccionNoEncontradaException;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/** Confirma o cancela acciones preparadas por MCP. Solo quien las preparó puede actuar sobre ellas. */\npublic final class HerramientasAccionesMcp {\n\n    private final ConfirmacionAcciones confirmaciones;\n    private final AccionesPendientes acciones;\n\n    /** Recibe el servicio de confirmación y el registro de acciones para las herramientas MCP. */\n    public HerramientasAccionesMcp(ConfirmacionAcciones confirmaciones, AccionesPendientes acciones) {\n        this.confirmaciones = confirmaciones;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta MCP: confirma una acción pendiente con su código. Un código incorrecto cancela la acción. */\n    @Tool(name = \"confirmar_accion\",\n          description = \"Confirma una acción pendiente con su identificador y su código de confirmación. \"\n                  + \"Solo funciona para la persona que la preparó y dentro de su vigencia. \"\n                  + \"Un código incorrecto cancela la acción.\")\n    public String confirmarAccion(\n            @ToolParam(description = \"Identificador de la acción preparada\", required = true) String accionId,\n            @ToolParam(description = \"Código de confirmación de 8 dígitos que devolvió la preparación\", required = true) String codigo) {\n        RegistroHerramientasUsadas.registrar(\"confirmar_accion\");\n        return confirmaciones.confirmarConCodigo(UUID.fromString(accionId), usuarioActual(), codigo);\n    }\n\n    /** Herramienta MCP: cancela una acción pendiente del usuario. */\n    @Tool(name = \"cancelar_accion\",\n          description = \"Cancela una acción pendiente sin ejecutarla. Solo funciona para la persona que la preparó.\")\n    public String cancelarAccion(\n            @ToolParam(description = \"Identificador de la acción preparada\", required = true) String accionId) {\n        RegistroHerramientasUsadas.registrar(\"cancelar_accion\");\n        acciones.cancelar(UUID.fromString(accionId), usuarioActual());\n        return \"Acción \" + accionId + \" cancelada.\";\n    }\n\n    /** Herramienta MCP: devuelve el estado de una acción pendiente del usuario. */\n    @Tool(name = \"consultar_estado_accion\",\n          description = \"Devuelve el estado de una acción preparada por la persona actual: PENDIENTE, CONFIRMADA o \"\n                  + \"EXPIRADA, con su resumen y su vencimiento. Solo funciona para quien la preparó.\")\n    public String consultarEstadoAccion(\n            @ToolParam(description = \"Identificador de la acción preparada\", required = true) String accionId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_estado_accion\");\n        UUID id;\n        try {\n            id = UUID.fromString(accionId.trim());\n        } catch (IllegalArgumentException | NullPointerException e) {\n            return \"El identificador de la acción no es válido.\";\n        }\n        AccionPendiente accion;\n        try {\n            accion = acciones.consultar(id, usuarioActual());\n        } catch (AccionNoEncontradaException e) {\n            return \"No encontré esa acción.\";\n        }\n        return FiltroDatosSensibles.redactar(\"Acción \" + accion.id() + \": estatus \" + accion.estatus()\n                + \". Resumen: \" + accion.resumen() + \". Vence: \" + accion.expiraUtc() + \".\").texto();\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasClientes.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.EnumSet;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.regex.Pattern;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas sobre clientes-ms, por gateway-ms con el token del usuario.\n * Las de lectura consultan datos; las de escritura solo preparan una acción que el usuario confirma en la aplicación.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasClientes {\n\n    static final String RUTA_BASE = \"/clientes-ms/v1/clientes\";\n    static final String RUTA_PROSPECTOS = \"/clientes-ms/v1/prospectos\";\n    static final String RUTA_METRICAS = \"/clientes-ms/v1/metricas/conversion\";\n    static final String NO_ENCONTRADO_CLIENTE = \"No encontré ese cliente.\";\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    private static final Pattern RFC = Pattern.compile(\"[A-Z&Ñ]{3,4}[0-9]{6}[A-Z0-9]{3}\");\n    private static final Pattern MES = Pattern.compile(\"\\\\d{4}-\\\\d{2}\");\n    private static final Set<String> ROLES_CONTACTO = Set.of(\"COMPRAS\", \"PAGOS\", \"ASISTENCIA\");\n    private static final Set<String> ESTATUS_CLIENTE = Set.of(\"ACTIVO\", \"SUSPENDIDO\", \"BAJA\");\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasClientes(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones para preparar altas y cambios. */\n    public HerramientasClientes(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: busca clientes por RFC exacto o por nombre. */\n    @Tool(name = \"buscar_clientes\",\n          description = \"Busca clientes por RFC o por nombre. Devuelve hasta 10 resultados con su última interacción.\")\n    public String buscarClientes(\n            @ToolParam(description = \"RFC completo y exacto (no admite búsqueda parcial). Vacío si se busca por nombre.\", required = false) String rfc,\n            @ToolParam(description = \"Nombre o razón social. Vacío si se busca por RFC.\", required = false) String nombre) {\n        RegistroHerramientasUsadas.registrar(\"buscar_clientes\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> {\n                    var uri = constructor.path(RUTA_BASE).queryParam(\"size\", 10);\n                    if (rfc != null && !rfc.isBlank()) {\n                        uri.queryParam(\"rfc\", rfc.trim());\n                    }\n                    if (nombre != null && !nombre.isBlank()) {\n                        uri.queryParam(\"nombre\", nombre.trim());\n                    }\n                    return uri.build();\n                })\n                .retrieve()\n                .body(String.class);\n        return redactar(cuerpo);\n    }\n\n    /** Herramienta del asistente: devuelve el detalle de un cliente. */\n    @Tool(name = \"obtener_cliente\",\n          description = \"Devuelve el detalle de un cliente por su identificador (UUID).\")\n    public String obtenerCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String id) {\n        RegistroHerramientasUsadas.registrar(\"obtener_cliente\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/{id}\", id)\n                .retrieve()\n                .body(String.class);\n        return redactar(cuerpo);\n    }\n\n    /** Herramienta del asistente: devuelve las interacciones registradas de un cliente. */\n    @Tool(name = \"consultar_interacciones_cliente\",\n          description = \"Lista las interacciones registradas de un cliente: tipo, fecha y resumen.\")\n    public String consultarInteraccionesCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_interacciones_cliente\");\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        return lectura(RUTA_BASE + \"/\" + id + \"/interacciones\", NO_ENCONTRADO_CLIENTE);\n    }\n\n    /** Herramienta del asistente: devuelve el detalle de un prospecto. */\n    @Tool(name = \"obtener_prospecto\",\n          description = \"Devuelve un prospecto por su identificador UUID: nombre, fuente, estatus y fecha de alta.\")\n    public String obtenerProspecto(\n            @ToolParam(description = \"Identificador UUID del prospecto\", required = true) String prospectoId) {\n        RegistroHerramientasUsadas.registrar(\"obtener_prospecto\");\n        UUID id = identificador(prospectoId);\n        if (id == null) {\n            return \"El identificador del prospecto no es válido.\";\n        }\n        return lectura(RUTA_PROSPECTOS + \"/\" + id, \"No encontré ese prospecto.\");\n    }\n\n    /** Herramienta del asistente: devuelve las métricas de conversión de un mes. */\n    @Tool(name = \"consultar_metricas_conversion\",\n          description = \"Devuelve la conversión de prospectos a clientes de un mes. El mes es AAAA-MM.\")\n    public String consultarMetricasConversion(\n            @ToolParam(description = \"Mes en formato AAAA-MM, por ejemplo 2026-09\", required = true) String mes) {\n        RegistroHerramientasUsadas.registrar(\"consultar_metricas_conversion\");\n        String valor = mes == null ? \"\" : mes.trim();\n        if (!MES.matcher(valor).matches()) {\n            return \"El mes debe tener formato AAAA-MM, por ejemplo 2026-09.\";\n        }\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_METRICAS).queryParam(\"mes\", valor).build())\n                .retrieve()\n                .body(String.class);\n        return redactar(cuerpo);\n    }\n\n    /** Herramienta del asistente: prepara el alta de un cliente. No lo crea; el usuario debe confirmarlo. */\n    @Tool(name = \"crear_cliente\",\n          description = \"Prepara el alta de un cliente con su contacto principal. NO lo crea: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo ADMIN puede usarla.\")\n    public String crearCliente(\n            @ToolParam(description = \"Razón social del cliente\", required = true) String razonSocial,\n            @ToolParam(description = \"RFC del cliente, en mayúsculas\", required = true) String rfc,\n            @ToolParam(description = \"Nombre del contacto principal\", required = true) String contactoNombre,\n            @ToolParam(description = \"Correo electrónico del contacto principal\", required = true) String contactoCorreo,\n            @ToolParam(description = \"Rol del contacto: COMPRAS, PAGOS o ASISTENCIA\", required = true) String contactoRol) {\n        RegistroHerramientasUsadas.registrar(\"crear_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        if (vacio(razonSocial) || razonSocial.trim().length() > 250) {\n            return \"La razón social es obligatoria y de hasta 250 caracteres.\";\n        }\n        String rfcNormalizado = rfc == null ? \"\" : rfc.trim().toUpperCase();\n        if (!RFC.matcher(rfcNormalizado).matches()) {\n            return \"El RFC no tiene un formato válido.\";\n        }\n        String rol = normalizar(contactoRol);\n        if (!ROLES_CONTACTO.contains(rol)) {\n            return \"El rol del contacto debe ser COMPRAS, PAGOS o ASISTENCIA.\";\n        }\n        if (!correoValido(contactoCorreo)) {\n            return \"El correo del contacto no es válido.\";\n        }\n        if (vacio(contactoNombre) || contactoNombre.trim().length() > 200) {\n            return \"El nombre del contacto es obligatorio y de hasta 200 caracteres.\";\n        }\n        Map<String, Object> contacto = new LinkedHashMap<>();\n        contacto.put(\"nombre\", contactoNombre.trim());\n        contacto.put(\"correo\", contactoCorreo.trim());\n        contacto.put(\"rol\", rol);\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"razonSocial\", razonSocial.trim());\n        cuerpo.put(\"rfc\", rfcNormalizado);\n        cuerpo.put(\"contactoPrincipal\", contacto);\n        String resumen = \"Alta de cliente \" + razonSocial.trim() + \" (RFC \" + rfcNormalizado + \")\";\n        return guardarAccion(AccionesPendientes.TIPO_CLIENTE_CREAR, cuerpo, resumen, \"Alta preparada, no creada.\");\n    }\n\n    /** Herramienta del asistente: prepara la actualización de la razón social de un cliente. */\n    @Tool(name = \"actualizar_cliente\",\n          description = \"Prepara el cambio de razón social de un cliente. NO lo cambia: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo ADMIN puede usarla.\")\n    public String actualizarCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Nueva razón social\", required = true) String razonSocial) {\n        RegistroHerramientasUsadas.registrar(\"actualizar_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        if (vacio(razonSocial) || razonSocial.trim().length() > 250) {\n            return \"La razón social es obligatoria y de hasta 250 caracteres.\";\n        }\n        if (!existeCliente(id)) {\n            return NO_ENCONTRADO_CLIENTE;\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", id.toString());\n        cuerpo.put(\"razonSocial\", razonSocial.trim());\n        String resumen = \"Cambiar la razón social del cliente \" + id + \" a \" + razonSocial.trim();\n        return guardarAccion(AccionesPendientes.TIPO_CLIENTE_ACTUALIZAR, cuerpo, resumen, \"Cambio preparado, no aplicado.\");\n    }\n\n    /** Herramienta del asistente: prepara agregar un contacto a un cliente. Valida el correo antes de preparar la acción. */\n    @Tool(name = \"agregar_contacto_cliente\",\n          description = \"Prepara el alta de un contacto en un cliente existente. NO lo agrega: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo ADMIN puede usarla.\")\n    public String agregarContactoCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Nombre del contacto\", required = true) String nombre,\n            @ToolParam(description = \"Correo electrónico del contacto\", required = true) String correo,\n            @ToolParam(description = \"Rol del contacto: COMPRAS, PAGOS o ASISTENCIA\", required = true) String rol,\n            @ToolParam(description = \"true si será el contacto principal; vacío o false en otro caso\", required = false) String principal) {\n        RegistroHerramientasUsadas.registrar(\"agregar_contacto_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        if (vacio(nombre) || nombre.trim().length() > 200) {\n            return \"El nombre del contacto es obligatorio y de hasta 200 caracteres.\";\n        }\n        if (!correoValido(correo)) {\n            return \"El correo del contacto no es válido.\";\n        }\n        String rolNormalizado = normalizar(rol);\n        if (!ROLES_CONTACTO.contains(rolNormalizado)) {\n            return \"El rol del contacto debe ser COMPRAS, PAGOS o ASISTENCIA.\";\n        }\n        if (!existeCliente(id)) {\n            return NO_ENCONTRADO_CLIENTE;\n        }\n        boolean esPrincipal = \"true\".equalsIgnoreCase(principal == null ? \"\" : principal.trim());\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", id.toString());\n        cuerpo.put(\"nombre\", nombre.trim());\n        cuerpo.put(\"correo\", correo.trim());\n        cuerpo.put(\"rol\", rolNormalizado);\n        cuerpo.put(\"principal\", esPrincipal);\n        String resumen = \"Agregar contacto \" + nombre.trim() + \" (\" + rolNormalizado + \") al cliente \" + id\n                + (esPrincipal ? \", como principal\" : \"\");\n        return guardarAccion(AccionesPendientes.TIPO_CLIENTE_CONTACTO_AGREGAR, cuerpo, resumen,\n                \"Alta de contacto preparada, no agregada.\");\n    }\n\n    /** Herramienta del asistente: prepara el cambio de estatus de un cliente. Solo acepta ACTIVO, SUSPENDIDO o BAJA. */\n    @Tool(name = \"cambiar_estatus_cliente\",\n          description = \"Prepara el cambio de estatus de un cliente a ACTIVO, SUSPENDIDO o BAJA. NO lo cambia: \"\n                  + \"devuelve un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. Solo ADMIN puede usarla.\")\n    public String cambiarEstatusCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Nuevo estatus: ACTIVO, SUSPENDIDO o BAJA\", required = true) String estatus) {\n        RegistroHerramientasUsadas.registrar(\"cambiar_estatus_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        String nuevo = estatus == null ? \"\" : estatus.trim().toUpperCase();\n        if (!ESTATUS_CLIENTE.contains(nuevo)) {\n            return \"El estatus debe ser ACTIVO, SUSPENDIDO o BAJA.\";\n        }\n        if (!existeCliente(id)) {\n            return NO_ENCONTRADO_CLIENTE;\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", id.toString());\n        cuerpo.put(\"estatus\", nuevo);\n        return guardarAccion(AccionesPendientes.TIPO_CLIENTE_ESTATUS, cuerpo,\n                \"Cambiar estatus del cliente \" + id + \" a \" + nuevo, \"Cambio preparado, no ejecutado.\");\n    }\n\n    /** Guarda la acción pendiente del usuario y devuelve un texto con su identificador. Los RFC se redactan en la respuesta. */\n    private String guardarAccion(String tipo, Map<String, Object> cuerpo, String resumen, String encabezado) {\n        AccionPendiente accion = acciones.preparar(usuarioActual(), tipo, aJson(cuerpo), resumen);\n        return redactar(encabezado + \" \" + resumen + \". accion_id: \" + accion.id()\n                + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\");\n    }\n\n    /** Indica si el cliente existe consultando el gateway. Si falla la consulta, lanza excepción en lugar de contestar que no existe. */\n    private boolean existeCliente(UUID id) {\n        try {\n            gateway.get().uri(RUTA_BASE + \"/\" + id).retrieve().body(String.class);\n            return true;\n        } catch (HttpClientErrorException.NotFound e) {\n            return false;\n        }\n    }\n\n    /** Consulta un recurso del gateway y devuelve su contenido, o un mensaje si no existe. */\n    private String lectura(String ruta, String noEncontrado) {\n        try {\n            String cuerpo = gateway.get().uri(ruta).retrieve().body(String.class);\n            return redactar(cuerpo);\n        } catch (HttpClientErrorException.NotFound e) {\n            return noEncontrado;\n        }\n    }\n\n    /** Redacta los RFC del texto antes de devolverlo al modelo. */\n    private static String redactar(String texto) {\n        return FiltroDatosSensibles.redactar(texto, EnumSet.of(FiltroDatosSensibles.Tipo.RFC)).texto();\n    }\n\n    /** Convierte un texto en UUID. Devuelve nulo si el valor es nulo y lanza excepción si no tiene formato de UUID. */\n    private static UUID identificador(String valor) {\n        try {\n            return valor == null ? null : UUID.fromString(valor.trim());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n\n    /** Indica si el texto es nulo o está en blanco. */\n    private static boolean vacio(String valor) {\n        return valor == null || valor.isBlank();\n    }\n\n    /** Revisa que el correo no esté vacío, tenga máximo 254 caracteres y contenga @. Es una validación básica, no de formato completo. */\n    private static boolean correoValido(String correo) {\n        return !vacio(correo) && correo.trim().length() <= 254 && correo.contains(\"@\");\n    }\n\n    /** Quita espacios y pasa el texto a mayúsculas. Un valor nulo se convierte en cadena vacía. */\n    private static String normalizar(String valor) {\n        return valor == null ? \"\" : valor.trim().toUpperCase();\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasCompras.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas sobre compras-proveedores-ms, por gateway-ms con el token del usuario.\n * Las de lectura consultan datos; las de escritura solo preparan una acción que el usuario confirma en la aplicación.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasCompras {\n\n    static final String RUTA_BASE = \"/compras-proveedores-ms/v1\";\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasCompras(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones para preparar operaciones de compra. */\n    public HerramientasCompras(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: devuelve los datos de un proveedor. */\n    @Tool(name = \"consultar_proveedor\",\n          description = \"Devuelve los datos de un proveedor por su identificador UUID: razón social, RFC enmascarado, correo enmascarado y estatus.\")\n    public String consultarProveedor(\n            @ToolParam(description = \"Identificador UUID del proveedor\", required = true) String proveedorId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_proveedor\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/proveedores/{id}\").build(UUID.fromString(proveedorId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve una orden de compra. */\n    @Tool(name = \"consultar_orden_compra\",\n          description = \"Devuelve una orden de compra por su identificador UUID: proveedor, moneda, líneas, cantidades recibidas, subtotales y estatus.\")\n    public String consultarOrdenCompra(\n            @ToolParam(description = \"Identificador UUID de la orden de compra\", required = true) String ordenId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_orden_compra\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/ordenes-compra/{id}\").build(UUID.fromString(ordenId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: busca proveedores por razón social, con mínimo 3 caracteres. */\n    @Tool(name = \"buscar_proveedores\",\n          description = \"Busca proveedores por parte de la razón social (mínimo 3 caracteres). Devuelve hasta 20 resultados con RFC y correo enmascarados.\")\n    public String buscarProveedores(\n            @ToolParam(description = \"Texto de la razón social, mínimo 3 caracteres\", required = true) String razonSocial) {\n        RegistroHerramientasUsadas.registrar(\"buscar_proveedores\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/proveedores\")\n                        .queryParam(\"razonSocial\", razonSocial.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    private static final java.util.Set<String> ESTATUS_ORDEN =\n            java.util.Set.of(\"BORRADOR\", \"APROBADA\", \"RECIBIDA_PARCIAL\", \"RECIBIDA\", \"CANCELADA\");\n\n    /** Herramienta del asistente: lista órdenes de compra, opcionalmente filtradas por estatus. */\n    @Tool(name = \"listar_ordenes_compra\",\n          description = \"Lista las órdenes de compra más recientes primero, hasta 15. Filtro opcional por un solo estatus: BORRADOR, APROBADA, RECIBIDA_PARCIAL, RECIBIDA o CANCELADA. Muestra la razón social del proveedor y la fecha de creación.\")\n    public String listarOrdenesCompra(\n            @ToolParam(description = \"Estatus para filtrar, opcional. Vacío para no filtrar.\", required = false) String estatus) {\n        RegistroHerramientasUsadas.registrar(\"listar_ordenes_compra\");\n        String filtro = estatus == null ? \"\" : estatus.trim().toUpperCase(java.util.Locale.ROOT);\n        if (!filtro.isEmpty() && !ESTATUS_ORDEN.contains(filtro)) {\n            return \"Estatus no válido. Use BORRADOR, APROBADA, RECIBIDA_PARCIAL, RECIBIDA o CANCELADA.\";\n        }\n        String cuerpo = gateway.get()\n                .uri(constructor -> {\n                    var ruta = constructor.path(RUTA_BASE + \"/ordenes-compra\");\n                    if (!filtro.isEmpty()) {\n                        ruta.queryParam(\"estatus\", filtro);\n                    }\n                    return ruta.build();\n                })\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: prepara el alta de un proveedor. */\n    @Tool(name = \"crear_proveedor\",\n          description = \"Prepara el alta de un proveedor. NO lo crea: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo COMPRAS puede usarla.\")\n    public String crearProveedor(\n            @ToolParam(description = \"Razón social del proveedor, de hasta 200 caracteres\", required = true) String razonSocial,\n            @ToolParam(description = \"RFC del proveedor, de hasta 13 caracteres\", required = true) String rfc,\n            @ToolParam(description = \"Correo electrónico del proveedor\", required = true) String correo) {\n        RegistroHerramientasUsadas.registrar(\"crear_proveedor\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        if (vacio(razonSocial) || razonSocial.trim().length() > 200) {\n            return \"La razón social es obligatoria y de hasta 200 caracteres.\";\n        }\n        String rfcLimpio = rfc == null ? \"\" : rfc.trim().toUpperCase();\n        if (rfcLimpio.isEmpty() || rfcLimpio.length() > 13) {\n            return \"El RFC es obligatorio y de hasta 13 caracteres.\";\n        }\n        if (!correoValido(correo)) {\n            return \"El correo del proveedor no es válido.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"razonSocial\", razonSocial.trim());\n        cuerpo.put(\"rfc\", rfcLimpio);\n        cuerpo.put(\"correo\", correo.trim());\n        String resumen = \"Alta de proveedor \" + razonSocial.trim() + \" (RFC \" + rfcLimpio + \")\";\n        return guardar(AccionesPendientes.TIPO_PROVEEDOR_CREAR, cuerpo, resumen, \"Alta preparada, no creada.\");\n    }\n\n    /** Herramienta del asistente: prepara una orden de compra para un proveedor. */\n    @Tool(name = \"crear_orden_compra\",\n          description = \"Prepara una orden de compra en borrador para un proveedor, con una sola línea. \"\n                  + \"NO la crea: devuelve un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. \"\n                  + \"Solo COMPRAS puede usarla.\")\n    public String crearOrdenCompra(\n            @ToolParam(description = \"Identificador UUID del proveedor\", required = true) String proveedorId,\n            @ToolParam(description = \"Moneda ISO, por ejemplo MXN\", required = true) String moneda,\n            @ToolParam(description = \"SKU del artículo\", required = true) String articuloSku,\n            @ToolParam(description = \"Cantidad mayor a cero, hasta 3 decimales\", required = true) String cantidad,\n            @ToolParam(description = \"Precio unitario, hasta 2 decimales\", required = true) String precioUnitario) {\n        RegistroHerramientasUsadas.registrar(\"crear_orden_compra\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(proveedorId);\n        if (id == null) {\n            return \"El identificador del proveedor no es válido.\";\n        }\n        String monedaLimpia = normalizar(moneda);\n        if (monedaLimpia.isEmpty() || monedaLimpia.length() > 3) {\n            return \"La moneda debe ser un código ISO de hasta 3 letras, por ejemplo MXN.\";\n        }\n        if (vacio(articuloSku) || articuloSku.trim().length() > 40) {\n            return \"El SKU es obligatorio y de hasta 40 caracteres.\";\n        }\n        BigDecimal cant = decimal(cantidad, 3, 9);\n        if (cant == null || cant.signum() <= 0) {\n            return \"La cantidad debe ser mayor a cero, con hasta 3 decimales y 9 dígitos enteros.\";\n        }\n        BigDecimal precio = decimal(precioUnitario, 2, 10);\n        if (precio == null || precio.signum() < 0) {\n            return \"El precio unitario no es válido: debe ser cero o positivo, con hasta 2 decimales.\";\n        }\n        if (recurso(RUTA_BASE + \"/proveedores/\" + id) == null) {\n            return \"No encontré ese proveedor.\";\n        }\n        Map<String, Object> linea = new LinkedHashMap<>();\n        linea.put(\"articuloSku\", articuloSku.trim());\n        linea.put(\"cantidad\", cant);\n        linea.put(\"precioUnitario\", precio);\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"proveedorId\", id.toString());\n        cuerpo.put(\"moneda\", monedaLimpia);\n        cuerpo.put(\"lineas\", java.util.List.of(linea));\n        String resumen = \"Orden de compra al proveedor \" + id + \": \" + cant.stripTrailingZeros().toPlainString()\n                + \" x \" + articuloSku.trim() + \" a \" + precio.toPlainString() + \" \" + monedaLimpia;\n        return guardar(AccionesPendientes.TIPO_ORDEN_COMPRA_CREAR, cuerpo, resumen, \"Orden preparada, no creada.\");\n    }\n\n    /** Herramienta del asistente: prepara el registro de la recepción de una orden de compra. */\n    @Tool(name = \"registrar_recepcion_orden\",\n          description = \"Prepara el registro de una recepción de mercancía en una orden aprobada o recibida parcialmente. \"\n                  + \"NO la registra: devuelve un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. \"\n                  + \"Solo ALMACEN puede usarla.\")\n    public String registrarRecepcionOrden(\n            @ToolParam(description = \"Identificador UUID de la orden de compra\", required = true) String ordenId,\n            @ToolParam(description = \"SKU del artículo recibido\", required = true) String articuloSku,\n            @ToolParam(description = \"Cantidad recibida, mayor a cero\", required = true) String cantidad) {\n        RegistroHerramientasUsadas.registrar(\"registrar_recepcion_orden\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(ordenId);\n        if (id == null) {\n            return \"El identificador de la orden no es válido.\";\n        }\n        if (vacio(articuloSku) || articuloSku.trim().length() > 40) {\n            return \"El SKU es obligatorio y de hasta 40 caracteres.\";\n        }\n        BigDecimal cant = decimal(cantidad, 3, 9);\n        if (cant == null || cant.signum() <= 0) {\n            return \"La cantidad debe ser mayor a cero, con hasta 3 decimales y 9 dígitos enteros.\";\n        }\n        JsonNode orden = recurso(RUTA_BASE + \"/ordenes-compra/\" + id);\n        if (orden == null) {\n            return \"No encontré esa orden.\";\n        }\n        String estatus = orden.path(\"estatus\").asText();\n        if (!\"APROBADA\".equals(estatus) && !\"RECIBIDA_PARCIAL\".equals(estatus)) {\n            return \"La orden está en estatus \" + estatus + \"; solo una orden aprobada o recibida parcialmente admite recepciones.\";\n        }\n        Map<String, Object> linea = new LinkedHashMap<>();\n        linea.put(\"articuloSku\", articuloSku.trim());\n        linea.put(\"cantidad\", cant);\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"ordenId\", id.toString());\n        cuerpo.put(\"lineas\", java.util.List.of(linea));\n        String resumen = \"Recepción de \" + cant.stripTrailingZeros().toPlainString() + \" x \" + articuloSku.trim()\n                + \" en la orden \" + id + \" (estatus actual \" + estatus + \")\";\n        return guardar(AccionesPendientes.TIPO_ORDEN_COMPRA_RECEPCION, cuerpo, resumen, \"Recepción preparada, no registrada.\");\n    }\n\n    /** Herramienta del asistente: prepara la cancelación de una orden de compra, con su motivo. */\n    @Tool(name = \"cancelar_orden_compra\",\n          description = \"Prepara la cancelación de una orden de compra que no esté recibida ni cancelada. \"\n                  + \"NO la cancela: devuelve un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. \"\n                  + \"Solo COMPRAS puede usarla.\")\n    public String cancelarOrdenCompra(\n            @ToolParam(description = \"Identificador UUID de la orden de compra\", required = true) String ordenId,\n            @ToolParam(description = \"Motivo de la cancelación, de hasta 200 caracteres\", required = true) String motivo) {\n        RegistroHerramientasUsadas.registrar(\"cancelar_orden_compra\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(ordenId);\n        if (id == null) {\n            return \"El identificador de la orden no es válido.\";\n        }\n        if (vacio(motivo) || motivo.trim().length() > 200) {\n            return \"El motivo es obligatorio y de hasta 200 caracteres.\";\n        }\n        JsonNode orden = recurso(RUTA_BASE + \"/ordenes-compra/\" + id);\n        if (orden == null) {\n            return \"No encontré esa orden.\";\n        }\n        String estatus = orden.path(\"estatus\").asText();\n        if (\"RECIBIDA\".equals(estatus) || \"CANCELADA\".equals(estatus)) {\n            return \"La orden está en estatus \" + estatus + \"; no puede cancelarse.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"ordenId\", id.toString());\n        cuerpo.put(\"motivo\", motivo.trim());\n        String resumen = \"Cancelar la orden \" + id + \" (estatus actual \" + estatus + \"): \" + motivo.trim();\n        return guardar(AccionesPendientes.TIPO_ORDEN_COMPRA_CANCELAR, cuerpo, resumen, \"Cancelación preparada, no ejecutada.\");\n    }\n\n    /** Guarda la acción pendiente del usuario y devuelve un texto con su identificador. Redacta los RFC de la respuesta. */\n    private String guardar(String tipo, Map<String, Object> cuerpo, String resumen, String encabezado) {\n        AccionPendiente accion = acciones.preparar(usuarioActual(), tipo, aJson(cuerpo), resumen);\n        return FiltroDatosSensibles.redactar(encabezado + \" \" + resumen + \". accion_id: \" + accion.id()\n                + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\").texto();\n    }\n\n    /** Consulta un recurso con el token del usuario. Devuelve null si no existe o no es visible para él. */\n    private JsonNode recurso(String ruta) {\n        try {\n            String cuerpo = gateway.get().uri(ruta).retrieve().body(String.class);\n            return JSON.readTree(cuerpo);\n        } catch (HttpClientErrorException.NotFound e) {\n            return null;\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"Respuesta no válida de \" + ruta, e);\n        }\n    }\n\n    /** Número decimal con la escala y los dígitos enteros máximos; null si no es válido. */\n    private static BigDecimal decimal(String valor, int escala, int enteros) {\n        try {\n            BigDecimal numero = new BigDecimal(valor.trim());\n            if (numero.scale() > escala || numero.precision() - numero.scale() > enteros) {\n                return null;\n            }\n            return numero;\n        } catch (NumberFormatException | NullPointerException e) {\n            return null;\n        }\n    }\n\n    /** Convierte un texto en UUID. Devuelve nulo si el valor es nulo; lanza excepción si no tiene formato de UUID. */\n    private static UUID identificador(String valor) {\n        try {\n            return valor == null ? null : UUID.fromString(valor.trim());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n\n    /** Indica si el texto es nulo o está en blanco. */\n    private static boolean vacio(String valor) {\n        return valor == null || valor.isBlank();\n    }\n\n    /** Revisa que el correo tenga máximo 254 caracteres y contenga @. Es una validación básica. */\n    private static boolean correoValido(String correo) {\n        return !vacio(correo) && correo.trim().length() <= 254 && correo.contains(\"@\");\n    }\n\n    /** Quita espacios y pasa el texto a mayúsculas. Un valor nulo se convierte en cadena vacía. */\n    private static String normalizar(String valor) {\n        return valor == null ? \"\" : valor.trim().toUpperCase(java.util.Locale.ROOT);\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasContabilidad.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas de solo lectura sobre contabilidad-ms, por gateway-ms con el token del usuario.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasContabilidad {\n\n    static final String RUTA_BASE = \"/contabilidad-ms/v1\";\n\n    private final RestClient gateway;\n\n    /** Recibe el cliente del gateway. Contabilidad es solo lectura: no prepara acciones. */\n    public HerramientasContabilidad(RestClient gateway) {\n        this.gateway = gateway;\n    }\n\n    /** Herramienta del asistente: devuelve una póliza contable. */\n    @Tool(name = \"consultar_poliza\",\n          description = \"Devuelve una póliza contable por su identificador UUID: periodo, tipo, fecha, estatus y movimientos (cargos y abonos por cuenta).\")\n    public String consultarPoliza(\n            @ToolParam(description = \"Identificador UUID de la póliza\", required = true) String polizaId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_poliza\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/polizas/{id}\")\n                        .build(UUID.fromString(polizaId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve los estados financieros de un periodo. */\n    @Tool(name = \"consultar_estados_financieros\",\n          description = \"Devuelve la balanza de comprobación de un periodo contable: saldos por cuenta. El periodo es AAAA-MM.\")\n    public String consultarEstadosFinancieros(\n            @ToolParam(description = \"Periodo contable en formato AAAA-MM, por ejemplo 2026-09\", required = true) String periodo) {\n        RegistroHerramientasUsadas.registrar(\"consultar_estados_financieros\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/estados-financieros\")\n                        .queryParam(\"periodo\", periodo.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista las pólizas de un periodo. */\n    @Tool(name = \"listar_polizas\",\n          description = \"Lista las pólizas contables de un periodo: identificador, tipo, fecha, estatus y movimientos.\")\n    public String listarPolizas(\n            @ToolParam(description = \"Periodo contable en formato AAAA-MM, por ejemplo 2026-09\", required = true) String periodo) {\n        RegistroHerramientasUsadas.registrar(\"listar_polizas\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/polizas\")\n                        .queryParam(\"periodo\", periodo.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve el catálogo de cuentas. */\n    @Tool(name = \"consultar_catalogo_cuentas\",\n          description = \"Lista las cuentas contables activas del catálogo: código, nombre, tipo y naturaleza.\")\n    public String consultarCatalogoCuentas() {\n        RegistroHerramientasUsadas.registrar(\"consultar_catalogo_cuentas\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/cuentas\").build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasDocumentos.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas sobre documentos-cumplimiento-ms, por gateway-ms con el token del usuario.\n * Las de lectura solo consultan metadato: la descarga de archivos no se ofrece al modelo.\n * La eliminación no se ejecuta aquí: prepara una acción que el usuario confirma en la aplicación.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasDocumentos {\n\n    static final String RUTA_BASE = \"/documentos-cumplimiento-ms/v1\";\n    static final int LIMITE_MOTIVO = 300;\n    private static final String NO_DISPONIBLE = \"La eliminación de documentos no está disponible en este momento.\";\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasDocumentos(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones. */\n    public HerramientasDocumentos(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: devuelve los tipos de documento disponibles. */\n    @Tool(name = \"consultar_tipos_documento\",\n          description = \"Devuelve el catálogo de tipos de documento legal que acepta el sistema.\")\n    public String consultarTiposDocumento() {\n        RegistroHerramientasUsadas.registrar(\"consultar_tipos_documento\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/catalogos/tipos-documento\")\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: prepara la eliminación de un documento. Requiere confirmación del usuario. */\n    @Tool(name = \"solicitar_eliminacion_documento\",\n          description = \"Prepara la eliminación de un documento legal. NO lo elimina: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. No se puede eliminar un documento dentro de su \"\n                  + \"periodo de retención ni uno ya eliminado; en esos casos la aplicación lo rechaza al confirmar.\")\n    public String solicitarEliminacionDocumento(\n            @ToolParam(description = \"Identificador UUID del documento\", required = true) String documentoId,\n            @ToolParam(description = \"Motivo de la eliminación, obligatorio, de hasta 300 caracteres\",\n                       required = true) String motivo) {\n        RegistroHerramientasUsadas.registrar(\"solicitar_eliminacion_documento\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id;\n        try {\n            id = UUID.fromString(documentoId.trim());\n        } catch (IllegalArgumentException | NullPointerException e) {\n            return \"El identificador del documento no es válido.\";\n        }\n        String motivoLimpio = motivo == null ? \"\" : motivo.trim();\n        if (motivoLimpio.isEmpty()) {\n            return \"El motivo de la eliminación es obligatorio.\";\n        }\n        if (motivoLimpio.length() > LIMITE_MOTIVO) {\n            return \"El motivo no puede tener más de \" + LIMITE_MOTIVO + \" caracteres.\";\n        }\n        if (!existe(id)) {\n            return \"No encontré ese documento.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"documentoId\", id.toString());\n        cuerpo.put(\"motivo\", motivoLimpio);\n        String resumen = \"Eliminar documento \" + id + \" (motivo: \" + motivoLimpio + \")\";\n        AccionPendiente accion = acciones.preparar(usuarioActual(), AccionesPendientes.TIPO_DOCUMENTO_ELIMINAR,\n                aJson(cuerpo), resumen);\n        return FiltroDatosSensibles.redactar(\"Eliminación preparada, no ejecutada. \" + resumen\n                + \". accion_id: \" + accion.id() + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\")\n                .texto();\n    }\n\n    /** Indica si el documento existe. Si la consulta falla, lanza excepción. */\n    private boolean existe(UUID id) {\n        try {\n            gateway.get().uri(RUTA_BASE + \"/documentos/\" + id).retrieve().body(String.class);\n            return true;\n        } catch (HttpClientErrorException.NotFound e) {\n            return false;\n        }\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n\n    /** Herramienta del asistente: devuelve un documento. */\n    @Tool(name = \"consultar_documento\",\n          description = \"Devuelve los datos de un documento legal por su identificador UUID: título, tipo, área, fecha de vencimiento y versiones (número, hash y fecha). No devuelve el contenido del archivo.\")\n    public String consultarDocumento(\n            @ToolParam(description = \"Identificador UUID del documento\", required = true) String documentoId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_documento\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/documentos/{id}\")\n                        .build(UUID.fromString(documentoId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista los documentos que vencen en los próximos días. */\n    @Tool(name = \"consultar_documentos_por_vencer\",\n          description = \"Lista los documentos que vencen en los próximos N días.\")\n    public String consultarDocumentosPorVencer(\n            @ToolParam(description = \"Número de días hacia adelante, por ejemplo 30\", required = true) int dias) {\n        RegistroHerramientasUsadas.registrar(\"consultar_documentos_por_vencer\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/documentos/por-vencer\")\n                        .queryParam(\"dias\", dias)\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: busca documentos por texto en el título. */\n    @Tool(name = \"buscar_documentos\",\n          description = \"Busca documentos legales no eliminados cuyo título contiene el texto (sin distinguir \"\n                  + \"mayúsculas). Devuelve hasta 15 documentos por título, con tipo, área, vencimiento y versiones. \"\n                  + \"Pide al menos 3 caracteres.\")\n    public String buscarDocumentos(\n            @ToolParam(description = \"Texto que debe contener el título del documento (mínimo 3 caracteres)\",\n                       required = true) String texto) {\n        RegistroHerramientasUsadas.registrar(\"buscar_documentos\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/documentos\")\n                        .queryParam(\"titulo\", texto.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasFinanzas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.time.format.DateTimeParseException;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas sobre facturacion-pagos-ms, por gateway-ms con el token del usuario.\n * Las de lectura consultan datos; la de escritura solo prepara una acción que el usuario confirma en la aplicación.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasFinanzas {\n\n    static final String RUTA_BASE = \"/facturacion-pagos-ms/v1\";\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasFinanzas(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones. */\n    public HerramientasFinanzas(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: devuelve un comprobante. */\n    @Tool(name = \"consultar_comprobante\",\n          description = \"Devuelve un comprobante por su identificador UUID: folio, subtotal, IVA, total, estatus, \"\n                  + \"estatus de cobro, monto pagado, saldo y lista de pagos.\")\n    public String consultarComprobante(\n            @ToolParam(description = \"Identificador UUID del comprobante\", required = true) String comprobanteId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_comprobante\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/comprobantes/{id}\")\n                        .build(UUID.fromString(comprobanteId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: busca un comprobante por su folio exacto. */\n    @Tool(name = \"buscar_comprobante_por_folio\",\n          description = \"Devuelve un comprobante por su folio exacto (por ejemplo, el folio asignado al emitir).\")\n    public String buscarComprobantePorFolio(\n            @ToolParam(description = \"Folio exacto del comprobante\", required = true) String folio) {\n        RegistroHerramientasUsadas.registrar(\"buscar_comprobante_por_folio\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/comprobantes\")\n                        .queryParam(\"folio\", folio.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista los pagos a proveedores. */\n    @Tool(name = \"listar_pagos_proveedor\",\n          description = \"Lista los últimos 15 pagos registrados a proveedores, del más reciente al más antiguo: \"\n                  + \"monto, fecha de pago, referencia y la cuenta por pagar a la que pertenecen.\")\n    public String listarPagosProveedor() {\n        RegistroHerramientasUsadas.registrar(\"listar_pagos_proveedor\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/cuentas-por-pagar/pagos\")\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista los comprobantes pendientes de cobro. */\n    @Tool(name = \"listar_comprobantes_pendientes_cobro\",\n          description = \"Lista los últimos 15 comprobantes emitidos con saldo por cobrar, del más reciente al más \"\n                  + \"antiguo: folio, moneda, total, saldo y estatus de cobro (PENDIENTE o PARCIAL).\")\n    public String listarComprobantesPendientesCobro() {\n        RegistroHerramientasUsadas.registrar(\"listar_comprobantes_pendientes_cobro\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/comprobantes/pendientes-cobro\")\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve una cuenta por pagar. */\n    @Tool(name = \"consultar_cuenta_por_pagar\",\n          description = \"Devuelve una cuenta por pagar a proveedor por su identificador UUID: proveedor, monto, saldo y pagos.\")\n    public String consultarCuentaPorPagar(\n            @ToolParam(description = \"Identificador UUID de la cuenta por pagar\", required = true) String cuentaId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_cuenta_por_pagar\");\n        UUID id = identificador(cuentaId);\n        if (id == null) {\n            return \"El identificador de la cuenta por pagar no es válido.\";\n        }\n        try {\n            String cuerpo = gateway.get()\n                    .uri(RUTA_BASE + \"/cuentas-por-pagar/{id}\", id)\n                    .retrieve()\n                    .body(String.class);\n            return FiltroDatosSensibles.redactar(cuerpo).texto();\n        } catch (HttpClientErrorException.NotFound e) {\n            return \"No encontré esa cuenta por pagar.\";\n        }\n    }\n\n    /** Herramienta del asistente: prepara el registro de un pago sobre un comprobante. Requiere confirmación. */\n    @Tool(name = \"registrar_pago_comprobante\",\n          description = \"Prepara el registro de un cobro sobre un comprobante. NO lo registra: devuelve un resumen y un \"\n                  + \"accion_id. El usuario debe confirmarlo en la aplicación. Solo FINANZAS puede usarla.\")\n    public String registrarPagoComprobante(\n            @ToolParam(description = \"Identificador UUID del comprobante\", required = true) String comprobanteId,\n            @ToolParam(description = \"Monto mayor a cero, hasta 2 decimales\", required = true) String monto,\n            @ToolParam(description = \"Fecha del pago en formato AAAA-MM-DD; vacío para hoy\", required = false) String fechaPago,\n            @ToolParam(description = \"Referencia bancaria o de transferencia, de hasta 100 caracteres\", required = false) String referencia) {\n        RegistroHerramientasUsadas.registrar(\"registrar_pago_comprobante\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(comprobanteId);\n        if (id == null) {\n            return \"El identificador del comprobante no es válido.\";\n        }\n        BigDecimal cantidad = decimal(monto);\n        if (cantidad == null || cantidad.signum() <= 0) {\n            return \"El monto debe ser mayor a cero, con hasta 2 decimales.\";\n        }\n        LocalDate fecha = null;\n        if (fechaPago != null && !fechaPago.isBlank()) {\n            try {\n                fecha = LocalDate.parse(fechaPago.trim());\n            } catch (DateTimeParseException e) {\n                return \"La fecha debe tener formato AAAA-MM-DD.\";\n            }\n        }\n        if (referencia != null && referencia.trim().length() > 100) {\n            return \"La referencia no puede tener más de 100 caracteres.\";\n        }\n        try {\n            gateway.get().uri(RUTA_BASE + \"/comprobantes/{id}\", id).retrieve().body(String.class);\n        } catch (HttpClientErrorException.NotFound e) {\n            return \"No encontré ese comprobante.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"comprobanteId\", id.toString());\n        cuerpo.put(\"monto\", cantidad);\n        if (fecha != null) {\n            cuerpo.put(\"fechaPago\", fecha.toString());\n        }\n        if (referencia != null && !referencia.isBlank()) {\n            cuerpo.put(\"referencia\", referencia.trim());\n        }\n        // Clave única por acción: si el cobro se reintenta, facturación no lo aplica dos veces.\n        cuerpo.put(\"idempotencyKey\", java.util.UUID.randomUUID().toString());\n        String resumen = \"Registrar un cobro de \" + cantidad.toPlainString() + \" sobre el comprobante \" + id\n                + (fecha == null ? \"\" : \" con fecha \" + fecha);\n        AccionPendiente accion = acciones.preparar(usuarioActual(), AccionesPendientes.TIPO_COMPROBANTE_PAGO_REGISTRAR,\n                aJson(cuerpo), resumen);\n        return FiltroDatosSensibles.redactar(\"Cobro preparado, no registrado. \" + resumen + \". accion_id: \"\n                + accion.id() + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\").texto();\n    }\n\n    /** Número decimal de hasta 2 decimales y 12 dígitos enteros; null si no es válido. */\n    private static BigDecimal decimal(String valor) {\n        try {\n            BigDecimal numero = new BigDecimal(valor.trim());\n            if (numero.scale() > 2 || numero.precision() - numero.scale() > 12) {\n                return null;\n            }\n            return numero;\n        } catch (NumberFormatException | NullPointerException e) {\n            return null;\n        }\n    }\n\n    /** Convierte un texto en UUID. Lanza excepción si no tiene formato válido. */\n    private static UUID identificador(String valor) {\n        try {\n            return valor == null ? null : UUID.fromString(valor.trim());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasInventario.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.util.LinkedHashMap;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas sobre inventario-operaciones-ms, por gateway-ms con el token del usuario.\n * Las de lectura consultan datos; las de escritura solo preparan una acción que el usuario confirma en la aplicación.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasInventario {\n\n    static final String RUTA_BASE = \"/inventario-operaciones-ms/v1\";\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    private static final Set<String> TIPOS_MOVIMIENTO = Set.of(\"ENTRADA\", \"SALIDA\", \"AJUSTE\", \"RESERVA\");\n    private static final Set<String> TIPOS_ORDEN = Set.of(\"PRODUCCION\", \"SERVICIO\");\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasInventario(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones. */\n    public HerramientasInventario(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: devuelve las existencias de un artículo. */\n    @Tool(name = \"consultar_existencias\",\n          description = \"Devuelve las existencias de un artículo por almacén: cantidad, reservado y disponible. Requiere el identificador UUID del artículo.\")\n    public String consultarExistencias(\n            @ToolParam(description = \"Identificador UUID del artículo\", required = true) String articuloId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_existencias\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/existencias\")\n                        .queryParam(\"articulo\", UUID.fromString(articuloId.trim()))\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve la trazabilidad de un lote. */\n    @Tool(name = \"consultar_trazabilidad_lote\",\n          description = \"Devuelve los movimientos de un lote para trazabilidad: artículo, almacén, tipo y cantidad.\")\n    public String consultarTrazabilidadLote(\n            @ToolParam(description = \"Identificador del lote, tal como fue registrado\", required = true) String lote) {\n        RegistroHerramientasUsadas.registrar(\"consultar_trazabilidad_lote\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/lotes/{lote}/trazabilidad\")\n                        .build(lote.trim()))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista los artículos por debajo del mínimo. */\n    @Tool(name = \"listar_articulos_bajo_minimo\",\n          description = \"Lista hasta 15 artículos cuya existencia total está por debajo de su mínimo, del mayor \"\n                  + \"faltante al menor: SKU, nombre, unidad, mínimo, existencia y faltante.\")\n    public String listarArticulosBajoMinimo() {\n        RegistroHerramientasUsadas.registrar(\"listar_articulos_bajo_minimo\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/articulos/bajo-minimo\")\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: lista los movimientos de un artículo. */\n    @Tool(name = \"listar_movimientos_articulo\",\n          description = \"Lista los últimos 15 movimientos de inventario de un artículo, del más reciente al más \"\n                  + \"antiguo: tipo, cantidad, almacén, lote y referencia.\")\n    public String listarMovimientosArticulo(\n            @ToolParam(description = \"Identificador UUID del artículo\", required = true) String articuloId) {\n        RegistroHerramientasUsadas.registrar(\"listar_movimientos_articulo\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/movimientos\")\n                        .queryParam(\"articulo\", UUID.fromString(articuloId.trim()))\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: prepara el alta de un artículo. */\n    @Tool(name = \"crear_articulo\",\n          description = \"Prepara el alta de un artículo. NO lo crea: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo OPERACIONES puede usarla.\")\n    public String crearArticulo(\n            @ToolParam(description = \"SKU del artículo, de hasta 40 caracteres\", required = true) String sku,\n            @ToolParam(description = \"Nombre del artículo, de hasta 150 caracteres\", required = true) String nombre,\n            @ToolParam(description = \"Unidad de medida, de hasta 10 caracteres, por ejemplo PZA o KG\", required = true) String unidad,\n            @ToolParam(description = \"true si el artículo exige lote; false o vacío en otro caso\", required = false) String loteObligatorio,\n            @ToolParam(description = \"Existencia mínima para alertas, cero o positiva; vacío si no aplica\", required = false) String minimo) {\n        RegistroHerramientasUsadas.registrar(\"crear_articulo\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        if (vacio(sku) || sku.trim().length() > 40) {\n            return \"El SKU es obligatorio y de hasta 40 caracteres.\";\n        }\n        if (vacio(nombre) || nombre.trim().length() > 150) {\n            return \"El nombre es obligatorio y de hasta 150 caracteres.\";\n        }\n        if (vacio(unidad) || unidad.trim().length() > 10) {\n            return \"La unidad es obligatoria y de hasta 10 caracteres.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"sku\", sku.trim());\n        cuerpo.put(\"nombre\", nombre.trim());\n        cuerpo.put(\"unidad\", unidad.trim());\n        cuerpo.put(\"loteObligatorio\", \"true\".equalsIgnoreCase(loteObligatorio == null ? \"\" : loteObligatorio.trim()));\n        if (!vacio(minimo)) {\n            BigDecimal valor = decimal(minimo, 3, 9);\n            if (valor == null || valor.signum() < 0) {\n                return \"El mínimo debe ser cero o positivo, con hasta 3 decimales y 9 dígitos enteros.\";\n            }\n            cuerpo.put(\"minimo\", valor);\n        }\n        String resumen = \"Alta de artículo \" + sku.trim() + \" (\" + nombre.trim() + \", \" + unidad.trim() + \")\";\n        return guardar(AccionesPendientes.TIPO_ARTICULO_CREAR, cuerpo, resumen, \"Alta preparada, no creada.\");\n    }\n\n    /** Herramienta del asistente: prepara un movimiento de inventario. */\n    @Tool(name = \"registrar_movimiento_inventario\",\n          description = \"Prepara un movimiento de inventario: entrada, salida, ajuste o reserva. NO lo registra: devuelve \"\n                  + \"un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. Solo ALMACEN puede usarla.\")\n    public String registrarMovimientoInventario(\n            @ToolParam(description = \"Identificador UUID del artículo\", required = true) String articuloId,\n            @ToolParam(description = \"Identificador UUID del almacén\", required = true) String almacenId,\n            @ToolParam(description = \"Tipo: ENTRADA, SALIDA, AJUSTE o RESERVA\", required = true) String tipo,\n            @ToolParam(description = \"Cantidad mayor a cero, hasta 3 decimales\", required = true) String cantidad,\n            @ToolParam(description = \"Lote, opcional, de hasta 60 caracteres\", required = false) String lote,\n            @ToolParam(description = \"Referencia, opcional, de hasta 100 caracteres\", required = false) String referencia) {\n        RegistroHerramientasUsadas.registrar(\"registrar_movimiento_inventario\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID articulo = identificador(articuloId);\n        UUID almacen = identificador(almacenId);\n        if (articulo == null || almacen == null) {\n            return \"El identificador del artículo y del almacén deben ser UUID válidos.\";\n        }\n        String tipoNormalizado = normalizar(tipo);\n        if (!TIPOS_MOVIMIENTO.contains(tipoNormalizado)) {\n            return \"El tipo debe ser ENTRADA, SALIDA, AJUSTE o RESERVA.\";\n        }\n        BigDecimal cant = decimal(cantidad, 3, 9);\n        if (cant == null || cant.signum() <= 0) {\n            return \"La cantidad debe ser mayor a cero, con hasta 3 decimales y 9 dígitos enteros.\";\n        }\n        if (!vacio(lote) && lote.trim().length() > 60) {\n            return \"El lote no puede tener más de 60 caracteres.\";\n        }\n        if (!vacio(referencia) && referencia.trim().length() > 100) {\n            return \"La referencia no puede tener más de 100 caracteres.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"articuloId\", articulo.toString());\n        cuerpo.put(\"almacenId\", almacen.toString());\n        cuerpo.put(\"tipo\", tipoNormalizado);\n        cuerpo.put(\"cantidad\", cant);\n        if (!vacio(lote)) {\n            cuerpo.put(\"lote\", lote.trim());\n        }\n        if (!vacio(referencia)) {\n            cuerpo.put(\"referencia\", referencia.trim());\n        }\n        // Clave única por acción: si el movimiento se reintenta, inventario no lo aplica dos veces.\n        cuerpo.put(\"idempotencyKey\", java.util.UUID.randomUUID().toString());\n        String resumen = \"Movimiento \" + tipoNormalizado + \" de \" + cant.stripTrailingZeros().toPlainString()\n                + \" del artículo \" + articulo + \" en el almacén \" + almacen;\n        return guardar(AccionesPendientes.TIPO_MOVIMIENTO_REGISTRAR, cuerpo, resumen, \"Movimiento preparado, no registrado.\");\n    }\n\n    /** Herramienta del asistente: prepara una orden de operación de producción o de servicio. */\n    @Tool(name = \"crear_orden_operacion\",\n          description = \"Prepara una orden de operación de producción o de servicio. NO la crea: devuelve un resumen y un \"\n                  + \"accion_id. El usuario debe confirmarlo en la aplicación. Solo OPERACIONES puede usarla.\")\n    public String crearOrdenOperacion(\n            @ToolParam(description = \"Tipo de orden: PRODUCCION o SERVICIO\", required = true) String tipo,\n            @ToolParam(description = \"Cantidad objetivo mayor a cero, hasta 3 decimales\", required = true) String cantidadObjetivo) {\n        RegistroHerramientasUsadas.registrar(\"crear_orden_operacion\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        String tipoNormalizado = normalizar(tipo);\n        if (!TIPOS_ORDEN.contains(tipoNormalizado)) {\n            return \"El tipo debe ser PRODUCCION o SERVICIO.\";\n        }\n        BigDecimal objetivo = decimal(cantidadObjetivo, 3, 9);\n        if (objetivo == null || objetivo.signum() <= 0) {\n            return \"La cantidad objetivo debe ser mayor a cero, con hasta 3 decimales y 9 dígitos enteros.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"tipo\", tipoNormalizado);\n        cuerpo.put(\"cantidadObjetivo\", objetivo);\n        String resumen = \"Orden de operación \" + tipoNormalizado + \" por \" + objetivo.stripTrailingZeros().toPlainString();\n        return guardar(AccionesPendientes.TIPO_ORDEN_OPERACION_CREAR, cuerpo, resumen, \"Orden preparada, no creada.\");\n    }\n\n    /** Herramienta del asistente: prepara el alta de un almacén. */\n    @Tool(name = \"crear_almacen\",\n          description = \"Prepara el alta de un almacén. NO lo crea: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo ALMACEN puede usarla.\")\n    public String crearAlmacen(\n            @ToolParam(description = \"Nombre del almacén, de hasta 100 caracteres\", required = true) String nombre,\n            @ToolParam(description = \"Ubicación del almacén, de hasta 200 caracteres\", required = true) String ubicacion) {\n        RegistroHerramientasUsadas.registrar(\"crear_almacen\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        if (vacio(nombre) || nombre.trim().length() > 100) {\n            return \"El nombre es obligatorio y de hasta 100 caracteres.\";\n        }\n        if (vacio(ubicacion) || ubicacion.trim().length() > 200) {\n            return \"La ubicación es obligatoria y de hasta 200 caracteres.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"nombre\", nombre.trim());\n        cuerpo.put(\"ubicacion\", ubicacion.trim());\n        return guardar(AccionesPendientes.TIPO_ALMACEN_CREAR, cuerpo,\n                \"Alta de almacén \" + nombre.trim(), \"Alta preparada, no creada.\");\n    }\n\n    /** Guarda la acción pendiente del usuario y devuelve un texto con su identificador. */\n    private String guardar(String tipo, Map<String, Object> cuerpo, String resumen, String encabezado) {\n        AccionPendiente accion = acciones.preparar(usuarioActual(), tipo, aJson(cuerpo), resumen);\n        return FiltroDatosSensibles.redactar(encabezado + \" \" + resumen + \". accion_id: \" + accion.id()\n                + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\").texto();\n    }\n\n    /** Número decimal con la escala y los dígitos enteros máximos; null si no es válido. */\n    private static BigDecimal decimal(String valor, int escala, int enteros) {\n        try {\n            BigDecimal numero = new BigDecimal(valor.trim());\n            if (numero.scale() > escala || numero.precision() - numero.scale() > enteros) {\n                return null;\n            }\n            return numero;\n        } catch (NumberFormatException | NullPointerException e) {\n            return null;\n        }\n    }\n\n    /** Convierte un texto en UUID. Devuelve nulo si el valor es nulo. */\n    private static UUID identificador(String valor) {\n        try {\n            return valor == null ? null : UUID.fromString(valor.trim());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n\n    /** Indica si el texto es nulo o está en blanco. */\n    private static boolean vacio(String valor) {\n        return valor == null || valor.isBlank();\n    }\n\n    /** Quita espacios y pasa el texto a mayúsculas. Un valor nulo se convierte en cadena vacía. */\n    private static String normalizar(String valor) {\n        return valor == null ? \"\" : valor.trim().toUpperCase(java.util.Locale.ROOT);\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasPoliticas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static java.util.stream.Collectors.joining;\n\nimport java.util.List;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\n\nimport com.mx.josesaid.develop.nexus.application.RecuperadorPoliticas;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Busca en las políticas internas solo lo que los roles del usuario pueden ver.\n * El resultado trae la fuente de cada fragmento para que la respuesta pueda citarla.\n */\npublic final class HerramientasPoliticas {\n\n    static final int LIMITE = 5;\n\n    private final RecuperadorPoliticas recuperador;\n\n    /** Recibe el recuperador de políticas. */\n    public HerramientasPoliticas(RecuperadorPoliticas recuperador) {\n        this.recuperador = recuperador;\n    }\n\n    /** Herramienta del asistente: busca en las políticas de la empresa la respuesta a una pregunta. */\n    @Tool(name = \"consultar_politicas\",\n          description = \"Busca en las políticas internas de la empresa que tu rol puede consultar y devuelve los fragmentos relevantes con su fuente. \"\n                  + \"Úsala para preguntas sobre reglas, límites o procesos internos. \"\n                  + \"Cita cada dato con la fuente entre corchetes, por ejemplo [título, regla 2]. \"\n                  + \"No afirmes una política que no aparezca en el resultado.\")\n    public String consultarPoliticas(\n            @ToolParam(description = \"Pregunta sobre la política que se quiere consultar\", required = true) String pregunta) {\n        RegistroHerramientasUsadas.registrar(\"consultar_politicas\");\n        List<ResultadoPolitica> resultados = recuperador.buscar(pregunta, AlcanceHerramientas.rolesDelUsuario(), LIMITE);\n        if (resultados.isEmpty()) {\n            return \"No encontré políticas vigentes para tus roles que respondan a esa pregunta.\";\n        }\n        String texto = resultados.stream()\n                .map(r -> \"[\" + r.titulo() + \", regla \" + (r.indice() + 1) + \"] \" + r.texto())\n                .collect(joining(\"\\n\"));\n        return FiltroDatosSensibles.redactar(texto).texto();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasPolizas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.function.Supplier;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.application.ServicioPolizas;\n\n/** Propone una póliza por MCP. Nunca la registra: devuelve el código que se necesita para confirmarla. */\npublic final class HerramientasPolizas {\n\n    /** Se resuelve al usarla: evita un ciclo de arranque con el modelo de chat, que también usa herramientas. */\n    private final Supplier<ServicioPolizas> servicio;\n    private final CodigoConfirmacion codigos;\n\n    /** Recibe un proveedor del servicio de pólizas. Así el servicio puede no existir todavía al crear la herramienta. */\n    public HerramientasPolizas(Supplier<ServicioPolizas> servicio, CodigoConfirmacion codigos) {\n        this.servicio = servicio;\n        this.codigos = codigos;\n    }\n\n    /** Herramienta del asistente: pide al servicio una sugerencia de póliza. Solo prepara la acción; el contador debe confirmarla. */\n    @Tool(name = \"sugerir_poliza\",\n          description = \"Propone una póliza contable a partir de la descripción de una operación. No la registra. \"\n                  + \"Devuelve el identificador de la acción y un código de confirmación de una sola vez; \"\n                  + \"la póliza solo se registra cuando se confirma con confirmar_accion usando ese código.\")\n    public String sugerirPoliza(\n            @ToolParam(description = \"Descripción de la operación contable, con montos y moneda\", required = true) String descripcion) {\n        RegistroHerramientasUsadas.registrar(\"sugerir_poliza\");\n        AccionPendiente accion = servicio.get().preparar(usuarioActual(), descripcion);\n        return \"Acción \" + accion.id() + \" preparada, vence \" + accion.expiraUtc() + \". \"\n                + accion.resumen() + \". Código de confirmación: \" + codigos.generar(accion.id(), accion.usuario())\n                + \". Nada se ha registrado todavía.\";\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasReportes.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.time.format.DateTimeParseException;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.regex.Pattern;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas de solo lectura sobre reportes-ejecutivos-ms.\n * Llaman por gateway-ms con el token del usuario; el servicio aplica sus propios permisos.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasReportes {\n\n    static final String RUTA_BASE = \"/reportes-ejecutivos-ms/v1\";\n\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    /** Áreas válidas para consultar reportes ejecutivos. */\n    private static final List<String> AREAS = List.of(\"VENTAS_ATENCION_CLIENTES\", \"FINANZAS_CONTABILIDAD\",\n            \"OPERACIONES\", \"COMPRAS_PROVEEDORES\", \"ADMINISTRACION_LEGAL\", \"DIRECCION_GENERAL\");\n    private static final Pattern PERIODO = Pattern.compile(\"^(\\\\d{4}-(0[1-9]|1[0-2])|\\\\d{4}-Q[1-4]|\\\\d{4})$\");\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasReportes(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Recibe el cliente del gateway y el registro de acciones. */\n    public HerramientasReportes(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: devuelve los indicadores de un área y periodo. */\n    @Tool(name = \"consultar_indicadores\",\n          description = \"Devuelve los indicadores consolidados de un periodo. El periodo es AAAA-MM, AAAA-Qn o AAAA.\")\n    public String consultarIndicadores(\n            @ToolParam(description = \"Periodo: AAAA-MM, AAAA-Q1..Q4 o AAAA\", required = true) String periodo,\n            @ToolParam(description = \"Área opcional. Valores válidos: VENTAS_ATENCION_CLIENTES, FINANZAS_CONTABILIDAD, OPERACIONES, COMPRAS_PROVEEDORES, ADMINISTRACION_LEGAL, DIRECCION_GENERAL. Vacío para todas.\",\n                       required = false) String area) {\n        RegistroHerramientasUsadas.registrar(\"consultar_indicadores\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> {\n                    var uri = constructor.path(RUTA_BASE + \"/indicadores\").queryParam(\"periodo\", periodo);\n                    if (area != null && !area.isBlank()) {\n                        uri.queryParam(\"area\", area.trim().toUpperCase());\n                    }\n                    return uri.build();\n                })\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve un reporte ejecutivo del área y periodo indicados. */\n    @Tool(name = \"consultar_reporte\",\n          description = \"Devuelve el reporte ejecutivo de un periodo (AAAA-MM, AAAA-Qn o AAAA) con su estatus.\")\n    public String consultarReporte(\n            @ToolParam(description = \"Periodo: AAAA-MM, AAAA-Q1..Q4 o AAAA\", required = true) String periodo) {\n        RegistroHerramientasUsadas.registrar(\"consultar_reporte\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/reportes/{periodo}\", periodo)\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: prepara el registro de un indicador. Requiere confirmación del usuario. */\n    @Tool(name = \"registrar_indicador\",\n          description = \"Prepara el registro de un indicador de un área para un periodo. NO lo registra: devuelve \"\n                  + \"un resumen y un accion_id. El usuario debe confirmarlo en la aplicación. Solo DIRECCION puede usarla.\")\n    public String registrarIndicador(\n            @ToolParam(description = \"Área. Valores válidos: VENTAS_ATENCION_CLIENTES, FINANZAS_CONTABILIDAD, OPERACIONES, COMPRAS_PROVEEDORES, ADMINISTRACION_LEGAL, DIRECCION_GENERAL\",\n                       required = true) String area,\n            @ToolParam(description = \"Nombre del indicador\", required = true) String nombre,\n            @ToolParam(description = \"Periodo: AAAA-MM, AAAA-Q1..Q4 o AAAA\", required = true) String periodo,\n            @ToolParam(description = \"Valor numérico del indicador\", required = true) String valor,\n            @ToolParam(description = \"Momento en que se actualizó la fuente, en ISO-8601 UTC, por ejemplo 2026-11-08T00:00:00Z\",\n                       required = true) String fuenteActualizadaUtc) {\n        RegistroHerramientasUsadas.registrar(\"registrar_indicador\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        String areaLimpia = area == null ? \"\" : area.trim().toUpperCase();\n        if (!AREAS.contains(areaLimpia)) {\n            return \"El área no es válida. Valores: \" + String.join(\", \", AREAS) + \".\";\n        }\n        if (nombre == null || nombre.isBlank()) {\n            return \"El nombre del indicador es obligatorio.\";\n        }\n        String periodoLimpio = periodo == null ? \"\" : periodo.trim();\n        if (!PERIODO.matcher(periodoLimpio).matches()) {\n            return \"El periodo debe ser AAAA-MM, AAAA-Qn o AAAA.\";\n        }\n        BigDecimal numero;\n        try {\n            numero = new BigDecimal(valor.trim());\n        } catch (NumberFormatException | NullPointerException e) {\n            return \"El valor debe ser numérico.\";\n        }\n        Instant fuente;\n        try {\n            fuente = Instant.parse(fuenteActualizadaUtc.trim());\n        } catch (DateTimeParseException | NullPointerException e) {\n            return \"La fecha de actualización debe estar en ISO-8601 UTC, por ejemplo 2026-11-08T00:00:00Z.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"area\", areaLimpia);\n        cuerpo.put(\"nombre\", nombre.trim());\n        cuerpo.put(\"periodo\", periodoLimpio);\n        cuerpo.put(\"valor\", numero);\n        cuerpo.put(\"fuenteActualizadaUtc\", fuente.toString());\n        String resumen = \"Registrar indicador \" + nombre.trim() + \" de \" + areaLimpia + \" (\" + periodoLimpio\n                + \") = \" + numero.toPlainString();\n        AccionPendiente accion = acciones.preparar(usuarioActual(), AccionesPendientes.TIPO_INDICADOR_REGISTRAR,\n                aJson(cuerpo), resumen);\n        return FiltroDatosSensibles.redactar(\"Registro preparado, no ejecutado. \" + resumen\n                + \". accion_id: \" + accion.id() + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\")\n                .texto();\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        return SecurityContextHolder.getContext().getAuthentication().getName();\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasUsuarios.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramienta de solo lectura sobre usuarios-accesos-ms, por gateway-ms con el token del usuario.\n * Solo ADMIN puede consultar usuarios. La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasUsuarios {\n\n    static final String RUTA_BASE = \"/usuarios-accesos-ms/v1\";\n\n    /** Roles que un alta puede asignar. JEFE_AREA no se asigna desde el alta. */\n    static final Set<String> ROLES_ALTA = Set.of(\"ADMIN\", \"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\",\n            \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\");\n\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n    private final CodigoConfirmacion codigos;\n\n    /** Versión sin registro de acciones ni códigos: solo permite consultar. */\n    public HerramientasUsuarios(RestClient gateway) {\n        this(gateway, null, null);\n    }\n\n    /** Recibe el cliente del gateway, el registro de acciones y el generador de códigos. Las altas se confirman con código. */\n    public HerramientasUsuarios(RestClient gateway, AccionesPendientes acciones, CodigoConfirmacion codigos) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n        this.codigos = codigos;\n    }\n\n    /** Herramienta del asistente: devuelve los datos de un usuario. No expone contraseñas. */\n    @Tool(name = \"consultar_usuario\",\n          description = \"Devuelve los datos de un usuario por su identificador UUID: correo y nombre enmascarados, estatus, roles y área.\")\n    public String consultarUsuario(\n            @ToolParam(description = \"Identificador UUID del usuario\", required = true) String usuarioId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_usuario\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/usuarios/{id}\")\n                        .build(UUID.fromString(usuarioId.trim())))\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /**\n     * Prepara un alta de usuario. No crea nada ni recibe contraseña: el administrador la escribe en la\n     * pantalla de altas, que la envía directo a usuarios-accesos. Nexus solo recibe el código de confirmación.\n     */\n    @Tool(name = \"preparar_alta_usuario\",\n          description = \"Prepara el alta de un usuario nuevo. No crea el usuario y no pide contraseña: \"\n                  + \"devuelve el identificador de la acción y un código de confirmación. \"\n                  + \"El administrador completa el alta en la pantalla de altas, donde escribe la contraseña temporal.\")\n    public String prepararAltaUsuario(\n            @ToolParam(description = \"Correo electrónico del usuario nuevo\", required = true) String correo,\n            @ToolParam(description = \"Nombre completo del usuario nuevo\", required = true) String nombreCompleto,\n            @ToolParam(description = \"Roles separados por coma. Valores: ADMIN, FINANZAS, CONTADOR, VENTAS, COMPRAS, \"\n                    + \"ALMACEN, OPERACIONES, CALIDAD, DIRECCION, LEGAL\", required = true) String roles) {\n        RegistroHerramientasUsadas.registrar(\"preparar_alta_usuario\");\n        String correoLimpio = correo == null ? \"\" : correo.trim();\n        String nombreLimpio = nombreCompleto == null ? \"\" : nombreCompleto.trim();\n        List<String> rolesLista = roles == null ? List.of()\n                : Arrays.stream(roles.split(\",\")).map(String::trim).filter(r -> !r.isEmpty()).toList();\n        if (!correoLimpio.matches(\"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\")) {\n            return \"El correo no es válido. Pide el correo completo del usuario.\";\n        }\n        if (nombreLimpio.isEmpty()) {\n            return \"Falta el nombre completo del usuario.\";\n        }\n        if (rolesLista.isEmpty() || !ROLES_ALTA.containsAll(rolesLista)) {\n            return \"Roles inválidos. Usa solo: \" + String.join(\", \", ROLES_ALTA) + \".\";\n        }\n        String usuario = SecurityContextHolder.getContext().getAuthentication().getName();\n        String payload = aJson(Map.of(\"correo\", correoLimpio, \"nombreCompleto\", nombreLimpio, \"roles\", rolesLista));\n        AccionPendiente accion = acciones.preparar(usuario, AccionesPendientes.TIPO_USUARIO_ALTA, payload,\n                \"Alta de usuario \" + correoLimpio + \" con roles \" + String.join(\", \", rolesLista));\n        return \"Alta preparada: acción \" + accion.id() + \", vence \" + accion.expiraUtc()\n                + \". Código de confirmación: \" + codigos.generar(accion.id(), accion.usuario())\n                + \". El usuario aún no existe. Completa el alta en /usuarios/altas/\" + accion.id()\n                + \", donde se escribe la contraseña temporal.\";\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> datos) {\n        try {\n            return JSON.writeValueAsString(datos);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar el alta\", e);\n        }\n    }\n\n    /** Herramienta del asistente: lista los usuarios de la empresa. */\n    @Tool(name = \"listar_usuarios\",\n          description = \"Lista los últimos 15 usuarios, del más reciente al más antiguo: correo y nombre enmascarados, \"\n                  + \"estatus, roles y área. Solo para administradores.\")\n    public String listarUsuarios() {\n        RegistroHerramientasUsadas.registrar(\"listar_usuarios\");\n        String cuerpo = gateway.get()\n                .uri(RUTA_BASE + \"/usuarios\")\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasVentas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.OffsetDateTime;\nimport java.time.format.DateTimeParseException;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\nimport java.util.UUID;\n\nimport org.springframework.ai.tool.annotation.Tool;\nimport org.springframework.ai.tool.annotation.ToolParam;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.comun.filtro.FiltroDatosSensibles;\n\n/**\n * Herramientas de solo lectura sobre pedidos-ventas-ms, por gateway-ms con el token del usuario.\n * La respuesta se redacta antes de volver al modelo.\n */\npublic final class HerramientasVentas {\n\n    static final String RUTA_BASE = \"/pedidos-ventas-ms/v1\";\n    static final String RUTA_CLIENTES_BASE = \"/clientes-ms/v1\";\n\n    private static final String NO_DISPONIBLE = \"La preparación de acciones no está disponible en este momento.\";\n    private static final Set<String> FUENTES_PROSPECTO = Set.of(\"CAMPANA\", \"REFERIDO\", \"EVENTO\");\n    private static final Set<String> MOTIVOS_CANCELACION = Set.of(\"CANCELACION_CLIENTE\", \"ERROR_CAPTURA\");\n    private static final Set<String> CANALES = Set.of(\"WEB\", \"TIENDA\", \"TELEFONO\");\n    private static final Set<String> TASAS_IVA = Set.of(\"IVA_GENERAL\", \"IVA_FRONTERIZO\", \"IVA_EXENTO\");\n    private static final Set<String> DESTINOS_PROSPECTO = Set.of(\"CONTACTADO\", \"CALIFICADO\", \"PERDIDO\");\n    /** Mismas transiciones que el dominio de clientes-ms; CONVERTIDO no se alcanza por cambio de estatus. */\n    private static final Map<String, Set<String>> TRANSICIONES_PROSPECTO = Map.of(\n            \"NUEVO\", Set.of(\"CONTACTADO\", \"PERDIDO\"),\n            \"CONTACTADO\", Set.of(\"CALIFICADO\", \"PERDIDO\"),\n            \"CALIFICADO\", Set.of(\"PERDIDO\"));\n    private static final Set<String> ROLES_CONTACTO = Set.of(\"COMPRAS\", \"PAGOS\", \"ASISTENCIA\");\n    private static final Set<String> TIPOS_INTERACCION = Set.of(\"LLAMADA\", \"CORREO\", \"VISITA\");\n\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    private final RestClient gateway;\n    private final AccionesPendientes acciones;\n\n    /** Versión sin registro de acciones: solo permite consultar. */\n    public HerramientasVentas(RestClient gateway) {\n        this(gateway, null);\n    }\n\n    /** Con acciones nulas la herramienta de preparar pedidos responde que no está disponible. */\n    public HerramientasVentas(RestClient gateway, AccionesPendientes acciones) {\n        this.gateway = gateway;\n        this.acciones = acciones;\n    }\n\n    /** Herramienta del asistente: lista pedidos, opcionalmente filtrados por estatus. */\n    @Tool(name = \"consultar_pedidos\",\n          description = \"Lista pedidos de venta. Filtros opcionales: estatus (BORRADOR, CONFIRMADO, ENTREGADO, CANCELADO), \"\n                  + \"canal (WEB, TIENDA, TELEFONO) y clienteId (UUID). Vacío para no filtrar.\")\n    public String consultarPedidos(\n            @ToolParam(description = \"Estatus del pedido: BORRADOR, CONFIRMADO, ENTREGADO o CANCELADO. Vacío para todos.\",\n                       required = false) String estatus,\n            @ToolParam(description = \"Canal de venta: WEB, TIENDA o TELEFONO. Vacío para todos.\", required = false) String canal,\n            @ToolParam(description = \"Identificador UUID del cliente. Vacío para todos.\", required = false) String clienteId) {\n        RegistroHerramientasUsadas.registrar(\"consultar_pedidos\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> {\n                    var uri = constructor.path(RUTA_BASE + \"/pedidos\");\n                    if (estatus != null && !estatus.isBlank()) {\n                        uri.queryParam(\"estatus\", estatus.trim().toUpperCase());\n                    }\n                    if (canal != null && !canal.isBlank()) {\n                        uri.queryParam(\"canal\", canal.trim().toUpperCase());\n                    }\n                    if (clienteId != null && !clienteId.isBlank()) {\n                        uri.queryParam(\"clienteId\", clienteId.trim());\n                    }\n                    return uri.build();\n                })\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: resumen de ventas de un periodo. */\n    @Tool(name = \"resumen_ventas\",\n          description = \"Devuelve el resumen de ventas de un mes: número de pedidos y ventas por moneda. El mes es AAAA-MM.\")\n    public String resumenVentas(\n            @ToolParam(description = \"Mes en formato AAAA-MM, por ejemplo 2026-09\", required = true) String mes) {\n        RegistroHerramientasUsadas.registrar(\"resumen_ventas\");\n        String cuerpo = gateway.get()\n                .uri(constructor -> constructor.path(RUTA_BASE + \"/metricas/ventas\")\n                        .queryParam(\"mes\", mes.trim())\n                        .build())\n                .retrieve()\n                .body(String.class);\n        return FiltroDatosSensibles.redactar(cuerpo).texto();\n    }\n\n    /** Herramienta del asistente: devuelve una cotización. */\n    @Tool(name = \"obtener_cotizacion\",\n          description = \"Devuelve una cotización por su identificador UUID: cliente, líneas, totales, vigencia y estatus.\")\n    public String obtenerCotizacion(\n            @ToolParam(description = \"Identificador UUID de la cotización\", required = true) String cotizacionId) {\n        RegistroHerramientasUsadas.registrar(\"obtener_cotizacion\");\n        UUID id = identificador(cotizacionId);\n        if (id == null) {\n            return \"El identificador de la cotización no es válido.\";\n        }\n        return lectura(RUTA_BASE + \"/cotizaciones/\" + id, \"No encontré esa cotización.\");\n    }\n\n    /** Herramienta del asistente: devuelve un pedido. */\n    @Tool(name = \"obtener_pedido\",\n          description = \"Devuelve un pedido por su identificador UUID: cliente, canal, líneas, totales y estatus.\")\n    public String obtenerPedido(\n            @ToolParam(description = \"Identificador UUID del pedido\", required = true) String pedidoId) {\n        RegistroHerramientasUsadas.registrar(\"obtener_pedido\");\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        return lectura(RUTA_BASE + \"/pedidos/\" + id, \"No encontré ese pedido.\");\n    }\n\n    /** Herramienta del asistente: devuelve las tasas de IVA vigentes. */\n    @Tool(name = \"consultar_tasas_iva\",\n          description = \"Devuelve las tasas de IVA que acepta el sistema para los pedidos y cotizaciones.\")\n    public String consultarTasasIva() {\n        RegistroHerramientasUsadas.registrar(\"consultar_tasas_iva\");\n        return lectura(RUTA_BASE + \"/catalogos/tasas-iva\", \"No encontré el catálogo de tasas de IVA.\");\n    }\n\n    /** Herramienta del asistente: devuelve las monedas disponibles. */\n    @Tool(name = \"consultar_monedas\",\n          description = \"Devuelve las monedas que acepta el sistema para pedidos y cotizaciones.\")\n    public String consultarMonedas() {\n        RegistroHerramientasUsadas.registrar(\"consultar_monedas\");\n        return lectura(RUTA_BASE + \"/catalogos/monedas\", \"No encontré el catálogo de monedas.\");\n    }\n\n    /** Lectura de solo consulta: el cuerpo se redacta antes de volver al modelo. */\n    private String lectura(String ruta, String noEncontrado) {\n        try {\n            String cuerpo = gateway.get()\n                    .uri(ruta)\n                    .retrieve()\n                    .body(String.class);\n            return FiltroDatosSensibles.redactar(cuerpo).texto();\n        } catch (HttpClientErrorException.NotFound e) {\n            return noEncontrado;\n        }\n    }\n\n    /** Herramienta del asistente: prepara un pedido borrador. No lo crea hasta que el usuario lo confirme. */\n    @Tool(name = \"preparar_pedido_borrador\",\n          description = \"Prepara un pedido de venta en borrador. NO lo guarda: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación antes de que se guarde. Úsala solo cuando el usuario pida crear un pedido.\")\n    public String prepararPedidoBorrador(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Canal de venta: WEB, TIENDA o TELEFONO\", required = true) String canal,\n            @ToolParam(description = \"Moneda ISO, por ejemplo MXN\", required = true) String moneda,\n            @ToolParam(description = \"Tasa de IVA: IVA_GENERAL, IVA_FRONTERIZO o IVA_EXENTO\", required = true) String tasaIva,\n            @ToolParam(description = \"Identificador UUID del producto\", required = true) String productoId,\n            @ToolParam(description = \"Descripción de la línea. Puede ir vacía.\", required = false) String descripcion,\n            @ToolParam(description = \"Cantidad entera mayor a cero\", required = true) int cantidad,\n            @ToolParam(description = \"Precio unitario en la moneda del pedido\", required = true) String precioUnitario) {\n        RegistroHerramientasUsadas.registrar(\"preparar_pedido_borrador\");\n        if (acciones == null) {\n            return \"La preparación de pedidos no está disponible en este momento.\";\n        }\n        if (cantidad <= 0) {\n            return \"La cantidad debe ser mayor a cero.\";\n        }\n        Map<String, Object> linea = new LinkedHashMap<>();\n        linea.put(\"productoId\", productoId.trim());\n        linea.put(\"descripcion\", descripcion == null || descripcion.isBlank() ? \"Artículo\" : descripcion.trim());\n        linea.put(\"cantidad\", cantidad);\n        linea.put(\"precioUnitario\", precioUnitario.trim());\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", clienteId.trim());\n        cuerpo.put(\"canal\", canal.trim().toUpperCase());\n        cuerpo.put(\"moneda\", moneda.trim().toUpperCase());\n        cuerpo.put(\"tasaIva\", tasaIva.trim().toUpperCase());\n        cuerpo.put(\"lineas\", List.of(linea));\n        String payload = aJson(cuerpo);\n        String resumen = \"Pedido en borrador para el cliente \" + clienteId.trim() + \": \" + cantidad + \" × \"\n                + productoId.trim() + \" a \" + precioUnitario.trim() + \" \" + moneda.trim().toUpperCase()\n                + \" (\" + canal.trim().toUpperCase() + \", \" + tasaIva.trim().toUpperCase() + \")\";\n        AccionPendiente accion = acciones.preparar(usuarioActual(), AccionesPendientes.TIPO_PEDIDO_BORRADOR,\n                payload, resumen);\n        return FiltroDatosSensibles.redactar(\"Pedido preparado, no guardado. \" + resumen\n                + \". accion_id: \" + accion.id() + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\")\n                .texto();\n    }\n\n    /** Herramienta del asistente: prepara un prospecto borrador para su confirmación. */\n    @Tool(name = \"crear_prospecto_borrador\",\n          description = \"Prepara un prospecto nuevo. NO lo guarda: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Úsala solo cuando el usuario pida registrar un prospecto.\")\n    public String crearProspectoBorrador(\n            @ToolParam(description = \"Nombre del prospecto\", required = true) String nombre,\n            @ToolParam(description = \"Correo electrónico del prospecto\", required = true) String correo,\n            @ToolParam(description = \"RFC del prospecto. Vacío si no se conoce.\", required = false) String rfc,\n            @ToolParam(description = \"Fuente del prospecto: CAMPANA, REFERIDO o EVENTO\", required = true) String fuente) {\n        RegistroHerramientasUsadas.registrar(\"crear_prospecto_borrador\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        String fuenteNormalizada = fuente == null ? \"\" : fuente.trim().toUpperCase();\n        if (!FUENTES_PROSPECTO.contains(fuenteNormalizada)) {\n            return \"La fuente debe ser CAMPANA, REFERIDO o EVENTO.\";\n        }\n        if (nombre == null || nombre.isBlank() || correo == null || !correo.contains(\"@\")) {\n            return \"Indica el nombre y un correo válido del prospecto.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"nombre\", nombre.trim());\n        cuerpo.put(\"correo\", correo.trim());\n        if (rfc != null && !rfc.isBlank()) {\n            cuerpo.put(\"rfc\", rfc.trim().toUpperCase());\n        }\n        cuerpo.put(\"fuente\", fuenteNormalizada);\n        String resumen = \"Prospecto nuevo, fuente \" + fuenteNormalizada;\n        return guardarAccion(AccionesPendientes.TIPO_PROSPECTO_BORRADOR, aJson(cuerpo), resumen,\n                \"Prospecto preparado, no guardado.\");\n    }\n\n    /** Herramienta del asistente: prepara la confirmación de un pedido. */\n    @Tool(name = \"confirmar_pedido\",\n          description = \"Prepara la confirmación de un pedido en borrador. NO lo confirma: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String confirmarPedido(\n            @ToolParam(description = \"Identificador UUID del pedido en borrador\", required = true) String pedidoId) {\n        RegistroHerramientasUsadas.registrar(\"confirmar_pedido\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        JsonNode pedido = pedido(id);\n        if (pedido == null) {\n            return \"No encontré ese pedido.\";\n        }\n        String estatus = pedido.path(\"estatus\").asText();\n        if (!\"BORRADOR\".equals(estatus)) {\n            return \"El pedido está en estatus \" + estatus + \"; solo un pedido en borrador puede confirmarse.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"pedidoId\", id.toString());\n        String resumen = \"Confirmar pedido \" + id + \" (estatus actual BORRADOR)\";\n        return guardarAccion(AccionesPendientes.TIPO_PEDIDO_CONFIRMAR, aJson(cuerpo), resumen,\n                \"Confirmación preparada, no ejecutada.\");\n    }\n\n    /** Herramienta del asistente: prepara la cancelación de un pedido. */\n    @Tool(name = \"cancelar_pedido\",\n          description = \"Prepara la cancelación de un pedido en borrador o confirmado. NO lo cancela: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Los motivos válidos son CANCELACION_CLIENTE o ERROR_CAPTURA.\")\n    public String cancelarPedido(\n            @ToolParam(description = \"Identificador UUID del pedido\", required = true) String pedidoId,\n            @ToolParam(description = \"Motivo: CANCELACION_CLIENTE o ERROR_CAPTURA\", required = true) String motivo) {\n        RegistroHerramientasUsadas.registrar(\"cancelar_pedido\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        String motivoNormalizado = motivo == null ? \"\" : motivo.trim().toUpperCase();\n        if (!MOTIVOS_CANCELACION.contains(motivoNormalizado)) {\n            return \"El motivo debe ser CANCELACION_CLIENTE o ERROR_CAPTURA.\";\n        }\n        JsonNode pedido = pedido(id);\n        if (pedido == null) {\n            return \"No encontré ese pedido.\";\n        }\n        String estatus = pedido.path(\"estatus\").asText();\n        if (!\"BORRADOR\".equals(estatus) && !\"CONFIRMADO\".equals(estatus)) {\n            return \"El pedido está en estatus \" + estatus + \"; solo un pedido en borrador o confirmado puede cancelarse.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"pedidoId\", id.toString());\n        cuerpo.put(\"motivo\", motivoNormalizado);\n        String resumen = \"Cancelar pedido \" + id + \" por \" + motivoNormalizado + \" (estatus actual \" + estatus + \")\";\n        return guardarAccion(AccionesPendientes.TIPO_PEDIDO_CANCELAR, aJson(cuerpo), resumen,\n                \"Cancelación preparada, no ejecutada.\");\n    }\n\n    /** Herramienta del asistente: prepara el registro de la entrega de un pedido. Esa entrega descuenta inventario al ejecutarse. */\n    @Tool(name = \"registrar_entrega_pedido\",\n          description = \"Prepara la entrega de un pedido confirmado. NO la registra: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación. Solo ALMACEN y DIRECCION pueden usarla.\")\n    public String registrarEntregaPedido(\n            @ToolParam(description = \"Identificador UUID del pedido confirmado\", required = true) String pedidoId) {\n        RegistroHerramientasUsadas.registrar(\"registrar_entrega_pedido\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"pedidoId\", id.toString());\n        return guardarAccion(AccionesPendientes.TIPO_PEDIDO_ENTREGAR, aJson(cuerpo),\n                \"Registrar entrega del pedido \" + id, \"Entrega preparada, no registrada.\");\n    }\n\n    /** Guarda la acción pendiente del usuario y devuelve un texto con su identificador. */\n    private String guardarAccion(String tipo, String payload, String resumen, String encabezado) {\n        AccionPendiente accion = acciones.preparar(usuarioActual(), tipo, payload, resumen);\n        return FiltroDatosSensibles.redactar(encabezado + \" \" + resumen\n                + \". accion_id: \" + accion.id() + \". Vence en 10 minutos; el usuario debe confirmarlo en la aplicación.\")\n                .texto();\n    }\n\n    /** Herramienta del asistente: prepara el envío de una cotización al cliente. */\n    @Tool(name = \"enviar_cotizacion\",\n          description = \"Prepara el envío de una cotización en borrador. NO la envía: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String enviarCotizacion(\n            @ToolParam(description = \"Identificador UUID de la cotización en borrador\", required = true) String cotizacionId) {\n        RegistroHerramientasUsadas.registrar(\"enviar_cotizacion\");\n        return prepararAccionCotizacion(cotizacionId, \"BORRADOR\", AccionesPendientes.TIPO_COTIZACION_ENVIAR,\n                \"Enviar cotización\", \"Envío preparado, no ejecutado.\", \"solo una cotización en borrador puede enviarse\");\n    }\n\n    /** Herramienta del asistente: prepara la aceptación de una cotización por el cliente. */\n    @Tool(name = \"aceptar_cotizacion\",\n          description = \"Prepara la aceptación de una cotización enviada. NO la acepta: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String aceptarCotizacion(\n            @ToolParam(description = \"Identificador UUID de la cotización enviada\", required = true) String cotizacionId) {\n        RegistroHerramientasUsadas.registrar(\"aceptar_cotizacion\");\n        return prepararAccionCotizacion(cotizacionId, \"ENVIADA\", AccionesPendientes.TIPO_COTIZACION_ACEPTAR,\n                \"Aceptar cotización\", \"Aceptación preparada, no ejecutada.\", \"solo una cotización enviada puede aceptarse\");\n    }\n\n    /** Herramienta del asistente: prepara la conversión de una cotización aceptada en pedido. */\n    @Tool(name = \"convertir_cotizacion_en_pedido\",\n          description = \"Prepara la conversión de una cotización aceptada en pedido. NO crea el pedido: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String convertirCotizacionEnPedido(\n            @ToolParam(description = \"Identificador UUID de la cotización aceptada\", required = true) String cotizacionId) {\n        RegistroHerramientasUsadas.registrar(\"convertir_cotizacion_en_pedido\");\n        return prepararAccionCotizacion(cotizacionId, \"ACEPTADA\", AccionesPendientes.TIPO_COTIZACION_A_PEDIDO,\n                \"Convertir cotización en pedido\", \"Conversión preparada, no ejecutada.\",\n                \"solo una cotización aceptada puede convertirse en pedido\");\n    }\n\n    /** Herramienta del asistente: prepara una cotización borrador. */\n    @Tool(name = \"crear_cotizacion_borrador\",\n          description = \"Prepara una cotización nueva para un cliente con una línea. NO la guarda: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarla en la aplicación. Úsala solo cuando el usuario pida crear una cotización.\")\n    public String crearCotizacionBorrador(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Canal de venta: WEB, TIENDA o TELEFONO\", required = true) String canal,\n            @ToolParam(description = \"Moneda ISO, por ejemplo MXN\", required = true) String moneda,\n            @ToolParam(description = \"Tasa de IVA: IVA_GENERAL, IVA_FRONTERIZO o IVA_EXENTO\", required = true) String tasaIva,\n            @ToolParam(description = \"Fecha hasta la que vale la cotización, en formato AAAA-MM-DD\", required = true) String vigenteHasta,\n            @ToolParam(description = \"Identificador UUID del producto\", required = true) String productoId,\n            @ToolParam(description = \"Descripción de la línea. Puede ir vacía.\", required = false) String descripcion,\n            @ToolParam(description = \"Cantidad entera mayor a cero\", required = true) int cantidad,\n            @ToolParam(description = \"Precio unitario en la moneda de la cotización\", required = true) String precioUnitario) {\n        RegistroHerramientasUsadas.registrar(\"crear_cotizacion_borrador\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        if (cantidad <= 0) {\n            return \"La cantidad debe ser mayor a cero.\";\n        }\n        String canalNormalizado = normalizar(canal);\n        if (!CANALES.contains(canalNormalizado)) {\n            return \"El canal debe ser WEB, TIENDA o TELEFONO.\";\n        }\n        String tasaNormalizada = normalizar(tasaIva);\n        if (!TASAS_IVA.contains(tasaNormalizada)) {\n            return \"La tasa de IVA debe ser IVA_GENERAL, IVA_FRONTERIZO o IVA_EXENTO.\";\n        }\n        LocalDate vigencia;\n        try {\n            vigencia = LocalDate.parse(vigenteHasta.trim());\n        } catch (DateTimeParseException | NullPointerException e) {\n            return \"La vigencia debe ir en formato AAAA-MM-DD, por ejemplo 2026-12-31.\";\n        }\n        if (cliente(id) == null) {\n            return \"No encontré ese cliente.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", id.toString());\n        cuerpo.put(\"canal\", canalNormalizado);\n        cuerpo.put(\"moneda\", moneda.trim().toUpperCase());\n        cuerpo.put(\"tasaIva\", tasaNormalizada);\n        cuerpo.put(\"vigenteHasta\", vigencia.toString());\n        cuerpo.put(\"lineas\", List.of(linea(productoId, descripcion, cantidad, precioUnitario)));\n        String resumen = \"Cotización para el cliente \" + id + \" vigente hasta \" + vigencia + \": \" + cantidad + \" × \"\n                + productoId.trim() + \" a \" + precioUnitario.trim() + \" \" + moneda.trim().toUpperCase()\n                + \" (\" + canalNormalizado + \", \" + tasaNormalizada + \")\";\n        return guardarAccion(AccionesPendientes.TIPO_COTIZACION_CREAR, aJson(cuerpo), resumen,\n                \"Cotización preparada, no guardada.\");\n    }\n\n    /** Herramienta del asistente: prepara el reemplazo de las líneas de un pedido. */\n    @Tool(name = \"reemplazar_lineas_pedido\",\n          description = \"Prepara el reemplazo de las líneas de un pedido en borrador por una sola línea. NO lo cambia: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String reemplazarLineasPedido(\n            @ToolParam(description = \"Identificador UUID del pedido en borrador\", required = true) String pedidoId,\n            @ToolParam(description = \"Identificador UUID del producto\", required = true) String productoId,\n            @ToolParam(description = \"Descripción de la línea. Puede ir vacía.\", required = false) String descripcion,\n            @ToolParam(description = \"Cantidad entera mayor a cero\", required = true) int cantidad,\n            @ToolParam(description = \"Precio unitario en la moneda del pedido\", required = true) String precioUnitario) {\n        RegistroHerramientasUsadas.registrar(\"reemplazar_lineas_pedido\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        if (cantidad <= 0) {\n            return \"La cantidad debe ser mayor a cero.\";\n        }\n        JsonNode pedido = pedido(id);\n        if (pedido == null) {\n            return \"No encontré ese pedido.\";\n        }\n        String estatus = pedido.path(\"estatus\").asText();\n        if (!\"BORRADOR\".equals(estatus)) {\n            return \"El pedido está en estatus \" + estatus + \"; solo un pedido en borrador admite cambios en sus líneas.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"pedidoId\", id.toString());\n        cuerpo.put(\"lineas\", List.of(linea(productoId, descripcion, cantidad, precioUnitario)));\n        String resumen = \"Reemplazar las líneas del pedido \" + id + \" por \" + cantidad + \" × \" + productoId.trim()\n                + \" a \" + precioUnitario.trim() + \" (estatus actual BORRADOR)\";\n        return guardarAccion(AccionesPendientes.TIPO_PEDIDO_REEMPLAZAR_LINEAS, aJson(cuerpo), resumen,\n                \"Cambio de líneas preparado, no ejecutado.\");\n    }\n\n    /** Herramienta del asistente: prepara la devolución de un pedido. */\n    @Tool(name = \"registrar_devolucion_pedido\",\n          description = \"Prepara la devolución total de un pedido entregado. NO la registra: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarlo en la aplicación.\")\n    public String registrarDevolucionPedido(\n            @ToolParam(description = \"Identificador UUID del pedido entregado\", required = true) String pedidoId) {\n        RegistroHerramientasUsadas.registrar(\"registrar_devolucion_pedido\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(pedidoId);\n        if (id == null) {\n            return \"El identificador del pedido no es válido.\";\n        }\n        JsonNode pedido = pedido(id);\n        if (pedido == null) {\n            return \"No encontré ese pedido.\";\n        }\n        String estatus = pedido.path(\"estatus\").asText();\n        if (!\"ENTREGADO\".equals(estatus)) {\n            return \"El pedido está en estatus \" + estatus + \"; solo un pedido entregado puede devolverse.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"pedidoId\", id.toString());\n        String resumen = \"Devolución total del pedido \" + id + \" (estatus actual ENTREGADO)\";\n        return guardarAccion(AccionesPendientes.TIPO_PEDIDO_DEVOLVER, aJson(cuerpo), resumen,\n                \"Devolución preparada, no registrada.\");\n    }\n\n    /** Herramienta del asistente: prepara el cambio de estatus de un prospecto. */\n    @Tool(name = \"cambiar_estatus_prospecto\",\n          description = \"Prepara el cambio de estatus de un prospecto a CONTACTADO, CALIFICADO o PERDIDO. NO lo cambia: devuelve un resumen y un accion_id. \"\n                  + \"Para convertir un prospecto en cliente usa convertir_prospecto_en_cliente. El usuario debe confirmarlo en la aplicación.\")\n    public String cambiarEstatusProspecto(\n            @ToolParam(description = \"Identificador UUID del prospecto\", required = true) String prospectoId,\n            @ToolParam(description = \"Nuevo estatus: CONTACTADO, CALIFICADO o PERDIDO\", required = true) String estatus) {\n        RegistroHerramientasUsadas.registrar(\"cambiar_estatus_prospecto\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(prospectoId);\n        if (id == null) {\n            return \"El identificador del prospecto no es válido.\";\n        }\n        String destino = normalizar(estatus);\n        if (!DESTINOS_PROSPECTO.contains(destino)) {\n            return \"El estatus debe ser CONTACTADO, CALIFICADO o PERDIDO. Para convertir un prospecto usa convertir_prospecto_en_cliente.\";\n        }\n        JsonNode prospecto = prospecto(id);\n        if (prospecto == null) {\n            return \"No encontré ese prospecto.\";\n        }\n        String actual = prospecto.path(\"estatus\").asText();\n        if (!TRANSICIONES_PROSPECTO.getOrDefault(actual, Set.of()).contains(destino)) {\n            return \"No se puede pasar el prospecto de \" + actual + \" a \" + destino + \".\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"prospectoId\", id.toString());\n        cuerpo.put(\"estatus\", destino);\n        String resumen = \"Cambiar el estatus del prospecto \" + id + \" de \" + actual + \" a \" + destino;\n        return guardarAccion(AccionesPendientes.TIPO_PROSPECTO_ESTATUS, aJson(cuerpo), resumen,\n                \"Cambio de estatus preparado, no ejecutado.\");\n    }\n\n    /** Herramienta del asistente: prepara la conversión de un prospecto en cliente. */\n    @Tool(name = \"convertir_prospecto_en_cliente\",\n          description = \"Prepara la conversión de un prospecto calificado en cliente con su contacto principal. \"\n                  + \"NO lo convierte: devuelve un resumen y un accion_id. El usuario debe confirmarlo en la aplicación.\")\n    public String convertirProspectoEnCliente(\n            @ToolParam(description = \"Identificador UUID del prospecto calificado\", required = true) String prospectoId,\n            @ToolParam(description = \"Razón social del cliente\", required = true) String razonSocial,\n            @ToolParam(description = \"RFC del cliente\", required = true) String rfc,\n            @ToolParam(description = \"Nombre del contacto principal\", required = true) String contactoNombre,\n            @ToolParam(description = \"Correo electrónico del contacto principal\", required = true) String contactoCorreo,\n            @ToolParam(description = \"Rol del contacto: COMPRAS, PAGOS o ASISTENCIA\", required = true) String contactoRol) {\n        RegistroHerramientasUsadas.registrar(\"convertir_prospecto_en_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(prospectoId);\n        if (id == null) {\n            return \"El identificador del prospecto no es válido.\";\n        }\n        if (vacio(razonSocial) || vacio(rfc) || vacio(contactoNombre) || vacio(contactoCorreo)\n                || !contactoCorreo.contains(\"@\")) {\n            return \"Indica la razón social, el RFC y un contacto con nombre y correo válido.\";\n        }\n        String rol = normalizar(contactoRol);\n        if (!ROLES_CONTACTO.contains(rol)) {\n            return \"El rol del contacto debe ser COMPRAS, PAGOS o ASISTENCIA.\";\n        }\n        JsonNode prospecto = prospecto(id);\n        if (prospecto == null) {\n            return \"No encontré ese prospecto.\";\n        }\n        String estatus = prospecto.path(\"estatus\").asText();\n        if (!\"CALIFICADO\".equals(estatus)) {\n            return \"El prospecto está en estatus \" + estatus + \"; solo un prospecto calificado puede convertirse en cliente.\";\n        }\n        Map<String, Object> contacto = new LinkedHashMap<>();\n        contacto.put(\"nombre\", contactoNombre.trim());\n        contacto.put(\"correo\", contactoCorreo.trim());\n        contacto.put(\"rol\", rol);\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"prospectoId\", id.toString());\n        cuerpo.put(\"razonSocial\", razonSocial.trim());\n        cuerpo.put(\"rfc\", rfc.trim().toUpperCase());\n        cuerpo.put(\"contactoPrincipal\", contacto);\n        String resumen = \"Convertir el prospecto \" + id + \" en el cliente \" + razonSocial.trim()\n                + \" con contacto \" + contactoNombre.trim() + \" (\" + rol + \")\";\n        return guardarAccion(AccionesPendientes.TIPO_PROSPECTO_CONVERTIR, aJson(cuerpo), resumen,\n                \"Conversión preparada, no ejecutada.\");\n    }\n\n    /** Herramienta del asistente: prepara el registro de una interacción con un cliente. */\n    @Tool(name = \"registrar_interaccion_cliente\",\n          description = \"Prepara el registro de una interacción con un cliente: llamada, correo o visita. NO la guarda: devuelve un resumen y un accion_id. \"\n                  + \"El usuario debe confirmarla en la aplicación.\")\n    public String registrarInteraccionCliente(\n            @ToolParam(description = \"Identificador UUID del cliente\", required = true) String clienteId,\n            @ToolParam(description = \"Tipo de interacción: LLAMADA, CORREO o VISITA\", required = true) String tipo,\n            @ToolParam(description = \"Fecha y hora ISO 8601 con zona, por ejemplo 2026-11-01T10:00:00-06:00\", required = true) String fecha,\n            @ToolParam(description = \"Resumen de lo tratado, máximo 2000 caracteres\", required = true) String resumen) {\n        RegistroHerramientasUsadas.registrar(\"registrar_interaccion_cliente\");\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(clienteId);\n        if (id == null) {\n            return \"El identificador del cliente no es válido.\";\n        }\n        String tipoNormalizado = normalizar(tipo);\n        if (!TIPOS_INTERACCION.contains(tipoNormalizado)) {\n            return \"El tipo debe ser LLAMADA, CORREO o VISITA.\";\n        }\n        Instant momento;\n        try {\n            momento = OffsetDateTime.parse(fecha.trim()).toInstant();\n        } catch (DateTimeParseException | NullPointerException e) {\n            return \"La fecha debe ir en formato ISO 8601 con zona, por ejemplo 2026-11-01T10:00:00-06:00.\";\n        }\n        if (vacio(resumen) || resumen.trim().length() > 2000) {\n            return \"El resumen es obligatorio y no puede pasar de 2000 caracteres.\";\n        }\n        if (cliente(id) == null) {\n            return \"No encontré ese cliente.\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"clienteId\", id.toString());\n        cuerpo.put(\"tipo\", tipoNormalizado);\n        cuerpo.put(\"fecha\", momento.toString());\n        cuerpo.put(\"resumen\", resumen.trim());\n        String encabezado = \"Registrar \" + tipoNormalizado + \" con el cliente \" + id + \" el \" + momento;\n        return guardarAccion(AccionesPendientes.TIPO_INTERACCION_REGISTRAR, aJson(cuerpo), encabezado,\n                \"Interacción preparada, no guardada.\");\n    }\n\n    /** Construye una línea de pedido con producto, descripción, cantidad y precio unitario. */\n    private static Map<String, Object> linea(String productoId, String descripcion, int cantidad, String precioUnitario) {\n        Map<String, Object> linea = new LinkedHashMap<>();\n        linea.put(\"productoId\", productoId.trim());\n        linea.put(\"descripcion\", descripcion == null || descripcion.isBlank() ? \"Artículo\" : descripcion.trim());\n        linea.put(\"cantidad\", cantidad);\n        linea.put(\"precioUnitario\", precioUnitario.trim());\n        return linea;\n    }\n\n    /** Quita espacios y pasa el texto a mayúsculas. Un valor nulo se convierte en cadena vacía. */\n    private static String normalizar(String valor) {\n        return valor == null ? \"\" : valor.trim().toUpperCase();\n    }\n\n    /** Indica si el texto es nulo o está en blanco. */\n    private static boolean vacio(String valor) {\n        return valor == null || valor.isBlank();\n    }\n\n    /** Prepara una acción sobre una cotización solo si está en el estatus requerido. Si no, responde con un mensaje y no crea la acción. */\n    private String prepararAccionCotizacion(String cotizacionId, String estatusRequerido, String tipo,\n                                            String etiqueta, String encabezado, String motivoRechazo) {\n        if (acciones == null) {\n            return NO_DISPONIBLE;\n        }\n        UUID id = identificador(cotizacionId);\n        if (id == null) {\n            return \"El identificador de la cotización no es válido.\";\n        }\n        JsonNode cotizacion = cotizacion(id);\n        if (cotizacion == null) {\n            return \"No encontré esa cotización.\";\n        }\n        String estatus = cotizacion.path(\"estatus\").asText();\n        if (!estatusRequerido.equals(estatus)) {\n            return \"La cotización está en estatus \" + estatus + \"; \" + motivoRechazo + \".\";\n        }\n        Map<String, Object> cuerpo = new LinkedHashMap<>();\n        cuerpo.put(\"cotizacionId\", id.toString());\n        String resumen = etiqueta + \" \" + id + \" (estatus actual \" + estatus + \")\";\n        return guardarAccion(tipo, aJson(cuerpo), resumen, encabezado);\n    }\n\n    /** Consulta la cotización con el token del usuario. Devuelve null si no existe o no es visible para él. */\n    private JsonNode cotizacion(UUID id) {\n        return recurso(RUTA_BASE + \"/cotizaciones/\" + id);\n    }\n\n    /** Consulta el pedido con el token del usuario. Devuelve null si no existe o no es visible para él. */\n    private JsonNode pedido(UUID id) {\n        return recurso(RUTA_BASE + \"/pedidos/\" + id);\n    }\n\n    /** Consulta el prospecto con el token del usuario. Devuelve null si no existe o no es visible para él. */\n    private JsonNode prospecto(UUID id) {\n        return recurso(RUTA_CLIENTES_BASE + \"/prospectos/\" + id);\n    }\n\n    /** Consulta el cliente con el token del usuario. Devuelve null si no existe o no es visible para él. */\n    private JsonNode cliente(UUID id) {\n        return recurso(RUTA_CLIENTES_BASE + \"/clientes/\" + id);\n    }\n\n    /** Consulta un recurso del gateway y devuelve su contenido como árbol JSON. */\n    private JsonNode recurso(String ruta) {\n        try {\n            String cuerpo = gateway.get()\n                    .uri(ruta)\n                    .retrieve()\n                    .body(String.class);\n            return JSON.readTree(cuerpo);\n        } catch (HttpClientErrorException.NotFound e) {\n            return null;\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"Respuesta no válida de \" + ruta, e);\n        }\n    }\n\n    /** Convierte un texto en UUID. Lanza excepción si no tiene formato válido. */\n    private static UUID identificador(String valor) {\n        try {\n            return valor == null ? null : UUID.fromString(valor.trim());\n        } catch (IllegalArgumentException e) {\n            return null;\n        }\n    }\n\n    /** Devuelve el nombre del usuario autenticado. */\n    private static String usuarioActual() {\n        var autenticacion = SecurityContextHolder.getContext().getAuthentication();\n        if (autenticacion instanceof JwtAuthenticationToken jwt) {\n            return jwt.getToken().getSubject();\n        }\n        throw new IllegalStateException(\"No hay un usuario autenticado para preparar la acción\");\n    }\n\n    /** Convierte un mapa en JSON para guardarlo en la acción pendiente. */\n    private static String aJson(Map<String, Object> cuerpo) {\n        try {\n            return JSON.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo serializar la acción\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/PoliticasClasspath.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.util.ArrayList;\nimport java.util.List;\n\nimport org.springframework.core.io.Resource;\nimport org.springframework.core.io.support.PathMatchingResourcePatternResolver;\n\nimport com.mx.josesaid.develop.nexus.application.Politica;\n\n/** Lee las políticas Markdown de classpath:politicas/. El id de cada política es su nombre de archivo sin extensión. */\npublic final class PoliticasClasspath {\n\n    private static final String PATRON = \"classpath*:politicas/*.md\";\n\n    /** Clase de utilidad: no se instancia. */\n    private PoliticasClasspath() {\n    }\n\n    /** Lee todas las políticas desde los resources del classpath, en la carpeta nexus/politicas. */\n    public static List<Politica> cargar() throws IOException {\n        Resource[] recursos = new PathMatchingResourcePatternResolver().getResources(PATRON);\n        List<Politica> politicas = new ArrayList<>();\n        for (Resource recurso : recursos) {\n            String nombre = recurso.getFilename();\n            String id = nombre.substring(0, nombre.length() - \".md\".length());\n            String contenido = new String(recurso.getContentAsByteArray(), StandardCharsets.UTF_8);\n            politicas.add(Politica.desde(id, contenido));\n        }\n        return politicas;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/RegistroHerramientasUsadas.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.util.ArrayList;\nimport java.util.List;\n\n/**\n * Colector por petición de las herramientas que el modelo ejecutó.\n * Las herramientas se invocan en el mismo hilo que la llamada al modelo, por eso se usa ThreadLocal.\n */\nfinal class RegistroHerramientasUsadas {\n\n    private static final ThreadLocal<List<String>> USADAS = new ThreadLocal<>();\n\n    /** Clase de utilidad: no se instancia. */\n    private RegistroHerramientasUsadas() {\n    }\n\n    /** Inicia el registro de herramientas usadas en la consulta actual. Usa un ThreadLocal, así que dura solo lo que dura la petición. */\n    static void iniciar() {\n        USADAS.set(new ArrayList<>());\n    }\n\n    /** Agrega el nombre de una herramienta usada a la lista de la consulta actual. Si no se inició el registro, no hace nada. */\n    static void registrar(String nombre) {\n        List<String> lista = USADAS.get();\n        if (lista != null) {\n            lista.add(nombre);\n        }\n    }\n\n    /** Devuelve las herramientas usadas en la consulta y limpia el registro del hilo. */\n    static List<String> terminar() {\n        List<String> lista = USADAS.get();\n        USADAS.remove();\n        return lista == null ? List.of() : List.copyOf(lista);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/VoyageEmbedder.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport java.time.Duration;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.Map;\n\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.MediaType;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.Embedder;\n\n/**\n * Genera embeddings con la API de Voyage AI. La clave viene de VOYAGE_API_KEY, nunca del código.\n * Ante un 429 (límite de solicitudes por minuto) espera y reintenta.\n */\npublic final class VoyageEmbedder implements Embedder {\n\n    static final String RUTA = \"/v1/embeddings\";\n    static final int MAX_INTENTOS = 4;\n    /** Con 3 solicitudes por minuto (cuenta sin método de pago), cada solicitud espera ~20 segundos. */\n    static final Duration ESPERA_429 = Duration.ofSeconds(21);\n\n    private final RestClient cliente;\n    private final String apiKey;\n    private final String modelo;\n    private final Duration espera;\n\n    /** Recibe el cliente HTTP, la clave de API y el modelo de embeddings de Voyage. */\n    public VoyageEmbedder(RestClient cliente, String apiKey, String modelo) {\n        this(cliente, apiKey, modelo, ESPERA_429);\n    }\n\n    VoyageEmbedder(RestClient cliente, String apiKey, String modelo, Duration espera) {\n        this.cliente = cliente;\n        this.apiKey = apiKey;\n        this.modelo = modelo;\n        this.espera = espera;\n    }\n\n    /** Calcula el embedding de cada texto. Los embeddings de consultas y documentos usan el tipo de entrada indicado. */\n    @Override\n    public List<float[]> embeber(List<String> textos, TipoEntrada tipo) {\n        if (apiKey == null || apiKey.isBlank()) {\n            throw new IllegalStateException(\"Falta VOYAGE_API_KEY para generar embeddings\");\n        }\n        if (textos.isEmpty()) {\n            return List.of();\n        }\n        RespuestaEmbeddings respuesta = pedir(Map.of(\n                \"input\", textos,\n                \"model\", modelo,\n                \"input_type\", tipo == TipoEntrada.CONSULTA ? \"query\" : \"document\"));\n        if (respuesta == null || respuesta.data() == null || respuesta.data().size() != textos.size()) {\n            throw new IllegalStateException(\"Respuesta de Voyage AI incompleta\");\n        }\n        float[][] vectores = new float[textos.size()][];\n        for (Dato dato : respuesta.data()) {\n            if (dato.index() < 0 || dato.index() >= vectores.length || dato.embedding() == null) {\n                throw new IllegalStateException(\"Respuesta de Voyage AI con índice inválido\");\n            }\n            vectores[dato.index()] = aFloat(dato.embedding());\n        }\n        return new ArrayList<>(Arrays.asList(vectores));\n    }\n\n    /** Envía la petición a Voyage. Si el servicio responde con límite de solicitudes, espera y reintenta. */\n    private RespuestaEmbeddings pedir(Map<String, Object> cuerpo) {\n        for (int intento = 1; ; intento++) {\n            try {\n                return cliente.post()\n                        .uri(RUTA)\n                        .header(HttpHeaders.AUTHORIZATION, \"Bearer \" + apiKey)\n                        .contentType(MediaType.APPLICATION_JSON)\n                        .body(cuerpo)\n                        .retrieve()\n                        .body(RespuestaEmbeddings.class);\n            } catch (HttpClientErrorException e) {\n                if (e.getStatusCode().value() != 429 || intento >= MAX_INTENTOS) {\n                    throw e;\n                }\n                esperar();\n            }\n        }\n    }\n\n    /** Espera un intervalo corto entre peticiones para no superar el límite de Voyage. */\n    private void esperar() {\n        try {\n            Thread.sleep(espera.toMillis());\n        } catch (InterruptedException e) {\n            Thread.currentThread().interrupt();\n            throw new IllegalStateException(\"Interrumpido mientras esperaba el límite de Voyage AI\", e);\n        }\n    }\n\n    /** Convierte la lista de números de la respuesta en un arreglo de float. */\n    private static float[] aFloat(List<Float> valores) {\n        float[] resultado = new float[valores.size()];\n        for (int i = 0; i < resultado.length; i++) {\n            resultado[i] = valores.get(i);\n        }\n        return resultado;\n    }\n\n    /**\n     * Respuesta de Voyage: lista de embeddings.\n     *\n     * @param data componente de tipo {@code List<Dato>}.\n     */\n    record RespuestaEmbeddings(List<Dato> data) {\n    }\n\n    /**\n     * Embedding de un texto, identificado por su posición en la petición.\n     *\n     * @param index componente de tipo {@code int}.\n     * @param embedding componente de tipo {@code List<Float>}.\n     */\n    record Dato(int index, List<Float> embedding) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/package-info.java": "/**\n * Capa \"infrastructure\" de Nexus. Ver docs/diseno.md para las reglas de dependencia entre capas.\n */\npackage com.mx.josesaid.develop.nexus.infrastructure;\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AccionPendienteEntidad.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\n\n/** Fila de la tabla de acciones pendientes. Guarda el payload completo para poder ejecutar la acción al confirmarla. */\n@Entity\n@Table(name = \"acciones_pendientes\")\npublic class AccionPendienteEntidad {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String usuario;\n\n    @Column(nullable = false, length = 40)\n    private String tipo;\n\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(nullable = false, length = 1000)\n    private String resumen;\n\n    @Column(nullable = false, length = 12)\n    private String estatus;\n\n    @Column(name = \"creada_utc\", nullable = false)\n    private Instant creadaUtc;\n\n    @Column(name = \"expira_utc\", nullable = false)\n    private Instant expiraUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected AccionPendienteEntidad() {\n    }\n\n    /** Crea una fila con todos los datos de la acción pendiente. */\n    public AccionPendienteEntidad(UUID id, String usuario, String tipo, String payload, String resumen,\n                                  String estatus, Instant creadaUtc, Instant expiraUtc) {\n        this.id = id;\n        this.usuario = usuario;\n        this.tipo = tipo;\n        this.payload = payload;\n        this.resumen = resumen;\n        this.estatus = estatus;\n        this.creadaUtc = creadaUtc;\n        this.expiraUtc = expiraUtc;\n    }\n\n    /** Devuelve el identificador de la acción. */\n    public UUID getId() { return id; }\n    /** Devuelve el usuario que preparó la acción. */\n    public String getUsuario() { return usuario; }\n    /** Devuelve el tipo de la acción. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el payload JSON de la acción. */\n    public String getPayload() { return payload; }\n    /** Devuelve el resumen legible de la acción. */\n    public String getResumen() { return resumen; }\n    /** Devuelve el estatus de la acción. */\n    public String getEstatus() { return estatus; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadaUtc() { return creadaUtc; }\n    /** Devuelve la fecha de vencimiento en UTC. */\n    public Instant getExpiraUtc() { return expiraUtc; }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AccionPendienteRepositorio.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Modifying;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n\n/** Acceso a la tabla de acciones pendientes con Spring Data JPA. */\npublic interface AccionPendienteRepositorio extends JpaRepository<AccionPendienteEntidad, UUID> {\n\n    @Modifying\n    @Query(\"delete from AccionPendienteEntidad a where a.expiraUtc < :limite\")\n    int borrarVencidasAntesDe(@Param(\"limite\") Instant limite);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AlmacenAccionesJpa.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.springframework.stereotype.Component;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\n\n/** Guarda las acciones pendientes en PostgreSQL con JPA. */\n@Component\npublic class AlmacenAccionesJpa implements AlmacenAcciones {\n\n    private final AccionPendienteRepositorio repositorio;\n\n    /** Recibe el repositorio de acciones pendientes. */\n    public AlmacenAccionesJpa(AccionPendienteRepositorio repositorio) {\n        this.repositorio = repositorio;\n    }\n\n    /** Guarda o actualiza una acción pendiente. */\n    @Override\n    public void guardar(AccionPendiente a) {\n        repositorio.save(new AccionPendienteEntidad(a.id(), a.usuario(), a.tipo(), a.payload(), a.resumen(),\n                a.estatus(), a.creadaUtc(), a.expiraUtc()));\n    }\n\n    /** Busca una acción pendiente por su identificador. */\n    @Override\n    public Optional<AccionPendiente> buscar(UUID id) {\n        return repositorio.findById(id).map(e -> new AccionPendiente(e.getId(), e.getUsuario(), e.getTipo(),\n                e.getPayload(), e.getResumen(), e.getEstatus(), e.getCreadaUtc(), e.getExpiraUtc()));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AlmacenFragmentosJdbc.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.sql.Date;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\n\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.transaction.support.TransactionTemplate;\n\nimport com.mx.josesaid.develop.nexus.application.AlmacenFragmentos;\nimport com.mx.josesaid.develop.nexus.application.FragmentoIndexado;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\n\n/** Implementación sobre PostgreSQL con pgvector. El filtro por rol y vigencia va en SQL, antes de ordenar por similitud. */\npublic final class AlmacenFragmentosJdbc implements AlmacenFragmentos {\n\n    private static final String INSERTAR = \"INSERT INTO fragmentos_politica \"\n            + \"(id, politica_id, indice, titulo, vigencia, roles, texto, embedding) \"\n            + \"VALUES (?, ?, ?, ?, ?, ?, ?, CAST(? AS vector))\";\n\n    private static final String BUSCAR = \"SELECT politica_id, indice, titulo, texto, \"\n            + \"1 - (embedding <=> CAST(? AS vector)) AS similitud \"\n            + \"FROM fragmentos_politica \"\n            + \"WHERE roles && CAST(? AS text[]) AND vigencia <= ? \"\n            + \"ORDER BY embedding <=> CAST(? AS vector) \"\n            + \"LIMIT ?\";\n\n    private final JdbcTemplate jdbc;\n    private final TransactionTemplate transacciones;\n\n    /** Recibe JdbcTemplate y el gestor de transacciones para las operaciones de fragmentos con vectores. */\n    public AlmacenFragmentosJdbc(JdbcTemplate jdbc, TransactionTemplate transacciones) {\n        this.jdbc = jdbc;\n        this.transacciones = transacciones;\n    }\n\n    /** Reemplaza todos los fragmentos de una política por los nuevos, dentro de una transacción. Así una política nunca queda a medio indexar. */\n    @Override\n    public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n        transacciones.executeWithoutResult(estado -> {\n            jdbc.update(\"DELETE FROM fragmentos_politica WHERE politica_id = ?\", politicaId);\n            if (fragmentos.isEmpty()) {\n                return;\n            }\n            jdbc.batchUpdate(INSERTAR, fragmentos, fragmentos.size(), (ps, f) -> {\n                ps.setObject(1, UUID.randomUUID());\n                ps.setString(2, f.politicaId());\n                ps.setInt(3, f.indice());\n                ps.setString(4, f.titulo());\n                ps.setDate(5, Date.valueOf(f.vigencia()));\n                ps.setArray(6, ps.getConnection().createArrayOf(\"text\", f.roles().toArray(String[]::new)));\n                ps.setString(7, f.texto());\n                ps.setString(8, aLiteral(f.vector()));\n            });\n        });\n    }\n\n    /** Busca los fragmentos más parecidos a la consulta. Solo devuelve políticas vigentes a la fecha y visibles para los roles indicados. */\n    @Override\n    public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n        String vector = aLiteral(consulta);\n        return jdbc.query(BUSCAR, ps -> {\n            ps.setString(1, vector);\n            ps.setArray(2, ps.getConnection().createArrayOf(\"text\", roles.toArray(String[]::new)));\n            ps.setDate(3, Date.valueOf(hoy));\n            ps.setString(4, vector);\n            ps.setInt(5, limite);\n        }, (rs, n) -> new ResultadoPolitica(rs.getString(\"politica_id\"), rs.getInt(\"indice\"),\n                rs.getString(\"titulo\"), rs.getString(\"texto\"), rs.getDouble(\"similitud\")));\n    }\n\n    /** Formato de pgvector: [0.1,0.2,...] */\n    static String aLiteral(float[] vector) {\n        StringBuilder sb = new StringBuilder(\"[\");\n        for (int i = 0; i < vector.length; i++) {\n            if (i > 0) {\n                sb.append(',');\n            }\n            sb.append(vector[i]);\n        }\n        return sb.append(']').toString();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AuditoriaJpa.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.util.UUID;\n\nimport org.springframework.stereotype.Component;\n\nimport com.mx.josesaid.develop.nexus.application.AuditoriaConsultas;\nimport com.mx.josesaid.develop.nexus.application.RegistroConsulta;\n\n/** Guarda la auditoría de consultas al asistente con JPA. */\n@Component\npublic class AuditoriaJpa implements AuditoriaConsultas {\n\n    private final ConsultaRepositorio repositorio;\n\n    /** Recibe el repositorio de consultas. */\n    public AuditoriaJpa(ConsultaRepositorio repositorio) {\n        this.repositorio = repositorio;\n    }\n\n    /** Registra una consulta en la auditoría. */\n    @Override\n    public void registrar(RegistroConsulta r) {\n        repositorio.save(new ConsultaEntidad(\n                UUID.randomUUID(), r.usuario(), r.preguntaRedactada(), r.respuestaResumen(),\n                r.herramientas(), r.tokensEntrada(), r.tokensSalida(), r.creadoUtc()));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/ConsultaEntidad.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\n\n/** Fila de la auditoría de consultas. Guarda la pregunta ya redactada, nunca el texto sensible original. */\n@Entity\n@Table(name = \"nexus_consultas\")\npublic class ConsultaEntidad {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String usuario;\n\n    @Column(name = \"pregunta_redactada\", nullable = false, columnDefinition = \"TEXT\")\n    private String preguntaRedactada;\n\n    @Column(name = \"respuesta_resumen\", length = 500)\n    private String respuestaResumen;\n\n    @Column(length = 500)\n    private String herramientas;\n\n    @Column(name = \"tokens_entrada\")\n    private Integer tokensEntrada;\n\n    @Column(name = \"tokens_salida\")\n    private Integer tokensSalida;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ConsultaEntidad() {\n    }\n\n    /** Crea una fila de auditoría con los datos de la consulta. */\n    public ConsultaEntidad(UUID id, String usuario, String preguntaRedactada, String respuestaResumen,\n                           String herramientas, Integer tokensEntrada, Integer tokensSalida, Instant creadoUtc) {\n        this.id = id;\n        this.usuario = usuario;\n        this.preguntaRedactada = preguntaRedactada;\n        this.respuestaResumen = respuestaResumen;\n        this.herramientas = herramientas;\n        this.tokensEntrada = tokensEntrada;\n        this.tokensSalida = tokensSalida;\n        this.creadoUtc = creadoUtc;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/ConsultaRepositorio.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.Query;\nimport org.springframework.data.repository.query.Param;\n\n/** Acceso a la tabla de consultas con Spring Data JPA. */\npublic interface ConsultaRepositorio extends JpaRepository<ConsultaEntidad, UUID> {\n\n    @Query(\"select coalesce(sum(coalesce(c.tokensEntrada, 0) + coalesce(c.tokensSalida, 0)), 0) \"\n            + \"from ConsultaEntidad c where c.usuario = :usuario and c.creadoUtc >= :desde\")\n    long sumarTokens(@Param(\"usuario\") String usuario, @Param(\"desde\") Instant desde);\n\n    @Query(\"select coalesce(sum(coalesce(c.tokensEntrada, 0) + coalesce(c.tokensSalida, 0)), 0) \"\n            + \"from ConsultaEntidad c where c.creadoUtc >= :desde\")\n    long sumarTokensServicio(@Param(\"desde\") Instant desde);\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/ConsumoTokensJpa.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Instant;\n\nimport org.springframework.stereotype.Component;\n\nimport com.mx.josesaid.develop.nexus.application.ConsumoTokens;\n\n/** Calcula el consumo de tokens a partir de la auditoría. */\n@Component\npublic class ConsumoTokensJpa implements ConsumoTokens {\n\n    private final ConsultaRepositorio repositorio;\n\n    /** Recibe el repositorio de consultas. */\n    public ConsumoTokensJpa(ConsultaRepositorio repositorio) {\n        this.repositorio = repositorio;\n    }\n\n    /** Suma los tokens consumidos por un usuario desde una fecha. */\n    @Override\n    public long desde(String usuario, Instant desde) {\n        return repositorio.sumarTokens(usuario, desde);\n    }\n\n    /** Suma los tokens consumidos por todo el servicio desde una fecha. */\n    @Override\n    public long delServicio(Instant desde) {\n        return repositorio.sumarTokensServicio(desde);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/LimpiezaAcciones.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport java.time.Clock;\nimport java.time.Duration;\n\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Borra las acciones pendientes vencidas hace más de una hora. El nombre y el correo del\n * prospecto viajan en el payload, así que no deben quedar guardados indefinidamente.\n */\n@Component\npublic class LimpiezaAcciones {\n\n    static final Duration RETENCION = Duration.ofHours(1);\n\n    private final AccionPendienteRepositorio repositorio;\n    private final Clock reloj;\n\n    /** Recibe el repositorio de acciones pendientes para la limpieza programada. */\n    @Autowired\n    public LimpiezaAcciones(AccionPendienteRepositorio repositorio) {\n        this(repositorio, Clock.systemUTC());\n    }\n\n    LimpiezaAcciones(AccionPendienteRepositorio repositorio, Clock reloj) {\n        this.repositorio = repositorio;\n        this.reloj = reloj;\n    }\n\n    /** Borra las acciones que ya no se pueden confirmar y tienen más de un día de vencidas. Se ejecuta de forma programada. */\n    @Scheduled(fixedDelayString = \"PT5M\", initialDelayString = \"PT1M\")\n    @Transactional\n    public int borrarVencidas() {\n        return repositorio.borrarVencidasAntesDe(reloj.instant().minus(RETENCION));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/api/NexusAutorizacionTest.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.AuditoriaConsultas;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoTokens;\nimport com.mx.josesaid.develop.nexus.application.ServicioPolizas;\nimport java.util.List;\nimport org.assertj.core.api.Assertions;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de NexusControlador y PolizasControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest({NexusControlador.class, PolizasControlador.class})\n@Import({com.mx.josesaid.develop.nexus.config.SeguridadConfig.class, NexusAutorizacionTest.Configuracion.class})\nclass NexusAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String CODIGO = \"{\\\"codigo\\\":\\\"12345678\\\"}\";\n    private static final String CONSULTA = \"{\\\"pregunta\\\":\\\"¿Cuál es el saldo de la cuenta 1000?\\\"}\";\n    private static final String SUGERENCIA = \"{\\\"descripcion\\\":\\\"Pago de renta de octubre\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private AsistenteIA asistente;\n\n    @MockitoBean\n    private AuditoriaConsultas auditoria;\n\n    @MockitoBean\n    private AccionesPendientes acciones;\n\n    @MockitoBean\n    private PresupuestoTokens presupuesto;\n\n    @MockitoBean\n    private ConfirmacionAcciones confirmacion;\n\n    @MockitoBean\n    private ServicioPolizas servicioPolizas;\n\n    @MockitoBean\n    private CodigoConfirmacion codigos;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO).claim(\"correo\", \"prueba@ejemplo.com\"))\n                .authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    private static MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b, String cuerpo) {\n        return b.contentType(MediaType.APPLICATION_JSON).content(cuerpo);\n    }\n\n    @Test\n    void confirmarAccion() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID + \"/confirmacion\";\n        permitido(peticion(json(post(ruta), CODIGO), \"VENTAS\"), \"POST confirmacion\", \"VENTAS\");\n        permitido(peticion(json(post(ruta), CODIGO), \"CONTADOR\"), \"POST confirmacion\", \"CONTADOR\");\n        denegado(peticion(json(post(ruta), CODIGO), \"ADMIN\"));\n    }\n\n    @Test\n    void datosAlta() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID + \"/alta\";\n        permitido(peticion(get(ruta), \"ADMIN\"), \"GET alta\", \"ADMIN\");\n        denegado(peticion(get(ruta), \"CONTADOR\"));\n    }\n\n    @Test\n    void verificarAlta() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID + \"/alta/verificacion\";\n        permitido(peticion(json(post(ruta), CODIGO), \"ADMIN\"), \"POST alta/verificacion\", \"ADMIN\");\n        denegado(peticion(json(post(ruta), CODIGO), \"VENTAS\"));\n    }\n\n    @Test\n    void completarAlta() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID + \"/alta/completacion\";\n        permitido(peticion(json(post(ruta), CODIGO), \"ADMIN\"), \"POST alta/completacion\", \"ADMIN\");\n        denegado(peticion(json(post(ruta), CODIGO), \"CONTADOR\"));\n    }\n\n    @Test\n    void consultarAccion() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID;\n        permitido(peticion(get(ruta), \"VENTAS\"), \"GET accion\", \"VENTAS\");\n        permitido(peticion(get(ruta), \"CONTADOR\"), \"GET accion\", \"CONTADOR\");\n        permitido(peticion(get(ruta), \"ADMIN\"), \"GET accion\", \"ADMIN\");\n        denegado(peticion(get(ruta), \"DIRECCION\"));\n    }\n\n    @Test\n    void cancelarAccion() throws Exception {\n        String ruta = \"/nexus/acciones/\" + ID + \"/cancelacion\";\n        permitido(peticion(post(ruta), \"VENTAS\"), \"POST cancelacion\", \"VENTAS\");\n        denegado(peticion(post(ruta), \"ADMIN\"));\n    }\n\n    @Test\n    void consultarAsistente() throws Exception {\n        String ruta = \"/nexus/consultas\";\n        permitido(peticion(json(post(ruta), CONSULTA), \"VENTAS\"), \"POST consultas\", \"VENTAS\");\n        permitido(peticion(json(post(ruta), CONSULTA), \"DIRECCION\"), \"POST consultas\", \"DIRECCION\");\n        // Cualquier usuario autenticado puede consultar; sin token la petición no entra.\n        mvc.perform(json(post(ruta), CONSULTA)).andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void sugerirPoliza() throws Exception {\n        String ruta = \"/nexus/polizas/sugerencias\";\n        permitido(peticion(json(post(ruta), SUGERENCIA), \"CONTADOR\"), \"POST sugerencias\", \"CONTADOR\");\n        denegado(peticion(json(post(ruta), SUGERENCIA), \"VENTAS\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/api/NexusControladorIdentidadTest.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport java.time.Instant;\n\nimport org.junit.jupiter.api.Test;\nimport org.mockito.ArgumentCaptor;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoTokens;\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.AuditoriaConsultas;\nimport com.mx.josesaid.develop.nexus.application.RegistroConsulta;\nimport com.mx.josesaid.develop.nexus.application.RespuestaAsistente;\n\nclass NexusControladorIdentidadTest {\n\n    private static final String SUBJECT = \"4962f8ee-4e35-4cb6-9919-8ad95d37c245\";\n\n    @Test\n    void auditaElCorreoDelUsuarioCuandoElTokenLoTrae() {\n        AsistenteIA asistente = mock(AsistenteIA.class);\n        AuditoriaConsultas auditoria = mock(AuditoriaConsultas.class);\n        when(asistente.consultar(any())).thenReturn(new RespuestaAsistente(\"respuesta\"));\n        NexusControlador controlador = new NexusControlador(asistente, auditoria, mock(AccionesPendientes.class), mock(PresupuestoTokens.class), mock(ConfirmacionAcciones.class));\n\n        controlador.consultar(new ConsultaRequest(\"Dame clientes\"), jwt(SUBJECT, \"admin@empresa.mx\"));\n\n        ArgumentCaptor<RegistroConsulta> captor = ArgumentCaptor.forClass(RegistroConsulta.class);\n        verify(auditoria).registrar(captor.capture());\n        assertEquals(\"admin@empresa.mx\", captor.getValue().usuario());\n    }\n\n    @Test\n    void usaElIdentificadorCuandoElTokenNoTraeCorreo() {\n        AsistenteIA asistente = mock(AsistenteIA.class);\n        AuditoriaConsultas auditoria = mock(AuditoriaConsultas.class);\n        when(asistente.consultar(any())).thenReturn(new RespuestaAsistente(\"respuesta\"));\n        NexusControlador controlador = new NexusControlador(asistente, auditoria, mock(AccionesPendientes.class), mock(PresupuestoTokens.class), mock(ConfirmacionAcciones.class));\n\n        controlador.consultar(new ConsultaRequest(\"Dame clientes\"), jwt(SUBJECT, null));\n\n        ArgumentCaptor<RegistroConsulta> captor = ArgumentCaptor.forClass(RegistroConsulta.class);\n        verify(auditoria).registrar(captor.capture());\n        assertEquals(SUBJECT, captor.getValue().usuario());\n    }\n\n    @Test\n    void enmascaraElRfcEnLaRespuestaFinal() {\n        AsistenteIA asistente = mock(AsistenteIA.class);\n        AuditoriaConsultas auditoria = mock(AuditoriaConsultas.class);\n        when(asistente.consultar(any())).thenReturn(new RespuestaAsistente(\"Cliente PRU000101XAB\"));\n        NexusControlador controlador = new NexusControlador(asistente, auditoria, mock(AccionesPendientes.class), mock(PresupuestoTokens.class), mock(ConfirmacionAcciones.class));\n\n        var respuesta = controlador.consultar(new ConsultaRequest(\"Busca el RFC\"), jwt(SUBJECT, \"admin@empresa.mx\"));\n\n        assertEquals(\"Cliente [RFC]\", respuesta.respuesta());\n    }\n\n    private static Jwt jwt(String subject, String correo) {\n        Instant ahora = Instant.now();\n        Jwt.Builder builder = Jwt.withTokenValue(\"token-de-prueba\")\n                .header(\"alg\", \"RS256\")\n                .subject(subject)\n                .issuedAt(ahora)\n                .expiresAt(ahora.plusSeconds(300));\n        if (correo != null) {\n            builder.claim(\"correo\", correo);\n        }\n        return builder.build();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/api/NexusControladorTest.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport org.junit.jupiter.api.Test;\n\n/** Mapeo de errores. La validación de la solicitud y el control de acceso por rol se prueban en el paso 20. */\nclass NexusControladorTest {\n\n    @Test\n    void errorDeTiempoAgotadoSeMapeaA504() {\n        ManejoErrores manejo = new ManejoErrores();\n        var problema = manejo.tiempoAgotado(new org.springframework.web.client.ResourceAccessException(\"timeout\"));\n\n        assertThat(problema.getStatus()).isEqualTo(504);\n        assertThat(problema.getTitle()).isEqualTo(\"Gateway Timeout\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/api/NexusIT.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.doThrow;\nimport static org.mockito.Mockito.never;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.nexus.application.AccionNoPendienteException;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.ConfirmacionAcciones;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoAgotadoException;\nimport com.mx.josesaid.develop.nexus.application.PresupuestoTokens;\nimport java.time.Instant;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.ai.anthropic.AnthropicChatOptions;\nimport org.springframework.ai.chat.messages.AssistantMessage;\nimport org.springframework.ai.chat.model.ChatModel;\nimport org.springframework.ai.chat.model.ChatResponse;\nimport org.springframework.ai.chat.model.Generation;\nimport org.springframework.ai.chat.prompt.Prompt;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;\nimport org.springframework.boot.jdbc.test.autoconfigure.AutoConfigureTestDatabase;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.testcontainers.containers.PostgreSQLContainer;\nimport org.testcontainers.utility.DockerImageName;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\n\n/**\n * Integración con PostgreSQL real (Testcontainers): permisos por rol, auditoría y migraciones.\n * El modelo se simula: esta prueba no hace llamadas a Claude.\n * Requiere Docker. Se ejecuta con: mvn verify (failsafe).\n */\n@SpringBootTest\n@AutoConfigureMockMvc\n@Testcontainers\nclass NexusIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>(DockerImageName.parse(\"pgvector/pgvector:pg17\").asCompatibleSubstituteFor(\"postgres\"));\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @MockitoBean\n    private ChatModel modelo;\n\n    @MockitoBean\n    private AccionesPendientes acciones;\n\n    @MockitoBean\n    private ConfirmacionAcciones confirmacion;\n\n    @MockitoBean\n    private PresupuestoTokens presupuesto;\n\n    private static final String ACCION_ID = \"7d3c1f2e-0000-4000-8000-000000000001\";\n\n    private static org.springframework.security.core.authority.SimpleGrantedAuthority rol(String nombre) {\n        return new org.springframework.security.core.authority.SimpleGrantedAuthority(nombre);\n    }\n\n    private static ChatResponse respuesta(String texto) {\n        return new ChatResponse(java.util.List.of(new Generation(new AssistantMessage(texto))));\n    }\n\n    @Test\n    void sinTokenResponde401() throws Exception {\n        mvc.perform(post(\"/nexus/consultas\").contentType(\"application/json\")\n                        .content(\"{\\\"pregunta\\\":\\\"Hola\\\"}\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void usuarioAutenticadoSinRolDeAreaResponde200() throws Exception {\n        when(modelo.getOptions()).thenReturn(AnthropicChatOptions.builder().build());\n        when(modelo.call(any(Prompt.class))).thenReturn(respuesta(\"No tengo herramientas para tu rol.\"));\n        mvc.perform(post(\"/nexus/consultas\").contentType(\"application/json\")\n                        .content(\"{\\\"pregunta\\\":\\\"Hola\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u9\")).authorities(\n                                new org.springframework.security.core.authority.SimpleGrantedAuthority(\"ROLE_OTRO\"))))\n                .andExpect(status().isOk());\n    }\n\n    @Test\n    void consultaValidaRespondeYQuedaAuditada() throws Exception {\n        when(modelo.getOptions()).thenReturn(AnthropicChatOptions.builder().build());\n        when(modelo.call(any(Prompt.class))).thenReturn(respuesta(\"Hay 2 contratos por vencer.\"));\n        Integer antes = jdbc.queryForObject(\"select count(*) from nexus_consultas\", Integer.class);\n\n        mvc.perform(post(\"/nexus/consultas\").contentType(\"application/json\")\n                        .content(\"{\\\"pregunta\\\":\\\"¿Qué contratos vencen? Escribe a a@b.com\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(\n                                new org.springframework.security.core.authority.SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.respuesta\").value(\"Hay 2 contratos por vencer.\"));\n\n        Integer despues = jdbc.queryForObject(\"select count(*) from nexus_consultas\", Integer.class);\n        assertThat(despues).isEqualTo(antes + 1);\n        String preguntaAuditada = jdbc.queryForObject(\n                \"select pregunta_redactada from nexus_consultas where usuario = 'u-ventas' order by creado_utc desc limit 1\",\n                String.class);\n        assertThat(preguntaAuditada).doesNotContain(\"a@b.com\").contains(\"[CORREO]\");\n    }\n\n    @Test\n    void confirmarSinTokenResponde401() throws Exception {\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void confirmarSinRolVentasResponde403() throws Exception {\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\")\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(\"{\\\"codigo\\\":\\\"12345678\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-compras\")).authorities(rol(\"ROLE_COMPRAS\"))))\n                .andExpect(status().isForbidden());\n    }\n\n    @Test\n    void confirmarPropiaAccionResponde201() throws Exception {\n        when(confirmacion.confirmarConCodigo(java.util.UUID.fromString(ACCION_ID), \"u-ventas\", \"12345678\"))\n                .thenReturn(\"{\\\"id\\\":\\\"ped-1\\\"}\");\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\")\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(\"{\\\"codigo\\\":\\\"12345678\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.id\").value(\"ped-1\"));\n    }\n\n    @Test\n    void confirmarSinCodigoResponde400() throws Exception {\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\")\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(\"{}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void confirmarAccionAjenaResponde404() throws Exception {\n        when(confirmacion.confirmarConCodigo(java.util.UUID.fromString(ACCION_ID), \"u-otro\", \"12345678\"))\n                .thenThrow(new com.mx.josesaid.develop.nexus.application.AccionNoEncontradaException(\"Acción no encontrada\"));\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\")\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(\"{\\\"codigo\\\":\\\"12345678\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-otro\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isNotFound());\n    }\n\n    @Test\n    void confirmarAccionYaConfirmadaResponde409() throws Exception {\n        when(confirmacion.confirmarConCodigo(java.util.UUID.fromString(ACCION_ID), \"u-ventas\", \"12345678\"))\n                .thenThrow(new com.mx.josesaid.develop.nexus.application.AccionNoPendienteException(\"La acción ya está confirmada\"));\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/confirmacion\")\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON).content(\"{\\\"codigo\\\":\\\"12345678\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isConflict());\n    }\n\n    @Test\n    void consultarAccionPropiaMuestraResumenSinPayload() throws Exception {\n        java.util.UUID id = java.util.UUID.fromString(ACCION_ID);\n        when(acciones.consultar(id, \"u-ventas\")).thenReturn(new AccionPendiente(id, \"u-ventas\",\n                \"PEDIDO_BORRADOR\", \"{\\\"clienteId\\\":\\\"c1\\\"}\", \"Pedido para c1\", \"PENDIENTE\",\n                Instant.now(), Instant.now().plusSeconds(600)));\n        mvc.perform(get(\"/nexus/acciones/\" + ACCION_ID)\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.resumen\").value(\"Pedido para c1\"))\n                .andExpect(jsonPath(\"$.estatus\").value(\"PENDIENTE\"))\n                .andExpect(jsonPath(\"$.payload\").doesNotExist());\n    }\n\n    @Test\n    void consultarAccionAjenaResponde404() throws Exception {\n        when(acciones.consultar(java.util.UUID.fromString(ACCION_ID), \"u-otro\"))\n                .thenThrow(new com.mx.josesaid.develop.nexus.application.AccionNoEncontradaException(\"Acción no encontrada\"));\n        mvc.perform(get(\"/nexus/acciones/\" + ACCION_ID)\n                        .with(jwt().jwt(j -> j.subject(\"u-otro\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isNotFound());\n    }\n\n    @Test\n    void cancelarPropiaAccionResponde204() throws Exception {\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/cancelacion\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isNoContent());\n    }\n\n    @Test\n    void cancelarAccionYaConfirmadaResponde409() throws Exception {\n        doThrow(new AccionNoPendienteException(\"La acción ya está confirmada\"))\n                .when(acciones).cancelar(java.util.UUID.fromString(ACCION_ID), \"u-ventas\");\n        mvc.perform(post(\"/nexus/acciones/\" + ACCION_ID + \"/cancelacion\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isConflict());\n    }\n\n    @Test\n    void preguntaVaciaResponde400() throws Exception {\n        mvc.perform(post(\"/nexus/consultas\").contentType(\"application/json\")\n                        .content(\"{\\\"pregunta\\\":\\\"\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u1\")).authorities(\n                                new org.springframework.security.core.authority.SimpleGrantedAuthority(\"ROLE_VENTAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void presupuestoAgotadoResponde429SinLlamarAlModelo() throws Exception {\n        doThrow(new PresupuestoAgotadoException(\"Alcanzaste tu límite diario de tokens.\"))\n                .when(presupuesto).exigirDisponible(\"u-ventas\");\n        mvc.perform(post(\"/nexus/consultas\").contentType(\"application/json\")\n                        .content(\"{\\\"pregunta\\\":\\\"Hola\\\"}\")\n                        .with(jwt().jwt(j -> j.subject(\"u-ventas\")).authorities(rol(\"ROLE_VENTAS\"))))\n                .andExpect(status().isTooManyRequests())\n                .andExpect(jsonPath(\"$.detail\").value(\"Alcanzaste tu límite diario de tokens.\"));\n        verify(modelo, never()).call(any(Prompt.class));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/api/ServidorMcpIT.java": "package com.mx.josesaid.develop.nexus.api;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.testcontainers.containers.PostgreSQLContainer;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.utility.DockerImageName;\n\nimport com.fasterxml.jackson.databind.JsonNode;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\n/**\n * Prueba el endpoint /mcp de punta a punta: JWT, lista de herramientas, confirmación con código\n * y permisos por rol. Requiere Docker. Se ejecuta con: mvn verify (failsafe).\n */\n@SpringBootTest(properties = \"nexus.rag.ingesta-al-arrancar=false\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass ServidorMcpIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>(\n            DockerImageName.parse(\"pgvector/pgvector:pg17\").asCompatibleSubstituteFor(\"postgres\"));\n\n    private static final String VERSION = \"2025-06-18\";\n    private static final String CONTADOR = \"u-contador\";\n    private static final ObjectMapper JSON = new ObjectMapper();\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Autowired\n    private AccionesPendientes acciones;\n\n    private int siguienteId = 1;\n\n    private String rpc(String metodo, String paramsJson, String rol, String sesion) throws Exception {\n        return rpcBody(metodo, paramsJson, rol, sesion, CONTADOR);\n    }\n\n    private String rpcBody(String metodo, String paramsJson, String rol, String sesion, String sujeto) throws Exception {\n        String cuerpo = \"{\\\"jsonrpc\\\":\\\"2.0\\\",\\\"id\\\":\" + siguienteId++ + \",\\\"method\\\":\\\"\" + metodo + \"\\\"\"\n                + (paramsJson == null ? \"\" : \",\\\"params\\\":\" + paramsJson) + \"}\";\n        var peticion = post(\"/mcp\").contentType(\"application/json\")\n                .accept(\"application/json\", \"text/event-stream\")\n                .header(\"MCP-Protocol-Version\", VERSION)\n                .content(cuerpo)\n                .with(jwt().jwt(j -> j.subject(sujeto)).authorities(new SimpleGrantedAuthority(rol)));\n        if (sesion != null) {\n            peticion.header(\"Mcp-Session-Id\", sesion);\n        }\n        MvcResult resultado = mvc.perform(peticion).andReturn();\n        return new String(resultado.getResponse().getContentAsByteArray(), java.nio.charset.StandardCharsets.UTF_8);\n    }\n\n    /** Extrae el JSON-RPC de la respuesta, sea JSON directo o un evento SSE. */\n    private static JsonNode json(String cuerpo) throws Exception {\n        String texto = cuerpo.contains(\"data:\")\n                ? cuerpo.substring(cuerpo.indexOf(\"data:\") + 5).split(\"\\n\")[0].trim()\n                : cuerpo.trim();\n        return JSON.readTree(texto);\n    }\n\n    private String iniciarSesion(String rol) throws Exception {\n        var peticion = post(\"/mcp\").contentType(\"application/json\")\n                .accept(\"application/json\", \"text/event-stream\")\n                .content(\"{\\\"jsonrpc\\\":\\\"2.0\\\",\\\"id\\\":0,\\\"method\\\":\\\"initialize\\\",\\\"params\\\":{\\\"protocolVersion\\\":\\\"\"\n                        + VERSION + \"\\\",\\\"capabilities\\\":{},\\\"clientInfo\\\":{\\\"name\\\":\\\"prueba\\\",\\\"version\\\":\\\"1\\\"}}}\")\n                .with(jwt().jwt(j -> j.subject(CONTADOR)).authorities(new SimpleGrantedAuthority(rol)));\n        MvcResult resultado = mvc.perform(peticion).andExpect(status().isOk()).andReturn();\n        String sesion = resultado.getResponse().getHeader(\"Mcp-Session-Id\");\n        assertThat(sesion).isNotBlank();\n        rpc(\"notifications/initialized\", null, rol, sesion);\n        return sesion;\n    }\n\n    private String textoDeHerramienta(String cuerpo) throws Exception {\n        JsonNode resultado = json(cuerpo).get(\"result\");\n        return resultado.get(\"content\").get(0).get(\"text\").asText();\n    }\n\n    @Test\n    void sinTokenResponde401() throws Exception {\n        mvc.perform(post(\"/mcp\").contentType(\"application/json\")\n                        .accept(\"application/json\", \"text/event-stream\")\n                        .content(\"{\\\"jsonrpc\\\":\\\"2.0\\\",\\\"id\\\":0,\\\"method\\\":\\\"initialize\\\"}\"))\n                .andExpect(status().isUnauthorized());\n    }\n\n    @Test\n    void listaSoloLasHerramientasDelServidorMcp() throws Exception {\n        String sesion = iniciarSesion(\"ROLE_CONTADOR\");\n\n        JsonNode lista = json(rpc(\"tools/list\", \"{}\", \"ROLE_CONTADOR\", sesion)).get(\"result\").get(\"tools\");\n        java.util.List<String> nombres = new java.util.ArrayList<>();\n        lista.forEach(t -> nombres.add(t.get(\"name\").asText()));\n\n        assertThat(nombres).contains(\"consultar_politicas\", \"sugerir_poliza\", \"confirmar_accion\", \"cancelar_accion\");\n        assertThat(nombres).doesNotContain(\"cancelar_pedido\", \"confirmar_pedido\");\n    }\n\n    @Test\n    void confirmarConCodigoIncorrectoCancelaLaAccion() throws Exception {\n        AccionPendiente preparada = acciones.preparar(CONTADOR, AccionesPendientes.TIPO_POLIZA_REGISTRAR,\n                \"{}\", \"Póliza de prueba\");\n        String sesion = iniciarSesion(\"ROLE_CONTADOR\");\n\n        String respuesta = rpc(\"tools/call\",\n                \"{\\\"name\\\":\\\"confirmar_accion\\\",\\\"arguments\\\":{\\\"accionId\\\":\\\"\" + preparada.id()\n                        + \"\\\",\\\"codigo\\\":\\\"00000000\\\"}}\", \"ROLE_CONTADOR\", sesion);\n\n        assertThat(textoDeHerramienta(respuesta)).contains(\"Código incorrecto\");\n        assertThat(acciones.consultar(preparada.id(), CONTADOR).estatus())\n                .isEqualTo(AccionPendiente.CANCELADA);\n    }\n\n    @Test\n    void rolSinPermisoNoEjecutaSugerirPoliza() throws Exception {\n        String sesion = iniciarSesion(\"ROLE_COMPRAS\");\n\n        String respuesta = rpc(\"tools/call\",\n                \"{\\\"name\\\":\\\"sugerir_poliza\\\",\\\"arguments\\\":{\\\"descripcion\\\":\\\"Venta de 1000\\\"}}\",\n                \"ROLE_COMPRAS\", sesion);\n\n        assertThat(json(respuesta).get(\"result\").get(\"isError\").asBoolean()).isTrue();\n        assertThat(textoDeHerramienta(respuesta)).contains(\"Sin permiso\");\n    }\n\n    @Test\n    void confirmarAccionAjenaNoSeEjecuta() throws Exception {\n        AccionPendiente ajena = acciones.preparar(\"u-otro\", AccionesPendientes.TIPO_POLIZA_REGISTRAR,\n                \"{}\", \"Póliza ajena\");\n        String sesion = iniciarSesion(\"ROLE_CONTADOR\");\n\n        String respuesta = rpc(\"tools/call\",\n                \"{\\\"name\\\":\\\"confirmar_accion\\\",\\\"arguments\\\":{\\\"accionId\\\":\\\"\" + ajena.id()\n                        + \"\\\",\\\"codigo\\\":\\\"00000000\\\"}}\", \"ROLE_CONTADOR\", sesion);\n\n        assertThat(textoDeHerramienta(respuesta)).contains(\"no encontrada\");\n        assertThat(acciones.consultar(ajena.id(), \"u-otro\").estatus()).isEqualTo(AccionPendiente.PENDIENTE);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/AccionesPendientesTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass AccionesPendientesTest {\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private final List<String> ejecuciones = new ArrayList<>();\n    private Instant ahora;\n    private AccionesPendientes servicio;\n    private boolean fallarEjecucion;\n\n    @BeforeEach\n    void preparar() {\n        ahora = Instant.parse(\"2026-11-01T00:00:00Z\");\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            if (fallarEjecucion) {\n                throw new IllegalStateException(\"servicio caído\");\n            }\n            ejecuciones.add(tipo + \":\" + payload);\n            return \"{\\\"id\\\":\\\"pedido-1\\\"}\";\n        };\n        Clock reloj = new Clock() {\n            @Override\n            public java.time.ZoneId getZone() {\n                return ZoneOffset.UTC;\n            }\n\n            @Override\n            public Clock withZone(java.time.ZoneId zona) {\n                return this;\n            }\n\n            @Override\n            public Instant instant() {\n                return ahora;\n            }\n        };\n        servicio = new AccionesPendientes(repo, ejecutor, reloj);\n    }\n\n    @Test\n    void elDuenoConfirmaYSeEjecutaUnaVez() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR,\n                \"{\\\"clienteId\\\":\\\"c1\\\"}\", \"resumen\");\n\n        String respuesta = servicio.confirmar(accion.id(), \"u-ventas\");\n\n        assertThat(respuesta).contains(\"pedido-1\");\n        assertThat(ejecuciones).containsExactly(\"PEDIDO_BORRADOR:{\\\"clienteId\\\":\\\"c1\\\"}\");\n        assertThat(almacen.get(accion.id()).estatus()).isEqualTo(AccionPendiente.CONFIRMADA);\n    }\n\n    @Test\n    void otroUsuarioNoPuedeConfirmarLaAccion() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n\n        assertThatThrownBy(() -> servicio.confirmar(accion.id(), \"u-otro\"))\n                .isInstanceOf(AccionNoEncontradaException.class);\n        assertThat(ejecuciones).isEmpty();\n    }\n\n    @Test\n    void unaAccionYaConfirmadaNoSeEjecutaDeNuevo() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n        servicio.confirmar(accion.id(), \"u-ventas\");\n\n        assertThatThrownBy(() -> servicio.confirmar(accion.id(), \"u-ventas\"))\n                .isInstanceOf(AccionNoPendienteException.class);\n        assertThat(ejecuciones).hasSize(1);\n    }\n\n    @Test\n    void unaAccionVencidaNoSeEjecuta() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n        ahora = ahora.plus(AccionesPendientes.VIGENCIA).plusSeconds(1);\n\n        assertThatThrownBy(() -> servicio.confirmar(accion.id(), \"u-ventas\"))\n                .isInstanceOf(AccionNoPendienteException.class);\n        assertThat(ejecuciones).isEmpty();\n        assertThat(almacen.get(accion.id()).estatus()).isEqualTo(AccionPendiente.EXPIRADA);\n    }\n\n    @Test\n    void siFallaLaEjecucionLaAccionSiguePendiente() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n        fallarEjecucion = true;\n\n        assertThatThrownBy(() -> servicio.confirmar(accion.id(), \"u-ventas\"))\n                .isInstanceOf(IllegalStateException.class);\n        assertThat(almacen.get(accion.id()).estatus()).isEqualTo(AccionPendiente.PENDIENTE);\n\n        fallarEjecucion = false;\n        servicio.confirmar(accion.id(), \"u-ventas\");\n        assertThat(ejecuciones).hasSize(1);\n    }\n\n    @Test\n    void consultarNoRevelaAccionesAjenas() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n\n        assertThatThrownBy(() -> servicio.consultar(accion.id(), \"u-otro\"))\n                .isInstanceOf(AccionNoEncontradaException.class);\n    }\n\n    @Test\n    void consultarMarcaComoExpiradaUnaAccionVencida() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n        ahora = ahora.plus(AccionesPendientes.VIGENCIA).plusSeconds(1);\n\n        AccionPendiente consultada = servicio.consultar(accion.id(), \"u-ventas\");\n\n        assertThat(consultada.estatus()).isEqualTo(AccionPendiente.EXPIRADA);\n        assertThat(almacen.get(accion.id()).estatus()).isEqualTo(AccionPendiente.EXPIRADA);\n    }\n\n    @Test\n    void cancelarImpideConfirmarDespues() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n\n        servicio.cancelar(accion.id(), \"u-ventas\");\n\n        assertThat(almacen.get(accion.id()).estatus()).isEqualTo(AccionPendiente.CANCELADA);\n        assertThatThrownBy(() -> servicio.confirmar(accion.id(), \"u-ventas\"))\n                .isInstanceOf(AccionNoPendienteException.class);\n        assertThat(ejecuciones).isEmpty();\n    }\n\n    @Test\n    void noSePuedeCancelarUnaAccionYaConfirmada() {\n        AccionPendiente accion = servicio.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR, \"{}\", \"r\");\n        servicio.confirmar(accion.id(), \"u-ventas\");\n\n        assertThatThrownBy(() -> servicio.cancelar(accion.id(), \"u-ventas\"))\n                .isInstanceOf(AccionNoPendienteException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/CodigoConfirmacionTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.nio.charset.StandardCharsets;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\n\nclass CodigoConfirmacionTest {\n\n    private static final UUID ACCION = UUID.fromString(\"11111111-1111-4111-8111-111111111111\");\n    private final CodigoConfirmacion codigos = new CodigoConfirmacion(\n            \"secreto-de-prueba-de-32-bytes-ok!\".getBytes(StandardCharsets.UTF_8));\n\n    @Test\n    void elCodigoTieneOchoDigitosYEsEstable() {\n        String codigo = codigos.generar(ACCION, \"contador1\");\n\n        assertThat(codigo).matches(\"\\\\d{8}\");\n        assertThat(codigos.generar(ACCION, \"contador1\")).isEqualTo(codigo);\n    }\n\n    @Test\n    void elCodigoDependeDelUsuarioQueLaPrepara() {\n        assertThat(codigos.generar(ACCION, \"contador1\")).isNotEqualTo(codigos.generar(ACCION, \"otro\"));\n    }\n\n    @Test\n    void coincideSoloConElCodigoCorrecto() {\n        String codigo = codigos.generar(ACCION, \"contador1\");\n\n        assertThat(codigos.coincide(ACCION, \"contador1\", codigo)).isTrue();\n        assertThat(codigos.coincide(ACCION, \"contador1\", \" \" + codigo + \" \")).isTrue();\n        assertThat(codigos.coincide(ACCION, \"contador1\", \"00000000\")).isFalse();\n        assertThat(codigos.coincide(ACCION, \"contador1\", null)).isFalse();\n    }\n\n    @Test\n    void unSecretoCortoSeRechaza() {\n        assertThatThrownBy(() -> new CodigoConfirmacion(new byte[4]))\n                .isInstanceOf(IllegalArgumentException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/ConfirmacionAccionesTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.nio.charset.StandardCharsets;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\n\nclass ConfirmacionAccionesTest {\n\n    private final Clock reloj = Clock.fixed(Instant.parse(\"2026-11-15T18:00:00Z\"), ZoneOffset.UTC);\n    private final Map<UUID, AccionPendiente> almacenadas = new HashMap<>();\n    private final List<String> ejecuciones = new ArrayList<>();\n    private final CodigoConfirmacion codigos = new CodigoConfirmacion(\n            \"secreto-de-prueba-de-32-bytes-ok!\".getBytes(StandardCharsets.UTF_8));\n    private final AccionesPendientes acciones = new AccionesPendientes(new AlmacenAcciones() {\n        @Override\n        public void guardar(AccionPendiente accion) {\n            almacenadas.put(accion.id(), accion);\n        }\n\n        @Override\n        public Optional<AccionPendiente> buscar(UUID id) {\n            return Optional.ofNullable(almacenadas.get(id));\n        }\n    }, (tipo, payload) -> {\n        ejecuciones.add(tipo);\n        return \"ok\";\n    }, reloj);\n    private final ConfirmacionAcciones confirmaciones = new ConfirmacionAcciones(acciones, codigos);\n\n    private AccionPendiente preparada() {\n        return acciones.preparar(\"contador1\", AccionesPendientes.TIPO_POLIZA_REGISTRAR, \"{}\", \"resumen\");\n    }\n\n    @Test\n    void conElCodigoCorrectoSeEjecuta() {\n        AccionPendiente accion = preparada();\n\n        String respuesta = confirmaciones.confirmarConCodigo(accion.id(), \"contador1\",\n                codigos.generar(accion.id(), \"contador1\"));\n\n        assertThat(respuesta).isEqualTo(\"ok\");\n        assertThat(ejecuciones).hasSize(1);\n        assertThat(almacenadas.get(accion.id()).estatus()).isEqualTo(AccionPendiente.CONFIRMADA);\n    }\n\n    @Test\n    void unCodigoIncorrectoCancelaLaAccionSinEjecutarla() {\n        AccionPendiente accion = preparada();\n\n        assertThatThrownBy(() -> confirmaciones.confirmarConCodigo(accion.id(), \"contador1\", \"12345678\"))\n                .isInstanceOf(CodigoConfirmacionInvalidoException.class);\n\n        assertThat(ejecuciones).isEmpty();\n        assertThat(almacenadas.get(accion.id()).estatus()).isEqualTo(AccionPendiente.CANCELADA);\n    }\n\n    @Test\n    void otroUsuarioNoPuedeConfirmarAunqueTengaElCodigo() {\n        AccionPendiente accion = preparada();\n\n        assertThatThrownBy(() -> confirmaciones.confirmarConCodigo(accion.id(), \"otro\",\n                codigos.generar(accion.id(), \"contador1\")))\n                .isInstanceOf(AccionNoEncontradaException.class);\n        assertThat(ejecuciones).isEmpty();\n    }\n\n    @Test\n    void elCodigoSeUsaUnaSolaVez() {\n        AccionPendiente accion = preparada();\n        String codigo = codigos.generar(accion.id(), \"contador1\");\n        confirmaciones.confirmarConCodigo(accion.id(), \"contador1\", codigo);\n\n        assertThatThrownBy(() -> confirmaciones.confirmarConCodigo(accion.id(), \"contador1\", codigo))\n                .isInstanceOf(AccionNoPendienteException.class);\n        assertThat(ejecuciones).hasSize(1);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/DatosAltaTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.util.List;\n\nimport org.junit.jupiter.api.Test;\n\nclass DatosAltaTest {\n\n    @Test\n    void leeCorreoNombreYRolesDelPayload() {\n        DatosAlta datos = DatosAlta.de(\"{\\\"correo\\\":\\\"ana@empresa.com\\\",\\\"nombreCompleto\\\":\\\"Ana López\\\",\"\n                + \"\\\"roles\\\":[\\\"VENTAS\\\",\\\"CONTADOR\\\"]}\");\n\n        assertThat(datos.correo()).isEqualTo(\"ana@empresa.com\");\n        assertThat(datos.nombreCompleto()).isEqualTo(\"Ana López\");\n        assertThat(datos.roles()).containsExactly(\"VENTAS\", \"CONTADOR\");\n    }\n\n    @Test\n    void payloadInvalidoFalla() {\n        assertThatThrownBy(() -> DatosAlta.de(\"no es json\"))\n                .isInstanceOf(IllegalStateException.class);\n    }\n\n    @Test\n    void listaVaciaSeConservaComoListaVacia() {\n        assertThat(DatosAlta.de(\"{\\\"correo\\\":\\\"a@b.co\\\",\\\"nombreCompleto\\\":\\\"A\\\",\\\"roles\\\":[]}\").roles())\n                .isEqualTo(List.of());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/IngestaPoliticasTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\nimport org.junit.jupiter.api.Test;\n\nclass IngestaPoliticasTest {\n\n    private static final String CUERPO = \"\"\"\n            # Política\n\n            1. Toda orden la crea COMPRAS.\n\n            2. Menos de 1,000,000 USD lo aprueba COMPRAS.\n            \"\"\";\n\n    @Test\n    void indexaCadaReglaComoFragmentoConMetadatos() {\n        Politica politica = new Politica(\"aprobacion\", \"Aprobación\", LocalDate.of(2026, 11, 1),\n                List.of(\"COMPRAS\", \"DIRECCION\"), CUERPO);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        IngestaPoliticas ingesta = new IngestaPoliticas(\n                (textos, tipo) -> textos.stream().map(t -> new float[]{t.length()}).toList(), almacen);\n\n        int total = ingesta.ingerir(List.of(politica));\n\n        assertThat(total).isEqualTo(2);\n        List<FragmentoIndexado> guardados = almacen.porPolitica.get(\"aprobacion\");\n        assertThat(guardados).hasSize(2);\n        assertThat(guardados.get(0).indice()).isZero();\n        assertThat(guardados.get(0).texto()).isEqualTo(\"1. Toda orden la crea COMPRAS.\");\n        assertThat(guardados.get(0).roles()).containsExactly(\"COMPRAS\", \"DIRECCION\");\n        assertThat(guardados.get(0).vigencia()).isEqualTo(LocalDate.of(2026, 11, 1));\n    }\n\n    @Test\n    void embebeConTituloComoContexto() {\n        Politica politica = new Politica(\"aprobacion\", \"Aprobación\", LocalDate.of(2026, 11, 1),\n                List.of(\"COMPRAS\"), CUERPO);\n        List<String> enviados = new ArrayList<>();\n        IngestaPoliticas ingesta = new IngestaPoliticas((textos, tipo) -> {\n            enviados.addAll(textos);\n            assertThat(tipo).isEqualTo(Embedder.TipoEntrada.DOCUMENTO);\n            return textos.stream().map(t -> new float[]{1f}).toList();\n        }, new AlmacenEnMemoria());\n\n        ingesta.ingerir(List.of(politica));\n\n        assertThat(enviados).allMatch(t -> t.startsWith(\"Aprobación. \"));\n    }\n\n    @Test\n    void reemplazaFragmentosAlVolverAIngerir() {\n        Politica politica = new Politica(\"aprobacion\", \"Aprobación\", LocalDate.of(2026, 11, 1),\n                List.of(\"COMPRAS\"), CUERPO);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        IngestaPoliticas ingesta = new IngestaPoliticas(\n                (textos, tipo) -> textos.stream().map(t -> new float[]{1f}).toList(), almacen);\n\n        ingesta.ingerir(List.of(politica));\n        ingesta.ingerir(List.of(politica));\n\n        assertThat(almacen.porPolitica.get(\"aprobacion\")).hasSize(2);\n    }\n\n    /** Almacén en memoria: solo guarda, no filtra. El filtro por rol se prueba en AlmacenFragmentosJdbcIT. */\n    static final class AlmacenEnMemoria implements AlmacenFragmentos {\n        final Map<String, List<FragmentoIndexado>> porPolitica = new java.util.HashMap<>();\n\n        @Override\n        public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n            porPolitica.put(politicaId, List.copyOf(fragmentos));\n        }\n\n        @Override\n        public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n            throw new UnsupportedOperationException();\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/PoliticaTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.time.LocalDate;\nimport java.util.List;\n\nimport org.junit.jupiter.api.Test;\n\nclass PoliticaTest {\n\n    private static final String CONTENIDO = \"\"\"\n            ---\n            titulo: Política de aprobación de órdenes de compra\n            vigencia: 2026-11-01\n            roles: [compras, DIRECCION]\n            ---\n\n            # Política\n\n            1. Toda orden la crea COMPRAS.\n            \"\"\";\n\n    @Test\n    void leeFrontMatterYCuerpo() {\n        Politica politica = Politica.desde(\"aprobacion-ordenes-compra\", CONTENIDO);\n\n        assertThat(politica.id()).isEqualTo(\"aprobacion-ordenes-compra\");\n        assertThat(politica.titulo()).isEqualTo(\"Política de aprobación de órdenes de compra\");\n        assertThat(politica.vigencia()).isEqualTo(LocalDate.of(2026, 11, 1));\n        assertThat(politica.roles()).containsExactly(\"COMPRAS\", \"DIRECCION\");\n        assertThat(politica.cuerpo()).contains(\"1. Toda orden la crea COMPRAS.\");\n    }\n\n    @Test\n    void rechazaPoliticaSinFrontMatter() {\n        assertThatThrownBy(() -> Politica.desde(\"x\", \"# Sin front matter\"))\n                .isInstanceOf(IllegalArgumentException.class)\n                .hasMessageContaining(\"front matter\");\n    }\n\n    @Test\n    void rechazaPoliticaSinRoles() {\n        String sinRoles = \"---\\ntitulo: T\\nvigencia: 2026-11-01\\nroles: []\\n---\\nTexto\";\n\n        assertThatThrownBy(() -> Politica.desde(\"x\", sinRoles))\n                .isInstanceOf(IllegalArgumentException.class)\n                .hasMessageContaining(\"roles\");\n    }\n\n    @Test\n    void rolesVacioEnRecordNoSeAcepta() {\n        assertThatThrownBy(() -> new Politica(\"x\", \"T\", LocalDate.now(), List.of(), \"Texto\"))\n                .isInstanceOf(IllegalArgumentException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/PresupuestoTokensEtiquetaTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.Test;\n\nclass PresupuestoTokensEtiquetaTest {\n\n    @Test\n    void noRegistraElCorreoEnClaro() {\n        String etiqueta = PresupuestoTokens.etiqueta(\"ana@empresa.com\");\n\n        assertThat(etiqueta).startsWith(\"u-\").doesNotContain(\"ana\").doesNotContain(\"@\");\n    }\n\n    @Test\n    void mismoUsuarioMismaEtiquetaSinImportarMayusculas() {\n        assertThat(PresupuestoTokens.etiqueta(\"Ana@Empresa.com\"))\n                .isEqualTo(PresupuestoTokens.etiqueta(\"ana@empresa.com\"));\n    }\n\n    @Test\n    void usuariosDistintosDistintaEtiqueta() {\n        assertThat(PresupuestoTokens.etiqueta(\"ana@empresa.com\"))\n                .isNotEqualTo(PresupuestoTokens.etiqueta(\"luis@empresa.com\"));\n    }\n\n    @Test\n    void sinUsuarioDevuelveDesconocido() {\n        assertThat(PresupuestoTokens.etiqueta(null)).isEqualTo(\"desconocido\");\n        assertThat(PresupuestoTokens.etiqueta(\"  \")).isEqualTo(\"desconocido\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/PresupuestoTokensTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.function.ToLongBiFunction;\nimport java.util.function.ToLongFunction;\n\nimport org.junit.jupiter.api.Test;\n\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\n\nclass PresupuestoTokensTest {\n\n    // 15 de noviembre de 2026, 12:00 en Ciudad de México (UTC-06:00).\n    private static final Clock RELOJ = Clock.fixed(Instant.parse(\"2026-11-15T18:00:00Z\"), ZoneOffset.UTC);\n    private static final Instant INICIO_DIA = Instant.parse(\"2026-11-15T06:00:00Z\");\n    private static final long SERVICIO = 1_000_000;\n\n    private static ConsumoTokens consumo(ToLongBiFunction<String, Instant> porUsuario, ToLongFunction<Instant> servicio) {\n        return new ConsumoTokens() {\n            @Override\n            public long desde(String usuario, Instant desde) {\n                return porUsuario.applyAsLong(usuario, desde);\n            }\n\n            @Override\n            public long delServicio(Instant desde) {\n                return servicio.applyAsLong(desde);\n            }\n        };\n    }\n\n    private static PresupuestoTokens presupuesto(ConsumoTokens consumo, SimpleMeterRegistry registro) {\n        return new PresupuestoTokens(consumo, 150_000, 15_000, SERVICIO, RELOJ, registro);\n    }\n\n    @Test\n    void sinConsumoHayPresupuesto() {\n        presupuesto(consumo((u, d) -> 0, d -> 0), new SimpleMeterRegistry()).exigirDisponible(\"u-ventas\");\n    }\n\n    @Test\n    void alcanzarElTopeDiarioDelUsuarioBloquea() {\n        PresupuestoTokens presupuesto = presupuesto(consumo((u, d) -> 15_000, d -> 0), new SimpleMeterRegistry());\n\n        assertThatThrownBy(() -> presupuesto.exigirDisponible(\"u-ventas\"))\n                .isInstanceOf(PresupuestoAgotadoException.class)\n                .hasMessageContaining(\"límite diario\");\n    }\n\n    @Test\n    void alcanzarElTopeMensualDelUsuarioBloqueaAunqueElDiaEstePermitido() {\n        PresupuestoTokens presupuesto = presupuesto(\n                consumo((u, d) -> d.equals(INICIO_DIA) ? 0 : 150_000, d -> 0), new SimpleMeterRegistry());\n\n        assertThatThrownBy(() -> presupuesto.exigirDisponible(\"u-ventas\"))\n                .isInstanceOf(PresupuestoAgotadoException.class)\n                .hasMessageContaining(\"límite mensual\");\n    }\n\n    @Test\n    void alcanzarElTopeDelServicioBloqueaATodos() {\n        SimpleMeterRegistry registro = new SimpleMeterRegistry();\n        PresupuestoTokens presupuesto = presupuesto(consumo((u, d) -> 0, d -> SERVICIO), registro);\n\n        assertThatThrownBy(() -> presupuesto.exigirDisponible(\"u-otro\"))\n                .isInstanceOf(PresupuestoAgotadoException.class)\n                .hasMessageContaining(\"presupuesto mensual del servicio\");\n        assertThat(registro.counter(\"nexus.presupuesto.bloqueos\", \"ambito\", \"servicio\").count()).isEqualTo(1.0);\n    }\n\n    @Test\n    void cruzarElOchentaPorCientoAvisaUnaVezPeroNoBloquea() {\n        SimpleMeterRegistry registro = new SimpleMeterRegistry();\n        PresupuestoTokens presupuesto = presupuesto(consumo((u, d) -> 0, d -> 850_000), registro);\n\n        presupuesto.exigirDisponible(\"u-ventas\");\n        presupuesto.exigirDisponible(\"u-ventas\");\n\n        assertThat(registro.counter(\"nexus.presupuesto.umbral.alcanzado\").count()).isEqualTo(1.0);\n        assertThat(registro.counter(\"nexus.presupuesto.bloqueos\", \"ambito\", \"servicio\").count()).isEqualTo(0.0);\n    }\n\n    @Test\n    void elGaugeMuestraElConsumoMensualDelServicio() {\n        SimpleMeterRegistry registro = new SimpleMeterRegistry();\n        presupuesto(consumo((u, d) -> 0, d -> 123_456), registro).exigirDisponible(\"u-ventas\");\n\n        assertThat(registro.get(\"nexus.presupuesto.servicio.consumo\").gauge().value()).isEqualTo(123_456.0);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/RecuperadorPoliticasTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.LocalDate;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\n\nimport org.junit.jupiter.api.Test;\n\nclass RecuperadorPoliticasTest {\n\n    private static final Clock RELOJ = Clock.fixed(Instant.parse(\"2026-11-02T12:00:00Z\"), ZoneOffset.UTC);\n\n    @Test\n    void sinRolesNoConsultaNada() {\n        AlmacenRegistrado almacen = new AlmacenRegistrado();\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedderFijo(), almacen, RELOJ);\n\n        assertThat(recuperador.buscar(\"¿cuál es el límite?\", Set.of(), 3)).isEmpty();\n        assertThat(recuperador.buscar(\"¿cuál es el límite?\", Set.of(\"  \"), 3)).isEmpty();\n        assertThat(almacen.llamadas).isZero();\n    }\n\n    @Test\n    void pasaRolesNormalizadosYFechaDeHoy() {\n        AlmacenRegistrado almacen = new AlmacenRegistrado();\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedderFijo(), almacen, RELOJ);\n\n        recuperador.buscar(\"límite\", Set.of(\"compras\", \" direccion \"), 3);\n\n        assertThat(almacen.rolesRecibidos).containsExactlyInAnyOrder(\"COMPRAS\", \"DIRECCION\");\n        assertThat(almacen.hoyRecibido).isEqualTo(LocalDate.of(2026, 11, 2));\n        assertThat(almacen.limiteRecibido).isEqualTo(3);\n    }\n\n    @Test\n    void limitaElNumeroDeResultados() {\n        AlmacenRegistrado almacen = new AlmacenRegistrado();\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedderFijo(), almacen, RELOJ);\n\n        recuperador.buscar(\"límite\", Set.of(\"COMPRAS\"), 500);\n\n        assertThat(almacen.limiteRecibido).isEqualTo(10);\n    }\n\n    @Test\n    void embebeLaPreguntaComoConsulta() {\n        List<Embedder.TipoEntrada> tipos = new ArrayList<>();\n        Embedder embedder = (textos, tipo) -> {\n            tipos.add(tipo);\n            return List.of(new float[]{1f});\n        };\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedder, new AlmacenRegistrado(), RELOJ);\n\n        recuperador.buscar(\"límite\", Set.of(\"COMPRAS\"), 3);\n\n        assertThat(tipos).containsExactly(Embedder.TipoEntrada.CONSULTA);\n    }\n\n    private static Embedder embedderFijo() {\n        return (textos, tipo) -> textos.stream().map(t -> new float[]{1f}).toList();\n    }\n\n    static final class AlmacenRegistrado implements AlmacenFragmentos {\n        int llamadas;\n        Set<String> rolesRecibidos;\n        LocalDate hoyRecibido;\n        int limiteRecibido;\n\n        @Override\n        public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n            throw new UnsupportedOperationException();\n        }\n\n        @Override\n        public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n            llamadas++;\n            rolesRecibidos = roles;\n            hoyRecibido = hoy;\n            limiteRecibido = limite;\n            return List.of();\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/ServicioPolizasTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\n\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.CuentaCatalogo;\nimport com.mx.josesaid.develop.nexus.application.PolizaSugerida.LineaSugerida;\n\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\n\n/** Verifica que Nexus sugiere pólizas pero no las registra por sí solo. */\nclass ServicioPolizasTest {\n\n    private static final Clock RELOJ = Clock.fixed(Instant.parse(\"2026-11-15T18:00:00Z\"), ZoneOffset.UTC);\n    private static final UUID CAJA = UUID.fromString(\"00000000-0000-4000-8000-000000000101\");\n    private static final UUID VENTAS = UUID.fromString(\"00000000-0000-4000-8000-000000000401\");\n    private static final List<CuentaCatalogo> CATALOGO = List.of(\n            new CuentaCatalogo(CAJA, \"101\", \"Caja\"),\n            new CuentaCatalogo(VENTAS, \"401\", \"Ventas\"));\n\n    private final Map<UUID, AccionPendiente> almacenadas = new HashMap<>();\n    private final List<String> ejecuciones = new ArrayList<>();\n    private final AccionesPendientes acciones = new AccionesPendientes(new AlmacenAcciones() {\n        @Override\n        public void guardar(AccionPendiente accion) {\n            almacenadas.put(accion.id(), accion);\n        }\n\n        @Override\n        public Optional<AccionPendiente> buscar(UUID id) {\n            return Optional.ofNullable(almacenadas.get(id));\n        }\n    }, (tipo, payload) -> {\n        ejecuciones.add(tipo + \" \" + payload);\n        return \"ok\";\n    }, RELOJ);\n\n    private static final PolizaSugerida VALIDA = new PolizaSugerida(\"INGRESO\", List.of(\n            new LineaSugerida(\"101\", new BigDecimal(\"1000\"), BigDecimal.ZERO),\n            new LineaSugerida(\"401\", BigDecimal.ZERO, new BigDecimal(\"1000\"))), 0.92, \"Venta de contado\");\n\n    private ServicioPolizas servicio(PolizaSugerida sugerencia) {\n        ContextoContable contexto = new ContextoContable() {\n            @Override\n            public List<CuentaCatalogo> catalogo() {\n                return CATALOGO;\n            }\n\n            @Override\n            public List<PolizaEjemplo> ejemplosRecientes() {\n                return List.of();\n            }\n        };\n        SugeridorPolizas sugeridor = (usuario, descripcion, catalogo, ejemplos) -> sugerencia;\n        PresupuestoTokens presupuesto = new PresupuestoTokens(new ConsumoTokens() {\n            @Override\n            public long desde(String usuario, Instant desde) {\n                return 0;\n            }\n\n            @Override\n            public long delServicio(Instant desde) {\n                return 0;\n            }\n        }, 150_000, 15_000, 1_000_000, RELOJ, new SimpleMeterRegistry());\n        return new ServicioPolizas(contexto, sugeridor, acciones, presupuesto, RELOJ);\n    }\n\n    @Test\n    void sugerirDejaUnaAccionPendienteYNoRegistraNada() {\n        AccionPendiente accion = servicio(VALIDA).preparar(\"contador1\", \"Venta de contado de 1000\");\n\n        assertThat(accion.estatus()).isEqualTo(AccionPendiente.PENDIENTE);\n        assertThat(accion.tipo()).isEqualTo(AccionesPendientes.TIPO_POLIZA_REGISTRAR);\n        assertThat(ejecuciones).as(\"ninguna póliza se registra antes de confirmar\").isEmpty();\n    }\n\n    @Test\n    void laPolizaSeRegistraSoloCuandoElContadorConfirma() {\n        AccionPendiente accion = servicio(VALIDA).preparar(\"contador1\", \"Venta de contado de 1000\");\n        assertThat(ejecuciones).isEmpty();\n\n        acciones.confirmar(accion.id(), \"contador1\");\n\n        assertThat(ejecuciones).hasSize(1);\n        assertThat(ejecuciones.get(0)).startsWith(AccionesPendientes.TIPO_POLIZA_REGISTRAR).contains(CAJA.toString());\n    }\n\n    @Test\n    void soloElQueSugirioPuedeConfirmar() {\n        AccionPendiente accion = servicio(VALIDA).preparar(\"contador1\", \"Venta de contado de 1000\");\n\n        assertThatThrownBy(() -> acciones.confirmar(accion.id(), \"otro-usuario\"))\n                .isInstanceOf(AccionNoEncontradaException.class);\n        assertThat(ejecuciones).isEmpty();\n    }\n\n    @Test\n    void unaSugerenciaQueNoCuadraSeRechazaSinGuardarAccion() {\n        PolizaSugerida descuadrada = new PolizaSugerida(\"INGRESO\", List.of(\n                new LineaSugerida(\"101\", new BigDecimal(\"1000\"), BigDecimal.ZERO),\n                new LineaSugerida(\"401\", BigDecimal.ZERO, new BigDecimal(\"900\"))), 0.9, \"\");\n\n        assertThatThrownBy(() -> servicio(descuadrada).preparar(\"contador1\", \"venta\"))\n                .isInstanceOf(SugerenciaPolizaInvalidaException.class)\n                .hasMessageContaining(\"no cuadra\");\n        assertThat(almacenadas).isEmpty();\n        assertThat(ejecuciones).isEmpty();\n    }\n\n    @Test\n    void unaCuentaFueraDelCatalogoSeRechaza() {\n        PolizaSugerida inventada = new PolizaSugerida(\"INGRESO\", List.of(\n                new LineaSugerida(\"999\", new BigDecimal(\"1000\"), BigDecimal.ZERO),\n                new LineaSugerida(\"401\", BigDecimal.ZERO, new BigDecimal(\"1000\"))), 0.9, \"\");\n\n        assertThatThrownBy(() -> servicio(inventada).preparar(\"contador1\", \"venta\"))\n                .isInstanceOf(SugerenciaPolizaInvalidaException.class)\n                .hasMessageContaining(\"999\");\n        assertThat(almacenadas).isEmpty();\n    }\n\n    @Test\n    void unaLineaConCargoYAbonoALaVezSeRechaza() {\n        PolizaSugerida ambos = new PolizaSugerida(\"DIARIO\", List.of(\n                new LineaSugerida(\"101\", new BigDecimal(\"1000\"), new BigDecimal(\"1000\")),\n                new LineaSugerida(\"401\", BigDecimal.ZERO, new BigDecimal(\"0\"))), 0.9, \"\");\n\n        assertThatThrownBy(() -> servicio(ambos).preparar(\"contador1\", \"venta\"))\n                .isInstanceOf(SugerenciaPolizaInvalidaException.class);\n        assertThat(almacenadas).isEmpty();\n    }\n\n    @Test\n    void unTipoDePolizaDesconocidoSeRechaza() {\n        PolizaSugerida tipoRaro = new PolizaSugerida(\"CHEQUE\", VALIDA.lineas(), 0.9, \"\");\n\n        assertThatThrownBy(() -> servicio(tipoRaro).preparar(\"contador1\", \"venta\"))\n                .isInstanceOf(SugerenciaPolizaInvalidaException.class);\n        assertThat(almacenadas).isEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/application/TemasEmpresaTest.java": "package com.mx.josesaid.develop.nexus.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.Test;\nimport org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.ValueSource;\n\nclass TemasEmpresaTest {\n\n    @ParameterizedTest\n    @ValueSource(strings = {\n            \"¿Cuántas existencias hay del SKU-001?\",\n            \"Dame el saldo del proveedor Acme\",\n            \"¿Qué comprobantes siguen pendientes de cobro?\",\n            \"Resumen de facturación del mes\",\n            \"¿Qué contratos vencen?\",\n            \"Revisa el RFC XAXX010101000\",\n            \"hola\",\n            \"¡Buenos días!\",\n            \"dame la info de esto: a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d\",\n            \"ok, eso sirve a1b2c3d4-e5f6-4a7b-8c9d-0e1f2a3b4c5d\"\n    })\n    void dejaPasarPreguntasDeEmpresa(String pregunta) {\n        assertThat(TemasEmpresa.esDeEmpresa(pregunta)).isTrue();\n    }\n\n    @ParameterizedTest\n    @ValueSource(strings = {\n            \"¿Cuánto es 2*2?\",\n            \"¿Quién ganó el mundial?\",\n            \"Escribe un poema sobre el mar\",\n            \"Hola, ¿cuánto es 2*2?\",\n            \"Dame una receta de pasta\",\n            \"\",\n            \"   \"\n    })\n    void rechazaPreguntasAjenas(String pregunta) {\n        assertThat(TemasEmpresa.esDeEmpresa(pregunta)).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/comun/filtro/FiltroRfcOmitidoTest.java": "package com.mx.josesaid.develop.nexus.comun.filtro;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.util.EnumSet;\n\nimport org.junit.jupiter.api.Test;\n\nclass FiltroRfcOmitidoTest {\n\n    @Test\n    void conservaElRfcCuandoSeOmite() {\n        var resultado = FiltroDatosSensibles.redactar(\"Cliente PRU000101XAB, correo a@b.com\",\n                EnumSet.of(FiltroDatosSensibles.Tipo.RFC));\n\n        assertEquals(\"Cliente PRU000101XAB, correo [CORREO]\", resultado.texto());\n    }\n\n    @Test\n    void enmascaraElRfcPorDefecto() {\n        assertEquals(\"Cliente [RFC]\", FiltroDatosSensibles.redactar(\"Cliente PRU000101XAB\").texto());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/evaluacion/LineaBaseIT.java": "package com.mx.josesaid.develop.nexus.evaluacion;\n\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\n\nimport org.junit.jupiter.api.Test;\nimport org.junit.jupiter.api.condition.EnabledIf;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\n\nimport com.mx.josesaid.develop.nexus.application.AsistenteIA;\nimport com.mx.josesaid.develop.nexus.application.PreguntaAsistente;\nimport com.mx.josesaid.develop.nexus.comun.evaluacion.CargadorCasos;\nimport com.mx.josesaid.develop.nexus.comun.evaluacion.EjecutorEvaluaciones;\n\n/**\n * Línea base de calidad (paso 22). Llama al modelo real con los casos de nexus-comun.\n * Corre solo con NEXUS_LINEA_BASE=1 y ANTHROPIC_API_KEY definida, con el stack levantado.\n * Así no se ejecuta en cada mvn verify.\n * Sin servicios de negocio levantados, el asistente responde sin datos: esta medición\n * valida reglas de forma, idioma y redacción. La medición con datos reales se hace con el\n * stack completo levantado (ver README).\n * Escribe el informe en target/linea-base-nexus.txt.\n */\n@SpringBootTest\n@EnabledIf(\"lineaBaseHabilitada\")\nclass LineaBaseIT {\n\n    static boolean lineaBaseHabilitada() {\n        String clave = System.getenv(\"ANTHROPIC_API_KEY\");\n        return \"1\".equals(System.getenv(\"NEXUS_LINEA_BASE\")) && clave != null && !clave.isBlank();\n    }\n\n    @Autowired\n    private AsistenteIA asistente;\n\n    @Test\n    void registraLaLineaBase() throws Exception {\n        var casos = CargadorCasos.cargar(getClass().getClassLoader());\n        var ejecutor = new EjecutorEvaluaciones(\n                pregunta -> asistente.consultar(new PreguntaAsistente(\"evaluacion\", pregunta)).texto());\n\n        var informe = ejecutor.ejecutar(casos);\n\n        StringBuilder salida = new StringBuilder();\n        salida.append(String.format(\"Línea base: %d de %d aprobados (%.0f%%)%n\",\n                informe.aprobados(), informe.total(), informe.tasaAprobacion() * 100));\n        informe.resultados().forEach(r -> salida.append(String.format(\"%s %s %s%n\",\n                r.aprobado() ? \"OK   \" : \"FALLO\", r.id(), r.fallos())));\n        Path destino = Path.of(\"target\", \"linea-base-nexus.txt\");\n        Files.createDirectories(destino.getParent());\n        Files.writeString(destino, salida.toString(), StandardCharsets.UTF_8);\n        System.out.println(salida);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/AlcanceHerramientasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.ai.support.ToolCallbacks;\nimport org.springframework.security.authentication.TestingAuthenticationToken;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.RestClient;\n\nclass AlcanceHerramientasTest {\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private static void comoRol(String rol) {\n        SecurityContextHolder.getContext().setAuthentication(new TestingAuthenticationToken(\"u\", null, rol));\n    }\n\n    @Test\n    void cadaHerramientaRegistradaTieneRolesDefinidos() {\n        RestClient sinRed = RestClient.builder().build();\n        var herramientas = ToolCallbacks.from(new HerramientasReportes(sinRed), new HerramientasClientes(sinRed),\n                new HerramientasVentas(sinRed), new HerramientasCompras(sinRed), new HerramientasFinanzas(sinRed),\n                new HerramientasContabilidad(sinRed), new HerramientasInventario(sinRed),\n                new HerramientasDocumentos(sinRed), new HerramientasUsuarios(sinRed));\n\n        assertThat(herramientas).isNotEmpty();\n        for (var h : herramientas) {\n            assertThat(AlcanceHerramientas.conoce(h.getToolDefinition().name()))\n                    .as(\"sin roles definidos: %s\", h.getToolDefinition().name())\n                    .isTrue();\n        }\n    }\n\n    @Test\n    void sinAutenticacionNoPuedeUsarNada() {\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_pedidos\")).isFalse();\n    }\n\n    @Test\n    void compras_puedeOrdenPeroNoTrazabilidadDeLotes() {\n        comoRol(\"ROLE_COMPRAS\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_orden_compra\")).isTrue();\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_trazabilidad_lote\")).isFalse();\n    }\n\n    @Test\n    void calidad_puedeTrazabilidadPeroNoUsuarios() {\n        comoRol(\"ROLE_CALIDAD\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_trazabilidad_lote\")).isTrue();\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_usuario\")).isFalse();\n    }\n\n    @Test\n    void ventas_noPuedeResumenDeVentas() {\n        comoRol(\"ROLE_VENTAS\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_pedidos\")).isTrue();\n        assertThat(AlcanceHerramientas.puedeUsar(\"resumen_ventas\")).isFalse();\n    }\n\n    @Test\n    void finanzas_puedeResumenDeVentas() {\n        comoRol(\"ROLE_FINANZAS\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(\"resumen_ventas\")).isTrue();\n    }\n\n    @Test\n    void herramientaDesconocidaSeNiega() {\n        comoRol(\"ROLE_ADMIN\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(\"herramienta_inexistente\")).isFalse();\n    }\n\n    @Test\n    void contador_puedeCatalogoDeCuentasPeroVentasNo() {\n        comoRol(\"ROLE_CONTADOR\");\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_catalogo_cuentas\")).isTrue();\n\n        comoRol(\"ROLE_VENTAS\");\n        assertThat(AlcanceHerramientas.puedeUsar(\"consultar_catalogo_cuentas\")).isFalse();\n    }\n\n    @Test\n    void almacen_puedeListarOrdenesPeroVentasNo() {\n        comoRol(\"ROLE_ALMACEN\");\n        assertThat(AlcanceHerramientas.puedeUsar(\"listar_ordenes_compra\")).isTrue();\n\n        comoRol(\"ROLE_VENTAS\");\n        assertThat(AlcanceHerramientas.puedeUsar(\"listar_ordenes_compra\")).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/AutorizacionMcpCallbackTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.when;\n\nimport java.util.Map;\nimport java.util.concurrent.atomic.AtomicReference;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.ai.chat.model.ToolContext;\nimport org.springframework.ai.mcp.McpToolUtils;\nimport org.springframework.ai.tool.ToolCallback;\nimport org.springframework.ai.tool.definition.ToolDefinition;\nimport org.springframework.security.authentication.UsernamePasswordAuthenticationToken;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\nimport io.modelcontextprotocol.common.McpTransportContext;\nimport io.modelcontextprotocol.server.McpSyncServerExchange;\n\nclass AutorizacionMcpCallbackTest {\n\n    private final AtomicReference<Authentication> vistoPorHerramienta = new AtomicReference<>();\n\n    private ToolCallback herramienta(String nombre) {\n        ToolDefinition definicion = mock(ToolDefinition.class);\n        when(definicion.name()).thenReturn(nombre);\n        ToolCallback callback = mock(ToolCallback.class);\n        when(callback.getToolDefinition()).thenReturn(definicion);\n        when(callback.call(org.mockito.ArgumentMatchers.anyString(), org.mockito.ArgumentMatchers.any()))\n                .thenAnswer(inv -> {\n                    vistoPorHerramienta.set(SecurityContextHolder.getContext().getAuthentication());\n                    return \"resultado\";\n                });\n        when(callback.call(org.mockito.ArgumentMatchers.anyString()))\n                .thenAnswer(inv -> {\n                    vistoPorHerramienta.set(SecurityContextHolder.getContext().getAuthentication());\n                    return \"resultado\";\n                });\n        return callback;\n    }\n\n    private static ToolContext contextoCon(Authentication autenticacion) {\n        McpSyncServerExchange exchange = mock(McpSyncServerExchange.class);\n        when(exchange.transportContext()).thenReturn(\n                McpTransportContext.create(Map.of(AutorizacionMcpCallback.CLAVE_AUTENTICACION, autenticacion)));\n        return new ToolContext(Map.of(McpToolUtils.TOOL_CONTEXT_MCP_EXCHANGE_KEY, exchange));\n    }\n\n    private static Authentication con(String... roles) {\n        return new UsernamePasswordAuthenticationToken(\"usuario-1\", null,\n                java.util.Arrays.stream(roles).map(SimpleGrantedAuthority::new).toList());\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @Test\n    void sinIdentidadLaHerramientaNoSeEjecuta() {\n        ToolCallback delegado = herramienta(\"consultar_politicas\");\n\n        assertThatThrownBy(() -> new AutorizacionMcpCallback(delegado).call(\"{}\", new ToolContext(Map.of())))\n                .isInstanceOf(AutorizacionMcpCallback.SinPermisoMcpException.class)\n                .hasMessage(AutorizacionMcpCallback.DENEGADO);\n        assertThat(vistoPorHerramienta.get()).isNull();\n    }\n\n    @Test\n    void conRolSinPermisoLaHerramientaSeNiegaSinEjecutarse() {\n        ToolCallback delegado = herramienta(\"consultar_politicas\");\n\n        assertThatThrownBy(() -> new AutorizacionMcpCallback(delegado).call(\"{}\", contextoCon(con(\"ROLE_VENTAS\"))))\n                .isInstanceOf(AutorizacionMcpCallback.SinPermisoMcpException.class);\n        assertThat(vistoPorHerramienta.get()).isNull();\n    }\n\n    @Test\n    void conRolPermitidoSeEjecutaConLaIdentidadDelClienteYRestauraElContexto() {\n        ToolCallback delegado = herramienta(\"consultar_politicas\");\n        SecurityContextHolder.getContext().setAuthentication(con(\"ROLE_LEGAL\"));\n        Authentication cliente = con(\"ROLE_DIRECCION\");\n\n        String respuesta = new AutorizacionMcpCallback(delegado).call(\"{}\", contextoCon(cliente));\n\n        assertThat(respuesta).isEqualTo(\"resultado\");\n        assertThat(vistoPorHerramienta.get()).isSameAs(cliente);\n        assertThat(SecurityContextHolder.getContext().getAuthentication().getAuthorities())\n                .extracting(a -> a.getAuthority()).containsExactly(\"ROLE_LEGAL\");\n    }\n\n    @Test\n    void unaHerramientaDesconocidaSeNiega() {\n        ToolCallback delegado = herramienta(\"herramienta_inventada\");\n\n        assertThatThrownBy(() -> new AutorizacionMcpCallback(delegado).call(\"{}\", contextoCon(con(\"ROLE_DIRECCION\"))))\n                .isInstanceOf(AutorizacionMcpCallback.SinPermisoMcpException.class);\n        assertThat(vistoPorHerramienta.get()).isNull();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/ClaudeAsistenteIATest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.ai.chat.messages.AssistantMessage;\nimport org.springframework.ai.chat.model.ChatModel;\nimport org.springframework.ai.chat.model.ChatResponse;\nimport org.springframework.ai.chat.model.Generation;\nimport org.springframework.ai.chat.prompt.Prompt;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.authentication.TestingAuthenticationToken;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AlmacenFragmentos;\nimport com.mx.josesaid.develop.nexus.application.FragmentoIndexado;\nimport com.mx.josesaid.develop.nexus.application.PreguntaAsistente;\nimport com.mx.josesaid.develop.nexus.application.RecuperadorPoliticas;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\nimport com.mx.josesaid.develop.nexus.comun.prompts.RepositorioPrompts;\nimport com.mx.josesaid.develop.nexus.comun.tokens.PreciosTokens;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokens;\n\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\n\nclass ClaudeAsistenteIATest {\n\n    private final List<Prompt> enviados = new ArrayList<>();\n    private String respuestaSimulada = \"Vencen 3 contratos.\";\n    private ClaudeAsistenteIA asistente;\n\n    @BeforeEach\n    void preparar() {\n        ChatModel modelo = new ChatModel() {\n            @Override\n            public ChatResponse call(Prompt prompt) {\n                enviados.add(prompt);\n                return new ChatResponse(List.of(new Generation(new AssistantMessage(respuestaSimulada))));\n            }\n        };\n        RestClient sinRed = RestClient.create(\"http://no-usado\");\n        var registro = new RegistroTokens(new SimpleMeterRegistry(), PreciosTokens.SIN_PRECIO);\n        asistente = new ClaudeAsistenteIA(modelo, registro, new RepositorioPrompts(),\n                new HerramientasReportes(sinRed), new HerramientasClientes(sinRed),\n                new HerramientasVentas(sinRed), new HerramientasCompras(sinRed),\n                new HerramientasFinanzas(sinRed), new HerramientasContabilidad(sinRed),\n                new HerramientasInventario(sinRed), new HerramientasDocumentos(sinRed),\n                new HerramientasUsuarios(sinRed), new HerramientasPoliticas(recuperadorVacio()));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    /** Recuperador sin fragmentos: la herramienta de políticas se registra pero no se usa en estas pruebas. */\n    private static RecuperadorPoliticas recuperadorVacio() {\n        AlmacenFragmentos almacen = new AlmacenFragmentos() {\n            @Override\n            public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n            }\n\n            @Override\n            public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n                return List.of();\n            }\n        };\n        return new RecuperadorPoliticas((textos, tipo) -> List.of(), almacen, Clock.systemUTC());\n    }\n\n    @Test\n    void devuelveLaRespuestaDelModelo() {\n        var respuesta = asistente.consultar(new PreguntaAsistente(\"u1\", \"¿Qué contratos vencen?\"));\n\n        assertThat(respuesta.texto()).isEqualTo(\"Vencen 3 contratos.\");\n    }\n\n    @Test\n    void dejaElRfcAlModeloYRedactaElCorreo() {\n        asistente.consultar(new PreguntaAsistente(\"u1\", \"Revisa el RFC XAXX010101000 y escribe a a@b.com\"));\n\n        String enviado = enviados.get(0).getUserMessage().getText();\n        assertThat(enviado).contains(\"XAXX010101000\").doesNotContain(\"a@b.com\");\n        assertThat(enviado).contains(\"[CORREO]\");\n    }\n\n    @Test\n    void incluyeElPromptVersionadoComoInstruccionDeSistema() {\n        asistente.consultar(new PreguntaAsistente(\"u1\", \"Hola\"));\n\n        String sistema = enviados.get(0).getInstructions().stream()\n                .filter(m -> m.getMessageType().name().equals(\"SYSTEM\"))\n                .map(m -> m.getText())\n                .findFirst()\n                .orElse(\"\");\n        assertThat(sistema).contains(\"Eres Nexus\", \"Responde siempre en español\");\n    }\n\n    @Test\n    void sinAutenticacionNoSeOfreceNingunaHerramienta() {\n        assertThat(AlcanceHerramientas.puedeConsultarReportes()).isFalse();\n        assertThat(AlcanceHerramientas.puedeConsultarClientes()).isFalse();\n    }\n\n    @Test\n    void direccionPuedeConsultarReportesPeroNoClientes() {\n        SecurityContextHolder.getContext().setAuthentication(\n                new TestingAuthenticationToken(\"u1\", null, \"ROLE_DIRECCION\"));\n\n        assertThat(AlcanceHerramientas.puedeConsultarReportes()).isTrue();\n        assertThat(AlcanceHerramientas.puedeConsultarClientes()).isFalse();\n    }\n\n    @Test\n    void ventasPuedeConsultarClientesPeroNoReportes() {\n        SecurityContextHolder.getContext().setAuthentication(\n                new TestingAuthenticationToken(\"u2\", null, \"ROLE_VENTAS\"));\n\n        assertThat(AlcanceHerramientas.puedeConsultarClientes()).isTrue();\n        assertThat(AlcanceHerramientas.puedeConsultarReportes()).isFalse();\n    }\n\n    @Test\n    void jefeDeAreaNoPuedeConsultarReportesNiClientesDesdeNexus() {\n        SecurityContextHolder.getContext().setAuthentication(\n                new TestingAuthenticationToken(\"u3\", null, \"ROLE_JEFE_AREA\"));\n\n        assertThat(AlcanceHerramientas.puedeConsultarReportes()).isFalse();\n        assertThat(AlcanceHerramientas.puedeConsultarClientes()).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/ClaudeSugeridorPolizasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.ai.chat.messages.AssistantMessage;\nimport org.springframework.ai.chat.model.ChatModel;\nimport org.springframework.ai.chat.model.ChatResponse;\nimport org.springframework.ai.chat.model.Generation;\nimport org.springframework.ai.chat.prompt.Prompt;\n\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.CuentaCatalogo;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.LineaEjemplo;\nimport com.mx.josesaid.develop.nexus.application.ContextoContable.PolizaEjemplo;\nimport com.mx.josesaid.develop.nexus.application.PolizaSugerida;\nimport com.mx.josesaid.develop.nexus.application.SugerenciaPolizaInvalidaException;\nimport com.mx.josesaid.develop.nexus.comun.tokens.PreciosTokens;\nimport com.mx.josesaid.develop.nexus.comun.tokens.RegistroTokens;\n\nimport io.micrometer.core.instrument.simple.SimpleMeterRegistry;\n\nclass ClaudeSugeridorPolizasTest {\n\n    private static final UUID CAJA = UUID.fromString(\"00000000-0000-4000-8000-000000000101\");\n    private static final UUID VENTAS = UUID.fromString(\"00000000-0000-4000-8000-000000000401\");\n    private static final List<CuentaCatalogo> CATALOGO = List.of(\n            new CuentaCatalogo(CAJA, \"101\", \"Caja\"),\n            new CuentaCatalogo(VENTAS, \"401\", \"Ventas\"));\n\n    private static ClaudeSugeridorPolizas sugeridor(String respuestaDelModelo) {\n        ChatModel modelo = new ChatModel() {\n            @Override\n            public ChatResponse call(Prompt prompt) {\n                return new ChatResponse(List.of(new Generation(new AssistantMessage(respuestaDelModelo))));\n            }\n        };\n        return new ClaudeSugeridorPolizas(modelo,\n                new RegistroTokens(new SimpleMeterRegistry(), PreciosTokens.SIN_PRECIO));\n    }\n\n    @Test\n    void leeLaSugerenciaAunqueVengaEnBloqueDeCodigo() {\n        String respuesta = \"\"\"\n                ```json\n                {\"tipo\":\"INGRESO\",\"lineas\":[{\"codigo\":\"101\",\"cargo\":1000,\"abono\":0},\n                {\"codigo\":\"401\",\"cargo\":0,\"abono\":1000}],\"confianza\":0.9,\"motivo\":\"Venta de contado\"}\n                ```\n                \"\"\";\n\n        PolizaSugerida s = sugeridor(respuesta).sugerir(\"contador1\", \"venta\", CATALOGO, List.of());\n\n        assertThat(s.tipo()).isEqualTo(\"INGRESO\");\n        assertThat(s.confianza()).isEqualTo(0.9);\n        assertThat(s.lineas()).hasSize(2);\n        assertThat(s.lineas().get(0).codigoCuenta()).isEqualTo(\"101\");\n        assertThat(s.lineas().get(0).cargo()).isEqualByComparingTo(new BigDecimal(\"1000\"));\n    }\n\n    @Test\n    void unaRespuestaSinJsonSeRechaza() {\n        assertThatThrownBy(() -> sugeridor(\"No sé contestar\").sugerir(\"contador1\", \"venta\", CATALOGO, List.of()))\n                .isInstanceOf(SugerenciaPolizaInvalidaException.class);\n    }\n\n    @Test\n    void elContextoIncluyeCatalogoYEjemplosConCodigos() {\n        List<PolizaEjemplo> ejemplos = List.of(new PolizaEjemplo(\"INGRESO\", LocalDate.of(2026, 10, 3),\n                List.of(new LineaEjemplo(CAJA, new BigDecimal(\"500\"), BigDecimal.ZERO),\n                        new LineaEjemplo(VENTAS, BigDecimal.ZERO, new BigDecimal(\"500\")))));\n\n        String contexto = ClaudeSugeridorPolizas.contexto(\"Venta de contado\", CATALOGO, ejemplos);\n\n        assertThat(contexto).contains(\"101 Caja\").contains(\"401 Ventas\");\n        assertThat(contexto).contains(\"INGRESO 2026-10-03: 101 cargo 500; 401 abono 500\");\n        assertThat(contexto).contains(\"Descripción de la operación: Venta de contado\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/EjecutorAccionesGatewayTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.hamcrest.Matchers.containsString;\nimport static org.hamcrest.Matchers.not;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.content;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.header;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.method;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\nclass EjecutorAccionesGatewayTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000003\";\n\n    @Test\n    void confirmarPedidoLlamaAlEndpointDeConfirmacion() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID + \"/confirmacion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_PEDIDO_CONFIRMAR, \"{\\\"pedidoId\\\":\\\"\" + ID + \"\\\"}\");\n\n        assertThat(respuesta).contains(ID);\n        servidor.verify();\n    }\n\n    @Test\n    void cancelarPedidoEnviaElMotivo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID + \"/cancelacion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"motivo\\\":\\\"ERROR_CAPTURA\\\"}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_PEDIDO_CANCELAR,\n                        \"{\\\"pedidoId\\\":\\\"\" + ID + \"\\\",\\\"motivo\\\":\\\"ERROR_CAPTURA\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void prospectoSeEnviaAClientesMs() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        String payload = \"{\\\"nombre\\\":\\\"Ana\\\",\\\"correo\\\":\\\"ana@ejemplo.com\\\",\\\"fuente\\\":\\\"CAMPANA\\\"}\";\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/prospectos\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(payload))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"p1\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PROSPECTO_BORRADOR, payload);\n\n        servidor.verify();\n    }\n\n    @Test\n    void eliminarDocumentoEnviaElMotivoAlEndpoint() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/documentos-cumplimiento-ms/v1/documentos/\" + ID + \"/eliminacion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"motivo\\\":\\\"Contrato vencido\\\"}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_DOCUMENTO_ELIMINAR,\n                        \"{\\\"documentoId\\\":\\\"\" + ID + \"\\\",\\\"motivo\\\":\\\"Contrato vencido\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void crearClienteEnviaElAltaAClientesMs() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        String payload = \"{\\\"razonSocial\\\":\\\"Acme\\\",\\\"rfc\\\":\\\"MOGJ850315AB3\\\",\"\n                + \"\\\"contactoPrincipal\\\":{\\\"nombre\\\":\\\"Ana\\\",\\\"correo\\\":\\\"ana@ejemplo.com\\\",\\\"rol\\\":\\\"COMPRAS\\\"}}\";\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(payload))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_CLIENTE_CREAR, payload);\n\n        servidor.verify();\n    }\n\n    @Test\n    void actualizarClienteEnviaSoloLaRazonSocial() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/\" + ID))\n                .andExpect(method(HttpMethod.PATCH))\n                .andExpect(content().json(\"{\\\"razonSocial\\\":\\\"Acme SA\\\"}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_CLIENTE_ACTUALIZAR,\n                        \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"razonSocial\\\":\\\"Acme SA\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void agregarContactoQuitaElClienteIdDelCuerpo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/\" + ID + \"/contactos\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"nombre\\\":\\\"Luis\\\",\\\"correo\\\":\\\"luis@ejemplo.com\\\",\\\"rol\\\":\\\"PAGOS\\\",\\\"principal\\\":false}\"))\n                .andExpect(content().string(org.hamcrest.Matchers.not(containsString(\"clienteId\"))))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"c2\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_CLIENTE_CONTACTO_AGREGAR,\n                        \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"nombre\\\":\\\"Luis\\\",\\\"correo\\\":\\\"luis@ejemplo.com\\\",\"\n                                + \"\\\"rol\\\":\\\"PAGOS\\\",\\\"principal\\\":false}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void recepcionEnviaLasLineasSinElOrdenId() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/ordenes-compra/\" + ID + \"/recepciones\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"TUB-1\\\",\\\"cantidad\\\":5}]}\"))\n                .andExpect(content().string(org.hamcrest.Matchers.not(containsString(\"ordenId\"))))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_ORDEN_COMPRA_RECEPCION,\n                        \"{\\\"ordenId\\\":\\\"\" + ID + \"\\\",\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"TUB-1\\\",\\\"cantidad\\\":5}]}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void cancelarOrdenEnviaElMotivo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/ordenes-compra/\" + ID + \"/cancelacion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"motivo\\\":\\\"Proveedor sin stock\\\"}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_ORDEN_COMPRA_CANCELAR,\n                        \"{\\\"ordenId\\\":\\\"\" + ID + \"\\\",\\\"motivo\\\":\\\"Proveedor sin stock\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void altaDeProveedorSeEnviaComoEstaEnElPayload() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        String payload = \"{\\\"razonSocial\\\":\\\"Tubos SA\\\",\\\"rfc\\\":\\\"TUB850315AB3\\\",\\\"correo\\\":\\\"ventas@tubos.mx\\\"}\";\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/proveedores\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(payload))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PROVEEDOR_CREAR, payload);\n\n        servidor.verify();\n    }\n\n    @Test\n    void movimientoEnviaLaClaveDeIdempotenciaComoCabecera() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/movimientos\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(header(\"Idempotency-Key\", \"clave-accion-1\"))\n                .andExpect(content().json(\"{\\\"tipo\\\":\\\"ENTRADA\\\",\\\"cantidad\\\":3}\"))\n                .andExpect(content().string(org.hamcrest.Matchers.not(containsString(\"idempotencyKey\"))))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"m1\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_MOVIMIENTO_REGISTRAR,\n                        \"{\\\"articuloId\\\":\\\"\" + ID + \"\\\",\\\"tipo\\\":\\\"ENTRADA\\\",\\\"cantidad\\\":3,\\\"idempotencyKey\\\":\\\"clave-accion-1\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void articuloYOrdenDeOperacionSeEnvianComoEstanEnElPayload() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/articulos\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"sku\\\":\\\"TUB-1\\\",\\\"loteObligatorio\\\":true}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"a1\\\"}\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/ordenes-operacion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"tipo\\\":\\\"SERVICIO\\\",\\\"cantidadObjetivo\\\":10}\"))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"o1\\\"}\", MediaType.APPLICATION_JSON));\n\n        EjecutorAccionesGateway ejecutor = new EjecutorAccionesGateway(builder.build());\n        ejecutor.ejecutar(AccionesPendientes.TIPO_ARTICULO_CREAR, \"{\\\"sku\\\":\\\"TUB-1\\\",\\\"loteObligatorio\\\":true}\");\n        ejecutor.ejecutar(AccionesPendientes.TIPO_ORDEN_OPERACION_CREAR, \"{\\\"tipo\\\":\\\"SERVICIO\\\",\\\"cantidadObjetivo\\\":10}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void pagoDeComprobanteEnviaLaClaveYElMontoSinElId() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/comprobantes/\" + ID + \"/pagos\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(header(\"Idempotency-Key\", \"clave-pago-1\"))\n                .andExpect(content().json(\"{\\\"monto\\\":1500.00,\\\"fechaPago\\\":\\\"2026-11-08\\\"}\"))\n                .andExpect(content().string(org.hamcrest.Matchers.not(containsString(\"comprobanteId\"))))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"p1\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_COMPROBANTE_PAGO_REGISTRAR,\n                        \"{\\\"comprobanteId\\\":\\\"\" + ID + \"\\\",\\\"monto\\\":1500.00,\\\"fechaPago\\\":\\\"2026-11-08\\\",\"\n                                + \"\\\"idempotencyKey\\\":\\\"clave-pago-1\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void tipoDesconocidoNoSeEjecuta() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n\n        assertThatThrownBy(() -> new EjecutorAccionesGateway(builder.build()).ejecutar(\"TIPO_RARO\", \"{}\"))\n                .isInstanceOf(IllegalArgumentException.class);\n        servidor.verify();\n    }\n\n    @Test\n    void accionesDeCotizacionLlamanASuEndpoint() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        String base = \"http://gateway/pedidos-ventas-ms/v1/cotizaciones/\" + ID;\n        servidor.expect(requestTo(base + \"/envio\")).andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(base + \"/aceptacion\")).andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(base + \"/pedido\")).andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n        EjecutorAccionesGateway ejecutor = new EjecutorAccionesGateway(builder.build());\n        String payload = \"{\\\"cotizacionId\\\":\\\"\" + ID + \"\\\"}\";\n\n        ejecutor.ejecutar(AccionesPendientes.TIPO_COTIZACION_ENVIAR, payload);\n        ejecutor.ejecutar(AccionesPendientes.TIPO_COTIZACION_ACEPTAR, payload);\n        ejecutor.ejecutar(AccionesPendientes.TIPO_COTIZACION_A_PEDIDO, payload);\n\n        servidor.verify();\n    }\n\n    @Test\n    void reemplazarLineasEnviaElPutSinElIdentificadorEnElCuerpo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID + \"/lineas\"))\n                .andExpect(method(HttpMethod.PUT))\n                .andExpect(content().json(\"{\\\"lineas\\\":[{\\\"cantidad\\\":3}]}\"))\n                .andExpect(content().string(not(containsString(\"pedidoId\"))))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PEDIDO_REEMPLAZAR_LINEAS,\n                \"{\\\"pedidoId\\\":\\\"\" + ID + \"\\\",\\\"lineas\\\":[{\\\"cantidad\\\":3}]}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void devolucionLlamaAlEndpointDeDevolucion() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID + \"/devolucion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build())\n                .ejecutar(AccionesPendientes.TIPO_PEDIDO_DEVOLVER, \"{\\\"pedidoId\\\":\\\"\" + ID + \"\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void cambioDeEstatusDeProspectoUsaPatch() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/prospectos/\" + ID + \"/estatus\"))\n                .andExpect(method(HttpMethod.PATCH))\n                .andExpect(content().json(\"{\\\"estatus\\\":\\\"CALIFICADO\\\"}\"))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PROSPECTO_ESTATUS,\n                \"{\\\"prospectoId\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CALIFICADO\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void conversionDeProspectoLlamaAlEndpointConElContacto() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/prospectos/\" + ID + \"/conversion\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"razonSocial\\\":\\\"Acme\\\",\\\"contactoPrincipal\\\":{\\\"rol\\\":\\\"PAGOS\\\"}}\"))\n                .andExpect(content().string(not(containsString(\"prospectoId\"))))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PROSPECTO_CONVERTIR,\n                \"{\\\"prospectoId\\\":\\\"\" + ID + \"\\\",\\\"razonSocial\\\":\\\"Acme\\\",\\\"rfc\\\":\\\"ACM010101AB1\\\",\"\n                        + \"\\\"contactoPrincipal\\\":{\\\"nombre\\\":\\\"Ana\\\",\\\"correo\\\":\\\"ana@acme.mx\\\",\\\"rol\\\":\\\"PAGOS\\\"}}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void interaccionLlamaAlEndpointDelCliente() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/\" + ID + \"/interacciones\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"tipo\\\":\\\"VISITA\\\",\\\"resumen\\\":\\\"Demo\\\"}\"))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_INTERACCION_REGISTRAR,\n                \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"tipo\\\":\\\"VISITA\\\",\\\"resumen\\\":\\\"Demo\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void cotizacionNuevaSeEnviaComoCuerpoAVentas() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/cotizaciones\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"canal\\\":\\\"WEB\\\",\\\"moneda\\\":\\\"MXN\\\"}\"))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_COTIZACION_CREAR,\n                \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"canal\\\":\\\"WEB\\\",\\\"moneda\\\":\\\"MXN\\\"}\");\n\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/EjecutorAccionesPolizaTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.content;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.method;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\n/** La póliza solo llega a contabilidad cuando se ejecuta una acción ya confirmada. */\nclass EjecutorAccionesPolizaTest {\n\n    @Test\n    void polizaConfirmadaSeEnviaAContabilidad() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        String payload = \"{\\\"tipo\\\":\\\"INGRESO\\\",\\\"fecha\\\":\\\"2026-11-15\\\",\\\"movimientos\\\":[\"\n                + \"{\\\"cuentaId\\\":\\\"00000000-0000-4000-8000-000000000101\\\",\\\"cargo\\\":1000,\\\"abono\\\":0},\"\n                + \"{\\\"cuentaId\\\":\\\"00000000-0000-4000-8000-000000000401\\\",\\\"cargo\\\":0,\\\"abono\\\":1000}]}\";\n        servidor.expect(requestTo(\"http://gateway/contabilidad-ms/v1/polizas\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(payload))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"p1\\\"}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_POLIZA_REGISTRAR, payload);\n\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/EjecutorNuevasAccionesTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.content;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.method;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\n\nclass EjecutorNuevasAccionesTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000021\";\n\n    @Test\n    void cambioDeEstatusDeClienteHaceElPatchAlEndpointReal() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/\" + ID + \"/estatus\"))\n                .andExpect(method(HttpMethod.PATCH))\n                .andExpect(content().json(\"{\\\"estatus\\\":\\\"BAJA\\\"}\"))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_CLIENTE_ESTATUS,\n                \"{\\\"clienteId\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BAJA\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void altaDeAlmacenHaceElPostAInventario() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/almacenes\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(content().json(\"{\\\"nombre\\\":\\\"Central\\\",\\\"ubicacion\\\":\\\"Zapopan\\\"}\"))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_ALMACEN_CREAR,\n                \"{\\\"nombre\\\":\\\"Central\\\",\\\"ubicacion\\\":\\\"Zapopan\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void entregaDePedidoHaceElPostSinCuerpo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID + \"/entrega\"))\n                .andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_PEDIDO_ENTREGAR,\n                \"{\\\"pedidoId\\\":\\\"\" + ID + \"\\\"}\");\n\n        servidor.verify();\n    }\n\n    @Test\n    void registroDeIndicadorHaceElPostAReportes() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/reportes-ejecutivos-ms/v1/indicadores\"))\n                .andExpect(method(HttpMethod.POST))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        new EjecutorAccionesGateway(builder.build()).ejecutar(AccionesPendientes.TIPO_INDICADOR_REGISTRAR,\n                \"{\\\"area\\\":\\\"OPERACIONES\\\",\\\"nombre\\\":\\\"x\\\",\\\"periodo\\\":\\\"2026-10\\\",\\\"valor\\\":1,\"\n                        + \"\\\"fuenteActualizadaUtc\\\":\\\"2026-11-08T00:00:00Z\\\"}\");\n\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/EvaluacionRecuperacionPoliticasIT.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.io.IOException;\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.Set;\n\nimport org.junit.jupiter.api.Test;\nimport org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AlmacenFragmentos;\nimport com.mx.josesaid.develop.nexus.application.Embedder;\nimport com.mx.josesaid.develop.nexus.application.FragmentoIndexado;\nimport com.mx.josesaid.develop.nexus.application.IngestaPoliticas;\nimport com.mx.josesaid.develop.nexus.application.RecuperadorPoliticas;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\n\n/**\n * Evaluación de calidad con Voyage AI real: para cada pregunta, la regla correcta de la política\n * de compras debe estar entre los 3 primeros resultados (la herramienta entrega 5 fragmentos al modelo).\n * Solo corre con VOYAGE_API_KEY definida.\n */\n@EnabledIfEnvironmentVariable(named = \"VOYAGE_API_KEY\", matches = \".+\")\nclass EvaluacionRecuperacionPoliticasIT {\n\n    private record Caso(String pregunta, String fragmentoEsperado) {\n    }\n\n    private static final List<Caso> CASOS = List.of(\n            new Caso(\"¿Quién aprueba una orden de 500 mil dólares?\", \"la puede aprobar COMPRAS\"),\n            new Caso(\"¿Quién aprueba una orden de 2 millones de dólares?\", \"requiere aprobación de DIRECCION\"),\n            new Caso(\"¿Puedo aprobar una orden que yo mismo creé?\", \"él mismo creó\"));\n\n    @Test\n    void laReglaCorrectaEstaEntreLasTresPrimeras() throws IOException {\n        Embedder embedder = new VoyageEmbedder(RestClient.builder().baseUrl(\"https://api.voyageai.com\").build(),\n                System.getenv(\"VOYAGE_API_KEY\"), \"voyage-3\");\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria();\n        new IngestaPoliticas(embedder, almacen).ingerir(PoliticasClasspath.cargar());\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedder, almacen, Clock.systemUTC());\n\n        for (Caso caso : CASOS) {\n            List<String> textos = recuperador.buscar(caso.pregunta(), Set.of(\"COMPRAS\"), 3).stream()\n                    .map(ResultadoPolitica::texto)\n                    .toList();\n            assertThat(textos).as(caso.pregunta()).anyMatch(t -> t.contains(caso.fragmentoEsperado()));\n        }\n    }\n\n    /** Almacén en memoria con el mismo criterio que la consulta SQL: rol en común y vigencia. */\n    static final class AlmacenEnMemoria implements AlmacenFragmentos {\n        private final List<FragmentoIndexado> guardados = new ArrayList<>();\n\n        @Override\n        public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n            guardados.removeIf(f -> f.politicaId().equals(politicaId));\n            guardados.addAll(fragmentos);\n        }\n\n        @Override\n        public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n            return guardados.stream()\n                    .filter(f -> f.roles().stream().anyMatch(roles::contains))\n                    .filter(f -> !f.vigencia().isAfter(hoy))\n                    .sorted(Comparator.comparingDouble((FragmentoIndexado f) -> similitud(f.vector(), consulta)).reversed())\n                    .limit(limite)\n                    .map(f -> new ResultadoPolitica(f.politicaId(), f.indice(), f.titulo(), f.texto(),\n                            similitud(f.vector(), consulta)))\n                    .toList();\n        }\n\n        private static double similitud(float[] a, float[] b) {\n            double punto = 0;\n            double normaA = 0;\n            double normaB = 0;\n            for (int i = 0; i < a.length; i++) {\n                punto += a[i] * b[i];\n                normaA += a[i] * a[i];\n                normaB += b[i] * b[i];\n            }\n            return punto / (Math.sqrt(normaA) * Math.sqrt(normaB));\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasAccionesMcpConsultaTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasAccionesMcpConsultaTest {\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"consultar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private static void comoUsuario(String sujeto) {\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(sujeto)\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))));\n    }\n\n    private HerramientasAccionesMcp herramientas() {\n        return new HerramientasAccionesMcp(null, acciones);\n    }\n\n    @Test\n    void quienLaPreparoVeSuEstado() {\n        comoUsuario(\"u-ventas\");\n        AccionPendiente accion = acciones.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR,\n                \"{}\", \"Crear pedido para cliente X\");\n\n        String respuesta = herramientas().consultarEstadoAccion(accion.id().toString());\n\n        assertThat(respuesta).contains(\"PENDIENTE\").contains(\"Crear pedido para cliente X\");\n    }\n\n    @Test\n    void otroUsuarioNoVeLaAccion() {\n        comoUsuario(\"u-ventas\");\n        AccionPendiente accion = acciones.preparar(\"u-ventas\", AccionesPendientes.TIPO_PEDIDO_BORRADOR,\n                \"{}\", \"Crear pedido\");\n\n        comoUsuario(\"u-otro\");\n        String respuesta = herramientas().consultarEstadoAccion(accion.id().toString());\n\n        assertThat(respuesta).isEqualTo(\"No encontré esa acción.\");\n    }\n\n    @Test\n    void identificadorInvalidoSeRechazaSinLanzar() {\n        comoUsuario(\"u-ventas\");\n\n        assertThat(herramientas().consultarEstadoAccion(\"no-es-uuid\"))\n                .isEqualTo(\"El identificador de la acción no es válido.\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasAccionesVentasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasAccionesVentasTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000002\";\n    private static final String URL_PEDIDO = \"http://gateway/pedidos-ventas-ms/v1/pedidos/\" + ID;\n    private static final String URL_COTIZACION = \"http://gateway/pedidos-ventas-ms/v1/cotizaciones/\" + ID;\n    private static final String URL_CLIENTE = \"http://gateway/clientes-ms/v1/clientes/\" + ID;\n    private static final String URL_PROSPECTO = \"http://gateway/clientes-ms/v1/prospectos/\" + ID;\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-01T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-ventas\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasVentas herramientas() {\n        return new HerramientasVentas(builder.build(), acciones);\n    }\n\n    @Test\n    void prospectoSePreparaSinLlamarAlGateway() {\n        String texto = herramientas().crearProspectoBorrador(\"Ana Prospecto\", \"ana@ejemplo.com\", \"\", \"referido\");\n\n        assertThat(texto).contains(\"no guardado\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PROSPECTO_BORRADOR);\n            assertThat(a.payload()).contains(\"\\\"fuente\\\":\\\"REFERIDO\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void prospectoRechazaUnaFuenteDesconocida() {\n        String texto = herramientas().crearProspectoBorrador(\"Ana\", \"ana@ejemplo.com\", \"\", \"radio\");\n\n        assertThat(texto).contains(\"CAMPANA, REFERIDO o EVENTO\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void confirmarPedidoSePreparaSiEstaEnBorrador() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BORRADOR\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().confirmarPedido(ID);\n\n        assertThat(texto).contains(\"no ejecutada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_CONFIRMAR));\n        servidor.verify();\n    }\n\n    @Test\n    void confirmarPedidoRechazaUnPedidoYaConfirmado() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONFIRMADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().confirmarPedido(ID);\n\n        assertThat(texto).contains(\"solo un pedido en borrador puede confirmarse\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void confirmarPedidoInexistenteResponde() {\n        servidor.expect(requestTo(URL_PEDIDO)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        String texto = herramientas().confirmarPedido(ID);\n\n        assertThat(texto).isEqualTo(\"No encontré ese pedido.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cancelarPedidoRechazaLaDevolucionTotal() {\n        String texto = herramientas().cancelarPedido(ID, \"DEVOLUCION_TOTAL\");\n\n        assertThat(texto).contains(\"CANCELACION_CLIENTE o ERROR_CAPTURA\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cancelarPedidoSePreparaSiEstaConfirmado() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONFIRMADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().cancelarPedido(ID, \"error_captura\");\n\n        assertThat(texto).contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_CANCELAR);\n            assertThat(a.payload()).contains(\"\\\"motivo\\\":\\\"ERROR_CAPTURA\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void enviarCotizacionSePreparaSiEstaEnBorrador() {\n        servidor.expect(requestTo(URL_COTIZACION))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BORRADOR\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().enviarCotizacion(ID);\n\n        assertThat(texto).contains(\"no ejecutado\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_COTIZACION_ENVIAR));\n        servidor.verify();\n    }\n\n    @Test\n    void aceptarCotizacionRechazaUnaCotizacionEnBorrador() {\n        servidor.expect(requestTo(URL_COTIZACION))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BORRADOR\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().aceptarCotizacion(ID);\n\n        assertThat(texto).contains(\"solo una cotización enviada puede aceptarse\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void convertirCotizacionAceptadaSePreparaComoPedido() {\n        servidor.expect(requestTo(URL_COTIZACION))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"ACEPTADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().convertirCotizacionEnPedido(ID);\n\n        assertThat(texto).contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_COTIZACION_A_PEDIDO));\n        servidor.verify();\n    }\n\n    @Test\n    void crearCotizacionSePreparaSiElClienteExiste() {\n        servidor.expect(requestTo(URL_CLIENTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().crearCotizacionBorrador(ID, \"web\", \"mxn\", \"iva_general\", \"2026-12-31\",\n                \"prod-1\", \"\", 2, \"100.00\");\n\n        assertThat(texto).contains(\"no guardada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_COTIZACION_CREAR);\n            assertThat(a.payload()).contains(\"\\\"vigenteHasta\\\":\\\"2026-12-31\\\"\")\n                    .contains(\"\\\"tasaIva\\\":\\\"IVA_GENERAL\\\"\").contains(\"\\\"canal\\\":\\\"WEB\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void crearCotizacionRechazaUnaVigenciaInvalidaSinConsultarNada() {\n        String texto = herramientas().crearCotizacionBorrador(ID, \"WEB\", \"MXN\", \"IVA_GENERAL\", \"31/12/2026\",\n                \"prod-1\", \"\", 2, \"100.00\");\n\n        assertThat(texto).contains(\"formato AAAA-MM-DD\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void crearCotizacionRechazaUnClienteInexistente() {\n        servidor.expect(requestTo(URL_CLIENTE)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        String texto = herramientas().crearCotizacionBorrador(ID, \"WEB\", \"MXN\", \"IVA_GENERAL\", \"2026-12-31\",\n                \"prod-1\", \"\", 2, \"100.00\");\n\n        assertThat(texto).contains(\"No encontré ese cliente.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void reemplazarLineasSoloSePreparaEnBorrador() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONFIRMADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().reemplazarLineasPedido(ID, \"prod-1\", \"\", 3, \"50\");\n\n        assertThat(texto).contains(\"solo un pedido en borrador admite cambios en sus líneas\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void reemplazarLineasPreparaLaAccionEnBorrador() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BORRADOR\\\"}\", MediaType.APPLICATION_JSON));\n\n        herramientas().reemplazarLineasPedido(ID, \"prod-1\", \"Tornillo\", 3, \"50\");\n\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_REEMPLAZAR_LINEAS);\n            assertThat(a.payload()).contains(\"\\\"pedidoId\\\":\\\"\" + ID + \"\\\"\").contains(\"\\\"cantidad\\\":3\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void devolucionSoloDePedidoEntregado() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONFIRMADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().registrarDevolucionPedido(ID);\n\n        assertThat(texto).contains(\"solo un pedido entregado puede devolverse\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void devolucionDePedidoEntregadoSePreparaComoAccion() {\n        servidor.expect(requestTo(URL_PEDIDO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"ENTREGADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().registrarDevolucionPedido(ID);\n\n        assertThat(texto).contains(\"no registrada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_DEVOLVER));\n        servidor.verify();\n    }\n\n    @Test\n    void cambiarEstatusNoAceptaConvertidoNiConsultaNada() {\n        String texto = herramientas().cambiarEstatusProspecto(ID, \"CONVERTIDO\");\n\n        assertThat(texto).contains(\"convertir_prospecto_en_cliente\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cambiarEstatusRespetaLasTransiciones() {\n        servidor.expect(requestTo(URL_PROSPECTO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"NUEVO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().cambiarEstatusProspecto(ID, \"CALIFICADO\");\n\n        assertThat(texto).contains(\"No se puede pasar el prospecto de NUEVO a CALIFICADO.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cambiarEstatusValidoSePreparaComoAccion() {\n        servidor.expect(requestTo(URL_PROSPECTO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONTACTADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        herramientas().cambiarEstatusProspecto(ID, \"calificado\");\n\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PROSPECTO_ESTATUS);\n            assertThat(a.payload()).contains(\"\\\"estatus\\\":\\\"CALIFICADO\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void convertirProspectoSoloSiEstaCalificado() {\n        servidor.expect(requestTo(URL_PROSPECTO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONTACTADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().convertirProspectoEnCliente(ID, \"Acme SA\", \"ACM010101AB1\", \"Ana\",\n                \"ana@acme.mx\", \"COMPRAS\");\n\n        assertThat(texto).contains(\"solo un prospecto calificado puede convertirse en cliente\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void convertirProspectoCalificadoSePreparaConSuContacto() {\n        servidor.expect(requestTo(URL_PROSPECTO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CALIFICADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        herramientas().convertirProspectoEnCliente(ID, \"Acme SA\", \"ACM010101AB1\", \"Ana\", \"ana@acme.mx\", \"compras\");\n\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PROSPECTO_CONVERTIR);\n            assertThat(a.payload()).contains(\"\\\"contactoPrincipal\\\"\").contains(\"\\\"rol\\\":\\\"COMPRAS\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void interaccionRechazaTipoYFechaInvalidosSinConsultarNada() {\n        HerramientasVentas herramientas = herramientas();\n\n        assertThat(herramientas.registrarInteraccionCliente(ID, \"CHAT\", \"2026-11-01T10:00:00-06:00\", \"Hola\"))\n                .contains(\"LLAMADA, CORREO o VISITA\");\n        assertThat(herramientas.registrarInteraccionCliente(ID, \"LLAMADA\", \"ayer\", \"Hola\"))\n                .contains(\"formato ISO 8601\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void interaccionSePreparaConLaFechaEnInstante() {\n        servidor.expect(requestTo(URL_CLIENTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        herramientas().registrarInteraccionCliente(ID, \"llamada\", \"2026-11-01T10:00:00-06:00\", \"Seguimiento\");\n\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_INTERACCION_REGISTRAR);\n            assertThat(a.payload()).contains(\"\\\"fecha\\\":\\\"2026-11-01T16:00:00Z\\\"\").contains(\"\\\"tipo\\\":\\\"LLAMADA\\\"\");\n        });\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasClientesTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasClientesTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000006\";\n    private static final String URL_CLIENTE = \"http://gateway/clientes-ms/v1/clientes/\" + ID;\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-admin\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_ADMIN\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasClientes herramientas() {\n        return new HerramientasClientes(builder.build(), acciones);\n    }\n\n    @Test\n    void altaDeClienteSePreparaSinEjecutarla() {\n        String texto = herramientas().crearCliente(\"Acme SA\", \"mogj850315ab3\", \"Ana\", \"ana@ejemplo.com\", \"compras\");\n\n        assertThat(texto).contains(\"no creada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_CLIENTE_CREAR);\n            assertThat(a.payload()).contains(\"\\\"rfc\\\":\\\"MOGJ850315AB3\\\"\").contains(\"\\\"rol\\\":\\\"COMPRAS\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void altaDeClienteRechazaUnRfcInvalido() {\n        String texto = herramientas().crearCliente(\"Acme\", \"123\", \"Ana\", \"ana@ejemplo.com\", \"COMPRAS\");\n\n        assertThat(texto).isEqualTo(\"El RFC no tiene un formato válido.\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void altaDeClienteRechazaUnRolDeContactoDesconocido() {\n        String texto = herramientas().crearCliente(\"Acme\", \"MOGJ850315AB3\", \"Ana\", \"ana@ejemplo.com\", \"DIRECCION\");\n\n        assertThat(texto).contains(\"COMPRAS, PAGOS o ASISTENCIA\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void cambioDeRazonSocialPreparaLaAccion() {\n        servidor.expect(requestTo(URL_CLIENTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().actualizarCliente(ID, \"Acme SA de CV\");\n\n        assertThat(texto).contains(\"no aplicado\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_CLIENTE_ACTUALIZAR));\n        servidor.verify();\n    }\n\n    @Test\n    void cambioDeRazonSocialDeClienteInexistenteResponde() {\n        servidor.expect(requestTo(URL_CLIENTE)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas().actualizarCliente(ID, \"Acme\")).isEqualTo(\"No encontré ese cliente.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void contactoNuevoSePreparaConElPrincipal() {\n        servidor.expect(requestTo(URL_CLIENTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().agregarContactoCliente(ID, \"Luis\", \"luis@ejemplo.com\", \"pagos\", \"true\");\n\n        assertThat(texto).contains(\"accion_id\").contains(\"como principal\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_CLIENTE_CONTACTO_AGREGAR);\n            assertThat(a.payload()).contains(\"\\\"principal\\\":true\").contains(\"\\\"rol\\\":\\\"PAGOS\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void interaccionesDeUnClienteSeConsultan() {\n        servidor.expect(requestTo(URL_CLIENTE + \"/interacciones\"))\n                .andRespond(withSuccess(\"[{\\\"tipo\\\":\\\"LLAMADA\\\"}]\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().consultarInteraccionesCliente(ID)).contains(\"LLAMADA\");\n        servidor.verify();\n    }\n\n    @Test\n    void interaccionesDeClienteInexistenteResponde() {\n        servidor.expect(requestTo(URL_CLIENTE + \"/interacciones\")).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas().consultarInteraccionesCliente(ID)).isEqualTo(\"No encontré ese cliente.\");\n        servidor.verify();\n    }\n\n    @Test\n    void metricasRechazanUnMesMal() {\n        assertThat(herramientas().consultarMetricasConversion(\"2026/09\"))\n                .isEqualTo(\"El mes debe tener formato AAAA-MM, por ejemplo 2026-09.\");\n    }\n\n    @Test\n    void prospectoSeConsulta() {\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/prospectos/\" + ID))\n                .andRespond(withSuccess(\"{\\\"estatus\\\":\\\"CALIFICADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().obtenerProspecto(ID)).contains(\"CALIFICADO\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasComprasEscrituraTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasComprasEscrituraTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000007\";\n    private static final String BASE = \"http://gateway/compras-proveedores-ms/v1\";\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-compras\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_COMPRAS\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasCompras herramientas() {\n        return new HerramientasCompras(builder.build(), acciones);\n    }\n\n    @Test\n    void altaDeProveedorSePreparaSinEjecutarla() {\n        String texto = herramientas().crearProveedor(\"Tubos SA\", \"tub850315ab3\", \"ventas@tubos.mx\");\n\n        assertThat(texto).contains(\"no creada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_PROVEEDOR_CREAR);\n            assertThat(a.payload()).contains(\"\\\"rfc\\\":\\\"TUB850315AB3\\\"\");\n        });\n    }\n\n    @Test\n    void altaDeProveedorRechazaUnCorreoInvalido() {\n        assertThat(herramientas().crearProveedor(\"Tubos\", \"TUB850315AB3\", \"sin-arroba\"))\n                .isEqualTo(\"El correo del proveedor no es válido.\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void ordenDeCompraVerificaElProveedorYGuardaNumerosNoTexto() {\n        servidor.expect(requestTo(BASE + \"/proveedores/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().crearOrdenCompra(ID, \"mxn\", \"TUB-1\", \"5\", \"120.50\");\n\n        assertThat(texto).contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_ORDEN_COMPRA_CREAR);\n            assertThat(a.payload()).contains(\"\\\"cantidad\\\":5\").contains(\"\\\"precioUnitario\\\":120.50\")\n                    .contains(\"\\\"moneda\\\":\\\"MXN\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void ordenDeCompraDeProveedorInexistenteResponde() {\n        servidor.expect(requestTo(BASE + \"/proveedores/\" + ID)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas().crearOrdenCompra(ID, \"MXN\", \"TUB-1\", \"5\", \"10\")).isEqualTo(\"No encontré ese proveedor.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void ordenDeCompraRechazaCantidadCero() {\n        assertThat(herramientas().crearOrdenCompra(ID, \"MXN\", \"TUB-1\", \"0\", \"10\")).contains(\"mayor a cero\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void recepcionSePreparaSoloSiLaOrdenEstaAprobada() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"APROBADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().registrarRecepcionOrden(ID, \"TUB-1\", \"2\");\n\n        assertThat(texto).contains(\"no registrada\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_ORDEN_COMPRA_RECEPCION));\n        servidor.verify();\n    }\n\n    @Test\n    void recepcionRechazaUnaOrdenEnBorrador() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"BORRADOR\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().registrarRecepcionOrden(ID, \"TUB-1\", \"2\")).contains(\"solo una orden aprobada\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cancelacionRechazaUnaOrdenRecibida() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"RECIBIDA\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().cancelarOrdenCompra(ID, \"Error\")).contains(\"no puede cancelarse\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cancelacionSePreparaParaUnaOrdenAbierta() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"APROBADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().cancelarOrdenCompra(ID, \"Proveedor sin stock\")).contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_ORDEN_COMPRA_CANCELAR));\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasComprasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasComprasTest {\n\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarProveedorRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/proveedores/\" + ID))\n                .andRespond(withSuccess(\"{\\\"razonSocial\\\":\\\"Acme\\\",\\\"correo\\\":\\\"a@b.com\\\",\\\"estatus\\\":\\\"ACTIVO\\\"}\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasCompras(builder.build()).consultarProveedor(ID);\n\n        assertThat(texto).contains(\"Acme\").doesNotContain(\"a@b.com\").contains(\"[CORREO]\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultarOrdenCompraPideLaOrden() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"estatus\\\":\\\"APROBADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasCompras(builder.build()).consultarOrdenCompra(ID);\n\n        assertThat(texto).contains(\"APROBADA\");\n        servidor.verify();\n    }\n\n    @Test\n    void buscarProveedoresPasaElTexto() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/compras-proveedores-ms/v1/proveedores?razonSocial=Acme\"))\n                .andRespond(withSuccess(\"[{\\\"razonSocial\\\":\\\"Acme SA\\\",\\\"correo\\\":\\\"a@b.com\\\"}]\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasCompras(builder.build()).buscarProveedores(\"Acme\");\n\n        assertThat(texto).contains(\"Acme SA\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasComprasValidacionTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.hamcrest.Matchers.containsString;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\n/** Validaciones y lecturas de HerramientasCompras que no cubre el flujo feliz. */\nclass HerramientasComprasValidacionTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000008\";\n    private static final String BASE = \"http://gateway/compras-proveedores-ms/v1\";\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        acciones = new AccionesPendientes(repo, ejecutor, Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC));\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-compras\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_COMPRAS\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasCompras herramientas() {\n        return new HerramientasCompras(builder.build(), acciones);\n    }\n\n    @Test\n    void sinServicioDeAccionesNoPreparaNada() {\n        HerramientasCompras sinAcciones = new HerramientasCompras(builder.build());\n\n        assertThat(sinAcciones.crearProveedor(\"Tubos\", \"TUB850315AB3\", \"a@b.mx\")).contains(\"no está disponible\");\n        assertThat(sinAcciones.crearOrdenCompra(ID, \"MXN\", \"T\", \"1\", \"1\")).contains(\"no está disponible\");\n        assertThat(sinAcciones.registrarRecepcionOrden(ID, \"T\", \"1\")).contains(\"no está disponible\");\n        assertThat(sinAcciones.cancelarOrdenCompra(ID, \"x\")).contains(\"no está disponible\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void altaDeProveedorValidaRazonRfcYLongitud() {\n        HerramientasCompras h = herramientas();\n\n        assertThat(h.crearProveedor(\" \", \"TUB850315AB3\", \"a@b.mx\")).contains(\"razón social\");\n        assertThat(h.crearProveedor(\"Tubos\", \" \", \"a@b.mx\")).contains(\"RFC es obligatorio\");\n        assertThat(h.crearProveedor(\"Tubos\", \"X\".repeat(14), \"a@b.mx\")).contains(\"RFC es obligatorio\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void ordenRechazaCadaCampoInvalido() {\n        HerramientasCompras h = herramientas();\n\n        assertThat(h.crearOrdenCompra(\"no-uuid\", \"MXN\", \"T\", \"1\", \"1\")).contains(\"identificador del proveedor\");\n        assertThat(h.crearOrdenCompra(ID, \" \", \"T\", \"1\", \"1\")).contains(\"moneda debe\");\n        assertThat(h.crearOrdenCompra(ID, \"MXNN\", \"T\", \"1\", \"1\")).contains(\"moneda debe\");\n        assertThat(h.crearOrdenCompra(ID, \"MXN\", \" \", \"1\", \"1\")).contains(\"SKU es obligatorio\");\n        assertThat(h.crearOrdenCompra(ID, \"MXN\", \"T\", \"abc\", \"1\")).contains(\"cantidad debe\");\n        assertThat(h.crearOrdenCompra(ID, \"MXN\", \"T\", \"1.2345\", \"1\")).contains(\"cantidad debe\");\n        assertThat(h.crearOrdenCompra(ID, \"MXN\", \"T\", \"1\", \"-1\")).contains(\"precio unitario no es válido\");\n        assertThat(h.crearOrdenCompra(ID, \"MXN\", \"T\", \"1\", \"abc\")).contains(\"precio unitario no es válido\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void recepcionValidaIdentificadorSkuYCantidad() {\n        HerramientasCompras h = herramientas();\n\n        assertThat(h.registrarRecepcionOrden(\"no-uuid\", \"T\", \"1\")).contains(\"identificador de la orden\");\n        assertThat(h.registrarRecepcionOrden(ID, \" \", \"1\")).contains(\"SKU es obligatorio\");\n        assertThat(h.registrarRecepcionOrden(ID, \"T\", \"0\")).contains(\"cantidad debe\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void recepcionDeOrdenInexistenteResponde() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas().registrarRecepcionOrden(ID, \"T\", \"1\")).isEqualTo(\"No encontré esa orden.\");\n        servidor.verify();\n    }\n\n    @Test\n    void cancelacionValidaIdentificadorMotivoYExistencia() {\n        HerramientasCompras h = herramientas();\n\n        assertThat(h.cancelarOrdenCompra(\"no-uuid\", \"Error\")).contains(\"identificador de la orden\");\n        assertThat(h.cancelarOrdenCompra(ID, \" \")).contains(\"motivo es obligatorio\");\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n        assertThat(h.cancelarOrdenCompra(ID, \"Error\")).isEqualTo(\"No encontré esa orden.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cancelacionRechazaUnaOrdenYaCancelada() {\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"estatus\\\":\\\"CANCELADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas().cancelarOrdenCompra(ID, \"Error\")).contains(\"no puede cancelarse\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultasDeProveedorYOrdenDevuelvenElDetalle() {\n        servidor.expect(requestTo(BASE + \"/proveedores/\" + ID))\n                .andRespond(withSuccess(\"{\\\"razonSocial\\\":\\\"Tubos\\\"}\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(BASE + \"/ordenes-compra/\" + ID))\n                .andRespond(withSuccess(\"{\\\"estatus\\\":\\\"APROBADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        HerramientasCompras h = herramientas();\n        assertThat(h.consultarProveedor(ID)).contains(\"Tubos\");\n        assertThat(h.consultarOrdenCompra(ID)).contains(\"APROBADA\");\n        servidor.verify();\n    }\n\n    @Test\n    void listarOrdenesRechazaUnEstatusDesconocidoYFiltraConUnoValido() {\n        HerramientasCompras h = herramientas();\n        assertThat(h.listarOrdenesCompra(\"ENVIADA\")).startsWith(\"Estatus no válido\");\n\n        servidor.expect(requestTo(containsString(\"/ordenes-compra?estatus=APROBADA\")))\n                .andRespond(withSuccess(\"[]\", MediaType.APPLICATION_JSON));\n        assertThat(h.listarOrdenesCompra(\"aprobada\")).isEqualTo(\"[]\");\n        servidor.verify();\n    }\n\n    @Test\n    void buscarProveedoresConsultaPorRazonSocial() {\n        servidor.expect(requestTo(containsString(\"/proveedores\")))\n                .andRespond(withSuccess(\"[]\", MediaType.APPLICATION_JSON));\n\n        herramientas().buscarProveedores(\"Tubos\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasContabilidadTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasContabilidadTest {\n\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarPolizaRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/contabilidad-ms/v1/polizas/\" + ID))\n                .andRespond(withSuccess(\"{\\\"periodo\\\":\\\"2026-09\\\",\\\"estatus\\\":\\\"APLICADA\\\",\\\"contacto\\\":\\\"a@b.com\\\"}\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasContabilidad(builder.build()).consultarPoliza(ID);\n\n        assertThat(texto).contains(\"2026-09\").contains(\"APLICADA\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultarEstadosFinancierosPasaElPeriodo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/contabilidad-ms/v1/estados-financieros?periodo=2026-09\"))\n                .andRespond(withSuccess(\"{\\\"periodo\\\":\\\"2026-09\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasContabilidad(builder.build()).consultarEstadosFinancieros(\"2026-09\");\n\n        assertThat(texto).contains(\"2026-09\");\n        servidor.verify();\n    }\n\n    @Test\n    void listarPolizasPasaElPeriodo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/contabilidad-ms/v1/polizas?periodo=2026-09\"))\n                .andRespond(withSuccess(\"[{\\\"periodo\\\":\\\"2026-09\\\",\\\"estatus\\\":\\\"APLICADA\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasContabilidad(builder.build()).listarPolizas(\"2026-09\");\n\n        assertThat(texto).contains(\"APLICADA\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasDocumentosBuscarTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasDocumentosBuscarTest {\n\n    @Test\n    void buscarDocumentosPideElTituloPorQueryParam() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/documentos-cumplimiento-ms/v1/documentos?titulo=contrato\"))\n                .andRespond(withSuccess(\"[{\\\"titulo\\\":\\\"Contrato marco\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasDocumentos(builder.build()).buscarDocumentos(\"contrato\");\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"Contrato marco\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasDocumentosCatalogoTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasDocumentosCatalogoTest {\n\n    @Test\n    void tiposDeDocumentoSeConsultanDelCatalogo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/documentos-cumplimiento-ms/v1/catalogos/tipos-documento\"))\n                .andRespond(withSuccess(\"[\\\"CONTRATO\\\",\\\"POLIZA_SEGURO\\\"]\", MediaType.APPLICATION_JSON));\n\n        assertThat(new HerramientasDocumentos(builder.build()).consultarTiposDocumento()).contains(\"CONTRATO\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasDocumentosEliminarTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasDocumentosEliminarTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000004\";\n    private static final String URL_DOCUMENTO = \"http://gateway/documentos-cumplimiento-ms/v1/documentos/\" + ID;\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-legal\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_LEGAL\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasDocumentos herramientas() {\n        return new HerramientasDocumentos(builder.build(), acciones);\n    }\n\n    @Test\n    void eliminacionSePreparaSinEjecutarla() {\n        servidor.expect(requestTo(URL_DOCUMENTO))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().solicitarEliminacionDocumento(ID, \"  Contrato vencido  \");\n\n        assertThat(texto).contains(\"no ejecutada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_DOCUMENTO_ELIMINAR);\n            assertThat(a.payload()).contains(\"\\\"motivo\\\":\\\"Contrato vencido\\\"\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void documentoInexistenteNoPreparaAccion() {\n        servidor.expect(requestTo(URL_DOCUMENTO)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        String texto = herramientas().solicitarEliminacionDocumento(ID, \"Duplicado\");\n\n        assertThat(texto).isEqualTo(\"No encontré ese documento.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void sinMotivoNoPreparaAccion() {\n        String texto = herramientas().solicitarEliminacionDocumento(ID, \"   \");\n\n        assertThat(texto).isEqualTo(\"El motivo de la eliminación es obligatorio.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void motivoLargoNoPreparaAccion() {\n        String texto = herramientas().solicitarEliminacionDocumento(ID, \"x\".repeat(301));\n\n        assertThat(texto).contains(\"300 caracteres\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void idInvalidoNoPreparaAccion() {\n        String texto = herramientas().solicitarEliminacionDocumento(\"no-es-uuid\", \"Duplicado\");\n\n        assertThat(texto).isEqualTo(\"El identificador del documento no es válido.\");\n        assertThat(almacen).isEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasDocumentosTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasDocumentosTest {\n\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarDocumentoRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/documentos-cumplimiento-ms/v1/documentos/\" + ID))\n                .andRespond(withSuccess(\"{\\\"titulo\\\":\\\"Contrato marco\\\",\\\"contacto\\\":\\\"a@b.com\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasDocumentos(builder.build()).consultarDocumento(ID);\n\n        assertThat(texto).contains(\"Contrato marco\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultarDocumentosPorVencerPasaLosDias() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/documentos-cumplimiento-ms/v1/documentos/por-vencer?dias=30\"))\n                .andRespond(withSuccess(\"[{\\\"titulo\\\":\\\"Poder notarial\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasDocumentos(builder.build()).consultarDocumentosPorVencer(30);\n\n        assertThat(texto).contains(\"Poder notarial\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasFinanzasComprobantesTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasFinanzasComprobantesTest {\n\n    @Test\n    void listarComprobantesPendientesPideLaRutaDeCobranza() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/comprobantes/pendientes-cobro\"))\n                .andRespond(withSuccess(\"[{\\\"folio\\\":\\\"F-1\\\",\\\"saldo\\\":1160.00}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasFinanzas(builder.build()).listarComprobantesPendientesCobro();\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"F-1\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasFinanzasEscrituraTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasFinanzasEscrituraTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-00000000000a\";\n    private static final String URL_COMPROBANTE = \"http://gateway/facturacion-pagos-ms/v1/comprobantes/\" + ID;\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        acciones = new AccionesPendientes(repo, ejecutor, Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC));\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-finanzas\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_FINANZAS\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasFinanzas herramientas() {\n        return new HerramientasFinanzas(builder.build(), acciones);\n    }\n\n    @Test\n    void cobroSePreparaSiElComprobanteExiste() {\n        servidor.expect(requestTo(URL_COMPROBANTE))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas().registrarPagoComprobante(ID, \"1500.5\", \"2026-11-08\", \"SPEI-99\");\n\n        assertThat(texto).contains(\"no registrado\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_COMPROBANTE_PAGO_REGISTRAR);\n            assertThat(a.payload()).contains(\"\\\"monto\\\":1500.5\").contains(\"\\\"fechaPago\\\":\\\"2026-11-08\\\"\")\n                    .contains(\"\\\"referencia\\\":\\\"SPEI-99\\\"\").contains(\"idempotencyKey\");\n        });\n        servidor.verify();\n    }\n\n    @Test\n    void cobroDeComprobanteInexistenteResponde() {\n        servidor.expect(requestTo(URL_COMPROBANTE)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas().registrarPagoComprobante(ID, \"10\", \"\", \"\")).isEqualTo(\"No encontré ese comprobante.\");\n        assertThat(almacen).isEmpty();\n        servidor.verify();\n    }\n\n    @Test\n    void cobroValidaMontoFechaYReferencia() {\n        HerramientasFinanzas h = herramientas();\n\n        assertThat(h.registrarPagoComprobante(\"no-uuid\", \"10\", \"\", \"\")).contains(\"identificador del comprobante\");\n        assertThat(h.registrarPagoComprobante(ID, \"0\", \"\", \"\")).contains(\"monto debe\");\n        assertThat(h.registrarPagoComprobante(ID, \"1.234\", \"\", \"\")).contains(\"monto debe\");\n        assertThat(h.registrarPagoComprobante(ID, \"10\", \"08/11/2026\", \"\")).contains(\"AAAA-MM-DD\");\n        assertThat(h.registrarPagoComprobante(ID, \"10\", \"\", \"R\".repeat(101))).contains(\"referencia\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void cuentaPorPagarSeConsulta() {\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/cuentas-por-pagar/\" + ID))\n                .andRespond(withSuccess(\"{\\\"saldo\\\":\\\"800.00\\\"}\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/cuentas-por-pagar/\" + ID))\n                .andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        HerramientasFinanzas h = herramientas();\n        assertThat(h.consultarCuentaPorPagar(ID)).contains(\"800.00\");\n        assertThat(h.consultarCuentaPorPagar(ID)).isEqualTo(\"No encontré esa cuenta por pagar.\");\n        assertThat(h.consultarCuentaPorPagar(\"x\")).contains(\"no es válido\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasFinanzasPagosTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasFinanzasPagosTest {\n\n    @Test\n    void listarPagosPideLaRutaDeCuentasPorPagar() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/cuentas-por-pagar/pagos\"))\n                .andRespond(withSuccess(\"[{\\\"monto\\\":150.00,\\\"referencia\\\":\\\"SPEI-1\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasFinanzas(builder.build()).listarPagosProveedor();\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"SPEI-1\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasFinanzasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasFinanzasTest {\n\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarComprobantePideElComprobanteYRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/comprobantes/\" + ID))\n                .andRespond(withSuccess(\"{\\\"folio\\\":\\\"F-001\\\",\\\"estatus\\\":\\\"EMITIDO\\\",\\\"contacto\\\":\\\"a@b.com\\\"}\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasFinanzas(builder.build()).consultarComprobante(ID);\n\n        assertThat(texto).contains(\"F-001\").contains(\"EMITIDO\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n\n    @Test\n    void buscarComprobantePorFolioPasaElFolio() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/facturacion-pagos-ms/v1/comprobantes?folio=F-001\"))\n                .andRespond(withSuccess(\"{\\\"folio\\\":\\\"F-001\\\",\\\"estatus\\\":\\\"EMITIDO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasFinanzas(builder.build()).buscarComprobantePorFolio(\"F-001\");\n\n        assertThat(texto).contains(\"F-001\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasInventarioBajoMinimoTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasInventarioBajoMinimoTest {\n\n    @Test\n    void listarArticulosBajoMinimoPideLaRutaDeInventario() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/articulos/bajo-minimo\"))\n                .andRespond(withSuccess(\"[{\\\"sku\\\":\\\"SKU-C\\\",\\\"faltante\\\":20}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasInventario(builder.build()).listarArticulosBajoMinimo();\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"SKU-C\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasInventarioEscrituraTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasInventarioEscrituraTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000009\";\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        acciones = new AccionesPendientes(repo, ejecutor, Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC));\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-almacen\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_ALMACEN\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private HerramientasInventario herramientas() {\n        return new HerramientasInventario(RestClient.builder().baseUrl(\"http://gateway\").build(), acciones);\n    }\n\n    @Test\n    void sinServicioDeAccionesNoPreparaNada() {\n        HerramientasInventario sinAcciones = new HerramientasInventario(RestClient.builder().build());\n\n        assertThat(sinAcciones.crearArticulo(\"T\", \"Tubo\", \"PZA\", \"\", \"\")).contains(\"no está disponible\");\n        assertThat(sinAcciones.registrarMovimientoInventario(ID, ID, \"ENTRADA\", \"1\", \"\", \"\")).contains(\"no está disponible\");\n        assertThat(sinAcciones.crearOrdenOperacion(\"SERVICIO\", \"1\")).contains(\"no está disponible\");\n    }\n\n    @Test\n    void articuloSePreparaConLoteYMinimo() {\n        String texto = herramientas().crearArticulo(\"TUB-1\", \"Tubo cobre\", \"PZA\", \"true\", \"5.5\");\n\n        assertThat(texto).contains(\"no creada\").contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_ARTICULO_CREAR);\n            assertThat(a.payload()).contains(\"\\\"loteObligatorio\\\":true\").contains(\"\\\"minimo\\\":5.5\");\n        });\n    }\n\n    @Test\n    void articuloValidaSkuNombreUnidadYMinimo() {\n        HerramientasInventario h = herramientas();\n\n        assertThat(h.crearArticulo(\" \", \"Tubo\", \"PZA\", \"\", \"\")).contains(\"SKU es obligatorio\");\n        assertThat(h.crearArticulo(\"T\", \" \", \"PZA\", \"\", \"\")).contains(\"nombre es obligatorio\");\n        assertThat(h.crearArticulo(\"T\", \"Tubo\", \"X\".repeat(11), \"\", \"\")).contains(\"unidad es obligatoria\");\n        assertThat(h.crearArticulo(\"T\", \"Tubo\", \"PZA\", \"\", \"-1\")).contains(\"mínimo debe\");\n        assertThat(h.crearArticulo(\"T\", \"Tubo\", \"PZA\", \"\", \"abc\")).contains(\"mínimo debe\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void movimientoSePreparaConClaveDeIdempotencia() {\n        String texto = herramientas().registrarMovimientoInventario(ID, ID, \"entrada\", \"3\", \"L-7\", \"OC-12\");\n\n        assertThat(texto).contains(\"no registrado\");\n        assertThat(almacen.values()).singleElement().satisfies(a -> {\n            assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_MOVIMIENTO_REGISTRAR);\n            assertThat(a.payload()).contains(\"\\\"tipo\\\":\\\"ENTRADA\\\"\").contains(\"\\\"lote\\\":\\\"L-7\\\"\")\n                    .contains(\"\\\"referencia\\\":\\\"OC-12\\\"\").contains(\"idempotencyKey\");\n        });\n    }\n\n    @Test\n    void movimientoValidaCadaCampo() {\n        HerramientasInventario h = herramientas();\n\n        assertThat(h.registrarMovimientoInventario(\"no-uuid\", ID, \"ENTRADA\", \"1\", \"\", \"\")).contains(\"UUID válidos\");\n        assertThat(h.registrarMovimientoInventario(ID, ID, \"PRESTAMO\", \"1\", \"\", \"\")).contains(\"ENTRADA, SALIDA\");\n        assertThat(h.registrarMovimientoInventario(ID, ID, \"ENTRADA\", \"0\", \"\", \"\")).contains(\"cantidad debe\");\n        assertThat(h.registrarMovimientoInventario(ID, ID, \"ENTRADA\", \"1\", \"L\".repeat(61), \"\")).contains(\"lote\");\n        assertThat(h.registrarMovimientoInventario(ID, ID, \"ENTRADA\", \"1\", \"\", \"R\".repeat(101))).contains(\"referencia\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void ordenDeOperacionValidaTipoYCantidad() {\n        HerramientasInventario h = herramientas();\n\n        assertThat(h.crearOrdenOperacion(\"MANUAL\", \"1\")).contains(\"PRODUCCION o SERVICIO\");\n        assertThat(h.crearOrdenOperacion(\"PRODUCCION\", \"-2\")).contains(\"cantidad objetivo debe\");\n        assertThat(almacen).isEmpty();\n\n        assertThat(h.crearOrdenOperacion(\"produccion\", \"12\")).contains(\"accion_id\");\n        assertThat(almacen.values()).singleElement()\n                .satisfies(a -> assertThat(a.tipo()).isEqualTo(AccionesPendientes.TIPO_ORDEN_OPERACION_CREAR));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasInventarioMovimientosTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasInventarioMovimientosTest {\n\n    private static final String ARTICULO = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void listarMovimientosPideElArticulo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/movimientos?articulo=\" + ARTICULO))\n                .andRespond(withSuccess(\"[{\\\"tipo\\\":\\\"ENTRADA\\\",\\\"cantidad\\\":5}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasInventario(builder.build()).listarMovimientosArticulo(ARTICULO);\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"ENTRADA\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasInventarioTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasInventarioTest {\n\n    private static final String ARTICULO = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarExistenciasPasaElArticulo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/existencias?articulo=\" + ARTICULO))\n                .andRespond(withSuccess(\"[{\\\"disponible\\\":10,\\\"contacto\\\":\\\"a@b.com\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasInventario(builder.build()).consultarExistencias(ARTICULO);\n\n        assertThat(texto).contains(\"10\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultarTrazabilidadLotePideElLote() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/inventario-operaciones-ms/v1/lotes/L-2026-09/trazabilidad\"))\n                .andRespond(withSuccess(\"[{\\\"tipo\\\":\\\"ENTRADA\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasInventario(builder.build()).consultarTrazabilidadLote(\"L-2026-09\");\n\n        assertThat(texto).contains(\"ENTRADA\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasNuevasEscriturasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\nimport org.springframework.http.MediaType;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\n\nclass HerramientasNuevasEscriturasTest {\n\n    private static final String CLIENTE = \"7d3c1f2e-0000-4000-8000-000000000011\";\n    private static final String PEDIDO = \"7d3c1f2e-0000-4000-8000-000000000012\";\n\n    private final Map<UUID, AccionPendiente> almacen = new HashMap<>();\n    private AccionesPendientes acciones;\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    @BeforeEach\n    void preparar() {\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar la acción\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-08T00:00:00Z\"), ZoneOffset.UTC);\n        acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        Jwt jwt = Jwt.withTokenValue(\"token\").header(\"alg\", \"none\").subject(\"u-operaciones\")\n                .issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();\n        SecurityContextHolder.getContext().setAuthentication(\n                new JwtAuthenticationToken(jwt, List.of(new SimpleGrantedAuthority(\"ROLE_ADMIN\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private AccionPendiente unicaAccion() {\n        assertThat(almacen).hasSize(1);\n        return almacen.values().iterator().next();\n    }\n\n    @Test\n    void cambioDeEstatusDeClienteSePreparaSinEjecutarlo() {\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/\" + CLIENTE))\n                .andRespond(withSuccess(\"{}\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasClientes(builder.build(), acciones)\n                .cambiarEstatusCliente(CLIENTE, \"suspendido\");\n\n        assertThat(respuesta).contains(\"Cambio preparado, no ejecutado.\").contains(\"accion_id\");\n        assertThat(unicaAccion().tipo()).isEqualTo(AccionesPendientes.TIPO_CLIENTE_ESTATUS);\n        assertThat(unicaAccion().payload()).contains(\"\\\"estatus\\\":\\\"SUSPENDIDO\\\"\");\n        servidor.verify();\n    }\n\n    @Test\n    void estatusDeClienteInvalidoSeRechaza() {\n        String respuesta = new HerramientasClientes(builder.build(), acciones)\n                .cambiarEstatusCliente(CLIENTE, \"PAUSADO\");\n\n        assertThat(respuesta).isEqualTo(\"El estatus debe ser ACTIVO, SUSPENDIDO o BAJA.\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void altaDeAlmacenSePreparaSinEjecutarla() {\n        String respuesta = new HerramientasInventario(builder.build(), acciones)\n                .crearAlmacen(\"Central\", \"Zapopan, Jalisco\");\n\n        assertThat(respuesta).contains(\"Alta preparada, no creada.\").contains(\"accion_id\");\n        assertThat(unicaAccion().tipo()).isEqualTo(AccionesPendientes.TIPO_ALMACEN_CREAR);\n    }\n\n    @Test\n    void altaDeAlmacenSinNombreSeRechaza() {\n        String respuesta = new HerramientasInventario(builder.build(), acciones)\n                .crearAlmacen(\" \", \"Zapopan\");\n\n        assertThat(respuesta).isEqualTo(\"El nombre es obligatorio y de hasta 100 caracteres.\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void entregaDePedidoSePreparaSinEjecutarla() {\n        String respuesta = new HerramientasVentas(builder.build(), acciones)\n                .registrarEntregaPedido(PEDIDO);\n\n        assertThat(respuesta).contains(\"Entrega preparada, no registrada.\").contains(\"accion_id\");\n        assertThat(unicaAccion().tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_ENTREGAR);\n        assertThat(unicaAccion().payload()).contains(PEDIDO);\n    }\n\n    @Test\n    void entregaDePedidoConIdentificadorInvalidoSeRechaza() {\n        assertThat(new HerramientasVentas(builder.build(), acciones).registrarEntregaPedido(\"no-es-uuid\"))\n                .isEqualTo(\"El identificador del pedido no es válido.\");\n        assertThat(almacen).isEmpty();\n    }\n\n    @Test\n    void indicadorSePreparaConAreaEnMayusculasYValorNumerico() {\n        String respuesta = new HerramientasReportes(builder.build(), acciones)\n                .registrarIndicador(\"operaciones\", \"Entregas a tiempo\", \"2026-10\", \"12.5\",\n                        \"2026-11-08T00:00:00Z\");\n\n        assertThat(respuesta).contains(\"Registro preparado, no ejecutado.\").contains(\"accion_id\");\n        AccionPendiente accion = unicaAccion();\n        assertThat(accion.tipo()).isEqualTo(AccionesPendientes.TIPO_INDICADOR_REGISTRAR);\n        assertThat(accion.payload()).contains(\"\\\"area\\\":\\\"OPERACIONES\\\"\").contains(\"\\\"periodo\\\":\\\"2026-10\\\"\");\n    }\n\n    @Test\n    void indicadorInvalidoSeRechazaEnCadaCampo() {\n        HerramientasReportes herramientas = new HerramientasReportes(builder.build(), acciones);\n\n        assertThat(herramientas.registrarIndicador(\"RRHH\", \"x\", \"2026-10\", \"1\", \"2026-11-08T00:00:00Z\"))\n                .startsWith(\"El área no es válida\");\n        assertThat(herramientas.registrarIndicador(\"OPERACIONES\", \"x\", \"2026-13\", \"1\", \"2026-11-08T00:00:00Z\"))\n                .startsWith(\"El periodo debe ser\");\n        assertThat(herramientas.registrarIndicador(\"OPERACIONES\", \"x\", \"2026-10\", \"abc\", \"2026-11-08T00:00:00Z\"))\n                .isEqualTo(\"El valor debe ser numérico.\");\n        assertThat(herramientas.registrarIndicador(\"OPERACIONES\", \"x\", \"2026-10\", \"1\", \"ayer\"))\n                .startsWith(\"La fecha de actualización\");\n        assertThat(almacen).isEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasPoliticasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Clock;\nimport java.time.LocalDate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.security.authentication.TestingAuthenticationToken;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\nimport com.mx.josesaid.develop.nexus.application.AlmacenFragmentos;\nimport com.mx.josesaid.develop.nexus.application.Embedder;\nimport com.mx.josesaid.develop.nexus.application.FragmentoIndexado;\nimport com.mx.josesaid.develop.nexus.application.RecuperadorPoliticas;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\n\nclass HerramientasPoliticasTest {\n\n    /** Almacén que filtra por rol como lo hace la consulta SQL: basta un rol en común. */\n    private final AlmacenFragmentos almacen = new AlmacenFragmentos() {\n        private final List<FragmentoIndexado> guardados = new ArrayList<>();\n\n        @Override\n        public void reemplazar(String politicaId, List<FragmentoIndexado> fragmentos) {\n            guardados.clear();\n            guardados.addAll(fragmentos);\n        }\n\n        @Override\n        public List<ResultadoPolitica> buscar(Set<String> roles, float[] consulta, LocalDate hoy, int limite) {\n            return guardados.stream()\n                    .filter(f -> f.roles().stream().anyMatch(roles::contains))\n                    .map(f -> new ResultadoPolitica(f.politicaId(), f.indice(), f.titulo(), f.texto(), 1.0))\n                    .toList();\n        }\n    };\n\n    private HerramientasPoliticas herramienta;\n\n    @BeforeEach\n    void preparar() {\n        Embedder embedder = (textos, tipo) -> textos.stream().map(t -> new float[]{1f}).toList();\n        RecuperadorPoliticas recuperador = new RecuperadorPoliticas(embedder, almacen, Clock.systemUTC());\n        almacen.reemplazar(\"aprobacion\", List.of(new FragmentoIndexado(\"aprobacion\", 0, \"Aprobación\",\n                LocalDate.of(2026, 11, 1), List.of(\"COMPRAS\", \"DIRECCION\"),\n                \"Menos de 1,000,000 USD lo aprueba COMPRAS.\", new float[]{1f})));\n        herramienta = new HerramientasPoliticas(recuperador);\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @Test\n    void devuelveElFragmentoConSuFuente() {\n        comoRoles(\"ROLE_COMPRAS\");\n\n        String texto = herramienta.consultarPoliticas(\"¿Quién aprueba una orden chica?\");\n\n        assertThat(texto).contains(\"[Aprobación, regla 1]\").contains(\"Menos de 1,000,000 USD\");\n    }\n\n    @Test\n    void unRolSinAccesoNoVeLaPolitica() {\n        comoRoles(\"ROLE_VENTAS\");\n\n        String texto = herramienta.consultarPoliticas(\"¿Quién aprueba una orden chica?\");\n\n        assertThat(texto).doesNotContain(\"1,000,000\").startsWith(\"No encontré\");\n    }\n\n    @Test\n    void sinAutenticacionNoDevuelveNada() {\n        String texto = herramienta.consultarPoliticas(\"¿Quién aprueba una orden chica?\");\n\n        assertThat(texto).startsWith(\"No encontré\");\n    }\n\n    private static void comoRoles(String... roles) {\n        SecurityContextHolder.getContext().setAuthentication(\n                new TestingAuthenticationToken(\"u1\", \"n/a\", roles));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasRedaccionTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasRedaccionTest {\n\n    @Test\n    void reportesRedactaLaRespuestaAntesDeVolverAlModelo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/reportes-ejecutivos-ms/v1/reportes/2026-10\"))\n                .andRespond(withSuccess(\"{\\\"responsable\\\":\\\"XAXX010101000\\\",\\\"contacto\\\":\\\"a@b.com\\\"}\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasReportes(builder.build()).consultarReporte(\"2026-10\");\n\n        assertThat(texto).doesNotContain(\"XAXX010101000\", \"a@b.com\").contains(\"[RFC]\", \"[CORREO]\");\n        servidor.verify();\n    }\n\n    @Test\n    void clientesDejanElRfcAlModeloYOcultanElTelefono() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/clientes-ms/v1/clientes/7c9e6679-7425-40de-944b-e07fc1f90ae7\"))\n                .andRespond(withSuccess(\"{\\\"rfc\\\":\\\"MOGJ850315AB3\\\",\\\"telefono\\\":\\\"3312345678\\\"}\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasClientes(builder.build())\n                .obtenerCliente(\"7c9e6679-7425-40de-944b-e07fc1f90ae7\");\n\n        assertThat(texto).contains(\"MOGJ850315AB3\").doesNotContain(\"3312345678\").contains(\"[TELEFONO]\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasUsuariosAltaTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.ArgumentMatchers.anyString;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.never;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.mockito.ArgumentCaptor;\nimport org.springframework.security.authentication.UsernamePasswordAuthenticationToken;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.CodigoConfirmacion;\n\nclass HerramientasUsuariosAltaTest {\n\n    private AccionesPendientes acciones;\n    private HerramientasUsuarios herramienta;\n\n    @BeforeEach\n    void preparar() {\n        acciones = mock(AccionesPendientes.class);\n        herramienta = new HerramientasUsuarios(mock(RestClient.class), acciones,\n                new CodigoConfirmacion(new byte[32]));\n        SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(\n                \"admin\", null, java.util.List.of(new SimpleGrantedAuthority(\"ROLE_ADMIN\"))));\n    }\n\n    @AfterEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @Test\n    void prepararAltaNoRecibeNiGuardaContrasena() {\n        UUID id = UUID.randomUUID();\n        when(acciones.preparar(anyString(), anyString(), anyString(), anyString())).thenReturn(\n                new AccionPendiente(id, \"admin\", AccionesPendientes.TIPO_USUARIO_ALTA, \"{}\", \"resumen\",\n                        AccionPendiente.PENDIENTE, Instant.now(), Instant.now().plusSeconds(600)));\n\n        String respuesta = herramienta.prepararAltaUsuario(\"ana@empresa.com\", \"Ana López\", \"VENTAS, CONTADOR\");\n\n        ArgumentCaptor<String> payload = ArgumentCaptor.forClass(String.class);\n        verify(acciones).preparar(eq(\"admin\"), eq(AccionesPendientes.TIPO_USUARIO_ALTA),\n                payload.capture(), any());\n        assertThat(payload.getValue()).contains(\"ana@empresa.com\").doesNotContain(\"password\");\n        assertThat(respuesta).contains(id.toString()).contains(\"Código de confirmación\");\n    }\n\n    @Test\n    void rechazaCorreoInvalidoSinPreparar() {\n        String respuesta = herramienta.prepararAltaUsuario(\"no-es-correo\", \"Ana\", \"VENTAS\");\n\n        assertThat(respuesta).contains(\"correo no es válido\");\n        verify(acciones, never()).preparar(anyString(), anyString(), anyString(), anyString());\n    }\n\n    @Test\n    void rechazaRolFueraDeLaListaSinPreparar() {\n        String respuesta = herramienta.prepararAltaUsuario(\"ana@empresa.com\", \"Ana\", \"VENTAS, JEFE_AREA\");\n\n        assertThat(respuesta).contains(\"Roles inválidos\");\n        verify(acciones, never()).preparar(anyString(), anyString(), anyString(), anyString());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasUsuariosListarTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasUsuariosListarTest {\n\n    @Test\n    void listarUsuariosPideLaRutaDeUsuarios() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/usuarios-accesos-ms/v1/usuarios\"))\n                .andRespond(withSuccess(\"[{\\\"estatus\\\":\\\"ACTIVO\\\"}]\", MediaType.APPLICATION_JSON));\n\n        String respuesta = new HerramientasUsuarios(builder.build()).listarUsuarios();\n\n        servidor.verify();\n        assertThat(respuesta).contains(\"ACTIVO\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasUsuariosTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasUsuariosTest {\n\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n\n    @Test\n    void consultarUsuarioPideElUsuarioYRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/usuarios-accesos-ms/v1/usuarios/\" + ID))\n                .andRespond(withSuccess(\"{\\\"estatus\\\":\\\"ACTIVO\\\",\\\"correo\\\":\\\"a@b.com\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasUsuarios(builder.build()).consultarUsuario(ID);\n\n        assertThat(texto).contains(\"ACTIVO\").doesNotContain(\"a@b.com\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasVentasLecturasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasVentasLecturasTest {\n\n    private static final String ID = \"7d3c1f2e-0000-4000-8000-000000000005\";\n    private static final String BASE = \"http://gateway/pedidos-ventas-ms/v1\";\n\n    private RestClient.Builder builder;\n    private MockRestServiceServer servidor;\n\n    private HerramientasVentas herramientas() {\n        builder = RestClient.builder().baseUrl(\"http://gateway\");\n        servidor = MockRestServiceServer.bindTo(builder).build();\n        return new HerramientasVentas(builder.build());\n    }\n\n    @Test\n    void obtenerPedidoDevuelveElDetalle() {\n        HerramientasVentas herramientas = herramientas();\n        servidor.expect(requestTo(BASE + \"/pedidos/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"CONFIRMADO\\\"}\", MediaType.APPLICATION_JSON));\n\n        String texto = herramientas.obtenerPedido(ID);\n\n        assertThat(texto).contains(\"CONFIRMADO\");\n        servidor.verify();\n    }\n\n    @Test\n    void obtenerPedidoInexistenteResponde() {\n        HerramientasVentas herramientas = herramientas();\n        servidor.expect(requestTo(BASE + \"/pedidos/\" + ID)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas.obtenerPedido(ID)).isEqualTo(\"No encontré ese pedido.\");\n        servidor.verify();\n    }\n\n    @Test\n    void obtenerPedidoRechazaUnIdentificadorInvalido() {\n        HerramientasVentas herramientas = herramientas();\n\n        assertThat(herramientas.obtenerPedido(\"no-es-uuid\")).isEqualTo(\"El identificador del pedido no es válido.\");\n        servidor.verify();\n    }\n\n    @Test\n    void obtenerCotizacionDevuelveElDetalle() {\n        HerramientasVentas herramientas = herramientas();\n        servidor.expect(requestTo(BASE + \"/cotizaciones/\" + ID))\n                .andRespond(withSuccess(\"{\\\"id\\\":\\\"\" + ID + \"\\\",\\\"estatus\\\":\\\"ENVIADA\\\"}\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas.obtenerCotizacion(ID)).contains(\"ENVIADA\");\n        servidor.verify();\n    }\n\n    @Test\n    void obtenerCotizacionInexistenteResponde() {\n        HerramientasVentas herramientas = herramientas();\n        servidor.expect(requestTo(BASE + \"/cotizaciones/\" + ID)).andRespond(withStatus(HttpStatus.NOT_FOUND));\n\n        assertThat(herramientas.obtenerCotizacion(ID)).isEqualTo(\"No encontré esa cotización.\");\n        servidor.verify();\n    }\n\n    @Test\n    void obtenerCotizacionRechazaUnIdentificadorInvalido() {\n        HerramientasVentas herramientas = herramientas();\n\n        assertThat(herramientas.obtenerCotizacion(\"x\")).isEqualTo(\"El identificador de la cotización no es válido.\");\n        servidor.verify();\n    }\n\n    @Test\n    void consultarTasasIvaYMonedasDevuelvenElCatalogo() {\n        HerramientasVentas herramientas = herramientas();\n        servidor.expect(requestTo(BASE + \"/catalogos/tasas-iva\"))\n                .andRespond(withSuccess(\"[\\\"IVA_GENERAL\\\"]\", MediaType.APPLICATION_JSON));\n        servidor.expect(requestTo(BASE + \"/catalogos/monedas\"))\n                .andRespond(withSuccess(\"[\\\"MXN\\\"]\", MediaType.APPLICATION_JSON));\n\n        assertThat(herramientas.consultarTasasIva()).contains(\"IVA_GENERAL\");\n        assertThat(herramientas.consultarMonedas()).contains(\"MXN\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/HerramientasVentasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.List;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.core.context.SecurityContextHolder;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport com.mx.josesaid.develop.nexus.application.AccionPendiente;\nimport com.mx.josesaid.develop.nexus.application.AccionesPendientes;\nimport com.mx.josesaid.develop.nexus.application.AlmacenAcciones;\nimport com.mx.josesaid.develop.nexus.application.EjecutorAcciones;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.RestClient;\n\nclass HerramientasVentasTest {\n\n    @Test\n    void consultarPedidosPasaLosFiltrosYRedactaElCorreo() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/pedidos?estatus=CONFIRMADO&canal=WEB\"))\n                .andRespond(withSuccess(\"[{\\\"estatus\\\":\\\"CONFIRMADO\\\",\\\"contacto\\\":\\\"a@b.com\\\"}]\",\n                        MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasVentas(builder.build()).consultarPedidos(\"confirmado\", \"web\", \"\");\n\n        assertThat(texto).contains(\"CONFIRMADO\").doesNotContain(\"a@b.com\").contains(\"[CORREO]\");\n        servidor.verify();\n    }\n\n    @Test\n    void resumenVentasPideElMes() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"http://gateway/pedidos-ventas-ms/v1/metricas/ventas?mes=2026-09\"))\n                .andRespond(withSuccess(\"{\\\"mes\\\":\\\"2026-09\\\",\\\"pedidos\\\":5}\", MediaType.APPLICATION_JSON));\n\n        String texto = new HerramientasVentas(builder.build()).resumenVentas(\"2026-09\");\n\n        assertThat(texto).contains(\"2026-09\");\n        servidor.verify();\n    }\n\n    @AfterEach\n    void limpiarContexto() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @Test\n    void prepararPedidoNoLlamaAlGatewayYDejaLaAccionPendiente() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"http://gateway\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        Map<UUID, AccionPendiente> almacen = new HashMap<>();\n        AlmacenAcciones repo = new AlmacenAcciones() {\n            @Override\n            public void guardar(AccionPendiente a) {\n                almacen.put(a.id(), a);\n            }\n\n            @Override\n            public Optional<AccionPendiente> buscar(UUID id) {\n                return Optional.ofNullable(almacen.get(id));\n            }\n        };\n        EjecutorAcciones ejecutor = (tipo, payload) -> {\n            throw new AssertionError(\"preparar no debe ejecutar\");\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-01T00:00:00Z\"), ZoneOffset.UTC);\n        AccionesPendientes acciones = new AccionesPendientes(repo, ejecutor, reloj);\n        SecurityContextHolder.getContext().setAuthentication(new JwtAuthenticationToken(\n                Jwt.withTokenValue(\"t\").header(\"alg\", \"none\").subject(\"u-ventas\").build(),\n                List.of(new SimpleGrantedAuthority(\"ROLE_VENTAS\"))));\n\n        String texto = new HerramientasVentas(builder.build(), acciones).prepararPedidoBorrador(\n                \"11111111-1111-1111-1111-111111111111\", \"web\", \"mxn\", \"iva_general\",\n                \"22222222-2222-2222-2222-222222222222\", \"Silla\", 2, \"500\");\n\n        assertThat(texto).contains(\"no guardado\").contains(\"accion_id\");\n        assertThat(almacen).hasSize(1);\n        AccionPendiente accion = almacen.values().iterator().next();\n        assertThat(accion.usuario()).isEqualTo(\"u-ventas\");\n        assertThat(accion.tipo()).isEqualTo(AccionesPendientes.TIPO_PEDIDO_BORRADOR);\n        assertThat(accion.payload()).contains(\"\\\"canal\\\":\\\"WEB\\\"\").contains(\"\\\"cantidad\\\":2\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/MatrizRolesHerramientasTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport org.junit.jupiter.api.AfterEach;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.CsvSource;\nimport org.springframework.security.authentication.TestingAuthenticationToken;\nimport org.springframework.security.core.context.SecurityContextHolder;\n\n/**\n * Matriz de escenarios: qué herramienta puede usar cada rol desde Nexus.\n * Fija el alcance por rol; si cambia el mapa de roles, esta prueba debe cambiar a propósito.\n */\nclass MatrizRolesHerramientasTest {\n\n    @BeforeEach\n    void limpiar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    @AfterEach\n    void cerrar() {\n        SecurityContextHolder.clearContext();\n    }\n\n    private static void como(String... roles) {\n        SecurityContextHolder.getContext().setAuthentication(new TestingAuthenticationToken(\"u\", null, roles));\n    }\n\n    @ParameterizedTest(name = \"{0} puede usar {1}: {2}\")\n    @CsvSource({\n            // Dirección: reportes, políticas, contabilidad en lectura; no escribe pólizas ni pedidos.\n            \"ROLE_DIRECCION, consultar_indicadores, true\",\n            \"ROLE_DIRECCION, resumen_ventas, true\",\n            \"ROLE_DIRECCION, consultar_politicas, true\",\n            \"ROLE_DIRECCION, consultar_poliza, true\",\n            \"ROLE_DIRECCION, confirmar_pedido, false\",\n            \"ROLE_DIRECCION, sugerir_poliza, false\",\n            \"ROLE_DIRECCION, buscar_clientes, false\",\n            // Ventas: clientes, pedidos y acciones de venta; sin políticas ni contabilidad.\n            \"ROLE_VENTAS, buscar_clientes, true\",\n            \"ROLE_VENTAS, confirmar_pedido, true\",\n            \"ROLE_VENTAS, confirmar_accion, true\",\n            \"ROLE_VENTAS, consultar_politicas, false\",\n            \"ROLE_VENTAS, sugerir_poliza, false\",\n            \"ROLE_VENTAS, consultar_poliza, false\",\n            \"ROLE_VENTAS, consultar_reporte, false\",\n            // Contador: pólizas y confirmación MCP; no políticas ni acciones de venta.\n            \"ROLE_CONTADOR, consultar_poliza, true\",\n            \"ROLE_CONTADOR, sugerir_poliza, true\",\n            \"ROLE_CONTADOR, confirmar_accion, true\",\n            \"ROLE_CONTADOR, consultar_politicas, false\",\n            \"ROLE_CONTADOR, confirmar_pedido, false\",\n            \"ROLE_CONTADOR, buscar_clientes, false\",\n            // Compras: políticas y órdenes de compra; no contabilidad ni ventas.\n            \"ROLE_COMPRAS, consultar_politicas, true\",\n            \"ROLE_COMPRAS, consultar_orden_compra, true\",\n            \"ROLE_COMPRAS, buscar_proveedores, true\",\n            \"ROLE_COMPRAS, consultar_poliza, false\",\n            \"ROLE_COMPRAS, sugerir_poliza, false\",\n            \"ROLE_COMPRAS, confirmar_pedido, false\",\n            // Almacén, legal, finanzas y administración.\n            \"ROLE_ALMACEN, consultar_existencias, true\",\n            \"ROLE_ADMIN, consultar_existencias, true\",\n            \"ROLE_ALMACEN, consultar_orden_compra, true\",\n            \"ROLE_ALMACEN, consultar_politicas, false\",\n            \"ROLE_ALMACEN, sugerir_poliza, false\",\n            \"ROLE_LEGAL, consultar_documento, true\",\n            \"ROLE_LEGAL, consultar_reporte, false\",\n            \"ROLE_LEGAL, consultar_politicas, false\",\n            \"ROLE_FINANZAS, consultar_comprobante, true\",\n            \"ROLE_FINANZAS, resumen_ventas, true\",\n            \"ROLE_FINANZAS, consultar_poliza, false\",\n            \"ROLE_FINANZAS, sugerir_poliza, false\",\n            \"ROLE_ADMIN, buscar_clientes, true\",\n            \"ROLE_ADMIN, consultar_usuario, true\",\n            \"ROLE_ADMIN, consultar_politicas, false\",\n            \"ROLE_ADMIN, confirmar_accion, false\",\n    })\n    void cadaRolVeSoloSuAlcance(String rol, String herramienta, boolean permitida) {\n        como(rol);\n\n        assertThat(AlcanceHerramientas.puedeUsar(herramienta)).isEqualTo(permitida);\n    }\n\n    @ParameterizedTest(name = \"rol no reconocido {0} no puede usar {1}\")\n    @CsvSource({\n            \"ROLE_JEFE_AREA, consultar_politicas\",\n            \"ROLE_JEFE_AREA, consultar_reporte\",\n            \"ROLE_OPERACIONES, sugerir_poliza\",\n            \"ROLE_OPERACIONES, confirmar_pedido\",\n    })\n    void rolesNoMapeadosSeNiegan(String rol, String herramienta) {\n        como(rol);\n\n        assertThat(AlcanceHerramientas.puedeUsar(herramienta)).isFalse();\n    }\n\n    @ParameterizedTest(name = \"sin identidad no puede usar {0}\")\n    @CsvSource({\"consultar_politicas\", \"consultar_reporte\", \"sugerir_poliza\", \"confirmar_accion\"})\n    void sinIdentidadNadaSeOfrece(String herramienta) {\n        assertThat(AlcanceHerramientas.puedeUsar(herramienta)).isFalse();\n    }\n\n    @ParameterizedTest(name = \"herramienta inexistente {0} se niega aun con rol de dirección\")\n    @CsvSource({\"herramienta_inventada\", \"borrar_todo\", \"exportar_base\"})\n    void herramientasInexistentesSeNiegan(String herramienta) {\n        como(\"ROLE_DIRECCION\");\n\n        assertThat(AlcanceHerramientas.puedeUsar(herramienta)).isFalse();\n    }\n\n    @ParameterizedTest(name = \"usuario con {0} y {1} hereda la unión de ambos alcances: {2}\")\n    @CsvSource({\n            \"ROLE_CONTADOR, ROLE_COMPRAS, consultar_politicas, true\",\n            \"ROLE_CONTADOR, ROLE_COMPRAS, sugerir_poliza, true\",\n            \"ROLE_CONTADOR, ROLE_COMPRAS, confirmar_pedido, false\",\n    })\n    void unUsuarioConVariosRolesSumaSusAlcances(String rolA, String rolB, String herramienta, boolean permitida) {\n        como(rolA, rolB);\n\n        assertThat(AlcanceHerramientas.puedeUsar(herramienta)).isEqualTo(permitida);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/VoyageEmbedderTest.java": "package com.mx.josesaid.develop.nexus.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.content;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.header;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.method;\nimport static org.springframework.test.web.client.match.MockRestRequestMatchers.requestTo;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withStatus;\nimport static org.springframework.test.web.client.response.MockRestResponseCreators.withSuccess;\n\nimport java.time.Duration;\nimport java.util.List;\n\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.HttpMethod;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.test.web.client.MockRestServiceServer;\nimport org.springframework.web.client.HttpClientErrorException;\nimport org.springframework.web.client.RestClient;\n\nimport com.mx.josesaid.develop.nexus.application.Embedder;\n\nclass VoyageEmbedderTest {\n\n    @Test\n    void enviaClaveModeloYTipoDeEntrada() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"https://voyage.test\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"https://voyage.test/v1/embeddings\"))\n                .andExpect(method(HttpMethod.POST))\n                .andExpect(header(\"Authorization\", \"Bearer clave-de-prueba\"))\n                .andExpect(content().json(\"{\\\"input\\\":[\\\"uno\\\"],\\\"model\\\":\\\"voyage-3\\\",\\\"input_type\\\":\\\"query\\\"}\"))\n                .andRespond(withSuccess(\"{\\\"data\\\":[{\\\"index\\\":0,\\\"embedding\\\":[0.5,0.25]}]}\",\n                        MediaType.APPLICATION_JSON));\n\n        List<float[]> vectores = new VoyageEmbedder(builder.build(), \"clave-de-prueba\", \"voyage-3\")\n                .embeber(List.of(\"uno\"), Embedder.TipoEntrada.CONSULTA);\n\n        assertThat(vectores).hasSize(1);\n        assertThat(vectores.get(0)).containsExactly(0.5f, 0.25f);\n        servidor.verify();\n    }\n\n    @Test\n    void ordenaLosVectoresPorIndice() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"https://voyage.test\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"https://voyage.test/v1/embeddings\"))\n                .andRespond(withSuccess(\"{\\\"data\\\":[{\\\"index\\\":1,\\\"embedding\\\":[2]},{\\\"index\\\":0,\\\"embedding\\\":[1]}]}\",\n                        MediaType.APPLICATION_JSON));\n\n        List<float[]> vectores = new VoyageEmbedder(builder.build(), \"clave\", \"voyage-3\")\n                .embeber(List.of(\"a\", \"b\"), Embedder.TipoEntrada.DOCUMENTO);\n\n        assertThat(vectores.get(0)).containsExactly(1f);\n        assertThat(vectores.get(1)).containsExactly(2f);\n    }\n\n    @Test\n    void reintentaTrasUn429() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"https://voyage.test\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        servidor.expect(requestTo(\"https://voyage.test/v1/embeddings\"))\n                .andRespond(withStatus(HttpStatus.TOO_MANY_REQUESTS));\n        servidor.expect(requestTo(\"https://voyage.test/v1/embeddings\"))\n                .andRespond(withSuccess(\"{\\\"data\\\":[{\\\"index\\\":0,\\\"embedding\\\":[3]}]}\", MediaType.APPLICATION_JSON));\n\n        List<float[]> vectores = new VoyageEmbedder(builder.build(), \"clave\", \"voyage-3\", Duration.ZERO)\n                .embeber(List.of(\"uno\"), Embedder.TipoEntrada.CONSULTA);\n\n        assertThat(vectores.get(0)).containsExactly(3f);\n        servidor.verify();\n    }\n\n    @Test\n    void noReintentaIndefinidamente() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"https://voyage.test\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n        for (int i = 0; i < VoyageEmbedder.MAX_INTENTOS; i++) {\n            servidor.expect(requestTo(\"https://voyage.test/v1/embeddings\"))\n                    .andRespond(withStatus(HttpStatus.TOO_MANY_REQUESTS));\n        }\n\n        assertThatThrownBy(() -> new VoyageEmbedder(builder.build(), \"clave\", \"voyage-3\", Duration.ZERO)\n                .embeber(List.of(\"uno\"), Embedder.TipoEntrada.CONSULTA))\n                .isInstanceOf(HttpClientErrorException.class);\n        servidor.verify();\n    }\n\n    @Test\n    void sinClaveNoLlamaAlProveedor() {\n        RestClient.Builder builder = RestClient.builder().baseUrl(\"https://voyage.test\");\n        MockRestServiceServer servidor = MockRestServiceServer.bindTo(builder).build();\n\n        assertThatThrownBy(() -> new VoyageEmbedder(builder.build(), \"\", \"voyage-3\")\n                .embeber(List.of(\"uno\"), Embedder.TipoEntrada.DOCUMENTO))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"VOYAGE_API_KEY\");\n        servidor.verify();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/AlmacenFragmentosJdbcIT.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.LocalDate;\nimport java.util.List;\nimport java.util.Set;\n\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DataSourceTransactionManager;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.springframework.transaction.support.TransactionTemplate;\nimport org.testcontainers.containers.PostgreSQLContainer;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.utility.DockerImageName;\n\nimport com.mx.josesaid.develop.nexus.application.FragmentoIndexado;\nimport com.mx.josesaid.develop.nexus.application.ResultadoPolitica;\n\n/** Prueba el filtro por rol y vigencia contra PostgreSQL real con pgvector. */\n@Testcontainers\nclass AlmacenFragmentosJdbcIT {\n\n    @Container\n    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>(\n            DockerImageName.parse(\"pgvector/pgvector:pg17\").asCompatibleSubstituteFor(\"postgres\"));\n\n    private static final LocalDate HOY = LocalDate.of(2026, 11, 2);\n\n    private AlmacenFragmentosJdbc almacen;\n\n    @BeforeEach\n    void prepararEsquema() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(postgres.getJdbcUrl(),\n                postgres.getUsername(), postgres.getPassword());\n        Flyway.configure().dataSource(ds).locations(\"classpath:db/migration\").load().migrate();\n        JdbcTemplate jdbc = new JdbcTemplate(ds);\n        jdbc.update(\"DELETE FROM fragmentos_politica\");\n        almacen = new AlmacenFragmentosJdbc(jdbc,\n                new TransactionTemplate(new DataSourceTransactionManager(ds)));\n    }\n\n    @Test\n    void soloDevuelvePoliticasDeLosRolesDelUsuario() {\n        almacen.reemplazar(\"compras\", List.of(fragmento(\"compras\", List.of(\"COMPRAS\", \"DIRECCION\"),\n                LocalDate.of(2026, 11, 1), 0)));\n        almacen.reemplazar(\"finanzas\", List.of(fragmento(\"finanzas\", List.of(\"FINANZAS\"),\n                LocalDate.of(2026, 11, 1), 0)));\n\n        List<ResultadoPolitica> paraCompras = almacen.buscar(Set.of(\"COMPRAS\"), vector(0), HOY, 5);\n        List<ResultadoPolitica> paraFinanzas = almacen.buscar(Set.of(\"FINANZAS\"), vector(0), HOY, 5);\n\n        assertThat(paraCompras).extracting(ResultadoPolitica::politicaId).containsExactly(\"compras\");\n        assertThat(paraFinanzas).extracting(ResultadoPolitica::politicaId).containsExactly(\"finanzas\");\n    }\n\n    @Test\n    void rolSinPoliticasNoRecibeNada() {\n        almacen.reemplazar(\"compras\", List.of(fragmento(\"compras\", List.of(\"COMPRAS\"),\n                LocalDate.of(2026, 11, 1), 0)));\n\n        assertThat(almacen.buscar(Set.of(\"VENTAS\"), vector(0), HOY, 5)).isEmpty();\n    }\n\n    @Test\n    void noDevuelvePoliticasQueAunNoEstanVigentes() {\n        almacen.reemplazar(\"futura\", List.of(fragmento(\"futura\", List.of(\"COMPRAS\"),\n                LocalDate.of(2027, 1, 1), 0)));\n\n        assertThat(almacen.buscar(Set.of(\"COMPRAS\"), vector(0), HOY, 5)).isEmpty();\n    }\n\n    @Test\n    void ordenaPorSimilitudYRespetaElLimite() {\n        almacen.reemplazar(\"compras\", List.of(\n                fragmento(\"compras\", List.of(\"COMPRAS\"), LocalDate.of(2026, 11, 1), 0),\n                fragmento(\"compras\", List.of(\"COMPRAS\"), LocalDate.of(2026, 11, 1), 1)));\n\n        List<ResultadoPolitica> resultados = almacen.buscar(Set.of(\"COMPRAS\"), vector(1), HOY, 1);\n\n        assertThat(resultados).hasSize(1);\n        assertThat(resultados.get(0).indice()).isEqualTo(1);\n        assertThat(resultados.get(0).similitud()).isGreaterThan(0.99);\n    }\n\n    @Test\n    void reemplazarBorraLosFragmentosAnteriores() {\n        almacen.reemplazar(\"compras\", List.of(\n                fragmento(\"compras\", List.of(\"COMPRAS\"), LocalDate.of(2026, 11, 1), 0),\n                fragmento(\"compras\", List.of(\"COMPRAS\"), LocalDate.of(2026, 11, 1), 1)));\n        almacen.reemplazar(\"compras\", List.of(fragmento(\"compras\", List.of(\"COMPRAS\"),\n                LocalDate.of(2026, 11, 1), 0)));\n\n        assertThat(almacen.buscar(Set.of(\"COMPRAS\"), vector(0), HOY, 10)).hasSize(1);\n    }\n\n    private static FragmentoIndexado fragmento(String politica, List<String> roles, LocalDate vigencia, int indice) {\n        return new FragmentoIndexado(politica, indice, \"Título \" + politica, vigencia, roles,\n                \"regla \" + indice, vector(indice));\n    }\n\n    /** Vector con un 1 en la posición indicada: dos vectores distintos tienen similitud baja. */\n    private static float[] vector(int posicion) {\n        float[] v = new float[1024];\n        v[posicion] = 1f;\n        return v;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/nexus/infrastructure/persistence/LimpiezaAccionesTest.java": "package com.mx.josesaid.develop.nexus.infrastructure.persistence;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\n\nimport org.junit.jupiter.api.Test;\n\nclass LimpiezaAccionesTest {\n\n    @Test\n    void borraLasVencidasAntesDeUnaHoraAtras() {\n        Instant ahora = Instant.parse(\"2026-11-05T12:00:00Z\");\n        Clock reloj = Clock.fixed(ahora, ZoneOffset.UTC);\n        AccionPendienteRepositorio repo = mock(AccionPendienteRepositorio.class);\n        when(repo.borrarVencidasAntesDe(any())).thenReturn(3);\n\n        int borradas = new LimpiezaAcciones(repo, reloj).borrarVencidas();\n\n        verify(repo).borrarVencidasAntesDe(ahora.minus(Duration.ofHours(1)));\n        assertThat(borradas).isEqualTo(3);\n    }\n}\n"};
